const WORDS = [{"id":0,"day":1,"w":"abroad","ph":"əˈbrɔːd","defs":[["ad.","在（到）国外，在（到）海外；传开",true]],"tier":"f","ety":"a-（在…上）+ broad（宽广）→ 在宽广的海那一边 → 国外","mem":"a + broad（宽）→ 出了国门，路一下子\"变宽\"了、天也变宽了 → 出国。画面：一步跨过大海，眼前豁然开朗","ex":"study abroad · She wants to study abroad next year.（她想明年出国留学。）","nua":"abroad 是副词，前面不加 in/to（go abroad，不是 go to abroad）；区别 aboard（在船/机上）"},{"id":1,"day":1,"w":"absent","ph":"ˈæbsənt","defs":[["a.","缺席的；缺乏的；漫不经心",true]],"tier":"f","ety":"ab-（离开）+ sent（=essence 在场）→ 人离开现场 → 缺席","mem":"ab（离开）+ sent（send 送走）→ 把自己\"送走\"了、人不在 → 缺席。画面：点名时人已经飘到门外","ex":"be absent from · He was absent from class yesterday.（他昨天缺课了。）","nua":"absent from（缺席某场合），不是 absent in；反义词 present（出席的）"},{"id":2,"day":1,"w":"accident","ph":"ˈæksɪdənt","defs":[["n.","事故；意外的事，偶然的事",true]],"tier":"f","ety":"ac-（朝向）+ cid（落）+ -ent → 突然落到头上 → 意外、事故","mem":"ac-cid-ent 中间藏 cid（摔落）→ 东西突然\"砸\"下来 → 意外事故。画面：一块砖从天而降","ex":"by accident · I met him by accident on the street.（我碰巧在街上遇到他。）","nua":"by accident（偶然）= by chance；accident 是意外事故，incident 是（小）事件"},{"id":3,"day":1,"w":"acid","ph":"ˈæsɪd","defs":[["n.","/a. 酸；酸的",true]],"tier":"f","ety":"拉丁 acidus（酸的），与 acrid（辛辣）同源","mem":"谐音\"爱吸的\"→ 酸得让人\"爱吸\"一口气、龇牙咧嘴。画面：咬一口柠檬，酸到倒吸凉气","ex":"acid rain · Acid rain harms the environment.（酸雨危害环境。）","nua":"acid 作形容词还引申\"尖刻的\"（an acid remark 尖刻的话）"},{"id":4,"day":1,"w":"back","ph":"bæk","defs":[["ad.","向后，后退；回复 n.背，背面，后面 a.后面的，背后的 vt.使后退；支持",false]],"tier":"l","hint":"基础词：背/后面/向后。词组 go back 回去、come back 回来、back up 支持","ex":"Please go back to your seat.（请回到你的座位。）"},{"id":5,"day":1,"w":"background","ph":"ˈbækɡraʊnd","defs":[["n.","背景；经历",false]],"tier":"l","hint":"back（后）+ ground（地面）→ 后面的地面 → 背景","ex":"The mountains form a beautiful background.（群山构成美丽的背景。）"},{"id":6,"day":1,"w":"balance","ph":"ˈbæləns","defs":[["vt.","使平衡 n.平衡；差额，结余；天平，秤",false]],"tier":"l","hint":"ba（天平两盘）+ lance → 天平两头一样 → 平衡。词组 keep balance 保持平衡","ex":"You should keep a balance between work and rest.（你应该劳逸结合。）"},{"id":7,"day":1,"w":"beak","ph":"biːk","defs":[["n.","喙",false]],"tier":"l","hint":"具体名词：鸟嘴。联想 peak（山峰）— 鸟嘴像尖尖的山峰","ex":"The bird has a long beak.（这只鸟长着长长的喙。）"},{"id":8,"day":1,"w":"camera","ph":"ˈkæmərə","defs":[["n.","照相机，摄影机",false]],"tier":"l","hint":"具体名词：照相机。联想 photo camera 相机，camera 里的 cam 像镜头","ex":"She took a photo with her camera.（她用相机拍了张照片。）"},{"id":9,"day":1,"w":"card","ph":"kɑːrd","defs":[["n.","卡片，名片；纸片",false]],"tier":"l","hint":"具体名词：卡片。词组 ID card 身份证、credit card 信用卡","ex":"He showed his ID card at the door.（他在门口出示了身份证。）"},{"id":10,"day":1,"w":"care","ph":"ker","defs":[["n.","注意，小心；挂念；照顾，照料 vi.关心，计较；喜欢，愿意",false]],"tier":"l","hint":"基础词：关心/照顾。词组 take care of 照顾、care about 关心","ex":"She takes care of her little brother.（她照顾弟弟。）"},{"id":11,"day":1,"w":"careless","ph":"ˈkerləs","defs":[["a.","粗心的，草率的",false]],"tier":"l","hint":"care（小心）+ -less（无）→ 不小心的 → 粗心","ex":"He made a careless mistake.（他犯了个粗心的错误。）"},{"id":12,"day":1,"w":"dance","ph":"dæns","defs":[["vi.","跳舞 n.舞蹈，舞会",false]],"tier":"l","hint":"具体动词：跳舞。联想 dancer 舞者","ex":"They danced happily at the party.（他们在聚会上开心地跳舞。）"},{"id":13,"day":1,"w":"danger","ph":"ˈdeɪndʒər","defs":[["n.","危险，威胁",false]],"tier":"l","hint":"危险。词组 in danger 处于危险中、out of danger 脱离危险","ex":"The climbers were in great danger.（登山者处于极大的危险中。）"},{"id":14,"day":1,"w":"dangerous","ph":"ˈdeɪndʒərəs","defs":[["a.","危险的，不安全的",false]],"tier":"l","hint":"danger（危险）+ -ous（形容词）→ 危险的","ex":"It is dangerous to swim here.（在这里游泳很危险。）"},{"id":15,"day":1,"w":"daughter","ph":"ˈdɔːtər","defs":[["n.","女儿",false]],"tier":"l","hint":"基础词：女儿。联想 son 儿子、granddaughter 孙女","ex":"Their daughter studies at a university.（他们的女儿在大学读书。）"},{"id":16,"day":1,"w":"eager","ph":"ˈiːɡər","defs":[["a.","热切的，渴望的",true]],"tier":"f","ety":"源自古法语 aigre（锐利的、急切的）","mem":"谐音\"一个儿\"→ 妈妈望子成龙，眼睛都\"一个劲地\"盯着 → 热切渴望。画面：伸长脖子往前探","ex":"be eager to · The students are eager to learn.（学生们渴望学习。）","nua":"be eager to do（渴望做）、be eager for（渴望某物）；同义 keen on，但 eager 更书面"},{"id":17,"day":1,"w":"economic","ph":"ˌiːkəˈnɑːmɪk","defs":[["a.","经济的，经济学的",false]],"tier":"l","hint":"economy（经济）+ -ic → 经济的。词组 economic growth 经济增长","ex":"The country faces economic problems.（这个国家面临经济问题。）"},{"id":18,"day":1,"w":"educated","ph":"ˈedʒukeɪtɪd","defs":[["a.","受过教育的",false]],"tier":"l","hint":"educate（教育）+ -ed → 受过教育的。联想 well-educated 受过良好教育的","ex":"He is a well-educated young man.（他是受过良好教育的年轻人。）"},{"id":19,"day":1,"w":"education","ph":"ˌedʒuˈkeɪʃn","defs":[["n.","教育，培养",false]],"tier":"l","hint":"educate（教育）+ -ion → 教育。词组 higher education 高等教育","ex":"Education is important for children.（教育对孩子很重要。）"},{"id":20,"day":1,"w":"fail","ph":"feɪl","defs":[["vi.","失败，不及格；衰退，减弱 vt. (to)未能；使失望；没通过",false]],"tier":"l","hint":"失败。词组 fail to do 未能做、fail the exam 考试不及格","ex":"He failed to pass the exam.（他没能通过考试。）"},{"id":21,"day":1,"w":"failure","ph":"ˈfeɪljər","defs":[["n.","失败，不及格；失败者；没做到；失灵",false]],"tier":"l","hint":"fail（失败）+ -ure → 失败。联想 success 成功（反义）","ex":"Failure is the mother of success.（失败是成功之母。）"},{"id":22,"day":1,"w":"fairly","ph":"ˈferli","defs":[["ad.","公平地，公正地；相当，完全",false]],"tier":"l","hint":"fair（公平）+ -ly → 公平地；也引申\"相当\"","ex":"The judge treated them fairly.（法官公平地对待他们。）"},{"id":23,"day":1,"w":"faithful","ph":"ˈfeɪθfl","defs":[["a.","忠诚的，忠实的",false]],"tier":"l","hint":"faith（信念、忠诚）+ -ful → 忠诚的。词组 be faithful to 忠于","ex":"A dog is a faithful friend to man.（狗是人类忠实的朋友。）"},{"id":24,"day":1,"w":"garage","ph":"ɡəˈrɑːʒ","defs":[["n.","车库；汽车修理厂",false]],"tier":"l","hint":"具体名词：车库。联想 car 车 + garage 车库（放车的地方）","ex":"He parked his car in the garage.（他把车停进了车库。）"},{"id":25,"day":1,"w":"garbage","ph":"ˈɡɑːrbɪdʒ","defs":[["n.","垃圾",true]],"tier":"f","ety":"中世纪英语，原指\"禽鸟内脏\"，引申为垃圾","mem":"gar（谐音\"嘎\"）+ bage → 垃圾桶\"嘎嘣\"一声合上盖 → 垃圾。画面：扔完垃圾盖子弹回的声音","ex":"garbage can · Please throw it into the garbage can.（请把它扔进垃圾桶。）","nua":"garbage（美，生活垃圾）、rubbish（英）；rubbish 还引申\"废话\"（口语）"},{"id":26,"day":1,"w":"garden","ph":"ˈɡɑːrdn","defs":[["n.","花园，菜园 vi.从事园艺",false]],"tier":"l","hint":"具体名词：花园。联想 gardener 园丁、gardening 园艺","ex":"There are many flowers in the garden.（花园里有很多花。）"},{"id":27,"day":1,"w":"general","ph":"ˈdʒenrəl","defs":[["a.","普通的，通用的；总的，大体的 n.将军",false]],"tier":"l","hint":"普通的、总的。词组 in general 一般来说、general idea 大意","ex":"In general, the plan is a good one.（总的来说，这个计划不错。）"},{"id":28,"day":1,"w":"half","ph":"hæf","defs":[["n.","/a./ad.半，一半",false]],"tier":"l","hint":"基础词：一半。词组 half an hour 半小时、in half 分成两半","ex":"It takes half an hour to get there.（到那里要半小时。）"},{"id":29,"day":1,"w":"hall","ph":"hɔːl","defs":[["n.","穿堂，门厅，大厅；会堂，礼堂；办公大楼",false]],"tier":"l","hint":"具体名词：大厅。联想 school hall 学校礼堂、dining hall 食堂","ex":"The meeting was held in the hall.（会议在大厅举行。）"},{"id":30,"day":1,"w":"illegal","ph":"ɪˈliːɡl","defs":[["a.","不合法的，非法的",false]],"tier":"l","hint":"il-（不）+ legal（合法的）→ 不合法的。联想 legal 合法的","ex":"It is illegal to drive without a license.（无证驾驶是违法的。）"},{"id":31,"day":1,"w":"jaw","ph":"dʒɔː","defs":[["n.","颌，颈",false]],"tier":"l","hint":"具体名词：下巴。联想 mouth 嘴、teeth 牙齿都在 jaw 上","ex":"He hurt his jaw in the accident.（他在事故中伤了下巴。）"},{"id":32,"day":1,"w":"key","ph":"kiː","defs":[["n.","钥匙；答案，解答；键，琴键；方法，关键 a.主要的，关键的",false]],"tier":"l","hint":"基础词：钥匙；关键的。词组 key to 关键、the key point 关键点","ex":"Hard work is the key to success.（努力是成功的关键。）"},{"id":33,"day":1,"w":"kill","ph":"kɪl","defs":[["vi.","杀死，消灭；破坏，毁灭；消磨（时间）",false]],"tier":"l","hint":"基础词：杀死；消磨。词组 kill time 消磨时间","ex":"They played cards to kill time.（他们打牌消磨时间。）"},{"id":34,"day":1,"w":"lack","ph":"læk","defs":[["n.","/v. 缺乏，没有，缺少",true]],"tier":"f","ety":"中古英语 lak（不足），与 leak（漏）同源","mem":"谐音\"赖克\"→ 东西\"赖\"着不给你、缺货 → 缺乏。画面：货架上空空如也","ex":"lack of · The plants died for lack of water.（植物因缺水而死。）","nua":"lack of（名词短语）+ 名词；lack 作动词直接接宾语，不加 of（He lacks money.）"},{"id":35,"day":1,"w":"language","ph":"ˈlæŋɡwɪdʒ","defs":[["n.","语言",false]],"tier":"l","hint":"语言。词组 foreign language 外语、native language 母语","ex":"She can speak three languages.（她会说三种语言。）"},{"id":36,"day":1,"w":"laugh","ph":"læf","defs":[["vi.","/n.笑",false]],"tier":"l","hint":"基础词：笑。词组 laugh at 嘲笑、burst into laughter 大笑","ex":"The joke made everyone laugh.（这个笑话让大家都笑了。）"},{"id":37,"day":1,"w":"magazine","ph":"ˈmæɡəziːn","defs":[["n.","杂志，期刊",false]],"tier":"l","hint":"具体名词：杂志。联想 newspaper 报纸、magazine 杂志","ex":"She likes reading fashion magazines.（她喜欢读时尚杂志。）"},{"id":38,"day":1,"w":"main","ph":"meɪn","defs":[["a.","主要的，总的 n.总管道，干线",false]],"tier":"l","hint":"主要的。词组 the main point 要点、main street 大街","ex":"What is the main idea of this passage?（这篇文章的主旨是什么？）"},{"id":39,"day":1,"w":"manager","ph":"ˈmænɪdʒər","defs":[["n.","经理，管理人",false]],"tier":"l","hint":"manage（管理）+ -er（人）→ 经理","ex":"He is the manager of the company.（他是这家公司的经理。）"},{"id":40,"day":1,"w":"nation","ph":"ˈneɪʃn","defs":[["n.","国家，民族",false]],"tier":"l","hint":"国家、民族。联想 national 国家的、international 国际的","ex":"China is a great nation.（中国是个伟大的国家。）"},{"id":41,"day":1,"w":"navy","ph":"ˈneɪvi","defs":[["n.","海军",false]],"tier":"l","hint":"海军。联想 army 陆军、navy 海军、air force 空军","ex":"He joined the navy when he was twenty.（他二十岁时加入了海军。）"},{"id":42,"day":1,"w":"obtain","ph":"əbˈteɪn","defs":[["vt.","获得，得到",true]],"tier":"f","ety":"ob-（加强）+ tain（抓住，同 ten-）→ 用力抓住 → 获得","mem":"tain = 抓（contain 里也藏着抓）→ ob-tain 就是\"把它抓到手\" → 获得。画面：伸手把目标稳稳抓住","ex":"obtain a degree · You can obtain a degree after three years.（三年后你可获得学位。）","nua":"obtain（正式、通过努力获得）、get（口语）、gain（获得抽象收益）；同根 contain/retain/maintain"},{"id":43,"day":1,"w":"occasion","ph":"əˈkeɪʒn","defs":[["n.","场合；时机，机会",true]],"tier":"f","ety":"oc-（向）+ cas（落下）+ -ion → 事情落到眼前 → 时机、场合","mem":"oc + cas（谐音\"开撕\"）+ ion → 重要\"场合\"上可不能\"开撕\"。画面：正式晚宴上保持体面","ex":"on this occasion · On this occasion, we should celebrate.（在这个场合，我们应该庆祝。）","nua":"occasion 是可数名词（an occasion）；occasionally（副词）偶然地，不是\"在场合上\""},{"id":44,"day":1,"w":"of","ph":"əv","defs":[["prep.","[表示从属关系]……的；由……制成（或组成） 的；含有……的，装有……的；[表示性质、状况]； [表示位置、距离]；关于；[表示同位关系]；[表示数 世、种类]；[表示部分或全部]；由于，因为；[表示 分离、除去、剥夺]；[表示行为主体或对象]",false]],"tier":"s"},{"id":45,"day":1,"w":"package","ph":"ˈpækɪdʒ","defs":[["n.","包装，包裹，箱；一揽子交易（或计划、建议等）",false]],"tier":"l","hint":"pack（打包）+ -age → 包裹。联想 parcel 包裹（同义）","ex":"The package arrived this morning.（包裹今早到了。）"},{"id":46,"day":1,"w":"railway","ph":"ˈreɪlweɪ","defs":[["n.","铁路",false]],"tier":"l","hint":"rail（铁轨）+ way（路）→ 铁路","ex":"The railway connects the two cities.（这条铁路连接两座城市。）"},{"id":47,"day":1,"w":"range","ph":"reɪndʒ","defs":[["n.","范围，距离，领域；排列，连续，（山)脉",false]],"tier":"l","hint":"范围。词组 a wide range of 各种各样的、in the range of 在…范围内","ex":"The shop sells a wide range of goods.（这家店卖各种各样的商品。）"},{"id":48,"day":1,"w":"salary","ph":"ˈsæləri","defs":[["n.","薪金，薪俸",true]],"tier":"f","ety":"拉丁 salarium（盐钱）→ 古罗马士兵领盐作报酬 → 薪水","mem":"sal（salt 盐）→ 古罗马发工资是发\"盐\" → 薪水。画面：古代人扛着一袋盐当工资","ex":"monthly salary · He gets a monthly salary of 5000 yuan.（他月薪五千元。）","nua":"salary（月薪，白领）、wage（周薪，体力劳动）、pay（统称）；同源 salad（盐拌的沙拉）"},{"id":49,"day":1,"w":"satisfaction","ph":"ˌsætɪsˈfækʃn","defs":[["n.","满足，满意",false]],"tier":"l","hint":"satisfy（满足）+ -action → 满足。词组 with satisfaction 满意地","ex":"He smiled with satisfaction.（他满意地笑了。）"},{"id":50,"day":1,"w":"satisfy","ph":"ˈsætɪsfaɪ","defs":[["vt.","使满足，使满意",false]],"tier":"l","hint":"满足。词组 be satisfied with 对…满意","ex":"The result satisfied everyone.（这个结果让每个人都满意。）"},{"id":51,"day":1,"w":"sauce","ph":"sɔːs","defs":[["n.","调味汁",false]],"tier":"l","hint":"调味汁。联想 soy sauce 酱油、tomato sauce 番茄酱","ex":"She put some sauce on the noodles.（她在面条上放了点酱汁。）"},{"id":52,"day":1,"w":"table","ph":"ˈteɪbl","defs":[["n.","桌子；表格，目录",false]],"tier":"l","hint":"基础词：桌子；表格。词组 at table 在吃饭、time table 时间表","ex":"The book is on the table.（书在桌子上。）"},{"id":53,"day":1,"w":"tape","ph":"teɪp","defs":[["n.","带子，磁带",true]],"tier":"f","ety":"源自古英语 tæppe（狭长的布条）","mem":"对比拼写：tape（磁带，多个 e 拖长）vs tap（水龙头，短促）→ 磁带是\"长长\"的一卷。画面：一长条带子卷成圈","ex":"tape recorder · She listened to the tape recorder.（她听录音机。）","nua":"tape（带子、磁带、胶带）、tap（水龙头、轻拍）；tape recorder 录音机"},{"id":54,"day":1,"w":"teacher","ph":"ˈtiːtʃər","defs":[["n.","教师，教员",false]],"tier":"l","hint":"teach（教）+ -er（人）→ 教师","ex":"Our teacher is very kind to us.（我们老师对我们很和蔼。）"},{"id":55,"day":1,"w":"teenage","ph":"ˈtiːneɪdʒ","defs":[["a.","十几岁的",true]],"tier":"f","ety":"teen（13-19 数字后缀）+ age（年龄）→ 十几岁","mem":"thirteen 到 nineteen 都带 teen，加上 age → 十几岁的年纪。画面：13-19 岁一排站","ex":"teenage problems · Teenage problems are common in schools.（青少年问题在学校很常见。）","nua":"teenage（形容词）、teenager（名词，青少年）；发音重音在前 teen"},{"id":56,"day":1,"w":"understand","ph":"ˌʌndərˈstænd","defs":[["vt.","懂，理解，领会；获悉，听说",false]],"tier":"l","hint":"under（在下面）+ stand（站）→ 站到下面看透 → 理解","ex":"I don't understand this sentence.（我不理解这个句子。）"},{"id":57,"day":1,"w":"understanding","ph":"","defs":[["","[ˌʌndərˈstændɪŋ] n.理解，理解力；谅解 a.能体谅人的，宽容的",false]],"tier":"l","hint":"understand（理解）+ -ing → 理解；宽容的","ex":"Thank you for your understanding.（谢谢你的理解。）"},{"id":58,"day":1,"w":"underwear","ph":"ˈʌndərwer","defs":[["n.","内衣",false]],"tier":"l","hint":"under（在下面）+ wear（穿）→ 穿在里面的 → 内衣","ex":"He bought some new underwear.（他买了些新内衣。）"},{"id":59,"day":1,"w":"valuable","ph":"ˈvæljuəbl","defs":[["a.","有价值的，贵重的 n. (pl.)贵重物品，财宝",false]],"tier":"l","hint":"value（价值）+ -able → 有价值的","ex":"The watch is very valuable.（这块表很值钱。）"},{"id":60,"day":1,"w":"wake","ph":"weɪk","defs":[["vt.","醒来，唤醒；使觉悟，激发，引起 vi.醒来",false]],"tier":"l","hint":"基础词：醒来。词组 wake up 醒来、wake sb up 叫醒某人","ex":"I usually wake up at six.（我通常六点醒。）"},{"id":61,"day":1,"w":"wall","ph":"wɔːl","defs":[["n.","墙壁，围墙",false]],"tier":"l","hint":"基础词：墙。词组 on the wall 在墙上","ex":"There is a picture on the wall.（墙上有一幅画。）"},{"id":62,"day":2,"w":"about","ph":"əˈbaʊt","defs":[["prep.","关于，对于；在……周围，在……附近 ad.在周围，附近；大约，差不多",false]],"tier":"s"},{"id":63,"day":2,"w":"above","ph":"əˈbʌv","defs":[["prep.","在……之上，超过 a.上面的，上述的 ad.在上面，以上",false]],"tier":"s"},{"id":64,"day":2,"w":"accent","ph":"ˈæksənt","defs":[["n.","重音；口音",true]],"tier":"f","ety":"ac-（加强）+ cent（唱）→ 唱出来的强调 → 重音","mem":"ac + cent（分币）→ 说话像\"分币\"轻重不一样 → 重音、口音。画面：说话抑扬顿挫","ex":"foreign accent · He speaks English with a foreign accent.（他说英语带外国口音。）","nua":"accent（口音、重音）、accident（事故）；别只差一个 i/d 就看错"},{"id":65,"day":2,"w":"account","ph":"əˈkaʊnt","defs":[["n.","/v. 账，账户；说明，叙述；解释",true]],"tier":"f","ety":"ac-（向）+ count（数）→ 数清楚 → 记账、说明","mem":"ac + count（数）→ 把一笔笔\"数\"清楚 → 账户、说明。画面：会计对着账本数数","ex":"account for · The weather accounts for the delay.（天气是延误的原因。）","nua":"account for 有\"解释原因\"和\"占比例\"两个意思；bank account 银行账户"},{"id":66,"day":2,"w":"achievement","ph":"əˈtʃiːvmənt","defs":[["n.","成就，成绩",true]],"tier":"f","ety":"achieve（完成）+ -ment（名词）→ 完成的事 → 成就","mem":"a + chieve（=chief 头）+ ment → 干成了\"头等\"大事 → 成就。画面：登顶领奖台","ex":"a great achievement · Winning the prize is a great achievement.（获奖是巨大成就。）","nua":"achievement（成就，抽象/具体）、accomplishment 同义但更强调技能；同根 achieve"},{"id":67,"day":2,"w":"across","ph":"əˈkrɔːs","defs":[["ad.","/prep.横越；交叉 prep.在……对面",false]],"tier":"s"},{"id":68,"day":2,"w":"bank","ph":"bæŋk","defs":[["n.","岸，堤；银行",false]],"tier":"l","hint":"一词多义：岸、银行。联想：河岸（river bank）像银行的柜台","ex":"The house is on the bank of the river.（房子在河岸上。）"},{"id":69,"day":2,"w":"battle","ph":"ˈbætl","defs":[["n.","战斗，战役，斗争 vi.战斗，战争，搏斗",false]],"tier":"l","hint":"战斗。联想 war 战争（更大规模）、battle 战役（具体一场）","ex":"They won the battle after a hard fight.（经过苦战他们打赢了这一仗。）"},{"id":70,"day":2,"w":"beach","ph":"biːtʃ","defs":[["n.","海滨，海滩",false]],"tier":"l","hint":"海滩。联想 coast 海岸（更长）、beach 海滩（可游泳）","ex":"We walked along the beach at sunset.（日落时我们沿海滩散步。）"},{"id":71,"day":2,"w":"cake","ph":"keɪk","defs":[["n.","月饼，糕，蛋糕",false]],"tier":"l","hint":"蛋糕。联想 birthday cake 生日蛋糕","ex":"She made a cake for my birthday.（她为我做了个生日蛋糕。）"},{"id":72,"day":2,"w":"calculate","ph":"ˈkælkjuleɪt","defs":[["vt.","计算，推算；估计",true]],"tier":"f","ety":"拉丁 calculus（小石子）→ 古人用小石子计数 → 计算","mem":"cal + cul + ate → 古人用\"小石子\"（calculus）一颗颗\"吃\"（ate）进账本 → 计算。画面：摆石子算数","ex":"calculate the cost · We need to calculate the cost first.（我们需要先计算成本。）","nua":"calculate（计算、推算）、compute（计算机计算）；calculator 计算器"},{"id":73,"day":2,"w":"cap","ph":"kæp","defs":[["n.","便帽，军帽；帽状物",false]],"tier":"l","hint":"帽子（有帽檐）。联想 hat 帽子（有边）、cap 便帽","ex":"He wore a cap to protect his eyes from the sun.（他戴帽子遮阳。）"},{"id":74,"day":2,"w":"deal","ph":"diːl","defs":[["vi.","(with)处理，应付 vt.给予 n.交易，买卖；契约",false]],"tier":"l","hint":"处理、交易。词组 deal with 处理、a great deal of 大量","ex":"We must deal with this problem at once.（我们必须马上处理这个问题。）"},{"id":75,"day":2,"w":"earth","ph":"ɜːrθ","defs":[["n.","地球；土壤；土地",false]],"tier":"l","hint":"地球、土地。联想 on earth 究竟、the earth 地球","ex":"The earth goes around the sun.（地球绕着太阳转。）"},{"id":76,"day":2,"w":"easy","ph":"ˈiːzi","defs":[["a.","容易；舒适，安心",false]],"tier":"s"},{"id":77,"day":2,"w":"edge","ph":"edʒ","defs":[["n.","/v. 刃；边缘",true]],"tier":"f","ety":"古英语 ecg（锋利的边）","mem":"谐音\"艾子\"→ 刀的\"刃\"像艾草的叶子一样锋利 → 边缘、刃。画面：刀刃闪着寒光","ex":"on the edge of · The company is on the edge of bankruptcy.（公司濒临破产。）","nua":"on the edge of（濒临）、at the edge of（在…边缘）；edge 还引申\"优势\"（have an edge）"},{"id":78,"day":2,"w":"fact","ph":"fækt","defs":[["n.","事实，实际，真相",false]],"tier":"l","hint":"事实。词组 in fact 事实上、as a matter of fact 事实上","ex":"In fact, I know nothing about it.（事实上，我对此一无所知。）"},{"id":79,"day":2,"w":"famous","ph":"ˈfeɪməs","defs":[["a.","著名的",false]],"tier":"l","hint":"著名的。词组 be famous for 因…出名","ex":"The city is famous for its old buildings.（这座城市以古老建筑闻名。）"},{"id":80,"day":2,"w":"farm","ph":"fɑːrm","defs":[["n.","农场，农庄，牧场 vi.耕作，经营农场",false]],"tier":"l","hint":"农场。联想 farmer 农民、farming 农业","ex":"They grow vegetables on the farm.（他们在农场种蔬菜。）"},{"id":81,"day":2,"w":"generally","ph":"ˈdʒenrəli","defs":[["ad.","通常，一般",false]],"tier":"l","hint":"general（一般的）+ -ly → 通常。词组 generally speaking 一般来说","ex":"Generally speaking, the plan works well.（总的来说，这个计划运行良好。）"},{"id":82,"day":2,"w":"hardly","ph":"ˈhɑːrdli","defs":[["ad.","几乎不，简直不，仅仅",false]],"tier":"l","hint":"几乎不（否定副词）。注意不是\"努力地\"，那是 hard","ex":"I can hardly hear you.（我几乎听不见你说话。）"},{"id":83,"day":2,"w":"harm","ph":"hɑːrm","defs":[["n.","/vt.损害，伤害，危害",false]],"tier":"l","hint":"伤害。词组 do harm to 对…有害","ex":"Smoking does great harm to your health.（吸烟对健康危害很大。）"},{"id":84,"day":2,"w":"harmful","ph":"ˈhɑːrmfl","defs":[["a.","有害的",false]],"tier":"l","hint":"harm（伤害）+ -ful → 有害的。词组 be harmful to 对…有害","ex":"The gas is harmful to the body.（这种气体对身体有害。）"},{"id":85,"day":2,"w":"imaginary","ph":"ɪˈmædʒɪneri","defs":[["a.","想象的，虚构的",false]],"tier":"l","hint":"imagine（想象）+ -ary → 想象的、虚构的","ex":"The story is about an imaginary world.（这个故事讲的是一个虚构的世界。）"},{"id":86,"day":2,"w":"imagine","ph":"ɪˈmædʒɪn","defs":[["n.","想象，设想；料想",false]],"tier":"l","hint":"想象。词组 imagine doing 想象做、imagine that 想象…","ex":"Can you imagine living on the moon?（你能想象住在月球上吗？）"},{"id":87,"day":2,"w":"keen","ph":"kiːn","defs":[["a.","锋利，尖锐；敏捷，敏锐；(on)热心，渴望",false]],"tier":"l","hint":"渴望的、敏锐的。词组 be keen on 热衷于","ex":"She is keen on learning English.（她热衷于学英语。）"},{"id":88,"day":2,"w":"keep","ph":"kiːp","defs":[["vi.","保持，坚持 vt.保留，保存；保持，继续；保守，遵守；防守，保卫； 抑制，防止；扣留，留住；赡养，饲养；经营，管理",false]],"tier":"l","hint":"保持、继续。词组 keep doing 一直做、keep on 继续","ex":"Keep quiet, please.（请保持安静。）"},{"id":89,"day":2,"w":"kilometer/-re","ph":"ˈkɪləmiːtər","defs":[["n.","公里，千米",false]],"tier":"l","hint":"kilo（千）+ meter（米）→ 千米。联想 meter 米","ex":"The village is ten kilometers away.（村子在十公里外。）"},{"id":90,"day":2,"w":"kitchen","ph":"ˈkɪtʃɪn","defs":[["n.","厨房",false]],"tier":"l","hint":"厨房。联想 cook 做饭的地方就是 kitchen","ex":"Mom is cooking in the kitchen.（妈妈正在厨房做饭。）"},{"id":91,"day":2,"w":"lake","ph":"leɪk","defs":[["n.","湖",false]],"tier":"l","hint":"湖。联想 river 河、sea 海、lake 湖","ex":"We went boating on the lake.（我们在湖上划船。）"},{"id":92,"day":2,"w":"lamb","ph":"læm","defs":[["n.","羔羊，小羊；羔羊肉",false]],"tier":"l","hint":"小羊。联想 sheep 绵羊（大）、lamb 羔羊（小）","ex":"The lamb is following its mother.（小羊跟着妈妈。）"},{"id":93,"day":2,"w":"lamp","ph":"læmp","defs":[["n.","灯",false]],"tier":"l","hint":"灯。联想 light 光、lamp 台灯/灯","ex":"He turned on the lamp and began to read.（他打开灯开始读书。）"},{"id":94,"day":2,"w":"land","ph":"lænd","defs":[["n.","陆地；土地；国土，国家 vi./vt.(使）靠岸，（使）登陆，(使)着陆",false]],"tier":"l","hint":"陆地、土地。联想 island 岛（海中的陆地）","ex":"The plane landed on the ground safely.（飞机安全着陆。）"},{"id":95,"day":2,"w":"late","ph":"leɪt","defs":[["ad.","迟，迟到地 a.迟的；晚，晚期的；已故的，过世的",false]],"tier":"s"},{"id":96,"day":2,"w":"male","ph":"meɪl","defs":[["a.","/n.男性（的），雄性（的）",false]],"tier":"l","hint":"男性的。联想 female 女性的（反义）","ex":"The school has both male and female teachers.（学校有男老师和女老师。）"},{"id":97,"day":2,"w":"name","ph":"neɪm","defs":[["n.","名字，名称；名声，名望；名义 vt.给……取名；列举；任命，提名",false]],"tier":"l","hint":"名字。词组 in the name of 以…的名义","ex":"What's your name?（你叫什么名字？）"},{"id":98,"day":2,"w":"nasty","ph":"ˈnæsti","defs":[["a.","令人厌恶的；难弄的；恶劣的；污秽的",false]],"tier":"l","hint":"令人厌恶的、恶劣的。联想 nasty weather 恶劣天气","ex":"The weather is nasty today.（今天天气很恶劣。）"},{"id":99,"day":2,"w":"natural","ph":"ˈnætʃrəl","defs":[["a.","自然界的，天生的；天赋的，固有的",false]],"tier":"l","hint":"nature（自然）+ -al → 自然的。词组 natural resources 自然资源","ex":"The country is rich in natural resources.（这个国家自然资源丰富。）"},{"id":100,"day":2,"w":"obey","ph":"əˈbeɪ","defs":[["vt.","服从，顺从",false]],"tier":"l","hint":"服从。联想 obey the law 守法、disobey 违抗（反义）","ex":"We must obey the traffic rules.（我们必须遵守交通规则。）"},{"id":101,"day":2,"w":"object","ph":"ˈɑːbdʒekt","defs":[["n.","物体；对象；目的",false]],"tier":"l","hint":"物体、目的。联想 object to 反对（动词）","ex":"The object of the game is to score points.（游戏的目标是得分。）"},{"id":102,"day":2,"w":"ocean","ph":"ˈoʊʃn","defs":[["n.","海洋",false]],"tier":"l","hint":"海洋。联想 the Pacific Ocean 太平洋","ex":"The ocean covers most of the earth.（海洋覆盖了地球大部分。）"},{"id":103,"day":2,"w":"offend","ph":"əˈfend","defs":[["vt.","冒犯，得罪；使不快",true]],"tier":"f","ety":"of-（相对）+ fend（打击）→ 反着打 → 冒犯","mem":"对比 defend（防守）vs offend（冒犯）→ 一个守、一个攻。画面：说错话把人\"得罪\"了","ex":"offend sb · I didn't mean to offend you.（我不是故意冒犯你。）","nua":"offend（冒犯）、defend（防守，含 de- 反着挡）；offensive（冒犯的）"},{"id":104,"day":2,"w":"pain","ph":"peɪn","defs":[["n.","痛苦，疼痛；(pl.)努力，劳苦",false]],"tier":"l","hint":"疼痛、痛苦。联想 painful 疼痛的、take pains 下功夫","ex":"She felt a sharp pain in her back.（她感到背部剧痛。）"},{"id":105,"day":2,"w":"paint","ph":"peɪnt","defs":[["vt.","涂，漆；画；绘，描述 n.油漆，颜料",false]],"tier":"l","hint":"油漆、画。联想 painter 画家、painting 绘画","ex":"He painted the wall white.（他把墙刷成了白色。）"},{"id":106,"day":2,"w":"painting","ph":"ˈpeɪntɪŋ","defs":[["n.","（一幅）油画，绘画；画法；（上）油漆",false]],"tier":"l","hint":"paint（画）+ -ing → 绘画、油画","ex":"There is a beautiful painting on the wall.（墙上有一幅美丽的油画。）"},{"id":107,"day":2,"w":"pair","ph":"per","defs":[["n.","（一）对，（一）双，（一）副；一对男女/夫妇vi./vt. （使）配对，成对",false]],"tier":"l","hint":"一对、一双。词组 a pair of 一双","ex":"I bought a pair of shoes.（我买了一双鞋。）"},{"id":108,"day":2,"w":"raise","ph":"reɪz","defs":[["vt.","举起，提高，提升；增加；筹集；引起；抚养，饲养； 提出，发起",false]],"tier":"l","hint":"举起、提高、抚养（及物，接宾语）。对比 rise（不及物，上升）","ex":"He raised his hand to ask a question.（他举手提问。）"},{"id":109,"day":2,"w":"same","ph":"seɪm","defs":[["a.","相同的，一样的 pron.同样的人，同样的事情",false]],"tier":"s"},{"id":110,"day":2,"w":"sand","ph":"sænd","defs":[["n.","沙；(pl.)沙滩",false]],"tier":"l","hint":"沙。联想 sand beach 沙滩、sandy 沙的","ex":"The children are playing in the sand.（孩子们在沙里玩。）"},{"id":111,"day":2,"w":"save","ph":"seɪv","defs":[["vt.","救，拯救；储存，贮存；节省，节约",false]],"tier":"l","hint":"救、节省、存。词组 save money 存钱、save time 省时间","ex":"The doctor saved the boy's life.（医生救了男孩的命。）"},{"id":112,"day":2,"w":"talk","ph":"tɔːk","defs":[["vt.","谈，讨论 vi.讲话，谈话，交谈 n.谈话，演讲，讲话",false]],"tier":"l","hint":"谈话。词组 talk about 谈论、talk with 和…交谈","ex":"They are talking about the plan.（他们在谈论这个计划。）"},{"id":113,"day":2,"w":"taste","ph":"teɪst","defs":[["vt.","尝，品尝；体验，领略 vi.尝起来，吃起来 n.滋味；味觉；趣味；口味；鉴赏力",false]],"tier":"l","hint":"尝、味道。词组 taste good 尝起来好","ex":"The soup tastes good.（这汤尝起来不错。）"},{"id":114,"day":2,"w":"tear","ph":"ter","defs":[["n.","(pl.)眼泪 vt.撕，撕下",false]],"tier":"l","hint":"一词两读：tear /tɪr/ 眼泪、tear /ter/ 撕","ex":"Tears ran down her face.（眼泪顺着她的脸流下来。）"},{"id":115,"day":2,"w":"technical","ph":"ˈteknɪkl","defs":[["a.","技术的，工艺的；专门性，专业性的",false]],"tier":"l","hint":"technology（技术）的形容词。词组 technical support 技术支持","ex":"The job needs technical skills.（这份工作需要技术技能。）"},{"id":116,"day":2,"w":"undo","ph":"ʌnˈduː","defs":[["vt.","解开，松开；取消，撤销",true]],"tier":"f","ety":"un-（反）+ do（做）→ 把做的还原 → 撤销、解开","mem":"un + do → 把\"做\"的反过来 → 撤销、解开。画面：Ctrl+Z 撤销","ex":"undo the damage · Nothing can undo the damage.（什么都无法挽回损失。）","nua":"undo（撤销、解开）、undone（未完成的，be left undone）"},{"id":117,"day":2,"w":"uniform","ph":"ˈjuːnɪfɔːrm","defs":[["n.","制服，军服 a.一致的，一律的",false]],"tier":"l","hint":"uni-（一）+ form（形式）→ 统一的形式 → 制服","ex":"Students must wear uniforms at school.（学生在校必须穿校服。）"},{"id":118,"day":2,"w":"union","ph":"ˈjuːniən","defs":[["n.","结合，组合，联合；协会，工会，联盟",false]],"tier":"l","hint":"联合、工会。联想 unite（联合）的名词","ex":"The workers joined the union.（工人们加入了工会。）"},{"id":119,"day":2,"w":"unite","ph":"juˈnaɪt","defs":[["vi.","/vt.统一，结合，合并；联合，团结",false]],"tier":"l","hint":"uni-（一）+ te → 合一 → 团结。词组 unite against 团结起来反对","ex":"The whole nation united against the enemy.（全国团结起来对抗敌人。）"},{"id":120,"day":2,"w":"value","ph":"ˈvæljuː","defs":[["n.","价值，实用性，重要性 vi.评价，估计；尊重，重视",false]],"tier":"l","hint":"价值。词组 of value 有价值的、value for money 物有所值","ex":"The book is of great value to me.（这本书对我很有价值。）"},{"id":121,"day":2,"w":"wage","ph":"weɪdʒ","defs":[["n.","(pl.)工资，报酬",false]],"tier":"l","hint":"工资（周薪）。对比 salary（月薪）","ex":"He gets his wages every Friday.（他每周五领工资。）"},{"id":122,"day":2,"w":"war","ph":"wɔːr","defs":[["n.","战争，战斗",false]],"tier":"l","hint":"战争。联想 peace 和平（反义）","ex":"The war lasted for four years.（战争持续了四年。）"},{"id":123,"day":2,"w":"warmth","ph":"wɔːrmθ","defs":[["n.","暖和，温暖；热忱，热烈；保暖",false]],"tier":"l","hint":"warm（温暖）+ -th（名词）→ 温暖。联想 -th 后缀：length、depth","ex":"The warmth of the sun made us comfortable.（阳光的温暖让我们很舒服。）"},{"id":124,"day":3,"w":"absence","ph":"ˈæbsəns","defs":[["n.","缺席；缺乏",true]],"tier":"f","ety":"absent（缺席的）的名词形式","mem":"absent（缺席，前面学过）+ -ence → 缺席、缺乏。联想 absent 一家","ex":"in the absence of · In the absence of proof, we can't decide.（缺乏证据时无法定论。）","nua":"absence（缺席、缺乏）、presence（出席、存在）；in the absence of（在缺乏…情况下）"},{"id":125,"day":3,"w":"acceptable","ph":"əkˈseptəbl","defs":[["a.","可接受的；合意的",true]],"tier":"f","ety":"accept（接受）+ -able（可…的）→ 可接受的","mem":"accept + able → \"能\"（able）被\"接受\"（accept）的 → 可接受的","ex":"acceptable to · The plan is acceptable to everyone.（这个计划大家都接受。）","nua":"acceptable（可接受的）、accepted（被认可的）；注意拼写 accept 不是 except"},{"id":126,"day":3,"w":"according(to)","ph":"əˈkɔːdɪŋ","defs":[["prep.","按照，根据",true]],"tier":"f","ety":"accord（一致）+ -ing → 与…一致 → 根据","mem":"accord（一致）+ ing → 跟它\"一致\"→ 根据。画面：照着尺子量","ex":"according to · According to the report, the number is rising.（根据报告，数字在上升。）","nua":"according to 后接名词/代词，不接观点（不说 according to me，说 in my opinion）"},{"id":127,"day":3,"w":"achieve","ph":"əˈtʃiːv","defs":[["vt.","完成，达到；获得",true]],"tier":"f","ety":"a-（到）+ chieve（=chief 头，顶点）→ 到达顶点 → 达到","mem":"a + chieve（=chief 头）→ 冲到\"头\"、到顶 → 达成。画面：冲线夺冠","ex":"achieve success · Hard work helps you achieve success.（努力帮你取得成功。）","nua":"achieve（达到目标）、reach（到达）、accomplish（完成）；名词 achievement"},{"id":128,"day":3,"w":"bake","ph":"beɪk","defs":[["vt.","烤，烘，焙",false]],"tier":"l","hint":"烘烤。联想 baker 面包师、bakery 面包店","ex":"She baked some bread this morning.（她今早烤了些面包。）"},{"id":129,"day":3,"w":"ball","ph":"bɔːl","defs":[["n.","球，球状物；大型舞会",false]],"tier":"l","hint":"球、舞会。一词多义：play ball 打球、a ball 一场舞会","ex":"The children are playing with a ball.（孩子们在玩球。）"},{"id":130,"day":3,"w":"base","ph":"beɪs","defs":[["n.","基（础），底（座）；基地 vt. (on)把……建立在……基础上",false]],"tier":"l","hint":"基础、基地。词组 be based on 以…为基础","ex":"The film is based on a true story.（这部电影基于真实故事。）"},{"id":131,"day":3,"w":"basket","ph":"ˈbæskɪt","defs":[["n.","篮子，篓",false]],"tier":"l","hint":"篮子。联想 basketball 篮球（basket+ball）","ex":"She put the apples in a basket.（她把苹果放进篮子里。）"},{"id":132,"day":3,"w":"bean","ph":"biːn","defs":[["n.","豆，菜豆",false]],"tier":"l","hint":"豆。联想 soya bean 大豆、bean 豆子","ex":"We planted some beans in the garden.（我们在园子里种了些豆子。）"},{"id":133,"day":3,"w":"calm","ph":"kɑːm","defs":[["n.","平静，镇静，沉着 vi./vt.（使）镇静，（使）镇定 n.平静，风平浪静",false]],"tier":"l","hint":"平静。词组 stay calm 保持冷静、calm down 冷静下来","ex":"Please stay calm in an emergency.（紧急情况下请保持冷静。）"},{"id":134,"day":3,"w":"camp","ph":"kæmp","defs":[["n.","野营，营地，帐篷 vi.设营，宿营",false]],"tier":"l","hint":"营地、露营。词组 go camping 去露营","ex":"We went camping by the river last summer.（去年夏天我们去河边露营。）"},{"id":135,"day":3,"w":"careful","ph":"ˈkerfl","defs":[["a.","小心的，仔细的",false]],"tier":"l","hint":"care（小心）+ -ful → 小心的。词组 be careful with 小心对待","ex":"Be careful when you cross the road.（过马路时要小心。）"},{"id":136,"day":3,"w":"daily","ph":"ˈdeɪli","defs":[["a.","每日的，日常的 ad.每日，天天 n. 日报",false]],"tier":"l","hint":"day（日）的形容词 → 每日的。词组 daily life 日常生活","ex":"Reading is part of my daily life.（阅读是我日常生活的一部分。）"},{"id":137,"day":3,"w":"damage","ph":"ˈdæmɪdʒ","defs":[["vt.","损害，毁坏 n.损害，毁坏；(pl.)损害赔偿费",false]],"tier":"l","hint":"损害。词组 do damage to 对…造成损害","ex":"The storm caused great damage to the crops.（暴风雨对庄稼造成了巨大损害。）"},{"id":138,"day":3,"w":"date","ph":"deɪt","defs":[["n.","日期，年代；约会 vi./vt.注日期；约会",false]],"tier":"l","hint":"日期、约会。词组 out of date 过时、make a date 约会","ex":"What's the date today?（今天几号？）"},{"id":139,"day":3,"w":"each","ph":"iːtʃ","defs":[["a.","/pron.每个，各，各自",false]],"tier":"s"},{"id":140,"day":3,"w":"ear","ph":"ɪr","defs":[["n.","耳朵，耳状物；听力，听觉",false]],"tier":"l","hint":"耳朵。联想 hear 听（用 ear）","ex":"Rabbits have long ears.（兔子有长耳朵。）"},{"id":141,"day":3,"w":"early","ph":"ˈɜːrli","defs":[["a.","早的，早日的，提早的 ad.早，初",false]],"tier":"s"},{"id":142,"day":3,"w":"eastern","ph":"ˈiːstərn","defs":[["a.","东方的，东部的，朝东的",false]],"tier":"l","hint":"east（东）+ -ern → 东方的。联想 western 西方的","ex":"The eastern part of China is near the sea.（中国东部靠近大海。）"},{"id":143,"day":3,"w":"educate","ph":"ˈedʒukeɪt","defs":[["vt.","教育，培养，训练",false]],"tier":"l","hint":"教育。联想 education 教育、educator 教育者","ex":"Teachers educate children at school.（老师在学校教育孩子。）"},{"id":144,"day":3,"w":"factory","ph":"ˈfæktri","defs":[["n.","工厂，制造厂",false]],"tier":"l","hint":"工厂。联想 make 制造的地方就是 factory","ex":"He works in a car factory.（他在一家汽车厂工作。）"},{"id":145,"day":3,"w":"faith","ph":"feɪθ","defs":[["n.","信任，信用；信念，信心；信仰",false]],"tier":"l","hint":"信念、信任。词组 have faith in 相信","ex":"We have faith in the future.（我们对未来有信心。）"},{"id":146,"day":3,"w":"family","ph":"ˈfæməli","defs":[["n.","家，家庭；氏族，家族；系，族，属",false]],"tier":"l","hint":"家庭。联想 family member 家庭成员","ex":"There are four people in my family.（我家有四口人。）"},{"id":147,"day":3,"w":"far","ph":"fɑːr","defs":[["a.","/ad.远，遥远，久远 ad.到……程度，……得多",false]],"tier":"s"},{"id":148,"day":3,"w":"farmer","ph":"ˈfɑːrmər","defs":[["n.","农夫，农场主",false]],"tier":"l","hint":"farm（农场）+ -er（人）→ 农民","ex":"The farmer is working in the field.（农民正在田里干活。）"},{"id":149,"day":3,"w":"gain","ph":"ɡeɪn","defs":[["vt.","获得，赢得 vi.增加，增进；（钟表）走快 n.赢利；(pl.)收益，利润；增加，增进，获利",false]],"tier":"l","hint":"获得、增加。词组 gain experience 获得经验","ex":"You will gain experience from this job.（你会从这份工作中获得经验。）"},{"id":150,"day":3,"w":"gather","ph":"ˈɡæðər","defs":[["vi.","聚集，集合；收集，采集；逐渐增加",false]],"tier":"l","hint":"聚集、收集。词组 gather together 聚集在一起","ex":"The students gathered in the playground.（学生们在操场集合。）"},{"id":151,"day":3,"w":"hang","ph":"hæŋ","defs":[["vt.","吊，悬挂；吊死，绞死 vi.悬挂，吊着",false]],"tier":"l","hint":"悬挂、吊。注意过去式 hung（挂）/ hanged（绞死）","ex":"She hung the picture on the wall.（她把画挂在墙上。）"},{"id":152,"day":3,"w":"hard","ph":"hɑːrd","defs":[["a.","硬，坚硬；困难的，艰苦的；冷酷无情的 ad.努力地；猛烈地；严厉地",false]],"tier":"s"},{"id":153,"day":3,"w":"ice","ph":"aɪs","defs":[["n.","冰；冷饮",false]],"tier":"l","hint":"冰。联想 ice cream 冰淇淋、icy 冰冷的","ex":"The lake is covered with ice in winter.（冬天湖面结冰。）"},{"id":154,"day":3,"w":"idea","ph":"aɪˈdɪːə","defs":[["n.","想法，念头；概念，观念；意见，主意",false]],"tier":"l","hint":"想法。词组 have no idea 不知道、good idea 好主意","ex":"I have a good idea.（我有个好主意。）"},{"id":155,"day":3,"w":"ignore","ph":"ɪɡˈnɔːr","defs":[["vt.","不理，不顾，忽视",false]],"tier":"l","hint":"忽视、不理。联想 i-（不）+ gnore（知道）→ 装作不知道 → 忽视","ex":"Don't ignore the small problems.（不要忽视这些小问题。）"},{"id":156,"day":3,"w":"ill","ph":"ɪl","defs":[["a.","有病的；坏的，恶意的 ad.坏，不利",false]],"tier":"l","hint":"生病的。联想 illness 疾病（名词）","ex":"She is ill in bed today.（她今天卧病在床。）"},{"id":157,"day":3,"w":"illness","ph":"ˈɪlnəs","defs":[["n.","病，疾病",false]],"tier":"l","hint":"ill（病）+ -ness → 疾病","ex":"He missed school because of illness.（他因病缺课。）"},{"id":158,"day":3,"w":"imagination","ph":"ɪˌmædʒɪˈneɪʃn","defs":[["n.","想象，想象力；空想，幻想",false]],"tier":"l","hint":"imagine（想象）+ -ation → 想象力","ex":"Children have rich imagination.（孩子们有丰富的想象力。）"},{"id":159,"day":3,"w":"jewel(l)ery","ph":"ˈdʒuːəlri","defs":[["n.","[总称]珠宝；珠宝饰物",false]],"tier":"l","hint":"jewel（宝石）+ -ery（总称）→ 珠宝（总称）","ex":"She keeps her jewellery in a box.（她把珠宝放在盒子里。）"},{"id":160,"day":3,"w":"kick","ph":"kɪk","defs":[["n.","/vi./vt.踢",false]],"tier":"l","hint":"踢。词组 kick off 开球、kick out 赶出","ex":"He kicked the ball into the goal.（他把球踢进了球门。）"},{"id":161,"day":3,"w":"king","ph":"kɪŋ","defs":[["n.","国王",false]],"tier":"l","hint":"国王。联想 queen 王后、kingdom 王国","ex":"The king ruled the country for many years.（这位国王统治国家多年。）"},{"id":162,"day":3,"w":"laughter","ph":"læftər","defs":[["n.","笑，笑声",false]],"tier":"l","hint":"laugh（笑）+ -ter → 笑声","ex":"The room was filled with laughter.（房间里充满了笑声。）"},{"id":163,"day":3,"w":"mad","ph":"mæd","defs":[["a.","疯的，神经错乱的；恼火的，狂怒的；狂热的， 着迷的",false]],"tier":"l","hint":"疯的、狂怒的。词组 be mad at 生…的气、go mad 发疯","ex":"He was mad at me for being late.（他因我迟到而生我的气。）"},{"id":164,"day":3,"w":"nail","ph":"neɪl","defs":[["n.","钉；指甲，爪 vt.钉，使牢固",false]],"tier":"l","hint":"指甲、钉子。一词多义：finger nail 指甲、nail 钉子","ex":"She painted her nails red.（她把指甲涂成了红色。）"},{"id":165,"day":3,"w":"narrow","ph":"ˈnæroʊ","defs":[["a.","狭的，狭窄的；狭隘的",false]],"tier":"l","hint":"狭窄的。联想 wide 宽的（反义）","ex":"The road is too narrow for two cars.（这条路太窄，两辆车过不去。）"},{"id":166,"day":3,"w":"nature","ph":"ˈneɪtʃər","defs":[["n.","自然，自然界，性质，本性，天性",false]],"tier":"l","hint":"自然、本性。词组 in nature 本质上、by nature 天生","ex":"We should protect nature.（我们应该保护自然。）"},{"id":167,"day":3,"w":"offence/-se","ph":"əˈfens","defs":[["n.","犯罪，犯规，过错；冒犯，触怒",false]],"tier":"l","hint":"offend（冒犯）的名词 → 冒犯、犯规","ex":"He apologized for his offence.（他为自己的冒犯道了歉。）"},{"id":168,"day":3,"w":"pack","ph":"pæk","defs":[["vt.","包装，打包；塞满，挤满 n.（一）包，（一）群，（一）幅",false]],"tier":"l","hint":"打包、包裹。词组 pack up 收拾行李","ex":"She packed her clothes into a bag.（她把衣服装进包里。）"},{"id":169,"day":3,"w":"page","ph":"peɪdʒ","defs":[["n.","页",false]],"tier":"l","hint":"页。联想 turn the page 翻页","ex":"Please turn to page ten.（请翻到第十页。）"},{"id":170,"day":3,"w":"pale","ph":"peɪl","defs":[["a.","苍白的；浅的，淡的",false]],"tier":"l","hint":"苍白的、浅的。联想 pale face 苍白的脸","ex":"Her face turned pale with fear.（她吓得脸色发白。）"},{"id":171,"day":3,"w":"parallel","ph":"ˈpærəlel","defs":[["a.","与……平行的；并列的；类似的 n.平行线；纬线；可相比拟的事物；相似处",false]],"tier":"l","hint":"para-（旁）+ llel → 并排 → 平行的。词组 parallel to 与…平行","ex":"The road runs parallel to the river.（这条路与河平行。）"},{"id":172,"day":3,"w":"parent","ph":"ˈperənt","defs":[["n.","父母",false]],"tier":"l","hint":"父母（单数指父或母）。联想 father 父 + mother 母","ex":"My parents are both teachers.（我父母都是老师。）"},{"id":173,"day":3,"w":"radio","ph":"ˈreɪdioʊ","defs":[["n.","无线电，收音机，无线电通信",false]],"tier":"l","hint":"收音机。词组 listen to the radio 听广播","ex":"He listens to the radio every morning.（他每天早晨听广播。）"},{"id":174,"day":3,"w":"rain","ph":"reɪn","defs":[["n.","雨 vi.下雨",false]],"tier":"l","hint":"雨、下雨。联想 rainy 多雨的","ex":"It is going to rain soon.（马上要下雨了。）"},{"id":175,"day":3,"w":"rare","ph":"rer","defs":[["a.","稀有的，难得的，珍奇的；稀薄的，稀疏的",false]],"tier":"l","hint":"稀有的。联想 rarely 很少地（副词）","ex":"This kind of bird is rare now.（这种鸟现在很稀有。）"},{"id":176,"day":3,"w":"safe","ph":"seɪf","defs":[["a.","安全的，牢靠的 n.保险箱",false]],"tier":"l","hint":"安全的。联想 safety 安全（名词）、save 救（动词）","ex":"The children are safe at home.（孩子们在家很安全。）"},{"id":177,"day":3,"w":"sale","ph":"seɪl","defs":[["n.","出卖，出售；贱卖，大减价；销数，销售",false]],"tier":"l","hint":"出售、销售。词组 on sale 在售/打折、for sale 待售","ex":"The house is for sale.（这栋房子待售。）"},{"id":178,"day":3,"w":"sandwich","ph":"ˈsænwɪtʃ","defs":[["n.","三明治，夹肉面包",false]],"tier":"l","hint":"三明治。音译词，联想\"三明治\"","ex":"I had a sandwich for lunch.（我午饭吃了个三明治。）"},{"id":179,"day":3,"w":"tail","ph":"teɪl","defs":[["n.","尾巴；尾部，后部",false]],"tier":"l","hint":"尾巴。联想 head 头（相对）、tail 尾","ex":"The dog is wagging its tail.（狗在摇尾巴。）"},{"id":180,"day":3,"w":"take","ph":"teɪk","defs":[["vt.","拿，取，握；拿走，带去；需要，花费；接收， 获得；认为，当作",false]],"tier":"l","hint":"拿、花费、带走。词组 take off 起飞、take care 小心","ex":"It takes two hours to get there.（到那里要花两小时。）"},{"id":181,"day":3,"w":"teach","ph":"tiːtʃ","defs":[["vt.","教，教书；教训",false]],"tier":"l","hint":"教。联想 teacher 教师、teach oneself 自学","ex":"She teaches English at a middle school.（她在中学教英语。）"},{"id":182,"day":3,"w":"team","ph":"tiːm","defs":[["n.","小队，小组",false]],"tier":"l","hint":"队、组。词组 team work 团队合作","ex":"Our team won the game.（我们队赢了比赛。）"},{"id":183,"day":3,"w":"technology","ph":"tekˈnɑːlədʒi","defs":[["n.","工业技术，应用科学",false]],"tier":"l","hint":"techno（技术）+ -logy（学）→ 科技。联想 -logy 学科后缀","ex":"Technology has changed our lives.（科技改变了我们的生活。）"},{"id":184,"day":3,"w":"under","ph":"ˈʌndər","defs":[["prep.","在……下面；少于，低于；在……指导下；在…… 情况下；在……中",false]],"tier":"s"},{"id":185,"day":3,"w":"waiter","ph":"ˈweɪtər","defs":[["n.","（男）侍者，（男）服务员",false]],"tier":"l","hint":"wait（服务）+ -er（人）→ 服务员（男）。联想 waitress 女服务员","ex":"The waiter brought us the menu.（服务员给我们拿来了菜单。）"},{"id":186,"day":4,"w":"ability","ph":"əˈbɪləti","defs":[["n.","能力，才能",true]],"tier":"f","ety":"able（能干的）+ -ity（名词）→ 能力","mem":"able + ity → \"能\"（able）的名词 → 能力","ex":"have the ability to · She has the ability to solve the problem.（她有能力解决这个问题。）","nua":"ability（能力，天生或习得）、capability（潜在能力）；have the ability to do"},{"id":187,"day":4,"w":"band","ph":"bænd","defs":[["n.","条，带；乐队，军乐队；一群，一伙；波段",false]],"tier":"l","hint":"一词多义：乐队、带子。联想 music band 乐队","ex":"The band is playing a popular song.（乐队正在演奏一首流行歌曲。）"},{"id":188,"day":4,"w":"bath","ph":"bæθ","defs":[["n.","洗澡，沐浴；浴缸，浴盆，浴池",false]],"tier":"l","hint":"洗澡。词组 take a bath 洗澡","ex":"He takes a bath every evening.（他每晚洗澡。）"},{"id":189,"day":4,"w":"beam","ph":"biːm","defs":[["n.","/v. 一束；横梁；发光",true]],"tier":"f","ety":"古英语 bēam（树、梁），后指\"光柱\"","mem":"谐音\"必木\"→ 一根\"木\"（beam 是横梁），又像一束光。画面：阳光像横梁一样照进来","ex":"a beam of light · A beam of light shone through the window.（一束光透过窗户照进来。）","nua":"beam（一束光、横梁、微笑发光）、bean（豆子）别混淆"},{"id":190,"day":4,"w":"call","ph":"kɔːl","defs":[["vt.","叫做，称为；叫，招呼；打电话 vi.拜访，访问；叫，招呼；打电话 n.叫，招呼；号召；拜访，访问；打电话",false]],"tier":"l","hint":"叫、打电话。词组 call up 打电话、call for 需要","ex":"Please call me tomorrow.（请明天给我打电话。）"},{"id":191,"day":4,"w":"can","ph":"kən","defs":[["aux.","v.能，会；可能；可以 n.罐头，铁罐，易拉罐",false]],"tier":"s"},{"id":192,"day":4,"w":"capital","ph":"ˈkæpɪtl","defs":[["n.","首都；资本，资金 a.主要的，基本的",false]],"tier":"l","hint":"一词多义：首都、资本。联想 capital letter 大写字母","ex":"Beijing is the capital of China.（北京是中国的首都。）"},{"id":193,"day":4,"w":"car","ph":"kɑːr","defs":[["n.","汽车，车辆，车",false]],"tier":"l","hint":"汽车。联想 drive a car 开车、park a car 停车","ex":"He drives his car to work every day.（他每天开车上班。）"},{"id":194,"day":4,"w":"dark","ph":"dɑːrk","defs":[["a.","暗，黑暗；深色，黑色 n.黑暗，暗处",false]],"tier":"l","hint":"黑暗的。联想 light 光（反义）、in the dark 在黑暗中","ex":"It gets dark early in winter.（冬天天黑得早。）"},{"id":195,"day":4,"w":"day","ph":"deɪ","defs":[["n.","白昼，白天；（一）天",false]],"tier":"l","hint":"天、白天。词组 day by day 一天天、one day 有一天","ex":"I go to school every day.（我每天上学。）"},{"id":196,"day":4,"w":"dead","ph":"ded","defs":[["a.","死的；无感觉的",false]],"tier":"l","hint":"死的。联想 die 死（动词）、death 死亡（名词）","ex":"The plant is dead because of no water.（这株植物因缺水死了。）"},{"id":197,"day":4,"w":"earn","ph":"ɜːrn","defs":[["vt.","赚得，赢得，获得",false]],"tier":"l","hint":"赚得。词组 earn money 赚钱、earn a living 谋生","ex":"He earns a lot of money every month.（他每月赚很多钱。）"},{"id":198,"day":4,"w":"east","ph":"iːst","defs":[["n.","/a.东方（的），东部（的） ad.向/自/在东方",false]],"tier":"l","hint":"东。联想 east 东、west 西、south 南、north 北","ex":"The sun rises in the east.（太阳从东方升起。）"},{"id":199,"day":4,"w":"fair","ph":"fer","defs":[["a.","公平的，合理的；相当的，尚好的；晴朗的；美丽 的，金发的 n.定期集市，交易会，博览会",false]],"tier":"l","hint":"公平的、晴朗的。词组 be fair to 对…公平","ex":"It's not fair to blame him.（责怪他是不公平的。）"},{"id":200,"day":4,"w":"false","ph":"fɔːls","defs":[["a.","假的；假造的，人造的；虚伪的",false]],"tier":"l","hint":"假的。联想 true 真的（反义）、false 假的","ex":"The answer is false.（这个答案是错的。）"},{"id":201,"day":4,"w":"game","ph":"ɡeɪm","defs":[["n.","游戏，玩耍；比赛；(pl.)运动会；猎物，野味",false]],"tier":"l","hint":"游戏、比赛。词组 play a game 玩游戏、Olympic Games 奥运会","ex":"The children are playing a game.（孩子们在玩游戏。）"},{"id":202,"day":4,"w":"gas","ph":"ɡæs","defs":[["n.","气体；煤气；汽油",false]],"tier":"l","hint":"气体、煤气、汽油。联想 gas station 加油站","ex":"The car is out of gas.（车没油了。）"},{"id":203,"day":4,"w":"gate","ph":"ɡeɪt","defs":[["n.","大门，城门",false]],"tier":"l","hint":"大门。联想 door 门（小）、gate 大门（大）","ex":"The school gate opens at seven.（校门七点开。）"},{"id":204,"day":4,"w":"habit","ph":"ˈhæbɪt","defs":[["n.","习惯，习性，脾性",false]],"tier":"l","hint":"习惯。词组 get into the habit of 养成…习惯","ex":"Reading is a good habit.（阅读是好习惯。）"},{"id":205,"day":4,"w":"hammer","ph":"ˈhæmər","defs":[["n.","锤，榔头 vi./vt.锤击，敲打",false]],"tier":"l","hint":"锤子。联想 nail 钉子（和 hammer 一起用）","ex":"He used a hammer to fix the chair.（他用锤子修椅子。）"},{"id":206,"day":4,"w":"hand","ph":"hænd","defs":[["n.","手；人手，职工，雇员；指针 vt.交出，传递",false]],"tier":"l","hint":"手。词组 give sb a hand 帮某人、hand in 上交","ex":"Please hand in your homework.（请上交你的作业。）"},{"id":207,"day":4,"w":"handle","ph":"ˈhændl","defs":[["n.","手柄，把手，拉手 vt.触，摸，抚弄；操纵；处理，应付",false]],"tier":"l","hint":"hand（手）+ -le → 用手拿 → 把手、处理","ex":"He can handle the problem by himself.（他能独自处理这个问题。）"},{"id":208,"day":4,"w":"happen","ph":"ˈhæpən","defs":[["vi.","发生；碰巧",false]],"tier":"l","hint":"发生。词组 happen to 碰巧、what happened 发生了什么","ex":"The accident happened last night.（事故昨晚发生了。）"},{"id":209,"day":4,"w":"image","ph":"ˈɪmɪdʒ","defs":[["n.","像，肖像，形象；影像，图像",false]],"tier":"l","hint":"形象、图像。联想 imagine 想象（同源）","ex":"The company cares about its public image.（这家公司注重公众形象。）"},{"id":210,"day":4,"w":"jacket","ph":"ˈdʒækɪt","defs":[["n.","短上衣，夹克衫",false]],"tier":"l","hint":"夹克衫。音译词，联想\"夹克\"","ex":"He wore a warm jacket in winter.（冬天他穿暖和的夹克。）"},{"id":211,"day":4,"w":"jewel","ph":"ˈdʒuːəl","defs":[["n.","宝石；宝石饰物",false]],"tier":"l","hint":"宝石。联想 jewelry 珠宝（总称）","ex":"The ring has a beautiful jewel on it.（戒指上有一颗美丽的宝石。）"},{"id":212,"day":4,"w":"kind","ph":"kaɪnd","defs":[["n.","种类 a.仁慈的，和善的，亲切的",false]],"tier":"l","hint":"一词多义：种类、仁慈的。词组 all kinds of 各种各样的","ex":"She is very kind to everyone.（她对每个人都很友善。）"},{"id":213,"day":4,"w":"large","ph":"lɑːrdʒ","defs":[["a.","大的，广大的；大规模的，众多的",false]],"tier":"s"},{"id":214,"day":4,"w":"last","ph":"læst","defs":[["a.","最后的；最近的，紧接前面的 ad.最后，最近 vi.持续，持久",false]],"tier":"s"},{"id":215,"day":4,"w":"machine","ph":"məˈʃiːn","defs":[["n.","机器，机械",false]],"tier":"l","hint":"机器。联想 machinery 机械（总称）","ex":"The machine is out of order.（这台机器出故障了。）"},{"id":216,"day":4,"w":"machinery","ph":"məˈʃiːnəri","defs":[["n.","[总称]机械，机器",false]],"tier":"l","hint":"machine（机器）+ -ery（总称）→ 机械（总称）","ex":"The factory bought new machinery.（工厂买了新机械。）"},{"id":217,"day":4,"w":"magic","ph":"ˈmædʒɪk","defs":[["n.","戏法，魔术，魔法 a.魔术的，有魔力的",false]],"tier":"l","hint":"魔术。联想 magician 魔术师、magic show 魔术表演","ex":"The children watched the magic show happily.（孩子们开心地看魔术表演。）"},{"id":218,"day":4,"w":"make","ph":"meɪk","defs":[["vt.","做，制造，建造；使，迫使；(使)成为，（使)变成； 整理，准备；获得，挣（钱）；总计，等于",false]],"tier":"l","hint":"做、使。词组 make up 组成、make sure 确保","ex":"She makes breakfast for the family.（她为家人做早饭。）"},{"id":219,"day":4,"w":"manage","ph":"ˈmænɪdʒ","defs":[["vt.","管理，经营，处理；设法，对付",false]],"tier":"l","hint":"管理、设法。词组 manage to do 设法做成","ex":"He managed to finish the work on time.（他设法按时完成了工作。）"},{"id":220,"day":4,"w":"national","ph":"ˈnæʃnəl","defs":[["a.","国家的；国立的；民族的",false]],"tier":"l","hint":"nation（国家）+ -al → 国家的。词组 National Day 国庆节","ex":"The national flag is red.（国旗是红色的。）"},{"id":221,"day":4,"w":"off","ph":"ɔːf","defs":[["ad.","离，距；切断，停止，中止；完，光；减掉，扣 掉，消除 prep.从……离开，离……，偏离",false]],"tier":"s"},{"id":222,"day":4,"w":"offensive","ph":"əˈfensɪv","defs":[["a.","讨厌的；无礼的；攻击性的 n.进攻；攻势",false]],"tier":"l","hint":"offend（冒犯）+ -ive → 冒犯的、攻击性的","ex":"His words were very offensive.（他的话很有攻击性。）"},{"id":223,"day":4,"w":"painful","ph":"ˈpeɪnfl","defs":[["a.","痛苦的，疼痛的；困难的，令人不快的",false]],"tier":"l","hint":"pain（疼痛）+ -ful → 疼痛的","ex":"The cut on my finger is painful.（我手指上的伤口很疼。）"},{"id":224,"day":4,"w":"pan","ph":"pæn","defs":[["n.","平底锅",false]],"tier":"l","hint":"平底锅。联想 fry 煎（用 pan）","ex":"She fried the eggs in a pan.（她在平底锅里煎鸡蛋。）"},{"id":225,"day":4,"w":"paper","ph":"ˈpeɪpər","defs":[["n.","纸；报纸；(pl.)文件；论文，文章；试卷",false]],"tier":"l","hint":"纸、报纸、论文。一词多义","ex":"Please write your name on the paper.（请在纸上写下你的名字。）"},{"id":226,"day":4,"w":"park","ph":"pɑːrk","defs":[["n.","公园，停车场 vi./vt.停放（汽车等）",false]],"tier":"l","hint":"一词多义：公园、停车。词组 park the car 停车","ex":"We had a walk in the park.（我们在公园散步。）"},{"id":227,"day":4,"w":"quality","ph":"ˈkwɑːləti","defs":[["n.","质，质量；品质，特性",false]],"tier":"l","hint":"质量。联想 quantity 数量（对比记忆）","ex":"The quality of the product is good.（这个产品质量好。）"},{"id":228,"day":4,"w":"quantity","ph":"ˈkwɑːnəti","defs":[["n.","量，数量；大量",false]],"tier":"l","hint":"数量。联想 quality 质量（对比记忆）","ex":"We need a large quantity of water.（我们需要大量的水。）"},{"id":229,"day":4,"w":"rabbit","ph":"ˈræbɪt","defs":[["n.","兔子",false]],"tier":"l","hint":"兔子。联想 hare 野兔","ex":"The rabbit is eating a carrot.（兔子在吃胡萝卜。）"},{"id":230,"day":4,"w":"race","ph":"reɪs","defs":[["n.","种族，人种；竞赛，赛跑 vt.使全速行进；和……竞赛（比赛） vi.疾走；竞走；参加竞赛",false]],"tier":"l","hint":"一词多义：竞赛、种族。词组 race against 与…赛跑","ex":"He won the 100-meter race.（他赢了百米赛跑。）"},{"id":231,"day":4,"w":"rank","ph":"ræŋk","defs":[["n.","排，行列；等级，地位 vt.评价，分等，归类",false]],"tier":"l","hint":"等级、行列。词组 in the ranks of 在…行列中","ex":"He holds a high rank in the army.（他在军队里军衔很高。）"},{"id":232,"day":4,"w":"rapid","ph":"ˈræpɪd","defs":[["a.","快的，急速的",false]],"tier":"l","hint":"迅速的。联想 fast 快的（同义）、rapidly 迅速地","ex":"The city has seen rapid growth.（这座城市发展迅速。）"},{"id":233,"day":4,"w":"sad","ph":"sæd","defs":[["a.","忧愁的，悲哀的",false]],"tier":"l","hint":"悲伤的。联想 happy 快乐（反义）、sadness 悲伤","ex":"She felt sad when her friend left.（朋友离开时她很难过。）"},{"id":234,"day":4,"w":"safety","ph":"ˈseɪfti","defs":[["n.","安全",false]],"tier":"l","hint":"safe（安全）+ -ty → 安全。词组 safety first 安全第一","ex":"Wear a helmet for your safety.（为了安全请戴头盔。）"},{"id":235,"day":4,"w":"sail","ph":"seɪl","defs":[["n.","帆，航行 vi.航行，开航",false]],"tier":"l","hint":"航行、帆。联想 sailor 水手、sail a boat 开船","ex":"The ship sailed across the sea.（船驶过了大海。）"},{"id":236,"day":4,"w":"salt","ph":"sɔːlt","defs":[["n.","盐，盐类 vt.盐渍，腌",false]],"tier":"l","hint":"盐。联想 salty 咸的、salt water 盐水","ex":"Please pass me the salt.（请把盐递给我。）"},{"id":237,"day":4,"w":"satisfactory","ph":"ˌsætɪsˈfæktəri","defs":[["a.","令人满意的",false]],"tier":"l","hint":"satisfy（满足）+ -ory → 令人满意的","ex":"The result is satisfactory to everyone.（这个结果令大家都满意。）"},{"id":238,"day":4,"w":"tall","ph":"tɔːl","defs":[["a.","高的，身材高的",false]],"tier":"l","hint":"高的。联想 high 高的（山）、tall 高的（人/物）","ex":"He is taller than his brother.（他比他哥哥高。）"},{"id":239,"day":4,"w":"tax","ph":"tæks","defs":[["vt.","征税n.税（款）",false]],"tier":"l","hint":"税。联想 tax payer 纳税人","ex":"Everyone should pay tax.（每个人都应该纳税。）"},{"id":240,"day":4,"w":"ugly","ph":"ˈʌɡli","defs":[["a.","丑的，丑陋的；讨厌的，邪恶的",false]],"tier":"l","hint":"丑的。联想 beautiful 美的（反义）","ex":"The ugly duckling became a swan.（丑小鸭变成了天鹅。）"},{"id":241,"day":4,"w":"unexpected","ph":"ˌʌnɪkˈspektɪd","defs":[["a.","想不到的，意外的",false]],"tier":"l","hint":"un-（不）+ expected（预期的）→ 意外的","ex":"We had an unexpected visitor last night.（昨晚来了位不速之客。）"},{"id":242,"day":4,"w":"unit","ph":"ˈjuːnɪt","defs":[["n.","单位，部队；单元，部件，元件；（作为计量标准 的）单位",false]],"tier":"l","hint":"单位、单元。联想 unit 1 第一单元","ex":"The book has ten units.（这本书有十个单元。）"},{"id":243,"day":4,"w":"valley","ph":"ˈvæli","defs":[["n.","谷，山谷",false]],"tier":"l","hint":"山谷。联想 mountain 山、valley 山谷","ex":"The village lies in a valley.（这个村庄坐落在山谷里。）"},{"id":244,"day":4,"w":"waist","ph":"weɪst","defs":[["n.","腰，腰部",true]],"tier":"f","ety":"古英语 wæst（腰）","mem":"同音辨析：waist（腰，中间有 i 像腰带）vs waste（浪费，e 像扔掉的垃圾）。画面：腰带系在\"腰\"上","ex":"around the waist · The belt is around her waist.（腰带系在她的腰上。）","nua":"waist（腰）、waste（浪费）；同音不同义是听力/拼写考点"},{"id":245,"day":4,"w":"wait","ph":"weɪt","defs":[["vi.","/vt.等候；伺候 n.等候，等待时间",false]],"tier":"l","hint":"等待。词组 wait for 等待、wait a moment 等一下","ex":"Please wait for me at the gate.（请在门口等我。）"},{"id":246,"day":4,"w":"walk","ph":"wɔːk","defs":[["vi.","步行，散步 n.步行，散步；人行道，散步场所",false]],"tier":"l","hint":"步行。词组 go for a walk 散步、walk to 步行去","ex":"I walk to school every day.（我每天步行上学。）"},{"id":247,"day":4,"w":"want","ph":"wɑːnt","defs":[["vt.","想要；需要；缺乏，缺少；通缉 n.必需品；缺乏，需要",false]],"tier":"l","hint":"想要。词组 want to do 想要做","ex":"I want to learn English well.（我想学好英语。）"},{"id":248,"day":4,"w":"warm","ph":"wɔːrm","defs":[["a.","暖的，温暖的；热忱的，热心的 vi./vt.（使）暖和",false]],"tier":"s"},{"id":249,"day":5,"w":"activity","ph":"ækˈtɪvəti","defs":[["n.","活动，活跃",true]],"tier":"f","ety":"act（做）+ -ivity（名词）→ 做的事 → 活动","mem":"act + ivity → \"做\"（act）出来的事 → 活动。联想 active（活跃的）","ex":"outdoor activity · Hiking is a popular outdoor activity.（徒步是流行的户外活动。）","nua":"activity（活动，可数）、action（行动，不可数多）"},{"id":250,"day":5,"w":"appearance","ph":"əˈpɪrəns","defs":[["n.","出现，出场，露面；外表，外观",false]],"tier":"l","hint":"appear（出现）+ -ance → 出现、外表","ex":"She cares a lot about her appearance.（她很在意自己的外表。）"},{"id":251,"day":5,"w":"bear","ph":"ber","defs":[["n.","熊 vt.忍受，容忍；负荷，负担",false]],"tier":"l","hint":"一词多义：熊、忍受。词组 bear with 忍受","ex":"I can't bear the noise any more.（我再也无法忍受这噪音了。）"},{"id":252,"day":5,"w":"cheek","ph":"tʃiːk","defs":[["n.","面颊",false]],"tier":"l","hint":"面颊。联想 face 脸、cheek 脸颊","ex":"The little girl has red cheeks.（小女孩脸颊红扑扑的。）"},{"id":253,"day":5,"w":"chin","ph":"tʃɪn","defs":[["n.","下巴",false]],"tier":"l","hint":"下巴。联想 jaw 下巴（颌）、chin 下巴（尖端）","ex":"He rested his chin on his hand.（他用手托着下巴。）"},{"id":254,"day":5,"w":"cloth","ph":"klɔːθ","defs":[["n.","布，织物，衣料；（一块）布",false]],"tier":"l","hint":"布。联想 clothes 衣服（用 cloth 做的）","ex":"She wiped the table with a cloth.（她用布擦桌子。）"},{"id":255,"day":5,"w":"cold","ph":"koʊld","defs":[["a.","冷的，寒冷的；冷淡的 n.寒冷；感冒",false]],"tier":"s"},{"id":256,"day":5,"w":"communicate","ph":"kəˈmjuːnɪkeɪt","defs":[["vt.","传达，交流，通信 vi.传达，传播",false]],"tier":"l","hint":"com-（共同）+ mun（分享）+ -icate → 交流。词组 communicate with 与…交流","ex":"We communicate with each other by email.（我们通过邮件交流。）"},{"id":257,"day":5,"w":"complicated","ph":"ˈkɑːmplɪkeɪtɪd","defs":[["a.","错综复杂的，难懂的",true]],"tier":"f","ety":"com-（一起）+ plic（折叠）+ -ated → 折在一起 → 复杂","mem":"com + plic（折叠）→ 一张纸\"折\"来折去 → 复杂。画面：纸折成一团理不清","ex":"a complicated problem · It's a complicated problem to solve.（这是个复杂难解的问题。）","nua":"complicated（复杂难懂）、complex（复杂，侧重结构）；反义 simple"},{"id":258,"day":5,"w":"decoration","ph":"ˌdekəˈreɪʃn","defs":[["n.","装饰，装潢",false]],"tier":"l","hint":"decorate（装饰）+ -ion → 装饰","ex":"The room is full of beautiful decorations.（房间里满是漂亮的装饰。）"},{"id":259,"day":5,"w":"email/e-mail","ph":"ˈiːmeɪl","defs":[["n.","电子邮件",false]],"tier":"l","hint":"e（电子）+ mail（邮件）→ 电子邮件。词组 send an email 发邮件","ex":"Please send me an email with the details.（请把详情发邮件给我。）"},{"id":260,"day":5,"w":"everywhere","ph":"ˈevriwer","defs":[["ad.","到处，处处",false]],"tier":"l","hint":"every（每个）+ where（地方）→ 到处","ex":"I looked for my keys everywhere.（我到处找钥匙。）"},{"id":261,"day":5,"w":"existence","ph":"ɪɡˈzɪstəns","defs":[["n.","存在，生存",false]],"tier":"l","hint":"exist（存在）+ -ence → 存在。词组 in existence 存在的","ex":"Do you believe in the existence of life on other planets?（你相信其他行星存在生命吗？）"},{"id":262,"day":5,"w":"feature","ph":"ˈfiːtʃər","defs":[["n.","面貌，容貌；特征，特色；特写",false]],"tier":"l","hint":"特征、特色。联想 a main feature 主要特征","ex":"The new phone has many useful features.（这款新手机有很多实用功能。）"},{"id":263,"day":5,"w":"fold","ph":"foʊld","defs":[["vi.","/vt.折叠，合拢 n.褶，褶痕",false]],"tier":"l","hint":"折叠。词组 fold up 折起","ex":"She folded the letter and put it away.（她把信折起来收好。）"},{"id":264,"day":5,"w":"follow","ph":"ˈfɑːloʊ","defs":[["vt.","跟随，追随，追求；顺……走；听从，遵循；理 解，听清楚，听懂",false]],"tier":"l","hint":"跟随、遵循。词组 follow the rules 遵守规则","ex":"Please follow the rules of the school.（请遵守学校规定。）"},{"id":265,"day":5,"w":"foreign","ph":"ˈfɔːrən","defs":[["a.","外国的，对外的；外国产的，外国来的",false]],"tier":"l","hint":"外国的。词组 foreign language 外语、foreigner 外国人","ex":"She is learning a foreign language.（她在学一门外语。）"},{"id":266,"day":5,"w":"formal","ph":"ˈfɔːrml","defs":[["a.","正式的；礼仪上的；形式的",false]],"tier":"l","hint":"正式的。联想 informal 非正式的（反义）","ex":"You should wear formal clothes to the meeting.（开会应穿正装。）"},{"id":267,"day":5,"w":"fur","ph":"fɜːr","defs":[["n.","软毛；毛皮，裘皮，皮衣",false]],"tier":"l","hint":"毛皮。联想 furry 毛茸茸的","ex":"The coat is made of fur.（这件大衣是毛皮做的。）"},{"id":268,"day":5,"w":"hunt","ph":"hʌnt","defs":[["vi.","/vt./n.打猎，狩猎；寻找，搜索",false]],"tier":"l","hint":"打猎、寻找。词组 hunt for 寻找","ex":"They are hunting for a new house.（他们在找新房子。）"},{"id":269,"day":5,"w":"infect","ph":"ɪnˈfekt","defs":[["vt.","传染，感染",false]],"tier":"l","hint":"感染。联想 infection 感染（名词）、infectious 传染的","ex":"The wound may become infected.（伤口可能会感染。）"},{"id":270,"day":5,"w":"knot","ph":"nɑːt","defs":[["n.","结；节，海里/小时",false]],"tier":"l","hint":"结。联想 tie a knot 打结","ex":"He tied a knot in the rope.（他在绳子上打了个结。）"},{"id":271,"day":5,"w":"learn","ph":"lɜːrn","defs":[["vt.","学习，学会，记住；(of)听说，获悉",false]],"tier":"l","hint":"学习。词组 learn from 向…学习、learn to do 学做","ex":"We should learn from our mistakes.（我们应该从错误中学习。）"},{"id":272,"day":5,"w":"light","ph":"laɪt","defs":[["n.","光，光亮，光线；灯，灯光 vt.点，点燃；照亮，照耀 a.轻的；轻捷的，轻快的；淡（色）；明亮的",false]],"tier":"l","hint":"光、灯、轻的。一词多义：turn on the light 开灯","ex":"Please turn off the light before you leave.（离开前请关灯。）"},{"id":273,"day":5,"w":"marriage","ph":"ˈmærɪdʒ","defs":[["n.","结婚，婚姻；结婚仪式",false]],"tier":"l","hint":"marry（结婚）+ -age → 婚姻","ex":"They have a happy marriage.（他们的婚姻很幸福。）"},{"id":274,"day":5,"w":"meat","ph":"miːt","defs":[["n.","肉，食用肉类",false]],"tier":"l","hint":"肉。联想 vegetable 蔬菜（相对）","ex":"We eat meat and vegetables every day.（我们每天吃肉和蔬菜。）"},{"id":275,"day":5,"w":"medical","ph":"ˈmedɪkl","defs":[["a.","医学的，医疗的；医药的；内科的",false]],"tier":"l","hint":"medicine（医学）+ -al → 医学的。词组 medical care 医疗","ex":"He needs medical treatment right away.（他需要立即治疗。）"},{"id":276,"day":5,"w":"meeting","ph":"ˈmiːtɪŋ","defs":[["n.","会议，集会",false]],"tier":"l","hint":"meet（见面）+ -ing → 会议。词组 hold a meeting 开会","ex":"The meeting will start at nine.（会议九点开始。）"},{"id":277,"day":5,"w":"mental","ph":"ˈmentl","defs":[["a.","思想的，精神的；智力的，脑力的",false]],"tier":"l","hint":"精神的、智力的。联想 physical 身体的（对比）","ex":"We should care about mental health.（我们应该关注心理健康。）"},{"id":278,"day":5,"w":"moon","ph":"muːn","defs":[["n.","月亮，月球，卫星",false]],"tier":"l","hint":"月亮。联想 sun 太阳、moon 月亮","ex":"The moon is bright tonight.（今晚月亮很亮。）"},{"id":279,"day":5,"w":"nerve","ph":"nɜːrv","defs":[["n.","神经；勇气，胆量",false]],"tier":"l","hint":"神经、勇气。词组 lose one's nerve 失去勇气","ex":"It takes nerve to speak in public.（当众发言需要勇气。）"},{"id":280,"day":5,"w":"note","ph":"noʊt","defs":[["n.","笔记，记录；便条；注意，注释，评论；钞票， 纸币",false]],"tier":"l","hint":"笔记、注意、钞票。词组 take notes 记笔记","ex":"Please take notes in class.（上课请记笔记。）"},{"id":281,"day":5,"w":"nothing","ph":"ˈnʌθɪŋ","defs":[["pron.","没有东西，什么也没有；无，小事 n.微不足道的人或事",false]],"tier":"l","hint":"没有东西。词组 nothing but 只有、for nothing 免费","ex":"There is nothing in the box.（盒子里什么也没有。）"},{"id":282,"day":5,"w":"offer","ph":"ˈɔːfər","defs":[["vt.","提出，提供；愿意做；奉献 n.提供，提议；报价，出价",false]],"tier":"l","hint":"提供。词组 offer to do 主动提出做","ex":"He offered to help me with my English.（他主动提出帮我学英语。）"},{"id":283,"day":5,"w":"original","ph":"əˈrɪdʒənl","defs":[["a.","最初的，原始的，原文的；新颖的，有独创性的",false]],"tier":"l","hint":"origin（起源）+ -al → 最初的、原创的","ex":"This is the original painting, not a copy.（这是原作，不是复制品。）"},{"id":284,"day":5,"w":"photo=photograph","ph":"","defs":[["v.","拍照    n.照片",false]],"tier":"l","hint":"照片（photograph 缩写）。词组 take a photo 拍照","ex":"Let's take a photo together.（我们一起拍张照吧。）"},{"id":285,"day":5,"w":"poetry","ph":"ˈpoʊətri","defs":[["n.","诗歌",false]],"tier":"l","hint":"poem（诗）的总称 → 诗歌","ex":"She likes reading poetry in her free time.（她空闲时喜欢读诗。）"},{"id":286,"day":5,"w":"powder","ph":"ˈpaʊdər","defs":[["n.","粉末，药粉；火药",false]],"tier":"l","hint":"粉末。联想 milk powder 奶粉","ex":"The medicine comes in powder form.（这种药是粉末状的。）"},{"id":287,"day":5,"w":"practical","ph":"ˈpræktɪkl","defs":[["a.","实际的，实用的",false]],"tier":"l","hint":"practice（实践）+ -al → 实用的","ex":"This is a practical way to save money.（这是省钱的实用方法。）"},{"id":288,"day":5,"w":"praise","ph":"preɪz","defs":[["vt.","称赞，表扬 n.称赞，赞美",false]],"tier":"l","hint":"表扬。词组 praise sb for 因…表扬某人","ex":"The teacher praised him for his hard work.（老师表扬他努力。）"},{"id":289,"day":5,"w":"pronounce","ph":"prəˈnaʊns","defs":[["vt.","发音",false]],"tier":"l","hint":"发音。联想 pronunciation 发音（名词）","ex":"How do you pronounce this word?（这个单词怎么发音？）"},{"id":290,"day":5,"w":"protest","ph":"ˈproʊtest","defs":[["vi.","/n.抗议，反对",false]],"tier":"l","hint":"抗议。词组 protest against 抗议","ex":"The workers protested against the new rule.（工人们抗议新规定。）"},{"id":291,"day":5,"w":"purpose","ph":"ˈpɜːrpəs","defs":[["n.","目的，意图；企图，打算",false]],"tier":"l","hint":"目的。词组 on purpose 故意、for the purpose of 为了…目的","ex":"What is the purpose of your visit?（你来访的目的是什么？）"},{"id":292,"day":5,"w":"refuse","ph":"rɪˈfjuːz","defs":[["vi.","/vt.拒绝，推辞",false]],"tier":"l","hint":"拒绝。词组 refuse to do 拒绝做","ex":"He refused to answer the question.（他拒绝回答这个问题。）"},{"id":293,"day":5,"w":"relax","ph":"rɪˈlæks","defs":[["vt.","使放松，使休息；缓和，放宽 vi.放松，休息；松弛，放松",false]],"tier":"l","hint":"放松。联想 relaxation 放松（名词）","ex":"Music helps me relax.（音乐帮我放松。）"},{"id":294,"day":5,"w":"remember","ph":"rɪˈmembər","defs":[["vt.","记住，记得；(to)转达问候 vi.记得，记住",false]],"tier":"l","hint":"记住。词组 remember to do 记得要做、remember doing 记得做过","ex":"Remember to close the door.（记得关门。）"},{"id":295,"day":5,"w":"represent","ph":"ˌreprɪˈzent","defs":[["vt.","代表；表示，阐明，说明；描写，表现，象征",false]],"tier":"l","hint":"代表。联想 representative 代表（名词）","ex":"The red rose represents love.（红玫瑰代表爱情。）"},{"id":296,"day":5,"w":"river","ph":"ˈrɪvər","defs":[["n.","江，河",false]],"tier":"l","hint":"河。联想 the Yangtze River 长江","ex":"The river runs through the city.（这条河流经城市。）"},{"id":297,"day":5,"w":"sensitive","ph":"ˈsensətɪv","defs":[["a.","敏感的；灵敏的",false]],"tier":"l","hint":"敏感的。词组 be sensitive to 对…敏感","ex":"She is sensitive to cold weather.（她对寒冷的天气很敏感。）"},{"id":298,"day":5,"w":"something","ph":"ˈsʌmθɪŋ","defs":[["n.","某物，某事",false]],"tier":"l","hint":"某事、某物。词组 something important 重要的事","ex":"There is something wrong with my bike.（我的自行车出问题了。）"},{"id":299,"day":5,"w":"soup","ph":"suːp","defs":[["n.","汤",false]],"tier":"l","hint":"汤。联想 spoon 勺子（喝汤用）","ex":"The soup is too hot to drink.（汤太烫了不能喝。）"},{"id":300,"day":5,"w":"speed","ph":"spiːd","defs":[["n.","速度，速率；快，迅速 vi.急行，飞驰 vt.使加速",false]],"tier":"l","hint":"速度。词组 at a high speed 高速、speed up 加速","ex":"The car was running at high speed.（汽车高速行驶。）"},{"id":301,"day":5,"w":"spin","ph":"spɪn","defs":[["n.","旋转，自转 vi./vt.旋转，自转；纺，纺纱；结网，吐丝",false]],"tier":"l","hint":"旋转。联想 the earth spins 地球自转","ex":"The wheel spins very fast.（轮子转得很快。）"},{"id":302,"day":5,"w":"stand","ph":"stænd","defs":[["vi.","站立；坐落，位于；经受，忍受 n.台，座；货摊；置物架；看台，观众席；立场， 看法",false]],"tier":"l","hint":"站立、忍受。词组 stand up 站起来、stand for 代表","ex":"Please stand up when the teacher comes in.（老师进来时请起立。）"},{"id":303,"day":5,"w":"strength","ph":"streŋθ","defs":[["n.","力，力量；实力，长处",false]],"tier":"l","hint":"strong（强壮）的名词 → 力量","ex":"Union is strength.（团结就是力量。）"},{"id":304,"day":5,"w":"suppose","ph":"səˈpoʊz","defs":[["vt.","猜想，料想；假定，以为",false]],"tier":"l","hint":"猜想、假定。词组 be supposed to 应该","ex":"I suppose he will come tomorrow.（我猜他明天会来。）"},{"id":305,"day":5,"w":"surprise","ph":"sərˈpraɪz","defs":[["n.","诧异，惊奇 vt.使诧异，使惊奇；突然袭击",false]],"tier":"l","hint":"惊奇。词组 to one's surprise 令某人惊讶的是","ex":"To my surprise, he passed the exam.（令我惊讶的是，他通过了考试。）"},{"id":306,"day":5,"w":"swear","ph":"swer","defs":[["vi.","宣誓，发誓；咒骂，骂人",false]],"tier":"l","hint":"发誓、咒骂。过去式 swore","ex":"He swore to tell the truth.（他发誓要说真话。）"},{"id":307,"day":5,"w":"sword","ph":"sɔːrd","defs":[["n.","刀，剑",true]],"tier":"f","ety":"古英语 sweord（剑）","mem":"sword 里 w 不发音，读作 sord；记 \"s + word（词）\"→ 一句话像一把\"剑\"。画面：唇枪舌剑","ex":"a double-edged sword · Technology is a double-edged sword.（科技是把双刃剑。）","nua":"sword 的 w 不发音（/sɔːrd/）；a double-edged sword 双刃剑（引申利弊并存）"},{"id":308,"day":5,"w":"tense","ph":"tens","defs":[["a.","拉紧的，绷紧的；紧张的",false]],"tier":"l","hint":"紧张的、拉紧的。联想 nervous 紧张的（同义）","ex":"She was tense before the exam.（考试前她很紧张。）"},{"id":309,"day":5,"w":"threaten","ph":"ˈθretn","defs":[["vt.","威胁，恫吓",false]],"tier":"l","hint":"threat（威胁）+ -en → 威胁。词组 threaten to do 威胁要做","ex":"The storm threatened the small village.（暴风雨威胁着这个小村庄。）"},{"id":310,"day":5,"w":"total","ph":"ˈtoʊtl","defs":[["n.","总数，合计 a.总的，完全的 vi.合计，总计",false]],"tier":"l","hint":"总的、总数。词组 in total 总共","ex":"The total cost is 1000 yuan.（总费用是一千元。）"},{"id":311,"day":5,"w":"useless","ph":"ˈjuːsləs","defs":[["a.","无用的，无价值的",false]],"tier":"l","hint":"use（用）+ -less（无）→ 无用的","ex":"The broken pen is useless now.（这支坏笔现在没用了。）"},{"id":312,"day":6,"w":"admire","ph":"ədˈmaɪər","defs":[["vt.","羡慕，赞赏，钦佩",true]],"tier":"f","ety":"ad-（向）+ mire（惊奇，同 miracle）→ 对…惊叹 → 钦佩","mem":"ad + mire（=miracle 奇迹）→ 看到\"奇迹\"心生惊叹 → 钦佩。画面：仰望大神","ex":"admire sb for · I admire her for her courage.（我钦佩她的勇气。）","nua":"admire sb for（因…钦佩）、admire 后不接从句；名词 admiration"},{"id":313,"day":6,"w":"afternoon","ph":"ˌæftərˈnuːn","defs":[["n.","下午，午后",false]],"tier":"l","hint":"after（后）+ noon（中午）→ 午后、下午","ex":"We have no class this afternoon.（我们今天下午没课。）"},{"id":314,"day":6,"w":"alcohol","ph":"ˈælkəhɔːl","defs":[["n.","酒精，乙醇 vt.使警觉",false]],"tier":"l","hint":"酒精。联想 alcoholic 含酒精的","ex":"He doesn't drink alcohol.（他不喝酒。）"},{"id":315,"day":6,"w":"almost","ph":"ˈɔːlmoʊst","defs":[["ad.","几乎，差不多",false]],"tier":"l","hint":"几乎。联想 nearly 几乎（同义）","ex":"It's almost ten o'clock.（快十点了。）"},{"id":316,"day":6,"w":"always","ph":"ˈɔːlweɪz","defs":[["ad.","总是，永远",false]],"tier":"s"},{"id":317,"day":6,"w":"angry","ph":"ˈæŋɡri","defs":[["a.","愤怒的，生气的",false]],"tier":"l","hint":"生气的。词组 be angry with sb 生某人的气","ex":"He was angry with me for being late.（他因我迟到而生我的气。）"},{"id":318,"day":6,"w":"average","ph":"ˈævərɪdʒ","defs":[["n.","平均，平均数 a.平均的；平常的，普通的",false]],"tier":"l","hint":"平均的、普通的。词组 on average 平均","ex":"On average, he reads one book a week.（他平均每周读一本书。）"},{"id":319,"day":6,"w":"beginning","ph":"bɪˈɡɪnɪŋ","defs":[["n.","开始，开端；起因",false]],"tier":"l","hint":"begin（开始）+ -ing → 开始。词组 at the beginning of 在…开始","ex":"At the beginning of the year, we made a plan.（年初我们做了计划。）"},{"id":320,"day":6,"w":"blue","ph":"bluː","defs":[["a.","蓝色的；脸色发灰的；忧郁的 n.蓝色",false]],"tier":"l","hint":"蓝色的、忧郁的。词组 feel blue 感到忧郁","ex":"The sky is blue today.（今天天空很蓝。）"},{"id":321,"day":6,"w":"boot","ph":"buːt","defs":[["n.","靴子",false]],"tier":"l","hint":"靴子。联想 shoe 鞋、boot 靴","ex":"He wore a pair of boots in the snow.（雪天他穿了双靴子。）"},{"id":322,"day":6,"w":"busy","ph":"ˈbɪzi","defs":[["a.","忙，忙碌；热闹的，繁忙的，（电话）占线",false]],"tier":"l","hint":"忙的。词组 be busy with 忙于、be busy doing 忙着做","ex":"She is busy with her homework.（她忙着写作业。）"},{"id":323,"day":6,"w":"chicken","ph":"ˈtʃɪkɪn","defs":[["n.","小鸡，鸡肉",false]],"tier":"l","hint":"鸡、鸡肉。联想 egg 蛋、hen 母鸡","ex":"We had chicken for dinner.（我们晚饭吃了鸡肉。）"},{"id":324,"day":6,"w":"clear","ph":"klɪr","defs":[["a.","明亮的，清澈的；晴朗的；清楚的 ad.清楚地，清晰地 vt.清除；澄清；晴朗起来",false]],"tier":"l","hint":"清楚的、晴朗的。词组 make clear 弄清楚","ex":"The water in the lake is very clear.（湖水很清澈。）"},{"id":325,"day":6,"w":"coast","ph":"koʊst","defs":[["n.","海岸，海滨",false]],"tier":"l","hint":"海岸。联想 beach 海滩、coast 海岸线","ex":"They live on the east coast.（他们住在东海岸。）"},{"id":326,"day":6,"w":"completely","ph":"kəmˈpliːtli","defs":[["ad.","完全地",false]],"tier":"l","hint":"complete（完全的）+ -ly → 完全地","ex":"I completely agree with you.（我完全同意你的看法。）"},{"id":327,"day":6,"w":"corn","ph":"kɔːrn","defs":[["n.","谷物；[美]玉米",false]],"tier":"l","hint":"玉米、谷物。联想 corn field 玉米地","ex":"The farmers grow corn in the field.（农民在地里种玉米。）"},{"id":328,"day":6,"w":"cup","ph":"kʌp","defs":[["n.","杯子，奖杯；（一）杯",false]],"tier":"l","hint":"杯子。词组 a cup of tea 一杯茶","ex":"I'd like a cup of coffee.（我想要杯咖啡。）"},{"id":329,"day":6,"w":"evil","ph":"ˈiːvl","defs":[["a.","坏的，邪恶的 n.邪恶，罪恶；祸害",false]],"tier":"l","hint":"邪恶的。联想 good 善（反义）、evil 恶","ex":"The story is about the fight between good and evil.（这个故事讲的是善恶之争。）"},{"id":330,"day":6,"w":"exact","ph":"ɪɡˈzækt","defs":[["a.","确切的，精确的",false]],"tier":"l","hint":"确切的。词组 to be exact 确切地说","ex":"Please give me the exact time.（请告诉我确切的时间。）"},{"id":331,"day":6,"w":"firm","ph":"fɜːrm","defs":[["a.","坚固的，结实的，稳固的；坚定的 n.公司，商号",false]],"tier":"l","hint":"坚固的、坚定的；公司。词组 firm belief 坚定的信念","ex":"He has a firm belief in himself.（他对自己有坚定的信念。）"},{"id":332,"day":6,"w":"force","ph":"fɔːrs","defs":[["n.","力，力量，力气；暴力，武力 vt.强迫，迫使",false]],"tier":"l","hint":"力量、强迫。词组 force sb to do 强迫某人做","ex":"Don't force children to study all day.（不要强迫孩子整天学习。）"},{"id":333,"day":6,"w":"girlfriend","ph":"ˈɡɜːrlfrend","defs":[["n.","女朋友",false]],"tier":"l","hint":"girl（女孩）+ friend（朋友）→ 女朋友。联想 boyfriend 男朋友","ex":"He went to the movies with his girlfriend.（他和女朋友去看电影了。）"},{"id":334,"day":6,"w":"give","ph":"ɡɪv","defs":[["vt.","给，赠送；提供，授予；举行，举办；交给，托 付；传授；进行，做",false]],"tier":"l","hint":"给。词组 give up 放弃、give in 屈服","ex":"Please give me a glass of water.（请给我一杯水。）"},{"id":335,"day":6,"w":"grain","ph":"ɡreɪn","defs":[["n.","谷物，谷类；颗粒，细粒",false]],"tier":"l","hint":"谷物、颗粒。联想 grain 粮食","ex":"The country produces a lot of grain.（这个国家生产大量粮食。）"},{"id":336,"day":6,"w":"grandfather","ph":"ˈɡrænfɑːðər","defs":[["n.","(外)祖父",false]],"tier":"l","hint":"grand（隔代的）+ father（父）→ 祖父","ex":"My grandfather tells me stories.（爷爷给我讲故事。）"},{"id":337,"day":6,"w":"greet","ph":"ɡriːt","defs":[["vt.","致敬，敬意，迎接",false]],"tier":"l","hint":"问候、迎接。联想 greeting 问候（名词）","ex":"She greeted the guests with a smile.（她微笑着迎接客人。）"},{"id":338,"day":6,"w":"heavy","ph":"ˈhevi","defs":[["a.","重的，沉重的，繁重的；大量的；猛烈的",false]],"tier":"l","hint":"重的。联想 light 轻的（反义）、heavily 重重地","ex":"The box is too heavy to lift.（这个箱子太重了，抬不动。）"},{"id":339,"day":6,"w":"historical","ph":"hɪˈstɔːrɪkl","defs":[["a.","历史的，有关历史的",false]],"tier":"l","hint":"history（历史）+ -ical → 历史的。词组 historical events 历史事件","ex":"We visited a historical site last week.（上周我们参观了一个历史遗迹。）"},{"id":340,"day":6,"w":"indoor(s)","ph":"ˈɪndɔːr","defs":[["a.","/ad.室内（的），户内（的）",false]],"tier":"l","hint":"in（内）+ door（门）→ 室内的。联想 outdoor 室外的（反义）","ex":"It's raining, so we play indoor games.（下雨了，所以我们玩室内游戏。）"},{"id":341,"day":6,"w":"intend","ph":"ɪnˈtend","defs":[["vt.","想要，打算，企图",false]],"tier":"l","hint":"打算。词组 intend to do 打算做","ex":"I intend to study abroad next year.（我打算明年出国留学。）"},{"id":342,"day":6,"w":"international","ph":"ˌɪntərˈnæʃnəl","defs":[["a.","国际的，世界的",false]],"tier":"l","hint":"inter-（之间）+ national（国家的）→ 国际的","ex":"English is an international language.（英语是国际语言。）"},{"id":343,"day":6,"w":"involve","ph":"ɪnˈvɑːlv","defs":[["vt.","(in)卷入，陷入，连累；包含，含有",false]],"tier":"l","hint":"涉及、卷入。词组 be involved in 参与、卷入","ex":"He was involved in the project.（他参与了这个项目。）"},{"id":344,"day":6,"w":"job","ph":"dʒɑːb","defs":[["n.","工作，职业；一件工作，活儿",false]],"tier":"l","hint":"工作（具体一份）。联想 work 工作（抽象）","ex":"She found a good job in the city.（她在城里找到了份好工作。）"},{"id":345,"day":6,"w":"judge","ph":"dʒʌdʒ","defs":[["n.","审判员，法官；评判员，裁判 vt.评价，鉴定；断定，判断；审判，裁判，裁决",false]],"tier":"l","hint":"法官、判断。词组 judge by 根据…判断","ex":"Don't judge a person by his appearance.（不要以貌取人。）"},{"id":346,"day":6,"w":"lend","ph":"lend","defs":[["vt.","出借，借给",false]],"tier":"l","hint":"借出。联想 borrow 借入（相对）","ex":"Can you lend me your pen?（你能把笔借给我吗？）"},{"id":347,"day":6,"w":"lesson","ph":"ˈlesn","defs":[["n.","一节课；功课；课程；教训",false]],"tier":"l","hint":"课、教训。词组 learn a lesson 吸取教训","ex":"We have an English lesson every day.（我们每天上英语课。）"},{"id":348,"day":6,"w":"mouth","ph":"maʊθ","defs":[["n.","嘴，口",false]],"tier":"l","hint":"嘴。联想 teeth 牙、tongue 舌（都在嘴里）","ex":"Open your mouth and say \"ah\".（张开嘴说\"啊\"。）"},{"id":349,"day":6,"w":"mysterious","ph":"mɪˈstɪriəs","defs":[["a.","神秘的，可疑的，难以理解的",false]],"tier":"l","hint":"mystery（神秘）+ -ous → 神秘的","ex":"There is a mysterious sound in the house.（房子里有种神秘的声音。）"},{"id":350,"day":6,"w":"number","ph":"ˈnʌmbər","defs":[["n.","数，数字；号码，编号",false]],"tier":"l","hint":"数字、号码。词组 a number of 许多、phone number 电话号码","ex":"What's your phone number?（你的电话号码是多少？）"},{"id":351,"day":6,"w":"opinion","ph":"əˈpɪnjən","defs":[["n.","意见，主张，看法",false]],"tier":"l","hint":"意见。词组 in my opinion 在我看来","ex":"In my opinion, the plan is good.（在我看来，这个计划不错。）"},{"id":352,"day":6,"w":"opponent","ph":"əˈpoʊnənt","defs":[["n.","对手，敌手",false]],"tier":"l","hint":"对手。联想 compete 竞争、opponent 竞争对手","ex":"He beat his opponent in the game.（他在比赛中击败了对手。）"},{"id":353,"day":6,"w":"phrase","ph":"freɪz","defs":[["n.","短语，词组，习语",true]],"tier":"f","ety":"希腊语 phrasis（表达方式）","mem":"谐音\"弗雷兹\"→ 几个词凑成\"一句话\"，像朋友\"弗雷兹\"在说 → 短语。画面：几个词手拉手","ex":"a set phrase · \"Kick the bucket\" is a set phrase.（\"kick the bucket\" 是个固定短语。）","nua":"phrase（短语，无主语谓语）、clause（从句，有主语谓语）；set phrase 固定短语"},{"id":354,"day":6,"w":"physics","ph":"ˈfɪzɪks","defs":[["n.","物理学",false]],"tier":"l","hint":"物理学。联想 -ics 学科后缀：physics 物理","ex":"Physics is my favorite subject.（物理是我最喜欢的科目。）"},{"id":355,"day":6,"w":"post","ph":"poʊst","defs":[["n.","(支)柱；邮政；哨所；岗位，职位 vt.贴出，宣布，公告；邮寄，投寄",false]],"tier":"l","hint":"一词多义：邮寄、岗位、张贴。词组 post a letter 寄信","ex":"I want to post a letter to my friend.（我想给朋友寄封信。）"},{"id":356,"day":6,"w":"quiet","ph":"ˈkwaɪət","defs":[["a.","/n.安静（的），平静（的），安定（的） vt.使安静，平定",false]],"tier":"l","hint":"安静的。联想 noise 噪音（反义）、keep quiet 保持安静","ex":"Please keep quiet in the library.（在图书馆请保持安静。）"},{"id":357,"day":6,"w":"recent","ph":"ˈriːsnt","defs":[["a.","最近的，近来的",false]],"tier":"l","hint":"最近的。联想 recently 最近（副词）","ex":"In recent years, the city has changed a lot.（近年来这座城市变化很大。）"},{"id":358,"day":6,"w":"regard","ph":"rɪˈɡɑːrd","defs":[["vt.","看作，对待；考虑，认为；尊重",false]],"tier":"l","hint":"看作、尊重。词组 regard...as 把…看作","ex":"We regard him as our best friend.（我们把他当作最好的朋友。）"},{"id":359,"day":6,"w":"rob","ph":"rɑːb","defs":[["vt.","(of)抢劫，盗取",false]],"tier":"l","hint":"抢劫。词组 rob sb of sth 抢某人某物","ex":"The man robbed the bank last night.（那人昨晚抢了银行。）"},{"id":360,"day":6,"w":"rose","ph":"roʊz","defs":[["n.","玫瑰，蔷薇",false]],"tier":"l","hint":"玫瑰。联想 rose 玫瑰、lily 百合","ex":"He gave her a red rose.（他送她一朵红玫瑰。）"},{"id":361,"day":6,"w":"show","ph":"ʃoʊ","defs":[["n.","表演，节目；展出，陈列；展览会/物 vt.给（人）看，出示；带领；说明，示范；表明， 证明；指示，指出 vi.显示，露面；演出",false]],"tier":"l","hint":"展示、表演。词组 show sb around 带某人参观","ex":"She showed me her new dress.（她给我看她的新裙子。）"},{"id":362,"day":6,"w":"sing","ph":"sɪŋ","defs":[["vi.","/vt.唱，唱歌；鸣叫",false]],"tier":"l","hint":"唱歌。联想 song 歌（名词）、singer 歌手","ex":"The birds sing in the morning.（鸟儿在早晨唱歌。）"},{"id":363,"day":6,"w":"sort","ph":"sɔːrt","defs":[["n.","种类，类别 vt. (out)分类，整理",false]],"tier":"l","hint":"种类、分类。词组 sort out 整理","ex":"There are all sorts of books in the library.（图书馆里有各种书。）"},{"id":364,"day":6,"w":"split","ph":"splɪt","defs":[["vi.","/vt.劈开，裂开 a.分裂的 n.裂缝，裂口；分化，分裂",false]],"tier":"l","hint":"劈开、裂开。词组 split into 分成","ex":"They split the cake into two parts.（他们把蛋糕分成两份。）"},{"id":365,"day":6,"w":"stretch","ph":"stretʃ","defs":[["vi.","/vt.拉长，延伸 n.拉长；伸展；连续的一段时间；一大片",false]],"tier":"l","hint":"伸展、延伸。词组 stretch out 伸展","ex":"He stretched his arms after sitting long.（久坐后他伸了伸胳膊。）"},{"id":366,"day":6,"w":"throat","ph":"θroʊt","defs":[["n.","喉咙",false]],"tier":"l","hint":"喉咙。联想 sore throat 嗓子疼","ex":"I have a sore throat today.（我今天嗓子疼。）"},{"id":367,"day":6,"w":"toilet","ph":"ˈtɔɪlət","defs":[["n.","盥洗室；梳洗",false]],"tier":"l","hint":"卫生间。联想 bathroom 浴室、toilet 马桶/卫生间","ex":"The toilet is at the end of the hall.（卫生间在走廊尽头。）"},{"id":368,"day":6,"w":"too","ph":"tuː","defs":[["ad.","也，又；太，过于",false]],"tier":"s"},{"id":369,"day":6,"w":"trouble","ph":"ˈtrʌbl","defs":[["n.","麻烦，困难 vt.麻烦，打扰 vi.费神，费力",false]],"tier":"l","hint":"麻烦。词组 get into trouble 陷入麻烦、have trouble doing 做…有困难","ex":"He helped me out of trouble.（他帮我摆脱了麻烦。）"},{"id":370,"day":6,"w":"type","ph":"taɪp","defs":[["n.","类型；印刷字体；活字，铅字 vi./vt.打字",false]],"tier":"l","hint":"类型、打字。词组 type of 类型","ex":"This type of phone is very popular.（这种手机很流行。）"},{"id":371,"day":6,"w":"visit","ph":"ˈvɪzɪt","defs":[["vi.","/vt./n.访问，参观；视察，巡视",false]],"tier":"l","hint":"参观、拜访。联想 visitor 游客、visit 参观","ex":"We will visit the museum tomorrow.（我们明天参观博物馆。）"},{"id":372,"day":6,"w":"wealth","ph":"welθ","defs":[["n.","财富，财产；丰富，大量",false]],"tier":"l","hint":"财富。联想 rich 富的、wealthy 富有的","ex":"Health is more important than wealth.（健康比财富更重要。）"},{"id":373,"day":6,"w":"weigh","ph":"weɪ","defs":[["vt.","称，量；重，重达；考虑，权衡 vi.重……",false]],"tier":"l","hint":"称重、重达。联想 weight 重量（名词）","ex":"The box weighs ten kilograms.（这个箱子重十公斤。）"},{"id":374,"day":7,"w":"act","ph":"ækt","defs":[["n.","行为，动作；（一）幕；法令，条例 vi.行动，举动；起作用；表演",false]],"tier":"l","hint":"行动、表演。词组 act as 充当、take action 采取行动","ex":"We should act at once.（我们应该立即行动。）"},{"id":375,"day":7,"w":"advantage","ph":"ədˈvæntɪdʒ","defs":[["n.","优点，有利条件；利益",true]],"tier":"f","ety":"avant（在前，同 advance）+ -age → 在前面的位置 → 优势","mem":"advance（前进）+ tage → 冲在\"前面\" → 优势。画面：起跑领先一步","ex":"take advantage of · We should take advantage of the chance.（我们应抓住这个机会。）","nua":"take advantage of（利用，中性/贬义都可）、have an advantage over（胜过）；反义 disadvantage"},{"id":376,"day":7,"w":"aim","ph":"eɪm","defs":[["n.","/v. 瞄准；目标；志在",true]],"tier":"f","ety":"古法语 esmer（估计、瞄准）","mem":"谐音\"诶母\"→ \"诶\"瞄准目标\"母\"靶心 → 瞄准、目标。画面：拉弓对准靶心","ex":"aim at · The policy aims at reducing pollution.（这项政策旨在减少污染。）","nua":"aim at + 名词/动名词、aim to + 动词原形；goal（目标）是近义名词"},{"id":377,"day":7,"w":"aircraft","ph":"ˈerkræft","defs":[["n.","飞机，飞行器",true]],"tier":"f","ety":"air（空中）+ craft（飞行器）→ 飞行器","mem":"air + craft → 在\"空中\"（air）的\"工艺\"（craft）→ 飞机。画面：飞机翱翔","ex":"a commercial aircraft · The aircraft is ready to take off.（飞机准备起飞。）","nua":"aircraft 单复数同形（one aircraft / two aircraft）；craft 本身也单复数同形"},{"id":378,"day":7,"w":"among","ph":"əˈmʌŋ","defs":[["prep.","在……之中，在……之间",false]],"tier":"s"},{"id":379,"day":7,"w":"area","ph":"ˈeriə","defs":[["n.","面积；地区；范围，领域",false]],"tier":"l","hint":"地区、面积、领域。词组 in the area of 在…领域","ex":"This area is famous for its tea.（这个地区以茶叶闻名。）"},{"id":380,"day":7,"w":"article","ph":"ˈɑːrtɪkl","defs":[["n.","文章；物件",false]],"tier":"l","hint":"文章、物件。联想 article 文章（报纸上的）","ex":"He wrote an article for the newspaper.（他为报纸写了篇文章。）"},{"id":381,"day":7,"w":"brush","ph":"brʌʃ","defs":[["vt.","刷 n.刷，毛刷，画笔",false]],"tier":"l","hint":"刷子、刷。词组 brush one's teeth 刷牙","ex":"You should brush your teeth twice a day.（你应该每天刷两次牙。）"},{"id":382,"day":7,"w":"butter","ph":"ˈbʌtər","defs":[["n.","黄油，奶油",false]],"tier":"l","hint":"黄油。联想 bread and butter 面包黄油（生计）","ex":"She spread butter on the bread.（她在面包上抹黄油。）"},{"id":383,"day":7,"w":"college","ph":"ˈkɑːlɪdʒ","defs":[["n.","学院，大学",false]],"tier":"l","hint":"学院、大学。词组 go to college 上大学","ex":"He will go to college next year.（他明年上大学。）"},{"id":384,"day":7,"w":"comb","ph":"koʊm","defs":[["n.","梳子 vt.梳理（头发）",false]],"tier":"l","hint":"梳子、梳理。联想 comb one's hair 梳头","ex":"She combed her hair before the mirror.（她在镜子前梳头。）"},{"id":385,"day":7,"w":"combination","ph":"ˌkɑːmbɪˈneɪʃn","defs":[["n.","结合，联合",true]],"tier":"f","ety":"com-（一起）+ bin（二）+ -ation → 两者合在一起 → 结合","mem":"com + bin（两个）+ ation → \"两\"个绑\"一起\" → 结合。画面：两根绳子拧成一股","ex":"in combination with · The drug works in combination with exercise.（这种药配合运动才有效。）","nua":"combination（结合）、combine（动词结合）；in combination with（与…结合）"},{"id":386,"day":7,"w":"competition","ph":"ˌkɑːmpəˈtɪʃn","defs":[["n.","比赛，竞赛",false]],"tier":"l","hint":"compete（竞争）+ -ition → 竞赛。词组 in competition with 与…竞争","ex":"He won the singing competition.（他赢得了歌唱比赛。）"},{"id":387,"day":7,"w":"computer","ph":"kəmˈpjuːtər","defs":[["n.","计算机",false]],"tier":"l","hint":"computer 计算机。联想 compute 计算","ex":"I use a computer to do my work.（我用电脑工作。）"},{"id":388,"day":7,"w":"could","ph":"kəd","defs":[["aux.","v.[can的过去式]",false]],"tier":"s"},{"id":389,"day":7,"w":"crack","ph":"kræk","defs":[["vi.","（使）破裂，砸开；发爆裂声 n.裂纹，龟裂；爆裂声",false]],"tier":"l","hint":"破裂、裂纹。联想 crack down 打击","ex":"The cup cracked when hot water was poured in.（倒入热水时杯子裂了。）"},{"id":390,"day":7,"w":"criticize/-se","ph":"ˈkrɪtɪsaɪz","defs":[["vt.","批评，评论",true]],"tier":"f","ety":"critic（批评家）+ -ize（动词）→ 批评","mem":"critic（批评家）+ ize → 批评家做的事 → 批评。画面：点评者挑毛病","ex":"criticize sb for · He was criticized for being late.（他因迟到被批评。）","nua":"criticize sb for（因…批评）、blame sb for（责怪）；英式拼 criticize/-se 皆可"},{"id":391,"day":7,"w":"current","ph":"ˈkɜːrənt","defs":[["n.","流，水流，气流，电流；潮流，趋势 a.通用的，流行的，当前的",false]],"tier":"l","hint":"一词多义：当前的、水流/电流。词组 current situation 当前形势","ex":"We must know the current situation.（我们必须了解当前形势。）"},{"id":392,"day":7,"w":"custom","ph":"ˈkʌstəm","defs":[["n.","习惯，风俗，惯例；(pl.)海关",false]],"tier":"l","hint":"风俗、习惯。联想 customs 海关、custom 习俗","ex":"Every country has its own customs.（每个国家都有自己的风俗。）"},{"id":393,"day":7,"w":"discussion","ph":"dɪˈskʌʃn","defs":[["n.","讨论",false]],"tier":"l","hint":"discuss（讨论）+ -ion → 讨论。词组 have a discussion 讨论","ex":"We had a discussion about the plan.（我们就这个计划进行了讨论。）"},{"id":394,"day":7,"w":"double","ph":"ˈdʌbl","defs":[["a.","两倍的；双，双重 vt.使加倍，翻一番",false]],"tier":"l","hint":"两倍的、双的。联想 single 单的、double 双的","ex":"The price is double what it was.（价格是原来的两倍。）"},{"id":395,"day":7,"w":"drunk","ph":"drʌŋk","defs":[["a.","酒醉的",true]],"tier":"f","ety":"drink（喝）的过去分词","mem":"drink（喝）→ drunk（喝多了的）。画面：喝到东倒西歪","ex":"get drunk · He got drunk at the party.（他在聚会上喝醉了。）","nua":"drunk（醉的，作形容词/名词）、drunken（醉酒的，作定语）；get drunk 喝醉"},{"id":396,"day":7,"w":"exercise","ph":"ˈeksərsaɪz","defs":[["n.","练习，习题；锻炼 vt.运用，行使，实行 vi.锻炼，训练",false]],"tier":"l","hint":"锻炼、练习。词组 do exercise 锻炼、take exercise 锻炼","ex":"Doing exercise is good for health.（锻炼有益健康。）"},{"id":397,"day":7,"w":"flash","ph":"flæʃ","defs":[["n.","闪光，一闪，闪光灯 vi.发闪光；闪现，闪过；飞驰，掠过",false]],"tier":"l","hint":"闪光、闪现。词组 in a flash 一刹那","ex":"Lightning flashed across the sky.（闪电划过天空。）"},{"id":398,"day":7,"w":"fly","ph":"flaɪ","defs":[["vi.","/vt.飞，飞行；(放)风筝，驾驶(飞机)；(使)飘扬 n.苍蝇",false]],"tier":"l","hint":"飞。过去式 flew。词组 fly a kite 放风筝","ex":"The birds fly south in winter.（鸟儿冬天飞向南方。）"},{"id":399,"day":7,"w":"frame","ph":"freɪm","defs":[["n.","框架；骨架，体格 vt.装框子",false]],"tier":"l","hint":"框架。联想 picture frame 相框","ex":"She put the photo in a frame.（她把照片放进相框。）"},{"id":400,"day":7,"w":"friend","ph":"frend","defs":[["n.","朋友，友人",false]],"tier":"l","hint":"朋友。词组 make friends with 与…交朋友","ex":"He is my best friend.（他是我最好的朋友。）"},{"id":401,"day":7,"w":"health","ph":"helθ","defs":[["n.","健康，卫生",false]],"tier":"l","hint":"健康。词组 be in good health 身体健康","ex":"Health is the most important thing.（健康是最重要的。）"},{"id":402,"day":7,"w":"heat","ph":"hiːt","defs":[["n.","热；热烈，激烈 vt.加热 vi.发热",false]],"tier":"l","hint":"热、加热。联想 cold 冷（反义）、hot 热的","ex":"The sun gives us light and heat.（太阳给我们光和热。）"},{"id":403,"day":7,"w":"hole","ph":"hoʊl","defs":[["n.","洞，窟窿",false]],"tier":"l","hint":"洞、窟窿。联想 dig a hole 挖洞","ex":"There is a hole in my sock.（我的袜子上有个洞。）"},{"id":404,"day":7,"w":"insect","ph":"ˈɪnsekt","defs":[["n.","虫，昆虫",false]],"tier":"l","hint":"昆虫。联想 in-（内）+ sect（切）→ 身体分节 → 昆虫","ex":"Butterflies are beautiful insects.（蝴蝶是美丽的昆虫。）"},{"id":405,"day":7,"w":"monkey","ph":"ˈmʌŋki","defs":[["n.","猴子",false]],"tier":"l","hint":"猴子。联想 monkey 猴子、ape 猿","ex":"The monkey is climbing the tree.（猴子在爬树。）"},{"id":406,"day":7,"w":"nearly","ph":"ˈnɪrli","defs":[["ad.","差不多，几乎",false]],"tier":"l","hint":"near（近）+ -ly → 几乎、差不多","ex":"It's nearly nine o'clock.（快九点了。）"},{"id":407,"day":7,"w":"pass","ph":"pæs","defs":[["vi.","/vt.经过；通过，穿过；传递；通过(考试等) n.通行证，护照；关隘；考试及格",false]],"tier":"l","hint":"经过、通过、传递。词组 pass the exam 通过考试","ex":"He passed the exam easily.（他轻松通过了考试。）"},{"id":408,"day":7,"w":"pause","ph":"pɔːz","defs":[["n.","/vi.暂停，中止",false]],"tier":"l","hint":"暂停。联想 stop 停止、pause 暂停（短暂）","ex":"She paused for a moment and then went on.（她停顿了一下又继续。）"},{"id":409,"day":7,"w":"peace","ph":"piːs","defs":[["n.","和平；平静",false]],"tier":"l","hint":"和平、平静。词组 in peace 和平地、peaceful 和平的","ex":"People all over the world love peace.（全世界人民都热爱和平。）"},{"id":410,"day":7,"w":"person","ph":"ˈpɜːrsn","defs":[["n.","人",false]],"tier":"l","hint":"人。词组 in person 亲自","ex":"He is a kind person.（他是个善良的人。）"},{"id":411,"day":7,"w":"plain","ph":"plen","defs":[["n.","平原 a.平易的，易懂的；简单的，朴素的",false]],"tier":"l","hint":"一词多义：平原、朴素的、易懂的。词组 plain English 简明英语","ex":"The book is written in plain language.（这本书用朴实的语言写成。）"},{"id":412,"day":7,"w":"poem","ph":"ˈpoʊəm","defs":[["n.","诗",false]],"tier":"l","hint":"诗。联想 poet 诗人、poetry 诗歌（总称）","ex":"She wrote a poem about spring.（她写了首关于春天的诗。）"},{"id":413,"day":7,"w":"powerful","ph":"ˈpaʊərfl","defs":[["a.","强大的，有力的，有权的",false]],"tier":"l","hint":"power（力量）+ -ful → 强大的","ex":"China is a powerful country.（中国是个强大的国家。）"},{"id":414,"day":7,"w":"profit","ph":"ˈprɑːfɪt","defs":[["n.","收益，利润，益处 vi.得利，获益",false]],"tier":"l","hint":"利润、收益。词组 make a profit 获利","ex":"The company made a big profit last year.（公司去年赚了很多利润。）"},{"id":415,"day":7,"w":"pronunciation","ph":"prəˌnʌnsiˈeɪʃn","defs":[["n.","发音；发音方法",false]],"tier":"l","hint":"pronounce（发音）的名词 → 发音","ex":"Her English pronunciation is very good.（她的英语发音很好。）"},{"id":416,"day":7,"w":"queen","ph":"kwiːn","defs":[["n.","女王，皇后，王后",false]],"tier":"l","hint":"女王、王后。联想 king 国王（相对）","ex":"The queen was loved by her people.（女王深受人民爱戴。）"},{"id":417,"day":7,"w":"return","ph":"rɪˈtɜːrn","defs":[["vi.","/n.归，回；归还 vt.归还，送回；回报，报答 a.回程的；回报的",false]],"tier":"l","hint":"归还、返回。词组 return to 回到、return...to 归还","ex":"Please return the book to the library.（请把书还给图书馆。）"},{"id":418,"day":7,"w":"rich","ph":"rɪtʃ","defs":[["a.","富，富饶，丰富；富丽，浓艳",false]],"tier":"l","hint":"富的、丰富的。词组 be rich in 富含","ex":"The country is rich in natural resources.（这个国家自然资源丰富。）"},{"id":419,"day":7,"w":"shake","ph":"ʃeɪk","defs":[["vi.","/vt.摇，摇动；震动，颤抖；握手 n.摇动，震动，抖动",false]],"tier":"l","hint":"摇、握手。过去式 shook。词组 shake hands 握手","ex":"They shook hands when they met.（他们见面时握手。）"},{"id":420,"day":7,"w":"shoe","ph":"ʃuː","defs":[["n.","鞋",false]],"tier":"l","hint":"鞋。词组 a pair of shoes 一双鞋","ex":"These shoes are too small for me.（这双鞋对我来说太小了。）"},{"id":421,"day":7,"w":"shout","ph":"ʃaʊt","defs":[["vi.","呼喊，呼叫 n.呼喊，叫声",false]],"tier":"l","hint":"呼喊。词组 shout at 对…喊叫","ex":"Don't shout at the children.（不要对孩子大喊大叫。）"},{"id":422,"day":7,"w":"similar","ph":"ˈsɪmələr","defs":[["a.","类似的，相似的",false]],"tier":"l","hint":"相似的。词组 be similar to 与…相似","ex":"Your idea is similar to mine.（你的想法和我的相似。）"},{"id":423,"day":7,"w":"stair","ph":"ster","defs":[["n.","(pl.)楼梯；阶梯",false]],"tier":"l","hint":"楼梯。词组 go up the stairs 上楼","ex":"She ran up the stairs quickly.（她飞快地跑上楼。）"},{"id":424,"day":7,"w":"star","ph":"stɑːr","defs":[["n.","星，恒星；明星，名人 vi.主演",false]],"tier":"l","hint":"星、明星。词组 movie star 电影明星","ex":"The stars shine at night.（星星在夜晚闪耀。）"},{"id":425,"day":7,"w":"stomach","ph":"ˈstʌmək","defs":[["n.","胃",false]],"tier":"l","hint":"胃。词组 stomach ache 胃痛","ex":"He has a stomach ache.（他胃疼。）"},{"id":426,"day":7,"w":"stop","ph":"stɑːp","defs":[["n.","停车站；停止，中止 vt.停止，中止 vi.阻止；堵塞；逗留，歇宿",false]],"tier":"l","hint":"停止、车站。词组 stop doing 停止做、stop to do 停下来去做","ex":"The bus stops at the station.（公交车在车站停。）"},{"id":427,"day":7,"w":"thin","ph":"θɪn","defs":[["a.","细的，薄的；稀的；瘦的 vi.变细，变薄",false]],"tier":"l","hint":"瘦的、薄的。联想 fat 胖的（反义）、thick 厚的（反义）","ex":"The ice is too thin to skate on.（冰太薄不能滑。）"},{"id":428,"day":7,"w":"track","ph":"træk","defs":[["n.","跑道，路线，轨道；足迹，踪迹 vt.跟踪，追踪",false]],"tier":"l","hint":"轨道、跟踪。词组 keep track of 追踪、track and field 田径","ex":"The police tracked the thief.（警察追踪小偷。）"},{"id":429,"day":7,"w":"tube","ph":"tuːb","defs":[["n.","管，软管；电子管，显像管；地铁",false]],"tier":"l","hint":"管、地铁。词组 by tube 乘地铁（英式）","ex":"He goes to work by tube.（他乘地铁上班。）"},{"id":430,"day":7,"w":"university","ph":"ˌjuːnɪˈvɜːrsəti","defs":[["n.","（综合性）大学",false]],"tier":"l","hint":"综合性大学。联想 college 学院（比 university 小）","ex":"She studies at a famous university.（她在一所著名大学学习。）"},{"id":431,"day":7,"w":"vote","ph":"voʊt","defs":[["n.","选举，表决；选票，选票数 vi.选举，表决",false]],"tier":"l","hint":"投票、选举。词组 vote for 投票支持","ex":"People voted for the new president.（人们投票选新总统。）"},{"id":432,"day":7,"w":"warning","ph":"ˈwɔːrnɪŋ","defs":[["n.","警告",false]],"tier":"l","hint":"warn（警告）+ -ing → 警告","ex":"The weather station gave a warning of the storm.（气象台发布了暴风雨警报。）"},{"id":433,"day":7,"w":"watch","ph":"wɑːtʃ","defs":[["vt.","观看，注视；窥伺，等待；看管，监视 n.表，手表；看管，监视",false]],"tier":"l","hint":"一词多义：观看、手表。词组 watch TV 看电视","ex":"We watch TV in the evening.（我们晚上看电视。）"},{"id":434,"day":7,"w":"wife","ph":"waɪf","defs":[["n.","妻子，夫人，太太",false]],"tier":"l","hint":"妻子。联想 husband 丈夫（相对）","ex":"His wife is a doctor.（他妻子是医生。）"},{"id":435,"day":7,"w":"worth","ph":"wɜːrθ","defs":[["prep.","值……，值得……的 n.价值",false]],"tier":"l","hint":"值得。词组 be worth doing 值得做","ex":"This book is worth reading.（这本书值得读。）"},{"id":436,"day":8,"w":"adult","ph":"ˈædʌlt","defs":[["n.","成人 a.成年的，成熟的",false]],"tier":"l","hint":"成年人。联想 child 孩子（反义）","ex":"The movie is for adults only.（这部电影只适合成人。）"},{"id":437,"day":8,"w":"anywhere","ph":"ˈeniwer","defs":[["ad.","无论哪里；[否定、疑问、条件句中]任何地方",false]],"tier":"l","hint":"any（任何）+ where（地方）→ 任何地方","ex":"You can sit anywhere you like.（你可以坐任何喜欢的地方。）"},{"id":438,"day":8,"w":"army","ph":"ˈɑːrmi","defs":[["n.","军队，陆军；大群，大批",false]],"tier":"l","hint":"军队。联想 soldier 士兵、army 军队","ex":"He joined the army at eighteen.（他十八岁参军。）"},{"id":439,"day":8,"w":"bend","ph":"bend","defs":[["n.","弯曲；曲折处 vt.折弯；使屈服",false]],"tier":"l","hint":"弯曲。过去式 bent。词组 bend down 弯腰","ex":"He bent down to pick up the pen.（他弯腰捡笔。）"},{"id":440,"day":8,"w":"bread","ph":"bred","defs":[["n.","面包",false]],"tier":"l","hint":"面包。词组 a piece of bread 一片面包","ex":"I had bread and milk for breakfast.（我早餐吃面包和牛奶。）"},{"id":441,"day":8,"w":"bus","ph":"bʌs","defs":[["n.","公共汽车",false]],"tier":"l","hint":"公交车。词组 by bus 乘公交、take a bus 坐公交","ex":"He goes to school by bus.（他坐公交上学。）"},{"id":442,"day":8,"w":"compare","ph":"kəmˈper","defs":[["vt.","比较，相比，对照",false]],"tier":"l","hint":"比较。词组 compare...with 把…与…比较","ex":"Compare your answer with mine.（把你的答案和我的比较。）"},{"id":443,"day":8,"w":"concern","ph":"kənˈsɜːrn","defs":[["v.","/n. 涉及，关系到；关心，担忧",true]],"tier":"f","ety":"con-（一起）+ cern（筛选）→ 一起分辨 → 关系到","mem":"con + cern（sift 筛选）→ 事情把你\"筛\"进来 → 与你有关 → 关心。画面：事情找上门","ex":"be concerned about · Parents are concerned about their children.（父母关心孩子。）","nua":"be concerned about（担心）、be concerned with（涉及）；concerning（介词，关于）"},{"id":444,"day":8,"w":"conscious","ph":"ˈkɑːnʃəs","defs":[["a.","意识到的；有知觉的",true]],"tier":"f","ety":"con-（一起）+ sci（知道，同 science）+ -ous → 一起知道 → 意识到的","mem":"con + sci（=science 知道）+ ous → 心里\"知道\"→ 有意识的。画面：清醒地感知到","ex":"be conscious of · He was conscious of his mistake.（他意识到自己的错误。）","nua":"be conscious of（意识到）、be aware of（同义，更常用）；反义 unconscious"},{"id":445,"day":8,"w":"desk","ph":"desk","defs":[["n.","书桌，服务台，办公桌",false]],"tier":"l","hint":"书桌。联想 table 桌子、desk 书桌","ex":"The book is on the desk.（书在书桌上。）"},{"id":446,"day":8,"w":"elbow","ph":"ˈelboʊ","defs":[["n.","肘，弯头，弯管 vi.用肘推，挤进",false]],"tier":"l","hint":"肘。联想 arm 手臂、elbow 肘","ex":"He hurt his elbow playing basketball.（他打篮球时伤了肘。）"},{"id":447,"day":8,"w":"engineer","ph":"ˌendʒɪˈnɪr","defs":[["n.","工程师",false]],"tier":"l","hint":"engine（引擎）+ -er → 工程师","ex":"He works as an engineer.（他当工程师。）"},{"id":448,"day":8,"w":"explanation","ph":"ˌekspləˈneɪʃn","defs":[["n.","解释，说明",false]],"tier":"l","hint":"explain（解释）+ -ation → 解释","ex":"He gave a clear explanation.（他给出了清楚的解释。）"},{"id":449,"day":8,"w":"fashionable","ph":"ˈfæʃnəbl","defs":[["a.","流行的，时髦的",false]],"tier":"l","hint":"fashion（时尚）+ -able → 时髦的","ex":"She always wears fashionable clothes.（她总穿时髦的衣服。）"},{"id":450,"day":8,"w":"film","ph":"fɪlm","defs":[["n.","电影，胶卷；膜，薄层 vt.把……拍成电影",false]],"tier":"l","hint":"电影、胶卷。词组 see a film 看电影","ex":"We saw a film last night.（我们昨晚看了场电影。）"},{"id":451,"day":8,"w":"flower","ph":"ˈflaʊər","defs":[["n.","花，花卉 vi.开花",false]],"tier":"l","hint":"花。联想 flower 花、garden 花园","ex":"The garden is full of flowers.（花园里开满花。）"},{"id":452,"day":8,"w":"football","ph":"fʊtbɔːl","defs":[["n.","足球，足球运动",false]],"tier":"l","hint":"foot（脚）+ ball（球）→ 足球。词组 play football 踢足球","ex":"The boys are playing football.（男孩们在踢足球。）"},{"id":453,"day":8,"w":"goods","ph":"ɡʊdz","defs":[["n.","货物，商品；财产",false]],"tier":"l","hint":"货物、商品。联想 good 好的、goods 货物","ex":"The shop sells many kinds of goods.（这家店卖很多商品。）"},{"id":454,"day":8,"w":"home","ph":"hoʊm","defs":[["n.","家，家乡；本国",false]],"tier":"l","hint":"家。词组 at home 在家、go home 回家","ex":"I go home at five every day.（我每天五点回家。）"},{"id":455,"day":8,"w":"intention","ph":"ɪnˈtenʃn","defs":[["n.","意图，意向，目的",false]],"tier":"l","hint":"intend（打算）+ -tion → 意图。词组 have no intention of 无意","ex":"He has no intention of leaving.（他无意离开。）"},{"id":456,"day":8,"w":"jump","ph":"dʒʌmp","defs":[["vi.","跳跃，跳动 n.跳跃；猛增",false]],"tier":"l","hint":"跳。词组 jump over 跳过","ex":"The cat jumped over the wall.（猫跳过墙。）"},{"id":457,"day":8,"w":"lip","ph":"lɪp","defs":[["n.","嘴唇",false]],"tier":"l","hint":"嘴唇。联想 mouth 嘴、lip 唇","ex":"She put lipstick on her lips.（她在嘴唇上涂口红。）"},{"id":458,"day":8,"w":"listen","ph":"ˈlɪsn","defs":[["vi.","(to)听；听从",false]],"tier":"l","hint":"听。词组 listen to 听（注意要加 to）","ex":"Listen to the teacher carefully.（认真听老师讲。）"},{"id":459,"day":8,"w":"lock","ph":"lɑːk","defs":[["n.","锁 vi./vt.上锁，锁住",false]],"tier":"l","hint":"锁。词组 lock the door 锁门、unlock 开锁（反义）","ex":"Remember to lock the door.（记得锁门。）"},{"id":460,"day":8,"w":"meaning","ph":"ˈmiːnɪŋ","defs":[["n.","意思，意义，含义",false]],"tier":"l","hint":"mean（意味着）+ -ing → 意思、意义","ex":"What's the meaning of this word?（这个单词什么意思？）"},{"id":461,"day":8,"w":"noticeable","ph":"ˈnoʊtɪsəbl","defs":[["a.","显而易见的，显著的，值得注意的",false]],"tier":"l","hint":"notice（注意）+ -able → 显而易见的","ex":"There is a noticeable change in him.（他有明显的变化。）"},{"id":462,"day":8,"w":"outside","ph":"ˌaʊtˈsaɪd","defs":[["n.","/a.外面（的），外部（的） ad.向外，在外 prep.在……外",false]],"tier":"l","hint":"out（外）+ side（边）→ 在外面。联想 inside 里面（反义）","ex":"It's cold outside.（外面很冷。）"},{"id":463,"day":8,"w":"over","ph":"ˈoʊvər","defs":[["prep.","在……上方；髙于，超过；在（做）……时候； 越过，横跨；关于，在……方面；到处，遍及 ad.翻过来；以上，超过；越过；在/向那边 a.完了的，结束的；太……的，过度……的",false]],"tier":"s"},{"id":464,"day":8,"w":"owe","ph":"oʊ","defs":[["vt.","欠，应向……付出；应归功于",false]],"tier":"l","hint":"欠、归功于。词组 owe...to 把…归功于","ex":"I owe my success to my teacher.（我把成功归功于老师。）"},{"id":465,"day":8,"w":"passage","ph":"ˈpæsɪdʒ","defs":[["n.","通过，经过；通路，走廊；段，节",false]],"tier":"l","hint":"pass（通过）+ -age → 段落、通道。词组 read the passage 读文章","ex":"Read the passage and answer the questions.（读文章并回答问题。）"},{"id":466,"day":8,"w":"pay","ph":"peɪ","defs":[["vt.","付款，缴纳；付清；给予，致以(问候),进行(访问) n.工资，薪饷；报酬",false]],"tier":"l","hint":"支付。过去式 paid。词组 pay for 支付、pay attention to 注意","ex":"He paid ten yuan for the book.（他花十元买这本书。）"},{"id":467,"day":8,"w":"pin","ph":"pɪn","defs":[["n.","大头针；别针；销，栓 vt.钉住，别住",false]],"tier":"l","hint":"别针、大头针。联想 pin 别针、pin up 别住","ex":"She pinned the note on the board.（她把便条别在板上。）"},{"id":468,"day":8,"w":"play","ph":"pleɪ","defs":[["vi.","/vt.玩，游玩；演奏，表演；比赛 n.游戏，娱乐；剧本，戏剧；比赛，运动",false]],"tier":"l","hint":"玩、打、演奏。词组 play football 踢球、play the piano 弹钢琴","ex":"The children are playing in the park.（孩子们在公园玩。）"},{"id":469,"day":8,"w":"preparation","ph":"ˌprepəˈreɪʃn","defs":[["n.","准备，预备；制剂，制备品",false]],"tier":"l","hint":"prepare（准备）+ -ation → 准备。词组 in preparation for 为…准备","ex":"He is making preparations for the exam.（他在为考试做准备。）"},{"id":470,"day":8,"w":"preserve","ph":"prɪˈzɜːrv","defs":[["vt.","保护，保存；腌制",true]],"tier":"f","ety":"pre-（预先）+ serve（保护，同 serve）→ 提前保护 → 保存","mem":"pre（预先）+ serve（保护）→ 提前保护起来 → 保存。画面：提前把食物腌起来防腐","ex":"preserve the environment · We must preserve the environment.（我们必须保护环境。）","nua":"preserve（保存原状、保护）、reserve（预订、保留）、conserve（节约资源）；三者易混"},{"id":471,"day":8,"w":"punish","ph":"ˈpʌnɪʃ","defs":[["vt.","处罚，惩罚",false]],"tier":"l","hint":"惩罚。词组 punish sb for 因…惩罚某人","ex":"The teacher punished him for cheating.（老师因作弊惩罚他。）"},{"id":472,"day":8,"w":"receive","ph":"rɪˈsiːv","defs":[["vt.","收到，接到；接待，接见：受到，蒙受",false]],"tier":"l","hint":"收到。联想 accept 接受（主观）、receive 收到（客观）","ex":"I received a letter from him yesterday.（我昨天收到他的信。）"},{"id":473,"day":8,"w":"refer","ph":"rɪˈfɜːr","defs":[["vi.","(to)参考，查阅，査询；(to)提到，引用，指",false]],"tier":"l","hint":"提及、参考。词组 refer to 提到、参考","ex":"He often refers to his notes.（他常参考笔记。）"},{"id":474,"day":8,"w":"rope","ph":"rəʊp","defs":[["n.","绳，索",false]],"tier":"l","hint":"绳子。联想 string 细绳、rope 粗绳","ex":"They tied the box with a rope.（他们用绳子捆箱子。）"},{"id":475,"day":8,"w":"rough","ph":"rʌf","defs":[["a.","粗糙的；粗野的，粗鲁的；大致的，粗略的",false]],"tier":"l","hint":"粗糙的、粗略的。联想 smooth 光滑的（反义）","ex":"The road is rough and bumpy.（这条路坑坑洼洼。）"},{"id":476,"day":8,"w":"royal","ph":"ˈrɔɪəl","defs":[["a.","王室的，皇家的",false]],"tier":"l","hint":"皇家的。联想 royal family 王室","ex":"The royal family visited the city.（王室访问了这座城市。）"},{"id":477,"day":8,"w":"ruler","ph":"ˈruːlər","defs":[["n.","统治者，支配者；尺子，直尺",false]],"tier":"l","hint":"rule（统治）+ -er → 统治者、尺子","ex":"Use a ruler to draw a line.（用尺子画线。）"},{"id":478,"day":8,"w":"secretary","ph":"ˈsekrəteri","defs":[["n.","书记；秘书；部长，大臣",false]],"tier":"l","hint":"秘书。联想 secretary 秘书、office 办公室","ex":"She works as a secretary.（她当秘书。）"},{"id":479,"day":8,"w":"series","ph":"ˈsɪriːz","defs":[["n.","—系列，一连串，序列；丛书",false]],"tier":"l","hint":"系列。词组 a series of 一系列","ex":"He gave a series of lectures.（他做了一系列讲座。）"},{"id":480,"day":8,"w":"settle","ph":"ˈsetl","defs":[["vt.","安定，安顿；定居；解决，调停；结算，支付 vi.定居；下沉；平静，稳定",false]],"tier":"l","hint":"解决、定居。词组 settle down 定居、settle a problem 解决问题","ex":"They settled the problem peacefully.（他们和平解决了问题。）"},{"id":481,"day":8,"w":"short","ph":"ʃɔːrt","defs":[["a.","短的，矮的；(of)缺乏的，不足的 n. (pl.)短裤",false]],"tier":"s"},{"id":482,"day":8,"w":"small","ph":"smɔːl","defs":[["a.","小的，少的",false]],"tier":"s"},{"id":483,"day":8,"w":"smoke","ph":"smoʊk","defs":[["n.","烟，烟尘 vi./vt.冒烟，冒气；吸烟，抽烟",false]],"tier":"l","hint":"吸烟、烟。词组 smoke a cigarette 吸烟","ex":"He gave up smoking last year.（他去年戒烟了。）"},{"id":484,"day":8,"w":"so","ph":"soʊ","defs":[["conj.","因此，那么；结果是；为的是，以便 ad.那么，如此地；非常，很；也，同样；不错，确 实；这样，那样",false]],"tier":"s"},{"id":485,"day":8,"w":"spend","ph":"spend","defs":[["vt.","花费，消耗；度过，消磨 vi.花费，浪费；耗尽",false]],"tier":"l","hint":"花费。过去式 spent。词组 spend...on 花…在、spend...doing 花时间做","ex":"He spent two hours doing his homework.（他花两小时写作业。）"},{"id":486,"day":8,"w":"spice","ph":"spaɪs","defs":[["n.","香料，（肉桂、姜、辣椒粉等）调味品 vi.使活泼生动；给……增添趣味",false]],"tier":"l","hint":"香料。联想 spicy 辣的、spice 香料","ex":"She added some spice to the dish.（她给菜加了香料。）"},{"id":487,"day":8,"w":"standard","ph":"ˈstændərd","defs":[["n.","标准，规格",false]],"tier":"l","hint":"标准。词组 standard of living 生活水平","ex":"The quality meets the standard.（质量达标。）"},{"id":488,"day":8,"w":"suck","ph":"sʌk","defs":[["vt.","吮，啜，吸；吸人，吸取",false]],"tier":"l","hint":"吸、吮。联想 suck 吸、suck the juice 吸汁","ex":"The baby sucked the milk from the bottle.（婴儿从瓶里吸奶。）"},{"id":489,"day":8,"w":"temporary","ph":"ˈtempəreri","defs":[["a.","暂时的，临时的",false]],"tier":"l","hint":"临时的。联想 permanent 永久的（反义）","ex":"He found a temporary job.（他找了份临时工作。）"},{"id":490,"day":8,"w":"test","ph":"test","defs":[["vi.","/vt./n.测验，试验，检验",false]],"tier":"l","hint":"测试、考试。词组 take a test 参加考试、pass the test 通过测试","ex":"We have a test tomorrow.（我们明天有考试。）"},{"id":491,"day":8,"w":"though","ph":"ðoʊ","defs":[["conj.","尽管，虽然 ad.可是，然而",false]],"tier":"l","hint":"虽然、但是。联想 although 虽然（同义）","ex":"Though he is old, he works hard.（虽然年纪大，他仍努力工作。）"},{"id":492,"day":8,"w":"throw","ph":"θroʊ","defs":[["vt.","投，扔，拋；摔落，摔倒",false]],"tier":"l","hint":"扔。过去式 threw。词组 throw away 扔掉","ex":"Don't throw rubbish on the ground.（别往地上扔垃圾。）"},{"id":493,"day":8,"w":"treatment","ph":"ˈtriːtmənt","defs":[["n.","待遇，对待；治疗，疗法",false]],"tier":"l","hint":"treat（治疗）+ -ment → 治疗、对待","ex":"He is receiving treatment for his illness.（他在接受治疗。）"},{"id":494,"day":8,"w":"twist","ph":"twɪst","defs":[["vi.","/vt.歪曲，曲解 n.搓，捻，拧，扭；扭转，扭曲",false]],"tier":"l","hint":"扭、拧。词组 twist one's ankle 扭伤脚踝","ex":"She twisted the cap off the bottle.（她拧开了瓶盖。）"},{"id":495,"day":8,"w":"verb","ph":"vɜːrb","defs":[["n.","动词",false]],"tier":"l","hint":"动词（语法术语）。联想 noun 名词、verb 动词","ex":"\"Run\" is a verb.（\"跑\"是动词。）"},{"id":496,"day":8,"w":"view","ph":"vjuː","defs":[["n.","观察；眼界；观点，见解，看法；景色，风景 vt.看待，考虑，观察",false]],"tier":"l","hint":"景色、观点。词组 in view of 鉴于、point of view 观点","ex":"The room has a beautiful view of the sea.（房间能看到美丽的海景。）"},{"id":497,"day":8,"w":"weather","ph":"ˈweðər","defs":[["n.","天气，气象",false]],"tier":"l","hint":"天气。词组 weather forecast 天气预报","ex":"The weather is fine today.（今天天气很好。）"},{"id":498,"day":9,"w":"amount","ph":"əˈmaʊnt","defs":[["n.","数量，数额，总数 vt. (to)合计，相当于，等同",false]],"tier":"l","hint":"数量、总数。词组 a large amount of 大量的","ex":"A large amount of money was spent on the project.（这个项目花了很多钱。）"},{"id":499,"day":9,"w":"arrange","ph":"əˈreɪndʒ","defs":[["vt.","整理，布置；安排，筹备",true]],"tier":"f","ety":"a-（到）+ range（排列）→ 排成一列 → 安排","mem":"a + range（范围、排列）→ 把东西排进\"范围\"里 → 安排。画面：把书一本本排好","ex":"arrange a meeting · Let's arrange a meeting next week.（我们下周安排个会议吧。）","nua":"arrange to do（安排做）、arrange for sb to do（安排某人做）；名词 arrangement"},{"id":500,"day":9,"w":"blood","ph":"blʌd","defs":[["n.","血，血液；血统，血亲",false]],"tier":"l","hint":"血。联想 bleed 流血、blood pressure 血压","ex":"The doctor checked his blood pressure.（医生给他量了血压。）"},{"id":501,"day":9,"w":"board","ph":"bɔːrd","defs":[["n.","板，木板，纸板；董事会，理事会 vt.上船/车/飞机",false]],"tier":"l","hint":"木板、董事会、上（船）。词组 on board 在船上/上船","ex":"The students got on board the bus.（学生们上了公交车。）"},{"id":502,"day":9,"w":"book","ph":"bʊk","defs":[["n.","书，书籍 vt.定，预订",false]],"tier":"l","hint":"书、预订。词组 book a ticket 订票","ex":"I booked a room for the night.（我订了一间房过夜。）"},{"id":503,"day":9,"w":"church","ph":"tʃɜːrtʃ","defs":[["n.","教堂，(C-)教会",false]],"tier":"l","hint":"教堂。联想 go to church 去做礼拜","ex":"They go to church on Sundays.（他们周日去做礼拜。）"},{"id":504,"day":9,"w":"cloud","ph":"klaʊd","defs":[["n.","云，云状物",false]],"tier":"l","hint":"云。联想 cloudy 多云的","ex":"There are many clouds in the sky.（天空中有很多云。）"},{"id":505,"day":9,"w":"comfort","ph":"ˈkʌmfərt","defs":[["vt.","/n.慰问，安慰 n.安逸，舒适",false]],"tier":"l","hint":"舒适、安慰。词组 comfort sb 安慰某人","ex":"Her words comforted me a lot.（她的话让我很安慰。）"},{"id":506,"day":9,"w":"company","ph":"ˈkʌmpəni","defs":[["n.","公司，商号；陪伴，同伴",false]],"tier":"l","hint":"一词多义：公司、陪伴。词组 keep sb company 陪伴某人","ex":"He works for a big company.（他在一家大公司工作。）"},{"id":507,"day":9,"w":"concert","ph":"ˈkɑːnsərt","defs":[["n.","音乐会，演奏会",false]],"tier":"l","hint":"音乐会。词组 go to a concert 去听音乐会","ex":"They went to a concert last night.（他们昨晚去听了音乐会。）"},{"id":508,"day":9,"w":"confuse","ph":"kənˈfjuːz","defs":[["vt.","使混淆，搞乱",false]],"tier":"l","hint":"使困惑。词组 be confused about 对…困惑","ex":"The difficult question confused me.（这道难题让我困惑。）"},{"id":509,"day":9,"w":"correct","ph":"kəˈrekt","defs":[["a.","正确的；恰当的，合适的 vt.改正，修改，矫正",false]],"tier":"l","hint":"正确的、改正。联想 right 对的（同义）","ex":"Please correct my mistakes.（请纠正我的错误。）"},{"id":510,"day":9,"w":"creature","ph":"ˈkriːtʃər","defs":[["n.","人，动物，生物",false]],"tier":"l","hint":"create（创造）+ -ure → 生物。联想 animal 动物、creature 生物","ex":"The sea is full of strange creatures.（海里满是奇怪的生物。）"},{"id":511,"day":9,"w":"delicate","ph":"ˈdelɪkət","defs":[["a.","易碎的；精美的；微妙的",true]],"tier":"f","ety":"拉丁 delicatus（令人愉悦的、精致的）","mem":"de + lic + ate → 精致得像甜点，\"吃\"（ate）都舍不得 → 精美的、易碎的。画面：捧着一只薄瓷杯","ex":"delicate balance · The body keeps a delicate balance.（身体保持着微妙的平衡。）","nua":"delicate（易碎、精美、微妙）、fragile（易碎的，侧重脆弱）；delicate balance 微妙平衡"},{"id":512,"day":9,"w":"difference","ph":"ˈdɪfrəns","defs":[["n.","差别，差异；分歧，争论",false]],"tier":"l","hint":"different（不同的）的名词 → 差异。词组 make a difference 有影响","ex":"There is a big difference between the two words.（这两个词有很大差异。）"},{"id":513,"day":9,"w":"distant","ph":"ˈdɪstənt","defs":[["a.","远的，疏远的，冷漠的",false]],"tier":"l","hint":"distance（距离）的形容词 → 遥远的","ex":"We could hear distant thunder.（我们能听到远处的雷声。）"},{"id":514,"day":9,"w":"employment","ph":"ɪmˈplɔɪmənt","defs":[["n.","职业，就业；雇用",false]],"tier":"l","hint":"employ（雇用）+ -ment → 就业","ex":"The city offers many employment opportunities.（这座城市提供很多就业机会。）"},{"id":515,"day":9,"w":"entertain","ph":"ˌentərˈteɪn","defs":[["vt.","使欢乐，使娱乐；招待",true]],"tier":"f","ety":"enter-（在…之间）+ tain（抓，同 ten-）→ 抓住注意力 → 娱乐","mem":"enter + tain（=抓）→ 进（enter）门把客人\"抓\"住、哄开心 → 招待、娱乐。画面：主人热情迎客","ex":"entertain guests · They entertained their guests with music.（他们用音乐招待客人。）","nua":"entertain（娱乐、招待）、entertainment（娱乐，名词）；entertaining（有趣的）"},{"id":516,"day":9,"w":"everything","ph":"ˈevriθɪŋ","defs":[["pron.","事事，凡事，一切东西",false]],"tier":"l","hint":"every（每）+ thing（东西）→ 一切","ex":"Everything is ready for the party.（聚会的一切都准备好了。）"},{"id":517,"day":9,"w":"examine","ph":"ɪɡˈzæmɪn","defs":[["vt.","检验，审査，调查；考试",false]],"tier":"l","hint":"检查、考试。联想 examination 考试（名词）","ex":"The doctor examined the patient carefully.（医生仔细检查了病人。）"},{"id":518,"day":9,"w":"favo(u)rable","ph":"ˈfevərəbəl","defs":[["a.","顺利的，有利的；称赞的，赞成的",false]],"tier":"l","hint":"favour（支持）+ -able → 有利的。词组 be favourable to 赞成","ex":"The weather is favourable for the trip.（天气有利于旅行。）"},{"id":519,"day":9,"w":"fill","ph":"fɪl","defs":[["vt.","装满，充满，填充；占据，担任，补缺",false]],"tier":"l","hint":"填满。词组 fill in 填写、fill...with 用…装满","ex":"Please fill in this form.（请填写这张表格。）"},{"id":520,"day":9,"w":"financial","ph":"faɪˈnænʃl","defs":[["a.","财政的，金融的",false]],"tier":"l","hint":"finance（财政）+ -ial → 财政的、金融的","ex":"The company is in financial trouble.（公司陷入财务困境。）"},{"id":521,"day":9,"w":"fish","ph":"fɪʃ","defs":[["n.","鱼 vi.捕鱼，钓鱼",false]],"tier":"l","hint":"鱼、钓鱼。词组 go fishing 去钓鱼","ex":"There are many fish in the river.（河里有很多鱼。）"},{"id":522,"day":9,"w":"float","ph":"floʊt","defs":[["vi.","浮动，漂浮 n.漂浮物，浮子，浮标",false]],"tier":"l","hint":"漂浮。联想 boat 船（浮在水上）","ex":"Wood floats on water.（木头浮在水面上。）"},{"id":523,"day":9,"w":"god","ph":"ɡɑːd","defs":[["n.","神；[G-]上帝",false]],"tier":"l","hint":"神、上帝。联想 God 上帝（大写）","ex":"They pray to God for peace.（他们向上帝祈祷和平。）"},{"id":524,"day":9,"w":"gradual","ph":"ˈɡrædʒuəl","defs":[["a.","逐渐的，逐步的",false]],"tier":"l","hint":"gradual 逐渐的。联想 gradually 逐渐地（副词）","ex":"There was a gradual change in the weather.（天气逐渐变化。）"},{"id":525,"day":9,"w":"growth","ph":"ɡroʊθ","defs":[["n.","生长；增长",false]],"tier":"l","hint":"grow（生长）+ -th → 增长。联想 -th 名词后缀","ex":"The city has seen rapid growth.（这座城市增长迅速。）"},{"id":526,"day":9,"w":"history","ph":"ˈhɪstri","defs":[["n.","历史；来历，经历，履历；病历，病史",false]],"tier":"l","hint":"历史。联想 historical 历史的、historic 有历史意义的","ex":"We study history at school.（我们在学校学历史。）"},{"id":527,"day":9,"w":"human","ph":"ˈhjuːmən","defs":[["a.","人的，人类的 n.人",false]],"tier":"l","hint":"人类的、人。联想 human being 人类","ex":"It's human nature to make mistakes.（犯错是人的天性。）"},{"id":528,"day":9,"w":"least","ph":"liːst","defs":[["a.","最小的，最少的",false]],"tier":"l","hint":"最少的。词组 at least 至少","ex":"You should sleep at least eight hours.（你应该至少睡八小时。）"},{"id":529,"day":9,"w":"little","ph":"ˈlɪtl","defs":[["a.","小的；不多的，少到几乎没有的 ad./n.不多，几乎没有",false]],"tier":"l","hint":"小的、少的。词组 a little 一点、little by little 逐渐","ex":"There is little water in the bottle.（瓶子里几乎没有水了。）"},{"id":530,"day":9,"w":"marry","ph":"ˈmæri","defs":[["vt.","结婚，嫁，娶",false]],"tier":"l","hint":"结婚。词组 marry sb 娶/嫁给某人、be married to 与…结婚","ex":"They married two years ago.（他们两年前结婚了。）"},{"id":531,"day":9,"w":"mineral","ph":"ˈmɪnərəl","defs":[["n.","矿物，矿石 a.矿物的，矿质的",false]],"tier":"l","hint":"矿物质。联想 mineral water 矿泉水","ex":"The area is rich in minerals.（这个地区矿产丰富。）"},{"id":532,"day":9,"w":"needle","ph":"ˈniːdl","defs":[["n.","针，指针，针状物",false]],"tier":"l","hint":"针。联想 sew 缝（用 needle）","ex":"She sewed the button with a needle.（她用针缝扣子。）"},{"id":533,"day":9,"w":"opposite","ph":"ˈɑːpəzət","defs":[["a.","对面的，对立的，相反的 n.对立物，对立面 prep.在……对面",false]],"tier":"l","hint":"相反的、对面。词组 be opposite to 与…相反","ex":"The bank is opposite the school.（银行在学校对面。）"},{"id":534,"day":9,"w":"organ","ph":"ˈɔːrɡən","defs":[["n.","器官；风琴；机构",false]],"tier":"l","hint":"器官、风琴。联想 organ 器官（身体器官）","ex":"The heart is an important organ.（心脏是重要的器官。）"},{"id":535,"day":9,"w":"participate","ph":"pɑːrˈtɪsɪpeɪt","defs":[["vi.","参与，参加",true]],"tier":"f","ety":"part（部分）+ -icipate（拿）→ 拿一份 → 参与","mem":"part（部分）+ i + cipate → 拿\"一部分\"（part）→ 参与。画面：分到一份活儿","ex":"participate in · Students should participate in class activities.（学生应参与课堂活动。）","nua":"participate in（参与，正式）、take part in（参加，口语）；名词 participation"},{"id":536,"day":9,"w":"pointed","ph":"ˈpɔɪntɪd","defs":[["a.","尖的；尖锐的，严厉的",false]],"tier":"l","hint":"point（点）+ -ed → 尖的、尖锐的","ex":"The cat has pointed ears.（这只猫有尖耳朵。）"},{"id":537,"day":9,"w":"politician","ph":"ˌpɑːləˈtɪʃn","defs":[["n.","政客，政治家",false]],"tier":"l","hint":"politics（政治）+ -ian（人）→ 政治家","ex":"The politician gave a speech.（这位政治家发表了演讲。）"},{"id":538,"day":9,"w":"possibly","ph":"ˈpɑːsəbli","defs":[["ad.","可能，也许",false]],"tier":"l","hint":"possible（可能的）+ -ly → 可能地","ex":"It may possibly rain tomorrow.（明天可能会下雨。）"},{"id":539,"day":9,"w":"prisoner","ph":"ˈprɪznər","defs":[["n.","囚徒",false]],"tier":"l","hint":"prison（监狱）+ -er（人）→ 囚犯","ex":"The prisoner escaped from the prison.（囚犯越狱了。）"},{"id":540,"day":9,"w":"protective","ph":"prəˈtektɪv","defs":[["a.","保护的，防卫的",false]],"tier":"l","hint":"protect（保护）+ -ive → 保护的","ex":"Wear protective clothing at work.（工作时穿防护服。）"},{"id":541,"day":9,"w":"public","ph":"ˈpʌblɪk","defs":[["a.","公共的，公用的；公众的，公开的，公然的 n.公众，大众",false]],"tier":"l","hint":"公共的。词组 in public 公开地、public transport 公共交通","ex":"Smoking is not allowed in public places.（公共场所禁止吸烟。）"},{"id":542,"day":9,"w":"purple","ph":"ˈpɜːrpl","defs":[["a.","/n.紫色",false]],"tier":"l","hint":"紫色。联想颜色词：red、blue、purple","ex":"She wore a purple dress.（她穿了条紫色裙子。）"},{"id":543,"day":9,"w":"reach","ph":"riːtʃ","defs":[["vt.","伸手，够到，触到；到，到达 vi.达到，延伸；伸出手 n.能达到的范围",false]],"tier":"l","hint":"到达、够到。词组 reach an agreement 达成协议","ex":"We reached the top of the mountain at noon.（中午我们到达了山顶。）"},{"id":544,"day":9,"w":"recognize/-se","ph":"ˈrekəɡnaɪz","defs":[["vt.","认出，识别；承认",false]],"tier":"l","hint":"认出、识别。联想 re-（再）+ cognize（知道）→ 再知道 → 认出","ex":"I recognized him at once.（我立刻认出了他。）"},{"id":545,"day":9,"w":"representative","ph":"ˌreprɪˈzentətɪv","defs":[["n.","代表，代理人 a.典型的，有代表性的",false]],"tier":"l","hint":"represent（代表）+ -ative → 代表。词组 a representative of 代表","ex":"He is a representative of the company.（他是公司的代表。）"},{"id":546,"day":9,"w":"result","ph":"rɪˈzʌlt","defs":[["n.","结果，成果，成绩 vi.产生于，来自；结果；导致",false]],"tier":"l","hint":"结果。词组 as a result 结果、as a result of 由于","ex":"He worked hard and as a result he passed the exam.（他努力学习，结果通过了考试。）"},{"id":547,"day":9,"w":"romantic","ph":"roʊˈmæntɪk","defs":[["a.","浪漫的，传奇式的；不切实际的，好幻想的",false]],"tier":"l","hint":"浪漫的。音译词，联想\"罗曼蒂克\"","ex":"They had a romantic dinner.（他们吃了顿浪漫的晚餐。）"},{"id":548,"day":9,"w":"sexual","ph":"ˈsekʃuəl","defs":[["a.","性的；性别的",false]],"tier":"l","hint":"sex（性别）+ -ual → 性的、性别的","ex":"The law protects against sexual discrimination.（法律保护免受性别歧视。）"},{"id":549,"day":9,"w":"silly","ph":"ˈsɪli","defs":[["a.","愚蠢的",false]],"tier":"l","hint":"愚蠢的、傻的。联想 foolish 傻的（同义）","ex":"Don't ask such a silly question.（别问这么傻的问题。）"},{"id":550,"day":9,"w":"sound","ph":"saʊnd","defs":[["n.","声音，声响 vi.发声；听起来 a.健康的，健全的；正当的，有根据的",false]],"tier":"l","hint":"一词多义：声音、听起来、健全的。词组 sound like 听起来像","ex":"The music sounds beautiful.（这音乐听起来很美。）"},{"id":551,"day":9,"w":"square","ph":"skwer","defs":[["n.","广场；正方形；平方 a.正方（形）（的），平方（的）",false]],"tier":"l","hint":"广场、正方形。联想 square 正方形","ex":"People gathered in the square.（人们聚集在广场。）"},{"id":552,"day":9,"w":"steady","ph":"ˈstedi","defs":[["a.","稳定，不变；稳固，平稳；坚定，扎实 vi./vt.（使）稳定",false]],"tier":"l","hint":"稳定的。联想 stable 稳定的（同义）","ex":"He has a steady job.（他有份稳定的工作。）"},{"id":553,"day":9,"w":"struggle","ph":"ˈstrʌɡl","defs":[["vi.","/n.斗争，奋斗，努力",false]],"tier":"l","hint":"挣扎、奋斗。词组 struggle for 为…奋斗","ex":"They struggled for freedom.（他们为自由而奋斗。）"},{"id":554,"day":9,"w":"swing","ph":"swɪŋ","defs":[["vi.","摇摆，摇荡；回转，转向 n.秋千",false]],"tier":"l","hint":"摇摆、秋千。联想 swing 荡秋千","ex":"The children are playing on the swing.（孩子们在荡秋千。）"},{"id":555,"day":9,"w":"threat","ph":"θret","defs":[["n.","威胁，危险迹象",false]],"tier":"l","hint":"威胁。联想 threaten 威胁（动词）","ex":"Pollution is a threat to our health.（污染是对我们健康的威胁。）"},{"id":556,"day":9,"w":"tower","ph":"ˈtaʊər","defs":[["n.","塔，高楼",false]],"tier":"l","hint":"塔。联想 tower 塔、Eiffel Tower 埃菲尔铁塔","ex":"The tower is very tall.（这座塔很高。）"},{"id":557,"day":9,"w":"useful","ph":"ˈjuːsfl","defs":[["a.","有用的，实用的；有益的，有帮助的",false]],"tier":"l","hint":"use（用）+ -ful → 有用的","ex":"This dictionary is very useful.（这本词典很有用。）"},{"id":558,"day":9,"w":"vehicle","ph":"ˈviːəkl","defs":[["n.","车辆，交通工具",false]],"tier":"l","hint":"车辆、交通工具。联想 car、bus 都是 vehicle","ex":"The road is full of vehicles.（路上满是车辆。）"},{"id":559,"day":9,"w":"victory","ph":"ˈvɪktəri","defs":[["n.","胜利，获胜",false]],"tier":"l","hint":"胜利。联想 win 赢、victory 胜利（名词）","ex":"The team celebrated their victory.（球队庆祝他们的胜利。）"},{"id":560,"day":9,"w":"wide","ph":"waɪd","defs":[["a.","宽阔的，广泛的 ad.完全地，充分地",false]],"tier":"l","hint":"宽的。联想 narrow 窄的（反义）、width 宽度（名词）","ex":"The river is very wide here.（这条河在这里很宽。）"},{"id":561,"day":10,"w":"address","ph":"ˈædres","defs":[["n.","地址，通讯处 vt./n.致词，讲话 vt.致函；写地址",false]],"tier":"l","hint":"地址、演讲。词组 home address 家庭住址","ex":"Please write your address here.（请在这里写下你的地址。）"},{"id":562,"day":10,"w":"arrival","ph":"əˈraɪvl","defs":[["n.","到来，到达",true]],"tier":"f","ety":"arrive（到达）+ -al（名词）→ 到达","mem":"arrive + al → 到达的名词。画面：列车进站","ex":"on arrival · We'll contact you on arrival.（我们一到就联系你。）","nua":"on arrival（一到就）、arrival 不可数多；arrive at/in（到达）"},{"id":563,"day":10,"w":"breed","ph":"briːd","defs":[["v.","/n. 繁殖，饲养；品种",true]],"tier":"f","ety":"古英语 brēdan（养育）","mem":"谐音\"布瑞德\"→ 养\"布\"谷鸟一样繁衍 → 繁殖。画面：一窝小动物","ex":"breed animals · Farmers breed animals for food.（农民饲养动物供食用。）","nua":"breed（繁殖、品种）、raise（饲养）；breed 的过去式 bred"},{"id":564,"day":10,"w":"broadcast","ph":"ˈbrɔːdkæst","defs":[["n.","/vt.广播，播音",false]],"tier":"l","hint":"broad（广）+ cast（投）→ 广播。联想 broadcast 广播节目","ex":"The news was broadcast on TV.（新闻在电视上播出了。）"},{"id":565,"day":10,"w":"certain","ph":"ˈsɜːrtn","defs":[["a.","确实的，可靠的；某一，某些；一定的，必然的",false]],"tier":"l","hint":"确定的、某个。词组 be certain of 确信、certain 某（些）","ex":"I am certain that he will come.（我确信他会来。）"},{"id":566,"day":10,"w":"comfortable","ph":"ˈkʌmftəbl","defs":[["a.","舒适的，舒服的",false]],"tier":"l","hint":"comfort（舒适）+ -able → 舒适的","ex":"This chair is very comfortable.（这把椅子很舒服。）"},{"id":567,"day":10,"w":"compete","ph":"kəmˈpiːt","defs":[["vi.","比赛，竞赛",true]],"tier":"f","ety":"com-（一起）+ pete（追求，同 pet-）→ 一起追求 → 竞争","mem":"com（一起）+ pete（追求）→ 一起\"追求\"同一目标 → 竞争。画面：赛跑你追我赶","ex":"compete with · We must compete with other companies.（我们必须与其他公司竞争。）","nua":"compete with/against（与…竞争）、compete for（争夺）；名词 competition、形容词 competitive"},{"id":568,"day":10,"w":"container","ph":"kənˈteɪnər","defs":[["n.","容器，集装箱",false]],"tier":"l","hint":"contain（包含）+ -er → 容器","ex":"Put the food in a container.（把食物放进容器里。）"},{"id":569,"day":10,"w":"criticism","ph":"ˈkrɪtɪsɪzəm","defs":[["n.","批评，评论",true]],"tier":"f","ety":"critic（批评家）+ -ism（名词）→ 批评","mem":"criticize（批评）+ ism → 批评的名词。联想前面学的 criticize","ex":"accept criticism · It's hard to accept criticism.（接受批评很难。）","nua":"criticism（批评，不可数）、comment（评论，中性）；constructive criticism 建设性批评"},{"id":570,"day":10,"w":"cross","ph":"krɔːs","defs":[["vi.","/vt.越过，穿过；使交叉，使相交 n.十字形，十字架 a.交叉的，横穿的",false]],"tier":"l","hint":"穿过、十字。词组 cross the road 过马路","ex":"Be careful when you cross the road.（过马路时要小心。）"},{"id":571,"day":10,"w":"decorate","ph":"ˈdekəreɪt","defs":[["vt.","装饰，装点",false]],"tier":"l","hint":"装饰。词组 decorate...with 用…装饰","ex":"They decorated the room with flowers.（他们用鲜花装饰房间。）"},{"id":572,"day":10,"w":"dependent","ph":"dɪˈpendənt","defs":[["a.","(on/upon)依靠的，依赖的，从属的",false]],"tier":"l","hint":"depend（依赖）+ -ent → 依赖的。词组 be dependent on 依赖","ex":"Children are dependent on their parents.（孩子依赖父母。）"},{"id":573,"day":10,"w":"destroy","ph":"dɪˈstrɔɪ","defs":[["vt.","破坏，摧毁；消灭，扑灭；打破，粉碎",false]],"tier":"l","hint":"破坏、毁灭。联想 destroy 摧毁、ruin 毁坏","ex":"The fire destroyed the whole building.（大火摧毁了整栋楼。）"},{"id":574,"day":10,"w":"direct","ph":"dəˈrekt","defs":[["a.","/ad.径直的/地，直接的/地；率直的/地 vt.把……对准；指示；管理，指导",false]],"tier":"l","hint":"直接的、指导。联想 indirect 间接的（反义）","ex":"Is there a direct train to Beijing?（有直达北京的火车吗？）"},{"id":575,"day":10,"w":"drug","ph":"drʌɡ","defs":[["n.","药品；(pl.)麻醉药，毒品",false]],"tier":"l","hint":"药、毒品。词组 take drugs 吸毒","ex":"Drugs are harmful to health.（毒品对健康有害。）"},{"id":576,"day":10,"w":"either","ph":"ˈaɪðər","defs":[["pron.","（两者中）任何一方，任何一个 ad.[与not连用]也（不）；[与or连用]或……或……， 不是……就是……",false]],"tier":"l","hint":"两者之一、也。词组 either...or 要么…要么","ex":"You can take either of the two books.（这两本书你可以拿任何一本。）"},{"id":577,"day":10,"w":"electronic","ph":"ɪˌlekˈtrɑːnɪk","defs":[["a.","电子的",false]],"tier":"l","hint":"electric（电的）+ -onic → 电子的。词组 electronic mail 电子邮件","ex":"Electronic products are popular now.（电子产品现在很流行。）"},{"id":578,"day":10,"w":"emotion","ph":"ɪˈmoʊʃn","defs":[["n.","情感，情绪",true]],"tier":"f","ety":"e-（出）+ mot（动，同 move）+ -ion → 心里涌动出来 → 情感","mem":"e + motion（动作）→ 情绪让你\"动\"起来 → 情感。画面：内心波动","ex":"control one's emotion · She couldn't control her emotion.（她无法控制情绪。）","nua":"emotion（强烈情感）、feeling（感受，更宽泛）；emotional（情感的、情绪化的）"},{"id":579,"day":10,"w":"employer","ph":"ɪmˈplɔɪər","defs":[["n.","雇主",false]],"tier":"l","hint":"employ（雇用）+ -er（人）→ 雇主。联想 employee 雇员","ex":"The employer praised his workers.（雇主表扬了他的工人。）"},{"id":580,"day":10,"w":"enough","ph":"ɪˈnʌf","defs":[["a.","/n.足够，充足 ad.足够地",false]],"tier":"l","hint":"足够的。词组 enough to do 足够做","ex":"We have enough time to finish the work.（我们有足够时间完成工作。）"},{"id":581,"day":10,"w":"ever","ph":"ˈevər","defs":[["ad.","曾经，在任何时候",false]],"tier":"l","hint":"曾经、无论何时。词组 for ever 永远","ex":"Have you ever been to Beijing?（你去过北京吗？）"},{"id":582,"day":10,"w":"exchange","ph":"ɪksˈtʃeɪndʒ","defs":[["vt.","/n.交换，交流；调换，兑换 n.交换台，交易所",false]],"tier":"l","hint":"交换、交流。词组 exchange...for 用…换","ex":"We exchanged ideas at the meeting.（我们在会上交流了想法。）"},{"id":583,"day":10,"w":"extremely","ph":"ɪkˈstriːmli","defs":[["ad.","极，非常",false]],"tier":"l","hint":"extreme（极端的）+ -ly → 极其","ex":"The weather is extremely cold today.（今天天气极其寒冷。）"},{"id":584,"day":10,"w":"form","ph":"fɔːrm","defs":[["n.","形状，形式，方式；类型，结构；表格，格式 vt.形成，构成，组成",false]],"tier":"l","hint":"形式、表格、形成。词组 fill in a form 填表","ex":"Please fill in this form with your name.（请在表格里填上你的名字。）"},{"id":585,"day":10,"w":"grow","ph":"ɡroʊ","defs":[["vi.","生长；增长，发展；渐渐变得，成为；种植，栽培 vt.种植，栽种",false]],"tier":"l","hint":"生长、种植、变成。词组 grow up 长大","ex":"The children are growing up fast.（孩子们长得很快。）"},{"id":586,"day":10,"w":"hide","ph":"haɪd","defs":[["vt.","隐藏，躲藏；隐瞒 vi.(躲)藏",false]],"tier":"l","hint":"隐藏。过去式 hid。词组 hide from 躲避","ex":"The cat hid behind the door.（猫藏在门后。）"},{"id":587,"day":10,"w":"introduce","ph":"ˌɪntrəˈduːs","defs":[["vt.","介绍；引进，传入；提出",false]],"tier":"l","hint":"介绍。词组 introduce...to 把…介绍给","ex":"Let me introduce myself.（让我自我介绍一下。）"},{"id":588,"day":10,"w":"invent","ph":"ɪnˈvent","defs":[["vt.","发明，创造；捏造，虚构",false]],"tier":"l","hint":"发明。联想 inventor 发明家、invention 发明（名词）","ex":"Edison invented the electric light.（爱迪生发明了电灯。）"},{"id":589,"day":10,"w":"joke","ph":"dʒoʊk","defs":[["n.","笑话，玩笑 vi.说笑话，开玩笑",false]],"tier":"l","hint":"笑话。词组 play a joke on 开…的玩笑、tell a joke 讲笑话","ex":"He told us a funny joke.（他给我们讲了个有趣的笑话。）"},{"id":590,"day":10,"w":"knock","ph":"nɑːk","defs":[["n.","/vi./vt.敲，敲打；碰撞",false]],"tier":"l","hint":"敲。词组 knock at 敲、knock down 撞倒","ex":"Someone is knocking at the door.（有人在敲门。）"},{"id":591,"day":10,"w":"knowledge","ph":"ˈnɑːlɪdʒ","defs":[["n.","知识，学识；知道，了解",false]],"tier":"l","hint":"know（知道）+ -ledge → 知识","ex":"Knowledge is power.（知识就是力量。）"},{"id":592,"day":10,"w":"lay","ph":"leɪ","defs":[["vt.","放，搁；下（蛋）；铺设，敷设；设置，布置",false]],"tier":"l","hint":"放、下蛋。过去式 laid。联想 lie（躺）lay（放）","ex":"He laid the book on the table.（他把书放在桌上。）"},{"id":593,"day":10,"w":"lid","ph":"lɪd","defs":[["n.","盖",false]],"tier":"l","hint":"盖子。联想 cover 盖（同义）","ex":"Please put the lid on the pot.（请把锅盖盖上。）"},{"id":594,"day":10,"w":"log","ph":"lɔːɡ","defs":[["n.","原木，木料",false]],"tier":"l","hint":"原木、日志。词组 log in 登录","ex":"Please log in to your account.（请登录你的账户。）"},{"id":595,"day":10,"w":"lord","ph":"lɔːrd","defs":[["n.","[L-]上帝，主；主人，长官",false]],"tier":"l","hint":"领主、上帝。联想 Lord 上帝（大写）","ex":"The lord owned the whole village.（领主拥有整个村庄。）"},{"id":596,"day":10,"w":"loss","ph":"lɔːs","defs":[["n.","丧失，丢失；亏损，损失；失败",false]],"tier":"l","hint":"lose（失去）的名词 → 损失。词组 at a loss 不知所措","ex":"The company suffered a great loss.（公司遭受了巨大损失。）"},{"id":597,"day":10,"w":"manner","ph":"ˈmænər","defs":[["n.","方式，方法；态度，举止；(pl.)礼貌，规矩",false]],"tier":"l","hint":"方式、礼貌。词组 in this manner 以这种方式、manners 礼貌","ex":"He has good manners.（他很有礼貌。）"},{"id":598,"day":10,"w":"mass","ph":"mæs","defs":[["n.","团，块，堆；(pl.)群众，民众；众多，大量；[物]质量",false]],"tier":"l","hint":"大量、群众。词组 a mass of 大量的、the masses 群众","ex":"A mass of people gathered in the square.（一大群人聚集在广场。）"},{"id":599,"day":10,"w":"matter","ph":"ˈmætər","defs":[["n.","物质，物体；事情，情况；毛病，麻烦事 vi.要紧，有关系",false]],"tier":"l","hint":"事情、要紧。词组 no matter 无论、as a matter of fact 事实上","ex":"It doesn't matter if you are late.（你迟到也没关系。）"},{"id":600,"day":10,"w":"meal","ph":"miːl","defs":[["n.","一餐，一顿饭，膳食",false]],"tier":"l","hint":"一顿饭。词组 three meals a day 一日三餐","ex":"We have three meals a day.（我们一日三餐。）"},{"id":601,"day":10,"w":"partner","ph":"ˈpɑːrtnər","defs":[["n.","伙伴，合伙人，舞伴；配偶，搭档",false]],"tier":"l","hint":"伙伴、搭档。联想 partner 合伙人","ex":"They are business partners.（他们是商业伙伴。）"},{"id":602,"day":10,"w":"path","ph":"pæθ","defs":[["n.","小路，路线，途径",false]],"tier":"l","hint":"小路、路径。联想 road 大路、path 小路","ex":"We walked along the path in the forest.（我们沿着林间小路走。）"},{"id":603,"day":10,"w":"piano","ph":"piˈænoʊ","defs":[["n.","钢琴",false]],"tier":"l","hint":"钢琴。词组 play the piano 弹钢琴","ex":"She plays the piano very well.（她钢琴弹得很好。）"},{"id":604,"day":10,"w":"pipe","ph":"paɪp","defs":[["n.","管子，导管；烟斗；笛",false]],"tier":"l","hint":"管子、烟斗。联想 water pipe 水管","ex":"The water pipe is broken.（水管破了。）"},{"id":605,"day":10,"w":"potato","ph":"pəˈteɪtoʊ","defs":[["n.","马铃薯",false]],"tier":"l","hint":"土豆。联想 tomato 西红柿（都常见蔬菜）","ex":"We had potatoes for dinner.（我们晚饭吃了土豆。）"},{"id":606,"day":10,"w":"pound","ph":"paʊnd","defs":[["n.","磅；英镑 vi./vt.猛击，击碎",false]],"tier":"l","hint":"英镑、磅。词组 a pound 一磅","ex":"The book costs five pounds.（这本书五英镑。）"},{"id":607,"day":10,"w":"prize","ph":"praɪz","defs":[["n.","奖，奖金，奖品 vt.珍视，珍惜",false]],"tier":"l","hint":"奖品、奖赏。词组 win a prize 获奖","ex":"She won the first prize in the contest.（她在比赛中获得一等奖。）"},{"id":608,"day":10,"w":"see","ph":"siː","defs":[["vt.","看见；理解，明白；会见，见面；获悉，知道",false]],"tier":"l","hint":"看见、明白。词组 see sb off 送行、see you 再见","ex":"I can see the mountain from here.（我从这里能看见那座山。）"},{"id":609,"day":10,"w":"sight","ph":"saɪt","defs":[["n.","视力，视觉；望见，瞥见；情景，奇观；(pl.)风景， 名胜",false]],"tier":"l","hint":"视力、景象。词组 at first sight 乍一看、catch sight of 看见","ex":"The Great Wall is a wonderful sight.（长城是奇观。）"},{"id":610,"day":10,"w":"sleep","ph":"sliːp","defs":[["vi.","/n.睡（眠）",false]],"tier":"l","hint":"睡觉。过去式 slept。词组 go to sleep 入睡","ex":"I sleep eight hours every night.（我每晚睡八小时。）"},{"id":611,"day":10,"w":"slight","ph":"slaɪt","defs":[["a.","轻微的，细微的；纤细的，瘦弱的",false]],"tier":"l","hint":"轻微的。词组 a slight mistake 小错误","ex":"There is a slight problem with the plan.（计划有个小问题。）"},{"id":612,"day":10,"w":"smooth","ph":"smuːð","defs":[["a.","光滑的，平滑的；平稳的，顺利的",false]],"tier":"l","hint":"光滑的、顺利的。联想 rough 粗糙的（反义）","ex":"The road is very smooth.（这条路很平坦。）"},{"id":613,"day":10,"w":"spot","ph":"spɑːt","defs":[["n.","地点，场所；点，斑点，污点 vt.认出，认清；玷污，弄脏",false]],"tier":"l","hint":"地点、斑点。词组 on the spot 当场","ex":"This is a beautiful spot for a picnic.（这是野餐的好地方。）"},{"id":614,"day":10,"w":"steam","ph":"stiːm","defs":[["n.","（蒸）汽 vt.发出蒸汽；行驶 vt.蒸煮",false]],"tier":"l","hint":"蒸汽。联想 steam 蒸汽、steam engine 蒸汽机","ex":"The water is giving off steam.（水在冒蒸汽。）"},{"id":615,"day":10,"w":"street","ph":"striːt","defs":[["n.","街道，马路",false]],"tier":"l","hint":"街道。联想 road 路、street 街道","ex":"The street is crowded with people.（街上挤满了人。）"},{"id":616,"day":10,"w":"string","ph":"strɪŋ","defs":[["n.","一串，一行，一列；弦，线，绳",false]],"tier":"l","hint":"绳子、细线。联想 rope 粗绳、string 细绳","ex":"She tied the package with a string.（她用绳子捆包裹。）"},{"id":617,"day":10,"w":"surface","ph":"ˈsɜːrfɪs","defs":[["n.","面，表面；外表，外观",false]],"tier":"l","hint":"表面。词组 on the surface 表面上","ex":"The surface of the lake is calm.（湖面平静。）"},{"id":618,"day":10,"w":"then","ph":"ðen","defs":[["ad.","在那时，当时；那么，因而；然后，于是",false]],"tier":"l","hint":"然后、那时。词组 by then 到那时","ex":"We had dinner and then watched TV.（我们吃了晚饭，然后看电视。）"},{"id":619,"day":10,"w":"upstairs","ph":"ˌʌpˈsterz","defs":[["ad.","在楼上，往楼上",false]],"tier":"l","hint":"up（上）+ stairs（楼梯）→ 楼上。联想 downstairs 楼下（反义）","ex":"The bedroom is upstairs.（卧室在楼上。）"},{"id":620,"day":10,"w":"violence","ph":"ˈvaɪələns","defs":[["n.","暴力；暴行；激烈，猛烈",false]],"tier":"l","hint":"violent（暴力的）的名词 → 暴力","ex":"We should say no to violence.（我们应该对暴力说不。）"},{"id":621,"day":10,"w":"weave","ph":"wiːv","defs":[["vt.","编织",false]],"tier":"l","hint":"编织。过去式 wove。联想 knit 编织","ex":"She is weaving a basket.（她在编篮子。）"},{"id":622,"day":10,"w":"wheel","ph":"wiːl","defs":[["n.","轮，车轮",false]],"tier":"l","hint":"轮子。联想 wheel 轮子、steering wheel 方向盘","ex":"The wheel of the car is turning.（车轮在转。）"},{"id":623,"day":10,"w":"wine","ph":"waɪn","defs":[["n.","（葡萄）酒，果酒",false]],"tier":"l","hint":"葡萄酒。联想 beer 啤酒、wine 葡萄酒","ex":"He drank a glass of red wine.（他喝了杯红酒。）"},{"id":624,"day":11,"w":"anything","ph":"ˈeniθɪŋ","defs":[["pron.","[否定、疑问、条件句中]任何事（物）；无 论什么事（物）",false]],"tier":"l","hint":"any（任何）+ thing（东西）→ 任何东西","ex":"Is there anything I can do for you?（有什么我能帮你的吗？）"},{"id":625,"day":11,"w":"arrangement","ph":"əˈreɪndʒmənt","defs":[["n.","安排，准备；布置",true]],"tier":"f","ety":"arrange（安排）+ -ment → 安排","mem":"arrange + ment → 安排的名词。联想前面学的 arrange","ex":"make arrangements · We made arrangements for the trip.（我们为旅行做了安排。）","nua":"make arrangements for（为…做准备，常用复数）"},{"id":626,"day":11,"w":"beyond","ph":"bɪˈjɑːnd","defs":[["prep.","在……那边，在……以外；超出，超过 ad.在那边，在远处",false]],"tier":"l","hint":"超出、在…之外。词组 beyond expectation 出乎意料","ex":"The problem is beyond my understanding.（这个问题超出了我的理解。）"},{"id":627,"day":11,"w":"boyfriend","ph":"ˈbɔɪfrend","defs":[["n.","男朋友",false]],"tier":"l","hint":"boy（男孩）+ friend（朋友）→ 男朋友。联想 girlfriend 女朋友","ex":"She went out with her boyfriend.（她和男朋友出去了。）"},{"id":628,"day":11,"w":"brave","ph":"breɪv","defs":[["a.","勇敢的，英勇的",false]],"tier":"l","hint":"勇敢的。联想 courage 勇气（名词）","ex":"The brave firefighter saved the child.（勇敢的消防员救了孩子。）"},{"id":629,"day":11,"w":"charge","ph":"tʃɑːrdʒ","defs":[["vt.","控诉，控告；要价，收费；充电 n.罪名，指控；收费；主管，看管；充电",false]],"tier":"l","hint":"一词多义：收费、负责、充电。词组 in charge of 负责、charge...for 收费","ex":"He is in charge of the project.（他负责这个项目。）"},{"id":630,"day":11,"w":"check","ph":"tʃek","defs":[["vt.","/n.检査，核对；制止，控制 n.支票，账单",false]],"tier":"l","hint":"检查、支票。词组 check in 登记入住、check out 结账离开","ex":"Please check your answers before handing in.（交卷前请检查答案。）"},{"id":631,"day":11,"w":"cigarette(te)","ph":"ˈsɪɡəret","defs":[["n.","香烟；纸烟",false]],"tier":"l","hint":"香烟。联想 smoke 吸烟","ex":"Smoking cigarettes is bad for health.（吸烟有害健康。）"},{"id":632,"day":11,"w":"commit","ph":"kəˈmɪt","defs":[["vt.","犯（罪），干（错事）；承诺",true]],"tier":"f","ety":"com-（一起）+ mit（送，同 miss）→ 一起送出 → 投入、犯","mem":"com + mit（=送）→ 把自己\"送\"进去 → 犯（罪）、投入。画面：一失足成千古恨","ex":"commit a crime · He committed a serious crime.（他犯了重罪。）","nua":"commit a crime（犯罪）、be committed to（致力于）；commit 还有\"承诺\"义"},{"id":633,"day":11,"w":"competitor","ph":"kəmˈpetɪtər","defs":[["n.","竞争对手",false]],"tier":"l","hint":"compete（竞争）+ -or（人）→ 竞争者","ex":"He beat all his competitors.（他击败了所有竞争对手。）"},{"id":634,"day":11,"w":"crazy","ph":"ˈkreɪzi","defs":[["a.","疯狂的，蠢的；(about)狂热爱好，着迷的",false]],"tier":"l","hint":"疯狂的、着迷的。词组 be crazy about 对…着迷","ex":"She is crazy about dancing.（她对跳舞着迷。）"},{"id":635,"day":11,"w":"curl","ph":"kɜːrl","defs":[["n.","卷曲，卷发 vt.弄卷 vi.卷曲，弯曲",false]],"tier":"l","hint":"卷曲。联想 curl 卷发、curly 卷曲的","ex":"She has curly hair.（她有一头卷发。）"},{"id":636,"day":11,"w":"deliver","ph":"dɪˈlɪvər","defs":[["vt.","交付，递送；释放，解救；发表，表达",false]],"tier":"l","hint":"递送、发表。词组 deliver a speech 发表演讲","ex":"The postman delivered the letters.（邮递员送信。）"},{"id":637,"day":11,"w":"discovery","ph":"dɪˈskʌvəri","defs":[["n.","发现",false]],"tier":"l","hint":"discover（发现）+ -y → 发现","ex":"The discovery changed our understanding.（这个发现改变了我们的认识。）"},{"id":638,"day":11,"w":"distance","ph":"ˈdɪstəns","defs":[["n.","距离，路程；远方，远处",false]],"tier":"l","hint":"距离。词组 in the distance 在远处","ex":"The school is within walking distance.（学校在步行可达的距离内。）"},{"id":639,"day":11,"w":"dress","ph":"dres","defs":[["n.","服装，女装 vt.给……穿衣，打扮",false]],"tier":"l","hint":"穿衣、连衣裙。词组 dress up 盛装、get dressed 穿衣服","ex":"She is wearing a beautiful dress.（她穿着漂亮的连衣裙。）"},{"id":640,"day":11,"w":"enjoyment","ph":"ɪnˈdʒɔɪmənt","defs":[["n.","令人愉快的事，享受",false]],"tier":"l","hint":"enjoy（享受）+ -ment → 乐趣","ex":"Reading gives me great enjoyment.（阅读给我很大乐趣。）"},{"id":641,"day":11,"w":"excellent","ph":"ˈeksələnt","defs":[["a.","优秀的，杰出的，卓越的",false]],"tier":"l","hint":"优秀的。联想 good 好、excellent 极好的","ex":"She is an excellent student.（她是优秀的学生。）"},{"id":642,"day":11,"w":"floor","ph":"flɔːr","defs":[["n.","地面，地板；楼梯，楼面",false]],"tier":"l","hint":"地板、楼层。词组 on the floor 在地板上","ex":"The book fell on the floor.（书掉到地板上。）"},{"id":643,"day":11,"w":"glad","ph":"ɡlæd","defs":[["a.","高兴，愉快；乐意",false]],"tier":"l","hint":"高兴的。词组 be glad to 高兴做","ex":"I'm glad to meet you.（很高兴认识你。）"},{"id":644,"day":11,"w":"gold","ph":"ɡoʊld","defs":[["n.","金，黄金；金币；金黄色 a.金的，金制的",false]],"tier":"l","hint":"金子。联想 golden 金色的","ex":"The ring is made of gold.（这枚戒指是金的。）"},{"id":645,"day":11,"w":"government","ph":"ˈɡʌvərnmənt","defs":[["n.","政府，内阁；管理，支配；政治，政体",false]],"tier":"l","hint":"govern（治理）+ -ment → 政府","ex":"The government passed a new law.（政府通过了一项新法律。）"},{"id":646,"day":11,"w":"law","ph":"lɔː","defs":[["n.","法律，法规；规律，法则，定律",false]],"tier":"l","hint":"法律。词组 obey the law 守法、break the law 违法","ex":"Everyone must obey the law.（每个人都必须守法。）"},{"id":647,"day":11,"w":"limit","ph":"ˈlɪmɪt","defs":[["n.","界线，限度；(pl.)范围 vt.限制，限定",false]],"tier":"l","hint":"限制、限度。词组 limit to 限制在","ex":"There is a speed limit on this road.（这条路上有限速。）"},{"id":648,"day":11,"w":"mathematics","ph":"ˌmæθəˈmætɪks","defs":[["n.","数学",false]],"tier":"l","hint":"数学（缩写 math）。联想 maths 数学","ex":"Mathematics is difficult for me.（数学对我来说很难。）"},{"id":649,"day":11,"w":"measure","ph":"ˈmeʒər","defs":[["n.","度量，测量；(pl.)措施，办法 vt.量，测量；有……长（宽/高等）",false]],"tier":"l","hint":"测量、措施。词组 take measures 采取措施","ex":"We must take measures to protect the environment.（我们必须采取措施保护环境。）"},{"id":650,"day":11,"w":"mile","ph":"maɪl","defs":[["n.","英里",false]],"tier":"l","hint":"英里。联想 kilometer 公里、mile 英里","ex":"The village is five miles away.（村子在五英里外。）"},{"id":651,"day":11,"w":"mixture","ph":"ˈmɪkstʃər","defs":[["n.","混合，混合物",false]],"tier":"l","hint":"mix（混合）+ -ture → 混合物","ex":"The city is a mixture of old and new.（这座城市新旧交融。）"},{"id":652,"day":11,"w":"model","ph":"ˈmɑːdl","defs":[["n.","样式；模型，原型，模特儿；模范，典型 vt.做……的模型；(after/on/upon)模仿",false]],"tier":"l","hint":"模型、模特。词组 a model of 模型","ex":"He made a model of a plane.（他做了个飞机模型。）"},{"id":653,"day":11,"w":"much","ph":"mʌtʃ","defs":[["n.","/a.许多（的），大量（的） ad.非常，更，……得多",false]],"tier":"l","hint":"许多（修饰不可数）。词组 too much 太多","ex":"There is too much noise here.（这里太吵了。）"},{"id":654,"day":11,"w":"musician","ph":"mjuˈzɪʃn","defs":[["n.","音乐家，乐师",false]],"tier":"l","hint":"music（音乐）+ -ian（人）→ 音乐家","ex":"Beethoven was a great musician.（贝多芬是伟大的音乐家。）"},{"id":655,"day":11,"w":"never","ph":"ˈnevər","defs":[["ad.","从不，永不；决不",false]],"tier":"l","hint":"从不。词组 never mind 没关系","ex":"I have never been to the sea.（我从未去过海边。）"},{"id":656,"day":11,"w":"oxygen","ph":"ˈɑːksɪdʒən","defs":[["n.","氧",false]],"tier":"l","hint":"氧气。联想 breathe 呼吸（吸氧气）","ex":"Plants give off oxygen.（植物释放氧气。）"},{"id":657,"day":11,"w":"people","ph":"ˈpiːpl","defs":[["n.","人，人们，人民；民族",false]],"tier":"l","hint":"人们（复数）。联想 person 人（单数）","ex":"Many people like to travel.（很多人喜欢旅行。）"},{"id":658,"day":11,"w":"pile","ph":"paɪl","defs":[["n.","堆 vi./vt.堆，迭，堆积",false]],"tier":"l","hint":"堆。词组 a pile of 一堆","ex":"There is a pile of books on the desk.（桌上有一堆书。）"},{"id":659,"day":11,"w":"polish","ph":"ˈpoʊlɪʃ","defs":[["vt.","(用擦亮剂等)擦光，擦亮 n.擦亮剂，上光剂",false]],"tier":"l","hint":"擦亮、波兰。词组 polish the shoes 擦鞋","ex":"He polished his shoes before going out.（他出门前擦了鞋。）"},{"id":660,"day":11,"w":"prayer","ph":"prer","defs":[["n.","祈祷，祷告，祷文",false]],"tier":"l","hint":"pray（祈祷）+ -er → 祈祷、祷文","ex":"She said a prayer before bed.（她睡前做了祷告。）"},{"id":661,"day":11,"w":"provide","ph":"prəˈvaɪd","defs":[["vt.","提供，供给",false]],"tier":"l","hint":"提供。词组 provide...for/with 为…提供","ex":"The school provides books for students.（学校为学生提供书。）"},{"id":662,"day":11,"w":"ready","ph":"ˈredi","defs":[["a.","准备好的；乐意的，情愿的；迅速的，立即的",false]],"tier":"l","hint":"准备好的。词组 be ready for 准备好、get ready 做好准备","ex":"Are you ready for the exam?（你准备好考试了吗？）"},{"id":663,"day":11,"w":"repair","ph":"rɪˈper","defs":[["n.","修理，修复 vt.修理，修补；补救，纠正",false]],"tier":"l","hint":"修理。联想 fix 修理（同义）","ex":"He repaired the broken bike.（他修好了坏自行车。）"},{"id":664,"day":11,"w":"ring","ph":"rɪŋ","defs":[["n.","戒指；圆圈，环；铃声，钟声；打电话 vt.敲钟，打铃",false]],"tier":"l","hint":"一词多义：戒指、铃声、打电话。过去式 rang","ex":"The phone is ringing.（电话在响。）"},{"id":665,"day":11,"w":"roll","ph":"roʊl","defs":[["vi.","/vt.滚动，转动；卷，绕 n.卷，卷状物，面包卷；名册，名单",false]],"tier":"l","hint":"滚动、卷。词组 roll up 卷起","ex":"The ball rolled down the hill.（球滚下了山坡。）"},{"id":666,"day":11,"w":"room","ph":"ruːm","defs":[["n.","房间，室；余地，空间",false]],"tier":"l","hint":"房间、空间。词组 make room for 为…腾空间","ex":"There is no room for more people.（没有空间容纳更多人了。）"},{"id":667,"day":11,"w":"run","ph":"rʌn","defs":[["vi.","奔，跑；逃跑；流，淌；蔓延；经营；运转 vt.使滑动，使移动；经营，管理；操纵；运送",false]],"tier":"l","hint":"跑、经营。过去式 ran。词组 run out of 用完","ex":"He runs every morning.（他每天早晨跑步。）"},{"id":668,"day":11,"w":"set","ph":"set","defs":[["vt.","放置；调整；树立，规定；使处于特定状态 vi.(日、月等）落山，下沉 n.一套，一付 a.固定的，规定的",false]],"tier":"l","hint":"放置、设置、一套。词组 set up 建立、set off 出发","ex":"They set up a new company.（他们成立了一家新公司。）"},{"id":669,"day":11,"w":"severe","ph":"sɪˈvɪr","defs":[["a.","严厉，严格；严重，凛冽；严峻，艰难",false]],"tier":"l","hint":"严重的、严厉的。词组 severe weather 恶劣天气","ex":"The area suffered a severe flood.（这个地区遭受了严重洪水。）"},{"id":670,"day":11,"w":"signal","ph":"ˈsɪɡnəl","defs":[["n.","信号，暗号 vi.发信号，打暗号",false]],"tier":"l","hint":"信号。联想 sign 标志、signal 信号","ex":"The traffic signal turned red.（交通信号灯变红了。）"},{"id":671,"day":11,"w":"someone","ph":"ˈsʌmwʌn","defs":[["pron.","某人，有人",false]],"tier":"l","hint":"some（某）+ one（人）→ 某人","ex":"Someone is knocking at the door.（有人在敲门。）"},{"id":672,"day":11,"w":"sour","ph":"ˈsaʊər","defs":[["a.","酸的，酸腐的；脾气坏的，刻薄的",false]],"tier":"l","hint":"酸的。联想 sweet 甜的、sour 酸的、bitter 苦的","ex":"The milk has turned sour.（牛奶变酸了。）"},{"id":673,"day":11,"w":"stage","ph":"steɪdʒ","defs":[["n.","阶段，时期；舞台，戏剧",false]],"tier":"l","hint":"舞台、阶段。词组 on stage 在舞台上","ex":"She sang on stage for the first time.（她第一次在舞台上唱歌。）"},{"id":674,"day":11,"w":"steal","ph":"stiːl","defs":[["vt.","偷，窃取",false]],"tier":"l","hint":"偷。过去式 stole。联想 thief 小偷","ex":"Someone stole his wallet.（有人偷了他的钱包。）"},{"id":675,"day":11,"w":"stiff","ph":"stɪf","defs":[["a.","硬，僵直；生硬，死板",false]],"tier":"l","hint":"僵硬的。联想 stiff 僵硬、flexible 灵活的（反义）","ex":"My neck feels stiff this morning.（今早我的脖子很僵硬。）"},{"id":676,"day":11,"w":"surprising","ph":"sərˈpraɪzɪŋ","defs":[["a.","令人惊讶的",false]],"tier":"l","hint":"surprise（惊奇）+ -ing → 令人惊讶的","ex":"The news is very surprising.（这消息很令人惊讶。）"},{"id":677,"day":11,"w":"sweet","ph":"swiːt","defs":[["a.","甜的，香的；悦耳/悦目的；可爱的 n. (pl.)糖果，甜食",false]],"tier":"l","hint":"甜的。联想 candy 糖果（sweet）","ex":"The cake is too sweet.（这个蛋糕太甜了。）"},{"id":678,"day":11,"w":"switch","ph":"swɪtʃ","defs":[["n.","转换，转变；电闸，开关；突然转向 vi.改变，交换",false]],"tier":"l","hint":"开关、转换。词组 switch on 打开、switch off 关掉","ex":"Please switch off the light.（请关灯。）"},{"id":679,"day":11,"w":"sympathy","ph":"ˈsɪmpəθi","defs":[["n.","同情，同情心；赞同，同感",false]],"tier":"l","hint":"sym-（共同）+ pathy（感受）→ 同情。词组 have sympathy for 同情","ex":"We all have sympathy for the victims.（我们都同情受害者。）"},{"id":680,"day":11,"w":"thought","ph":"θɔːt","defs":[["n.","思想，思维，思考；想法，观念",false]],"tier":"l","hint":"think（想）的过去式/名词 → 想法","ex":"He lost himself in thought.（他陷入沉思。）"},{"id":681,"day":11,"w":"tough","ph":"tʌf","defs":[["a.","坚韧的，难嚼烂的；结实的；艰巨的，困难的",false]],"tier":"l","hint":"艰难的、坚强的。联想 tough 艰难、rough 粗糙","ex":"It was a tough decision to make.（这是个艰难的决定。）"},{"id":682,"day":11,"w":"transparent","ph":"trænsˈpærənt","defs":[["a.","透明的",false]],"tier":"l","hint":"trans-（穿过）+ parent → 透明的。联想 transparent 透明的","ex":"Glass is transparent.（玻璃是透明的。）"},{"id":683,"day":11,"w":"white","ph":"waɪt","defs":[["a.","白的，白色的；苍白的；白种的 n.白色；白种人",false]],"tier":"l","hint":"白色。联想 black 黑色（反义）","ex":"She wore a white dress.（她穿了条白裙子。）"},{"id":684,"day":11,"w":"who","ph":"huː","defs":[["pron.","谁，什么人；[限制性关系代词]……人；[非 限制性关系代词]他/她，他们",false]],"tier":"l","hint":"谁。词组 who else 还有谁","ex":"Who is that man?（那个人是谁？）"},{"id":685,"day":11,"w":"window","ph":"ˈwɪndoʊ","defs":[["n.","窗，窗户",false]],"tier":"l","hint":"窗户。联想 door 门、window 窗","ex":"Please open the window.（请打开窗户。）"},{"id":686,"day":12,"w":"advise","ph":"ədˈvaɪz","defs":[["vt.","忠告，劝告，建议",true]],"tier":"f","ety":"ad-（向）+ vise（看，同 vis-）→ 帮人看清 → 建议","mem":"ad + vise（=vision 看）→ 帮人\"看清\"方向 → 建议。画面：指路人","ex":"advise sb to do · The doctor advised him to rest.（医生建议他休息。）","nua":"advise（动词，s 发音 /z/）、advice（名词，c 发音 /s/）；advise sb to do / advise doing"},{"id":687,"day":12,"w":"asleep","ph":"əˈsliːp","defs":[["a.","睡着的",false]],"tier":"l","hint":"a-（在）+ sleep（睡）→ 睡着的。词组 fall asleep 入睡","ex":"The baby fell asleep quickly.（婴儿很快睡着了。）"},{"id":688,"day":12,"w":"association","ph":"əˌsoʊʃiˈeɪʃn","defs":[["n.","协会，团体；交往；联合，合伙",false]],"tier":"l","hint":"associate（联系）+ -ion → 协会、联系","ex":"He joined a football association.（他加入了一个足球协会。）"},{"id":689,"day":12,"w":"before","ph":"bɪˈfɔːr","defs":[["prep.","/conj.在……之前 prep.在……前面 ad.从前，早些时候",false]],"tier":"l","hint":"在…之前。词组 before long 不久","ex":"Please finish it before Friday.（请在周五前完成。）"},{"id":690,"day":12,"w":"belt","ph":"belt","defs":[["n.","带，腰带",false]],"tier":"l","hint":"腰带、地带。词组 seat belt 安全带","ex":"Please fasten your seat belt.（请系好安全带。）"},{"id":691,"day":12,"w":"biology","ph":"baɪˈɑːlədʒi","defs":[["n.","生物学",true]],"tier":"f","ety":"bio（生命）+ -logy（学问）→ 生命科学 → 生物学","mem":"bio（生命）+ logy（学）→ 研究\"生命\"的学问 → 生物学。画面：显微镜下的细胞","ex":"study biology · She wants to study biology at college.（她想在大学学生物。）","nua":"-logy 学科后缀：biology 生物、psychology 心理、geology 地质、technology 技术"},{"id":692,"day":12,"w":"brown","ph":"braʊn","defs":[["a.","/n.棕色",false]],"tier":"l","hint":"棕色。联想颜色词：red、brown","ex":"He has brown eyes.（他有棕色的眼睛。）"},{"id":693,"day":12,"w":"coat","ph":"koʊt","defs":[["n.","外套，上衣；涂层 vt.涂上，包上",false]],"tier":"l","hint":"外套。联想 jacket 夹克、coat 大衣","ex":"Put on your coat, it's cold outside.（穿上外套，外面冷。）"},{"id":694,"day":12,"w":"common","ph":"ˈkɑːmən","defs":[["a.","普通的，平常的；公共的，共同的",false]],"tier":"l","hint":"共同的、普通的。词组 in common 共同、common sense 常识","ex":"They have a lot in common.（他们有很多共同点。）"},{"id":695,"day":12,"w":"confident","ph":"ˈkɑːnfɪdənt","defs":[["a.","确信的，有自信的",false]],"tier":"l","hint":"confidence（自信）的形容词 → 自信的。词组 be confident of 对…有信心","ex":"She is confident of passing the exam.（她自信能通过考试。）"},{"id":696,"day":12,"w":"cupboard","ph":"ˈkʌbərd","defs":[["n.","碗柜",true]],"tier":"f","ety":"cup（杯）+ board（板）→ 放杯子的板柜 → 碗柜","mem":"cup + board → 放\"杯子\"的\"板\"柜 → 碗柜。注意 p 不发音（读 /ˈkʌbərd/）","ex":"a kitchen cupboard · The plates are in the cupboard.（盘子在碗柜里。）","nua":"cupboard 的 p 不发音；合成词拆分帮助拼写"},{"id":697,"day":12,"w":"deep","ph":"diːp","defs":[["a.","深的，深刻的；深奥的；深切的 ad.深深地",false]],"tier":"l","hint":"深的。联想 shallow 浅的（反义）、depth 深度（名词）","ex":"The river is very deep here.（这条河在这里很深。）"},{"id":698,"day":12,"w":"dictionary","ph":"ˈdɪkʃəneri","defs":[["n.","字典，词典",false]],"tier":"l","hint":"词典。联想 look up a word in the dictionary 查词典","ex":"Look up the word in the dictionary.（在词典里查这个单词。）"},{"id":699,"day":12,"w":"enclose","ph":"ɪnˈkloʊz","defs":[["vt.","包围，围住；附上",true]],"tier":"f","ety":"en-（使）+ close（关）→ 关进去 → 包围","mem":"en + close → 使\"关\"（close）进去 → 包围、封入。画面：把信封进信封","ex":"enclose a photo · I enclose a photo with the letter.（我在信中附上一张照片。）","nua":"enclose（围住、附上）、enclosure（附件、围场）；en- 使动前缀：enable、enrich"},{"id":700,"day":12,"w":"excuse","ph":"ɪkˈskjuːs","defs":[["vt.","原谅 n.借口，理由",false]],"tier":"l","hint":"原谅、借口。词组 excuse me 对不起","ex":"Excuse me, where is the station?（请问，车站在哪里？）"},{"id":701,"day":12,"w":"flood","ph":"flʌd","defs":[["n.","洪水，水灾 vi./vt.泛滥，淹没",false]],"tier":"l","hint":"洪水。联想 flood 洪水、drought 干旱","ex":"The flood destroyed many houses.（洪水摧毁了很多房子。）"},{"id":702,"day":12,"w":"forget","ph":"fərˈɡet","defs":[["vi.","/vt.忘记，遗忘",false]],"tier":"l","hint":"忘记。过去式 forgot。词组 forget to do 忘记要做、forget doing 忘记做过","ex":"Don't forget to lock the door.（别忘了锁门。）"},{"id":703,"day":12,"w":"golf","ph":"ɡɑːlf","defs":[["n.","高尔夫球",false]],"tier":"l","hint":"高尔夫。音译词。词组 play golf 打高尔夫","ex":"He plays golf every weekend.（他每周末打高尔夫。）"},{"id":704,"day":12,"w":"grandparent","ph":"ˈɡrænperənt","defs":[["n.","(外)祖父，（外)祖母",false]],"tier":"l","hint":"grand（隔代）+ parent（父母）→ 祖父母","ex":"My grandparents live in the countryside.（我祖父母住在乡下。）"},{"id":705,"day":12,"w":"heart","ph":"hɑːrt","defs":[["n.","心，心脏；中心，要点；内心，心肠",false]],"tier":"l","hint":"心。词组 learn by heart 记住、break one's heart 伤某人的心","ex":"Please learn the poem by heart.（请把这首诗背下来。）"},{"id":706,"day":12,"w":"heaven","ph":"ˈhevn","defs":[["n.","天堂，天国；天，天空；[H-]上帝，神",false]],"tier":"l","hint":"天堂。联想 hell 地狱（反义）","ex":"The old man believes in heaven.（这位老人相信有天堂。）"},{"id":707,"day":12,"w":"hurry","ph":"ˈhɜːri","defs":[["vi.","/n.赶忙，匆忙，慌忙",false]],"tier":"l","hint":"匆忙。词组 hurry up 赶快、in a hurry 匆忙","ex":"Hurry up, or we'll be late.（快点，否则我们要迟到了。）"},{"id":708,"day":12,"w":"industrial","ph":"ɪnˈdʌstriəl","defs":[["a.","工业的，产业的",true]],"tier":"f","ety":"industry（工业）+ -al（形容词）→ 工业的","mem":"industry + al → 工业的。画面：工厂烟囱","ex":"industrial development · Industrial development is rapid here.（这里的工业发展很快。）","nua":"industrial（工业的）、industrious（勤奋的，易混淆）；industry 工业/勤奋"},{"id":709,"day":12,"w":"influence","ph":"ˈɪnfluəns","defs":[["vt.","影响，感化 n.势力，权势；影响，感化",false]],"tier":"l","hint":"影响。词组 have an influence on 对…有影响","ex":"Parents have a great influence on children.（父母对孩子有很大影响。）"},{"id":710,"day":12,"w":"instruction","ph":"ɪnˈstrʌkʃn","defs":[["n.","(pl.)指令，指示，说明；教学，教导",false]],"tier":"l","hint":"instruct（指导）+ -ion → 指示、说明。词组 follow the instructions 遵循说明","ex":"Read the instructions before using it.（使用前先读说明书。）"},{"id":711,"day":12,"w":"joint","ph":"dʒɔɪnt","defs":[["n.","关节，骨节；接合处，接缝 a.联合的，共同的，连接的",false]],"tier":"l","hint":"关节、联合的。词组 joint effort 共同努力","ex":"This is a joint effort of the whole team.（这是全队的共同努力。）"},{"id":712,"day":12,"w":"list","ph":"lɪst","defs":[["n.","表，目录，名单 vt.列举，把……编列成表",false]],"tier":"l","hint":"名单、列表。词组 a shopping list 购物清单","ex":"Please make a list of what you need.（请把你需要的列个清单。）"},{"id":713,"day":12,"w":"lonely","ph":"ˈloʊnli","defs":[["a.","孤独的，寂寞的；荒凉的，人迹稀少的",false]],"tier":"l","hint":"孤独的。联想 alone 单独的、lonely 孤独的（情绪）","ex":"He felt lonely in the big city.（他在大城市里感到孤独。）"},{"id":714,"day":12,"w":"melt","ph":"melt","defs":[["vi.","/vt.熔化，融化",false]],"tier":"l","hint":"融化。联想 ice melts 冰融化","ex":"The snow melts in spring.（雪在春天融化。）"},{"id":715,"day":12,"w":"money","ph":"ˈmʌni","defs":[["n.","货币，金钱",false]],"tier":"l","hint":"钱。词组 make money 赚钱、save money 省钱","ex":"He saves money to buy a car.（他攒钱买车。）"},{"id":716,"day":12,"w":"multiply","ph":"ˈmʌltɪplaɪ","defs":[["vi.","/vt.乘；增加；繁殖",false]],"tier":"l","hint":"乘、增加。联想 multi-（多）+ ply → 变多 → 乘","ex":"If you multiply 3 by 4, you get 12.（3 乘以 4 等于 12。）"},{"id":717,"day":12,"w":"on","ph":"ɑːn","defs":[["prep.","在……上；靠近,在……旁；关于,有关；在…… 时候；朝,向,针对；凭,根据；向前,(继续)下去；在从 事……中,处于……情况；在……供职,(是)……成员 ad.(放/穿/连接)上；向前；(继续)下去",false]],"tier":"l","hint":"在…上。词组 on time 准时、on duty 值班","ex":"The book is on the desk.（书在桌子上。）"},{"id":718,"day":12,"w":"origin","ph":"ˈɔːrɪdʒɪn","defs":[["n.","起源，由来；出身，血统",false]],"tier":"l","hint":"起源。联想 original 最初的（同源）","ex":"What is the origin of this custom?（这个习俗的起源是什么？）"},{"id":719,"day":12,"w":"partly","ph":"ˈpɑːrtli","defs":[["ad.","在一定程度上，部分地，不完全地",false]],"tier":"l","hint":"part（部分）+ -ly → 部分地","ex":"The story is partly true.（这个故事部分是真的。）"},{"id":720,"day":12,"w":"plant","ph":"plænt","defs":[["n.","植物；工厂 vt.种，植，播",false]],"tier":"l","hint":"一词多义：植物、工厂、种植。词组 plant trees 种树","ex":"We plant trees every spring.（我们每年春天种树。）"},{"id":721,"day":12,"w":"point","ph":"pɔɪnt","defs":[["vi.","/vt.指 n.尖端，头；点，小数点；论点，观点，要点；得分",false]],"tier":"l","hint":"点、指出。词组 point out 指出、point to 指向","ex":"Please point out the mistakes in my work.（请指出我作业中的错误。）"},{"id":722,"day":12,"w":"political","ph":"pəˈlɪtɪkl","defs":[["a.","政治的",true]],"tier":"f","ety":"polit（城市，同 policy）+ -ical → 治理城市 → 政治的","mem":"policy（政策）+ tical → 跟\"政策\"有关 → 政治的。画面：议会大厅","ex":"political issue · This is a sensitive political issue.（这是个敏感的政治议题。）","nua":"political（政治的）、politics（政治，学科）、politician（政客）；police 也同源（治理城邦）"},{"id":723,"day":12,"w":"politics","ph":"ˈpɑːlətɪks","defs":[["n.","政治；政见，政纲",false]],"tier":"l","hint":"政治（学科）。联想 political 政治的","ex":"He is interested in politics.（他对政治感兴趣。）"},{"id":724,"day":12,"w":"pray","ph":"preɪ","defs":[["vi.","祈祷，祈求；请求，恳求",false]],"tier":"l","hint":"祈祷。词组 pray for 为…祈祷","ex":"They prayed for good weather.（他们祈祷好天气。）"},{"id":725,"day":12,"w":"prison","ph":"ˈprɪzn","defs":[["n.","监狱",false]],"tier":"l","hint":"监狱。词组 in prison 在狱中、be sent to prison 入狱","ex":"He was sent to prison for the crime.（他因犯罪入狱。）"},{"id":726,"day":12,"w":"quite","ph":"kwaɪt","defs":[["ad.","完全，十分；相当，颇",false]],"tier":"l","hint":"相当、完全。词组 quite a few 相当多","ex":"The film is quite interesting.（这部电影相当有趣。）"},{"id":727,"day":12,"w":"recently","ph":"ˈriːsntli","defs":[["ad.","最近，新近",false]],"tier":"l","hint":"recent（最近的）+ -ly → 最近","ex":"I have been very busy recently.（我最近很忙。）"},{"id":728,"day":12,"w":"refusal","ph":"rɪˈfjuːzl","defs":[["n.","拒绝，回绝",true]],"tier":"f","ety":"refuse（拒绝）+ -al（名词）→ 拒绝","mem":"refuse + al → 拒绝的名词（注意 refuse 结尾 e 去掉）。画面：摇头摆手","ex":"a flat refusal · He gave a flat refusal.（他断然拒绝。）","nua":"refuse（动词拒绝）、refusal（名词拒绝）、reject（拒绝，更强烈）；a flat refusal 断然拒绝"},{"id":729,"day":12,"w":"remove","ph":"rɪˈmuːv","defs":[["vt.","排除，消除，去掉；搬迁，移动，运走",false]],"tier":"l","hint":"移除。词组 remove...from 从…移除","ex":"Please remove the books from the table.（请把书从桌上拿走。）"},{"id":730,"day":12,"w":"repeat","ph":"rɪˈpiːt","defs":[["vi.","/vt.重复，重说，重做；背，背诵 n.重复",false]],"tier":"l","hint":"重复。词组 repeat after me 跟我读","ex":"Please repeat what I said.（请重复我说的话。）"},{"id":731,"day":12,"w":"roof","ph":"ruːf","defs":[["n.","屋顶",false]],"tier":"l","hint":"屋顶。联想 house 房子、roof 屋顶","ex":"The rain is beating on the roof.（雨打在屋顶上。）"},{"id":732,"day":12,"w":"round","ph":"raʊnd","defs":[["a.","圆的，球形的；往返的 prep.围绕 ad.在周围 n.一圈，一周；巡回",false]],"tier":"l","hint":"圆的、围绕。词组 all year round 全年","ex":"The earth is round.（地球是圆的。）"},{"id":733,"day":12,"w":"row","ph":"raʊ","defs":[["n.","(一）排，（一）行 vt.划（船）",false]],"tier":"l","hint":"一排、划船。词组 in a row 连续","ex":"The students sat in the first row.（学生们坐在第一排。）"},{"id":734,"day":12,"w":"sentence","ph":"ˈsentəns","defs":[["n.","判决，宣判；句子 vt.判决，宣判",false]],"tier":"l","hint":"句子、判刑。词组 make a sentence 造句","ex":"Please make a sentence with this word.（请用这个词造句。）"},{"id":735,"day":12,"w":"sharp","ph":"ʃɑːrp","defs":[["a.","锋利的；强烈的；尖刻的；敏锐的；鲜明的；急转 的，突然的；尖声的 ad.(时间）整，准（时）",false]],"tier":"l","hint":"锋利的、敏锐的。联想 dull 钝的（反义）","ex":"Be careful, the knife is sharp.（小心，刀很锋利。）"},{"id":736,"day":12,"w":"shirt","ph":"ʃɜːrt","defs":[["n.","衬衫",false]],"tier":"l","hint":"衬衫。联想 T-shirt T恤","ex":"He wore a white shirt to work.（他穿白衬衫上班。）"},{"id":737,"day":12,"w":"sincere","ph":"sɪnˈsɪr","defs":[["a.","诚恳的，真诚的",false]],"tier":"l","hint":"真诚的。联想 sincerely 真诚地","ex":"Please accept my sincere thanks.（请接受我真诚的感谢。）"},{"id":738,"day":12,"w":"slide","ph":"slaɪd","defs":[["vi.","滑，滑动 n.滑动；幻灯片",false]],"tier":"l","hint":"滑动、滑梯。词组 slide down 滑下","ex":"The children slid down the slope.（孩子们从坡上滑下来。）"},{"id":739,"day":12,"w":"special","ph":"ˈspeʃl","defs":[["a.","专门的，特殊的；特别好的",false]],"tier":"l","hint":"特别的。联想 ordinary 普通的（反义）、especially 尤其","ex":"Today is a special day for me.（今天对我来说很特别。）"},{"id":740,"day":12,"w":"spread","ph":"spred","defs":[["vt.","伸展，展开；散布，传播，蔓延；涂，撒 vi.展开，伸展；传开，蔓延",false]],"tier":"l","hint":"传播、展开。词组 spread out 展开","ex":"The news spread quickly.（消息迅速传播。）"},{"id":741,"day":12,"w":"sticky","ph":"ˈstɪki","defs":[["a.","黏的，有黏性的",false]],"tier":"l","hint":"stick（粘）+ -y → 粘的","ex":"The floor is sticky with sugar.（地板因糖而发粘。）"},{"id":742,"day":12,"w":"tendency","ph":"ˈtendənsi","defs":[["n.","倾向，趋势",false]],"tier":"l","hint":"tend（倾向）+ -ency → 趋势。词组 have a tendency to 倾向于","ex":"There is a tendency to use more technology.（有更多使用科技的趋势。）"},{"id":743,"day":12,"w":"tooth","ph":"tuːθ","defs":[["n.","牙齿；齿，齿状物",false]],"tier":"l","hint":"牙齿（复数 teeth）。词组 brush one's teeth 刷牙","ex":"He brushes his teeth twice a day.（他每天刷两次牙。）"},{"id":744,"day":12,"w":"trap","ph":"træp","defs":[["n.","陷阱，圈套 vt.诱捕，使中圈套",false]],"tier":"l","hint":"陷阱。词组 fall into a trap 落入陷阱","ex":"The hunter set a trap for the animal.（猎人给动物设了陷阱。）"},{"id":745,"day":12,"w":"upset","ph":"ʌpˈset","defs":[["vt.","弄翻，打翻；扰乱，打乱，使不安 vi.倾覆",false]],"tier":"l","hint":"沮丧的、打乱。词组 be upset about 为…心烦","ex":"She was upset about the bad news.（她因坏消息而心烦。）"},{"id":746,"day":12,"w":"western","ph":"ˈwestərn","defs":[["a.","西的，西方的",false]],"tier":"l","hint":"west（西）+ -ern → 西方的。联想 eastern 东方的","ex":"He likes western food.（他喜欢西餐。）"},{"id":747,"day":12,"w":"whip","ph":"wɪp","defs":[["n.","鞭子，车夫 vt.鞭打，抽打",false]],"tier":"l","hint":"鞭子、鞭打。联想 whip 鞭打","ex":"He whipped the horse to go faster.（他鞭打马让它快跑。）"},{"id":748,"day":12,"w":"wind","ph":"wɪnd","defs":[["n.","风",false]],"tier":"l","hint":"风（名词 /wɪnd/）、缠绕（动词 /waɪnd/）。词组 strong wind 大风","ex":"The wind is blowing strongly.（风刮得很猛。）"},{"id":749,"day":13,"w":"advertise","ph":"ˈædvərtaɪz","defs":[["vt.","做广告，宣传",true]],"tier":"f","ety":"ad-（向）+ vert（转，同 vers-）+ -ise → 把注意力转过来 → 广告","mem":"ad + vert（转）+ ise → 让路人把注意力\"转\"过来 → 打广告。画面：霓虹灯吸引眼球","ex":"advertise a product · They advertise their products on TV.（他们在电视上给产品做广告。）","nua":"advertise（动词）、advertisement（名词，广告）；advertise for（登广告招聘）"},{"id":750,"day":13,"w":"another","ph":"əˈnʌðər","defs":[["a.","另一，再一；别的 pron.另一个",false]],"tier":"l","hint":"另一个。词组 one another 互相","ex":"Can I have another cup of tea?（我能再来一杯茶吗？）"},{"id":751,"day":13,"w":"birth","ph":"bɜːrθ","defs":[["n.","出生；出身；起源",false]],"tier":"l","hint":"出生。词组 give birth to 生下、birthday 生日","ex":"She gave birth to a baby boy.（她生了个男孩。）"},{"id":752,"day":13,"w":"bush","ph":"bʊʃ","defs":[["n.","灌木，灌木丛",true]],"tier":"f","ety":"古英语 busc（灌木）","mem":"谐音\"布什\"→ 美国总统布什名字就念 bush → 灌木丛（名字联想）。画面：一丛矮树","ex":"beat around the bush · Stop beating around the bush.（别再拐弯抹角了。）","nua":"beat around the bush（说话绕弯子，习语）"},{"id":753,"day":13,"w":"chain","ph":"tʃeɪn","defs":[["n.","链，链条；一连串，连锁",false]],"tier":"l","hint":"链条、连锁。词组 a chain of 一连串","ex":"He wore a gold chain around his neck.（他脖子上戴着金链子。）"},{"id":754,"day":13,"w":"communication","ph":"kəˌmjuːnɪˈkeɪʃn","defs":[["n.","通讯，通信；交际，交流；传达，传送",false]],"tier":"l","hint":"communicate（交流）+ -ion → 交流","ex":"Good communication is important in a team.（良好的沟通在团队中很重要。）"},{"id":755,"day":13,"w":"connect","ph":"kəˈnekt","defs":[["vt.","连接，联结 vi.连接，相通",false]],"tier":"l","hint":"连接。词组 connect...with 把…连接","ex":"The bridge connects the two cities.（这座桥连接两座城市。）"},{"id":756,"day":13,"w":"cook","ph":"kʊk","defs":[["vt.","烹调，煮，烧 n.炊事员，厨师",false]],"tier":"l","hint":"做饭、厨师。词组 cook dinner 做饭","ex":"My mother cooks dinner for us.（妈妈给我们做饭。）"},{"id":757,"day":13,"w":"cut","ph":"kʌt","defs":[["n.","/vt.切，剪，割，削；删，缩减 n.伤口",false]],"tier":"l","hint":"切、砍。过去式 cut。词组 cut down 砍倒、cut off 切断","ex":"Please cut the apple into pieces.（请把苹果切成块。）"},{"id":758,"day":13,"w":"difficulty","ph":"ˈdɪfɪkəlti","defs":[["n.","困难，难事；困境",false]],"tier":"l","hint":"difficult（困难的）的名词 → 困难。词组 have difficulty in 做…有困难","ex":"He has difficulty in learning English.（他学英语有困难。）"},{"id":759,"day":13,"w":"duty","ph":"ˈduːti","defs":[["n.","职责；义务，责任；税，关税",false]],"tier":"l","hint":"责任、职责。词组 on duty 值班、do one's duty 尽责","ex":"It's our duty to protect the environment.（保护环境是我们的责任。）"},{"id":760,"day":13,"w":"establish","ph":"ɪˈstæblɪʃ","defs":[["vt.","建立，设立，创办；确立，使确认",false]],"tier":"l","hint":"建立。联想 set up 建立（同义）","ex":"They established a new school in the village.（他们在村里建了新学校。）"},{"id":761,"day":13,"w":"feed","ph":"fiːd","defs":[["vt.","喂养，饲养 vi.(牛，马）吃东西 n.伺料",false]],"tier":"l","hint":"喂养。过去式 fed。词组 feed...on 用…喂","ex":"She feeds the baby with milk.（她用牛奶喂宝宝。）"},{"id":762,"day":13,"w":"feeling","ph":"ˈfiːlɪŋ","defs":[["n.","感觉，知觉；情感，心情，情绪",false]],"tier":"l","hint":"feel（感觉）+ -ing → 感觉、感情","ex":"I have a good feeling about this.（我对此感觉很好。）"},{"id":763,"day":13,"w":"few","ph":"fjuː","defs":[["a.","/n.不多(的)，少数(的)，很少(的)，没有几个",false]],"tier":"l","hint":"很少（修饰可数）。词组 a few 几个","ex":"There are a few apples in the basket.（篮子里有几个苹果。）"},{"id":764,"day":13,"w":"fix","ph":"fɪks","defs":[["vt.","固定，安装；修理",false]],"tier":"l","hint":"修理、固定。词组 fix up 修理","ex":"He fixed the broken chair.（他修好了坏椅子。）"},{"id":765,"day":13,"w":"fresh","ph":"freʃ","defs":[["a.","新的，新鲜的；有生气的；清新的，凉爽的； 新颖的，独特的；淡水的",false]],"tier":"l","hint":"新鲜的。词组 fresh air 新鲜空气、fresh fruit 新鲜水果","ex":"Let's go out for some fresh air.（我们出去呼吸新鲜空气吧。）"},{"id":766,"day":13,"w":"friendly","ph":"ˈfrendli","defs":[["a.","友谊的，友好的",false]],"tier":"l","hint":"friend（朋友）+ -ly → 友好的。词组 be friendly to 对…友好","ex":"The people here are friendly to visitors.（这里的人对游客很友好。）"},{"id":767,"day":13,"w":"funny","ph":"ˈfʌni","defs":[["a.","滑稽的，可笑的，有趣的；稀奇的，古怪的",false]],"tier":"l","hint":"fun（乐趣）+ -ny → 有趣的、滑稽的","ex":"He told a funny story.（他讲了个滑稽的故事。）"},{"id":768,"day":13,"w":"furniture","ph":"ˈfɜːrnɪtʃər","defs":[["n.","家具",false]],"tier":"l","hint":"家具（总称，不可数）。联想 furniture 家具","ex":"We bought some new furniture.（我们买了些新家具。）"},{"id":769,"day":13,"w":"hit","ph":"hɪt","defs":[["vt.","/n.打击，击中，碰撞",false]],"tier":"l","hint":"打、击中。过去式 hit。词组 hit on 偶然发现","ex":"The ball hit the window.（球击中了窗户。）"},{"id":770,"day":13,"w":"interest","ph":"ˈɪntrəst","defs":[["n.","兴趣，关心，注意(pl.)利益；利息，利率 vt.使发生兴趣",false]],"tier":"l","hint":"兴趣、利息。词组 be interested in 对…感兴趣、take an interest in 对…感兴趣","ex":"She is interested in music.（她对音乐感兴趣。）"},{"id":771,"day":13,"w":"justice","ph":"ˈdʒʌstɪs","defs":[["n.","公道，公平；审判，司法",false]],"tier":"l","hint":"just（公正）+ -ice → 正义。词组 do justice to 公平对待","ex":"Everyone wants justice.（每个人都想要正义。）"},{"id":772,"day":13,"w":"kneel","ph":"niːl","defs":[["vi.","跪，下跪",false]],"tier":"l","hint":"跪。过去式 knelt。词组 kneel down 跪下","ex":"He knelt down to pick up the pen.（他跪下捡起笔。）"},{"id":773,"day":13,"w":"leg","ph":"leɡ","defs":[["n.","腿，腿脚",false]],"tier":"l","hint":"腿。联想 arm 手臂、leg 腿","ex":"He broke his leg in the accident.（他在事故中摔断了腿。）"},{"id":774,"day":13,"w":"liter/-re","ph":"ˈliːtər","defs":[["n.","公升",false]],"tier":"l","hint":"升（容量单位）。联想 liter 升、liter of water 一升水","ex":"Please buy a liter of milk.（请买一升牛奶。）"},{"id":775,"day":13,"w":"literature","ph":"ˈlɪtrətʃər","defs":[["n.","文学，文学作品；文献",false]],"tier":"l","hint":"文学。联想 literature 文学、literary 文学的","ex":"She studies Chinese literature at college.（她在大学学中国文学。）"},{"id":776,"day":13,"w":"load","ph":"loʊd","defs":[["vt.","装载，装填 n.负荷，负担；（一）担，（一）车",false]],"tier":"l","hint":"装载、负荷。词组 a load of 大量","ex":"The truck is carrying a heavy load.（卡车载着重物。）"},{"id":777,"day":13,"w":"lose","ph":"luːz","defs":[["vt.","丢，丢失，丧失；失败，输；迷路",false]],"tier":"l","hint":"失去、输。过去式 lost。词组 lose weight 减肥、lose one's way 迷路","ex":"I lost my keys this morning.（我今早丢了钥匙。）"},{"id":778,"day":13,"w":"loud","ph":"laʊd","defs":[["a.","响亮的，大声的；吵闹的，喧嚣的 ad.响亮地，大声地",false]],"tier":"l","hint":"大声的。联想 quiet 安静的（反义）、loudly 大声地","ex":"Please don't speak so loud.（请不要这么大声说话。）"},{"id":779,"day":13,"w":"march","ph":"mɑːrtʃ","defs":[["v.","行进，行军；游行示威 n.行进，行军；进行曲",false]],"tier":"l","hint":"行军、三月。词组 march on 前进","ex":"The soldiers marched across the field.（士兵们行军穿过田野。）"},{"id":780,"day":13,"w":"official","ph":"əˈfɪʃl","defs":[["n.","官员，行政人员 ad.官方的；正式的；公务的",false]],"tier":"l","hint":"官方的、官员。联想 office 办公室（同源）","ex":"He is a government official.（他是政府官员。）"},{"id":781,"day":13,"w":"own","ph":"oʊn","defs":[["vt.","拥有 a.自 己的；特有的",false]],"tier":"l","hint":"自己的、拥有。词组 of one's own 自己的、on one's own 独立","ex":"She has her own room.（她有自己的房间。）"},{"id":782,"day":13,"w":"party","ph":"ˈpɑːrti","defs":[["n.","党，政党；聚会；一方，当事人",false]],"tier":"l","hint":"聚会、政党。词组 birthday party 生日聚会","ex":"We had a party last night.（我们昨晚开了个聚会。）"},{"id":783,"day":13,"w":"passenger","ph":"ˈpæsɪndʒər","defs":[["n.","乘客，旅客",false]],"tier":"l","hint":"乘客。联想 passenger 乘客（火车/飞机上的）","ex":"The bus is full of passengers.（公交车上满是乘客。）"},{"id":784,"day":13,"w":"plan","ph":"plæn","defs":[["n.","计划，打算；平面图 vt.计划，制订计划 vi.计划",false]],"tier":"l","hint":"计划。词组 plan to do 计划做","ex":"We plan to visit Beijing next month.（我们计划下个月去北京。）"},{"id":785,"day":13,"w":"plastic","ph":"ˈplæstɪk","defs":[["n.","(pl.)塑料 a.塑料的，塑性的；可塑的",false]],"tier":"l","hint":"塑料。联想 plastic bag 塑料袋","ex":"We should use fewer plastic bags.（我们应该少用塑料袋。）"},{"id":786,"day":13,"w":"proper","ph":"ˈprɑːpər","defs":[["a.","适当，恰当；特有的，固有的",false]],"tier":"l","hint":"恰当的。词组 proper way 恰当的方式","ex":"This is not the proper way to do it.（这不是做这件事的恰当方式。）"},{"id":787,"day":13,"w":"read","ph":"riːd","defs":[["vt.","朗读，阅读；辨认，观察 vi.阅读；朗读；读到，获悉；读起来",false]],"tier":"l","hint":"读。过去式 read（读音不同）。词组 read aloud 朗读","ex":"She reads books every day.（她每天读书。）"},{"id":788,"day":13,"w":"root","ph":"ruːt","defs":[["n.","根，根源，来源",false]],"tier":"l","hint":"根。词组 the root of 根源","ex":"The root of the tree is deep.（树根很深。）"},{"id":789,"day":13,"w":"rub","ph":"rʌb","defs":[["vi.","/vt.擦，（使）摩擦 n.磨，擦；障碍",false]],"tier":"l","hint":"摩擦。词组 rub out 擦掉","ex":"He rubbed his hands together.（他搓了搓手。）"},{"id":790,"day":13,"w":"screen","ph":"skriːn","defs":[["vt.","遮蔽，庇护；选拔，淘汰 n.屏风，幕，屏幕",false]],"tier":"l","hint":"屏幕。联想 computer screen 电脑屏幕","ex":"The screen is too bright.（屏幕太亮了。）"},{"id":791,"day":13,"w":"seem","ph":"siːm","defs":[["vi.","好像，仿佛",false]],"tier":"l","hint":"似乎。词组 seem to be 似乎是","ex":"He seems to be very happy.（他似乎很开心。）"},{"id":792,"day":13,"w":"side","ph":"saɪd","defs":[["n.","旁边，侧面；坡，岸；一边，一侧，一方 vi. (with)支持",false]],"tier":"l","hint":"边、侧面。词组 on the other side 在另一边、side by side 肩并肩","ex":"The shop is on the other side of the street.（商店在街对面。）"},{"id":793,"day":13,"w":"since","ph":"sɪns","defs":[["prep.","/conj.自从，从……以来 conj.因为，既然 ad.后来，从那以后",false]],"tier":"l","hint":"自从、因为。词组 ever since 从那以后","ex":"I have lived here since 2010.（我从 2010 年起住在这里。）"},{"id":794,"day":13,"w":"skill","ph":"skɪl","defs":[["n.","技巧，技能，手艺；熟练",false]],"tier":"l","hint":"技能。联想 skilled 熟练的、skillful 技巧好的","ex":"Learning a language takes time and skill.（学语言需要时间和技巧。）"},{"id":795,"day":13,"w":"skin","ph":"skɪn","defs":[["n.","皮，皮肤 vt.剥皮",false]],"tier":"l","hint":"皮肤。联想 skin 皮肤、skincare 护肤","ex":"The baby has soft skin.（婴儿皮肤柔软。）"},{"id":796,"day":13,"w":"sometimes","ph":"ˈsʌmtaɪmz","defs":[["ad.","有时，间或",false]],"tier":"l","hint":"some（某）+ times（时候）→ 有时","ex":"I sometimes go to the library.（我有时去图书馆。）"},{"id":797,"day":13,"w":"spell","ph":"spel","defs":[["vt.","拼写",false]],"tier":"l","hint":"拼写。词组 spell the word 拼写单词","ex":"Can you spell your name?（你能拼写你的名字吗？）"},{"id":798,"day":13,"w":"statement","ph":"ˈsteɪtmənt","defs":[["n.","声明，陈述",false]],"tier":"l","hint":"state（陈述）+ -ment → 声明","ex":"He made a statement to the press.（他向媒体发表了声明。）"},{"id":799,"day":13,"w":"stick","ph":"stɪk","defs":[["n.","棍，棒；手杖 vt.刺，截，扎；粘贴 vi. (to)黏着，附着",false]],"tier":"l","hint":"棍、粘住。过去式 stuck。词组 stick to 坚持","ex":"You should stick to your plan.（你应该坚持你的计划。）"},{"id":800,"day":13,"w":"telephone","ph":"ˈtelɪfoʊn","defs":[["n.","电话 vt.打电话",false]],"tier":"l","hint":"电话（缩写 phone）。词组 on the telephone 在打电话","ex":"The telephone is ringing.（电话在响。）"},{"id":801,"day":13,"w":"theater/-re","ph":"ˈθiːətər","defs":[["n.","戏院，剧院",false]],"tier":"l","hint":"剧院。词组 go to the theater 去看戏","ex":"We went to the theater last night.（我们昨晚去了剧院。）"},{"id":802,"day":13,"w":"time","ph":"taɪm","defs":[["n.","时间，时刻；次；时期；(pl.)时代；倍",false]],"tier":"l","hint":"时间、次数。词组 on time 准时、in time 及时","ex":"What time is it now?（现在几点了？）"},{"id":803,"day":13,"w":"tobacco","ph":"təˈbækoʊ","defs":[["n.","烟草，烟叶",false]],"tier":"l","hint":"烟草。联想 smoke tobacco 吸烟","ex":"Tobacco is harmful to health.（烟草对健康有害。）"},{"id":804,"day":13,"w":"tonight","ph":"təˈnaɪt","defs":[["n.","/ad.今晚",false]],"tier":"l","hint":"to（到）+ night（夜）→ 今晚","ex":"We will have a party tonight.（我们今晚有聚会。）"},{"id":805,"day":13,"w":"treat","ph":"triːt","defs":[["vt.","对待，处理；治疗 n.款待，请客",false]],"tier":"l","hint":"对待、治疗、款待。词组 treat...as 把…当作","ex":"They treat him as a member of the family.（他们把他当家人对待。）"},{"id":806,"day":13,"w":"universe","ph":"ˈjuːnɪvɜːrs","defs":[["n.","宇宙，万物",false]],"tier":"l","hint":"uni-（一）+ verse（转）→ 万物合一 → 宇宙","ex":"The universe is very large.（宇宙非常浩瀚。）"},{"id":807,"day":13,"w":"upright","ph":"ˈʌpraɪt","defs":[["a.","直立的，竖立的；正直的，诚实的",false]],"tier":"l","hint":"up（上）+ right（直）→ 直立的、正直的","ex":"The old man sat upright in his chair.（老人笔直地坐在椅子上。）"},{"id":808,"day":13,"w":"urgent","ph":"ˈɜːrdʒənt","defs":[["a.","紧迫的；催促的",false]],"tier":"l","hint":"紧急的。联想 emergency 紧急情况（同源）","ex":"There is an urgent need for help.（急需帮助。）"},{"id":809,"day":13,"w":"will","ph":"wɪl","defs":[["aux.","v.将，会；愿，要 n.决心，意志；愿望，意愿；遗嘱",false]],"tier":"l","hint":"将要、意愿。词组 at will 随意","ex":"I will call you tomorrow.（我明天给你打电话。）"},{"id":810,"day":13,"w":"wrong","ph":"rɔːŋ","defs":[["a.","错误的，有毛病的；不正常的，不好的；不 合适的；不道德的，不正当的 ad.不对，错误地，不正确地",false]],"tier":"l","hint":"错误的。词组 go wrong 出错、What's wrong? 怎么了？","ex":"What's wrong with you?（你怎么了？）"},{"id":811,"day":13,"w":"yet","ph":"jet","defs":[["ad.","还，仍然；更；到目前为止 conj.然而，可是",false]],"tier":"l","hint":"还、然而。词组 not yet 还没有","ex":"I haven't finished my homework yet.（我还没完成作业。）"},{"id":812,"day":14,"w":"action","ph":"ˈækʃn","defs":[["n.","行动；作用",true]],"tier":"f","ety":"act（做）+ -ion → 行为、行动","mem":"act + ion → \"做\"（act）的名词 → 行动。画面：说干就干","ex":"take action · We must take action to stop pollution.（我们必须采取行动阻止污染。）","nua":"take action（采取行动，不可数）、actions（行为，可数复数）；action 与 activity 区别"},{"id":813,"day":14,"w":"additional","ph":"əˈdɪʃənl","defs":[["a.","增加的，附加的",false]],"tier":"l","hint":"add（增加）+ -itional → 额外的","ex":"There is an additional charge for the service.（这项服务有额外费用。）"},{"id":814,"day":14,"w":"afterward(s)","ph":"ˈæftərwərd","defs":[["ad.","以后，后来",true]],"tier":"f","ety":"after（之后）+ -ward（方向）→ 往后 → 后来","mem":"after + ward（=向）→ 朝\"之后\"的方向 → 后来。画面：时间轴往后","ex":"soon afterward · Soon afterward, he left the city.（不久之后，他离开了城市。）","nua":"afterward（美）、afterwards（英）同义；beforehand（事先）是其反方向"},{"id":815,"day":14,"w":"anyone","ph":"ˈeniwʌn","defs":[["pron.","[否定、疑问、条件句中]任何人；[肯定句中]随 便哪一个人",false]],"tier":"l","hint":"any（任何）+ one（人）→ 任何人","ex":"Is there anyone in the room?（房间里有人吗？）"},{"id":816,"day":14,"w":"bird","ph":"bɜːrd","defs":[["n.","鸟，禽",false]],"tier":"l","hint":"鸟。联想 bird 鸟、fly 飞","ex":"The birds are singing in the tree.（鸟儿在树上唱歌。）"},{"id":817,"day":14,"w":"breakfast","ph":"ˈbrekfəst","defs":[["n.","早饭，早餐",false]],"tier":"l","hint":"break（打破）+ fast（禁食）→ 打破禁食 → 早餐。词组 have breakfast 吃早餐","ex":"I have breakfast at seven.（我七点吃早餐。）"},{"id":818,"day":14,"w":"bridge","ph":"brɪdʒ","defs":[["n.","桥，桥梁；桥牌",false]],"tier":"l","hint":"桥。词组 cross the bridge 过桥","ex":"The bridge is very old.（这座桥很古老。）"},{"id":819,"day":14,"w":"bury","ph":"ˈberi","defs":[["vt.","埋，安葬",false]],"tier":"l","hint":"埋葬。联想 bury 埋、funeral 葬礼","ex":"They buried the dog in the garden.（他们把狗埋在了花园里。）"},{"id":820,"day":14,"w":"clothes","ph":"kloʊðz","defs":[["n.","衣服",false]],"tier":"l","hint":"衣服（复数）。联想 cloth 布、clothes 衣服","ex":"She bought some new clothes.（她买了些新衣服。）"},{"id":821,"day":14,"w":"crop","ph":"krɑːp","defs":[["n.","农作物，庄稼；收成",false]],"tier":"l","hint":"庄稼、收成。联想 crop 庄稼、harvest 收获","ex":"The farmers are harvesting the crops.（农民在收割庄稼。）"},{"id":822,"day":14,"w":"detail","ph":"ˈdiːteɪl","defs":[["n.","细节，详情；枝节，琐事 vt.详述，详谈",false]],"tier":"l","hint":"细节。词组 in detail 详细地","ex":"Please describe the accident in detail.（请详细描述事故。）"},{"id":823,"day":14,"w":"embarrass","ph":"ɪmˈbærəs","defs":[["vt.","使窘迫，使为难",true]],"tier":"f","ety":"em-（使）+ barrass（阻碍）→ 使人卡住 → 窘迫","mem":"拼写记忆：em + bar（酒吧）+ r + ass → 在酒吧里出丑 → 尴尬。画面：当众出糗","ex":"embarrass sb · His question embarrassed me.（他的问题让我很尴尬。）","nua":"embarrass（及物，使尴尬）、be embarrassed（感到尴尬）、embarrassing（令人尴尬的）"},{"id":824,"day":14,"w":"even","ph":"ˈiːvn","defs":[["ad.","甚至，连……都",false]],"tier":"l","hint":"甚至、甚至更。词组 even if 即使、even though 尽管","ex":"Even a child can understand it.（连孩子都能理解。）"},{"id":825,"day":14,"w":"explosive","ph":"ɪkˈsploʊsɪv","defs":[["a.","爆炸（性）的 n.炸药",false]],"tier":"l","hint":"explode（爆炸）+ -ive → 爆炸性的、炸药","ex":"The workers found some explosives.（工人们发现了一些炸药。）"},{"id":826,"day":14,"w":"fine","ph":"faɪn","defs":[["a.","美好的，优良的，优秀的；晴朗的，明朗的 n./vt.罚款",false]],"tier":"l","hint":"好的、罚款。词组 pay a fine 交罚款","ex":"The weather is fine today.（今天天气很好。）"},{"id":827,"day":14,"w":"forgive","ph":"fərˈɡɪv","defs":[["vt.","原谅，宽恕，饶恕",false]],"tier":"l","hint":"原谅。过去式 forgave。词组 forgive sb for 原谅某人","ex":"Please forgive me for being late.（请原谅我迟到。）"},{"id":828,"day":14,"w":"grandmother","ph":"ˈɡrænmʌðər","defs":[["n.","(外)祖母",false]],"tier":"l","hint":"grand（隔代）+ mother（母）→ 祖母","ex":"My grandmother is eighty years old.（我祖母八十岁了。）"},{"id":829,"day":14,"w":"green","ph":"ɡriːn","defs":[["a.","绿色的；生的，未成熟的；缺乏经验的，生疏的 n.绿色",false]],"tier":"l","hint":"绿色。联想 green 绿色、环保的","ex":"The grass is green in spring.（春天草是绿的。）"},{"id":830,"day":14,"w":"greeting","ph":"ˈɡriːtɪŋ","defs":[["n.","致敬，问候，祝贺",false]],"tier":"l","hint":"greet（问候）+ -ing → 问候","ex":"They exchanged greetings at the door.（他们在门口互相问候。）"},{"id":831,"day":14,"w":"hundred","ph":"ˈhʌndrəd","defs":[["n.","一百；(pl.)数以百计",false]],"tier":"l","hint":"百。词组 hundreds of 数百","ex":"There are hundreds of students in the school.（学校有数百名学生。）"},{"id":832,"day":14,"w":"improve","ph":"ɪmˈpruːv","defs":[["vt.","改善，改进 vi.好转，进步",false]],"tier":"l","hint":"改进、提高。词组 improve oneself 提高自己","ex":"Reading can improve your English.（阅读能提高你的英语。）"},{"id":833,"day":14,"w":"invitation","ph":"ˌɪnvɪˈteɪʃn","defs":[["n.","请柬；邀请，招待",false]],"tier":"l","hint":"invite（邀请）+ -ation → 邀请","ex":"He sent me an invitation to the party.（他给我发了聚会邀请。）"},{"id":834,"day":14,"w":"join","ph":"dʒɔɪn","defs":[["vi.","/vt.结合，接合，连接；参加，加入",false]],"tier":"l","hint":"加入、连接。词组 join in 参加、join the army 参军","ex":"Would you like to join us?（你想加入我们吗？）"},{"id":835,"day":14,"w":"knife","ph":"naɪf","defs":[["n.","刀，餐刀 vt.用刀切，用 匕首刺",false]],"tier":"l","hint":"刀（复数 knives）。联想 fork 叉、knife 刀","ex":"Be careful with the knife.（小心用刀。）"},{"id":836,"day":14,"w":"leaf","ph":"liːf","defs":[["n.","叶，叶子；页，张",false]],"tier":"l","hint":"叶子（复数 leaves）。联想 leaf 叶子、leaves 树叶","ex":"The leaves turn yellow in autumn.（秋天树叶变黄。）"},{"id":837,"day":14,"w":"length","ph":"leŋθ","defs":[["n.","长，长度",false]],"tier":"l","hint":"long（长）的名词 → 长度。词组 at length 详细地、最终","ex":"The bridge is 100 meters in length.（这座桥长 100 米。）"},{"id":838,"day":14,"w":"live","ph":"lɪv","defs":[["vi.","住，居住；生活，过活，生存 vt.过生活 a.活的，有生命的；实况播送的",false]],"tier":"l","hint":"居住、活的。词组 live on 靠…生活","ex":"They live in the countryside.（他们住在乡下。）"},{"id":839,"day":14,"w":"logic","ph":"ˈlɑːdʒɪk","defs":[["n.","逻辑，逻辑学",false]],"tier":"l","hint":"逻辑。联想 logical 合逻辑的","ex":"There is no logic in his argument.（他的论证没有逻辑。）"},{"id":840,"day":14,"w":"minister","ph":"ˈmɪnɪstər","defs":[["n.","部长，大臣",false]],"tier":"l","hint":"部长、大臣。联想 prime minister 首相","ex":"The minister visited the school.（部长参观了学校。）"},{"id":841,"day":14,"w":"muscle","ph":"ˈmʌsl","defs":[["n.","心肌肉，体力",false]],"tier":"l","hint":"肌肉。联想 muscle 肌肉、strong muscles 强壮的肌肉","ex":"Exercise builds strong muscles.（锻炼塑造强壮的肌肉。）"},{"id":842,"day":14,"w":"net","ph":"net","defs":[["n.","网，网状物 a.净的，纯净的",false]],"tier":"l","hint":"网。联想 net 网、the Internet 互联网","ex":"The fisherman caught fish with a net.（渔民用网捕鱼。）"},{"id":843,"day":14,"w":"none","ph":"nʌn","defs":[["pron.","谁也不，哪个都不 ad.一点也不",false]],"tier":"l","hint":"没有一个。词组 none of 没有一个","ex":"None of the students was late.（没有一个学生迟到。）"},{"id":844,"day":14,"w":"pattern","ph":"ˈpætərn","defs":[["n.","模式，样式；图案，花样",false]],"tier":"l","hint":"模式、图案。联想 pattern 图案、花纹","ex":"The cloth has a beautiful pattern.（这块布有漂亮的图案。）"},{"id":845,"day":14,"w":"problem","ph":"ˈprɑːbləm","defs":[["n.","问题，难题",false]],"tier":"l","hint":"问题。词组 solve a problem 解决问题、no problem 没问题","ex":"We must solve this problem quickly.（我们必须尽快解决这个问题。）"},{"id":846,"day":14,"w":"program(me)","ph":"ˈproʊɡræm","defs":[["n.","计划，规划，大纲；节目，节目单；程序 vt.编制程序",false]],"tier":"l","hint":"节目、程序。词组 computer program 计算机程序","ex":"The TV program is very popular.（这个电视节目很受欢迎。）"},{"id":847,"day":14,"w":"project","ph":"prəˈdʒekt","defs":[["n.","计划，方案；工程，项目 vt.设计，规划；投射；放映；使突出",false]],"tier":"l","hint":"项目、计划。词组 a project 项目、do a project 做项目","ex":"They are working on a new project.（他们在做一个新项目。）"},{"id":848,"day":14,"w":"punishment","ph":"ˈpʌnɪʃmənt","defs":[["n.","处罚，惩罚",false]],"tier":"l","hint":"punish（惩罚）+ -ment → 惩罚","ex":"The boy received punishment for lying.（男孩因说谎受罚。）"},{"id":849,"day":14,"w":"quick","ph":"kwɪk","defs":[["a.","快的，迅速的；敏捷的，伶俐的；性急的，敏锐的",false]],"tier":"l","hint":"快的。词组 be quick 快点、quickly 迅速地","ex":"Be quick, or you'll miss the bus.（快点，否则赶不上公交了。）"},{"id":850,"day":14,"w":"reasonable","ph":"ˈriːznəbl","defs":[["a.","合理的；讲理的；公道的",false]],"tier":"l","hint":"reason（理由）+ -able → 合理的","ex":"The price is reasonable.（价格合理。）"},{"id":851,"day":14,"w":"remain","ph":"rɪˈmeɪn","defs":[["vi.","留下，余留 n.(pl.)余，残余，遗迹；遗体",false]],"tier":"l","hint":"保持、留下。词组 remain silent 保持沉默","ex":"Please remain seated.（请保持坐着。）"},{"id":852,"day":14,"w":"remark","ph":"rɪˈmɑːrk","defs":[["n.","评语，意见 vt.说，评论 vi. (on)议论，评论",false]],"tier":"l","hint":"评论、注意到。联想 remark 评论、comment 评论","ex":"He made a funny remark.（他说了句风趣的话。）"},{"id":853,"day":14,"w":"report","ph":"rɪˈpɔːrt","defs":[["n.","报告，报道；传说，传闻 vt.报告，报道 vi.报到；报告",false]],"tier":"l","hint":"报告、报道。词组 report on 报道","ex":"The newspaper reported the news.（报纸报道了这条新闻。）"},{"id":854,"day":14,"w":"rock","ph":"rɑːk","defs":[["n.","岩，岩石 vt.摇",false]],"tier":"l","hint":"岩石、摇滚乐。联想 stone 石头、rock 岩石","ex":"The ship hit a rock in the sea.（船在海里撞上了礁石。）"},{"id":855,"day":14,"w":"school","ph":"skuːl","defs":[["n.","学校，学院；学派，流派",false]],"tier":"l","hint":"学校。词组 go to school 上学、after school 放学后","ex":"The children go to school at eight.（孩子们八点上学。）"},{"id":856,"day":14,"w":"science","ph":"ˈsaɪəns","defs":[["n.","科学；学科",false]],"tier":"l","hint":"科学。联想 scientist 科学家、scientific 科学的","ex":"Science has changed our lives.（科学改变了我们的生活。）"},{"id":857,"day":14,"w":"scientist","ph":"ˈsaɪəntɪst","defs":[["n.","科学家",false]],"tier":"l","hint":"science（科学）+ -ist（人）→ 科学家","ex":"The scientist made an important discovery.（这位科学家有重要发现。）"},{"id":858,"day":14,"w":"score","ph":"skɔː","defs":[["n.","得分，分数；二十 vi./vt.得分，记分",false]],"tier":"l","hint":"分数、得分。词组 high score 高分","ex":"He got a high score in the exam.（他考试得了高分。）"},{"id":859,"day":14,"w":"serve","ph":"sɜːrv","defs":[["vt.","服务，尽责；伺候，招待；适用，适合；服役 vi.服务，供职；有用，起作用",false]],"tier":"l","hint":"服务、招待。词组 serve the people 为人民服务","ex":"The waiter served us dinner.（服务员给我们上晚餐。）"},{"id":860,"day":14,"w":"shame","ph":"ʃeɪm","defs":[["n.","羞愧，耻辱；可耻的人/物 vt.使羞愧，玷辱",false]],"tier":"l","hint":"羞耻、遗憾。词组 What a shame! 真遗憾！","ex":"It's a shame that you can't come.（你不能来真遗憾。）"},{"id":861,"day":14,"w":"shine","ph":"ʃaɪn","defs":[["vi.","/vt.（使）发光；照耀，擦亮 n.光，光泽",false]],"tier":"l","hint":"发光。过去式 shone。词组 the sun shines 阳光照耀","ex":"The sun shines brightly today.（今天阳光灿烂。）"},{"id":862,"day":14,"w":"sock","ph":"sɑːk","defs":[["n.","(pl.)短袜",false]],"tier":"l","hint":"袜子。词组 a pair of socks 一双袜子","ex":"He wears white socks.（他穿白袜子。）"},{"id":863,"day":14,"w":"southern","ph":"ˈsʌðərn","defs":[["a.","南方的，南的",false]],"tier":"l","hint":"south（南）+ -ern → 南方的。联想 northern 北方的","ex":"They live in the southern part of the country.（他们住在该国南部。）"},{"id":864,"day":14,"w":"station","ph":"ˈsteɪʃn","defs":[["n.","车站；站，局，所；身份，地位；岗位，位置",false]],"tier":"l","hint":"车站。词组 railway station 火车站、bus station 公交站","ex":"The train arrived at the station.（火车到站了。）"},{"id":865,"day":14,"w":"strict","ph":"strɪkt","defs":[["a.","严格的；严谨的，精确的",false]],"tier":"l","hint":"严格的。词组 be strict with 对…严格","ex":"Our teacher is strict with us.（我们老师对我们很严格。）"},{"id":866,"day":14,"w":"sympathetic","ph":"ˌsɪmpəˈθetɪk","defs":[["a.","同情的，共鸣的",false]],"tier":"l","hint":"sympathy（同情）+ -etic → 同情的","ex":"She was sympathetic to my problem.（她对我的问题表示同情。）"},{"id":867,"day":14,"w":"through","ph":"θruː","defs":[["prep.","通过，穿过；因为，由于；自始至终 ad.通过，穿过；彻底地，完全地",false]],"tier":"l","hint":"穿过、通过。词组 go through 经历","ex":"The train went through the tunnel.（火车穿过了隧道。）"},{"id":868,"day":14,"w":"tiring","ph":"ˈtaɪərɪŋ","defs":[["a.","使人疲倦的",false]],"tier":"l","hint":"tire（累）+ -ing → 令人疲劳的","ex":"The long journey was very tiring.（长途旅行很累。）"},{"id":869,"day":14,"w":"top","ph":"tɑːp","defs":[["n.","顶，顶部；最上端，首位；上面，盖子 a.最高的；最优秀的 vt.居……之首，居……之上；高过，超过",false]],"tier":"l","hint":"顶部、顶级的。词组 on top of 在…顶部","ex":"We reached the top of the mountain.（我们到达了山顶。）"},{"id":870,"day":14,"w":"tourist","ph":"ˈtʊrɪst","defs":[["n.","旅游者，观光者",false]],"tier":"l","hint":"tour（旅游）+ -ist（人）→ 游客","ex":"Many tourists visit the city every year.（每年很多游客来这座城市。）"},{"id":871,"day":14,"w":"warn","ph":"wɔːrn","defs":[["vt.","警告，告诫",false]],"tier":"l","hint":"警告。词组 warn sb of 警告某人、warn sb not to 警告某人不要","ex":"The doctor warned him not to smoke.（医生警告他不要吸烟。）"},{"id":872,"day":14,"w":"wear","ph":"wer","defs":[["vi.","/vt.穿戴，佩带；磨损，用旧",false]],"tier":"l","hint":"穿、戴。过去式 wore。词组 wear out 穿破","ex":"She wears glasses.（她戴眼镜。）"},{"id":873,"day":14,"w":"write","ph":"raɪt","defs":[["vi.","/vt.写，书写；写作；写信（给）",false]],"tier":"l","hint":"写。过去式 wrote。词组 write down 写下、write to 写信给","ex":"Please write down your name.（请写下你的名字。）"},{"id":874,"day":14,"w":"year","ph":"jɪr","defs":[["n.","年，年度，学年",false]],"tier":"l","hint":"年。词组 this year 今年、year after year 年复一年","ex":"I will graduate next year.（我明年毕业。）"},{"id":875,"day":15,"w":"amusing","ph":"əˈmjuːzɪŋ","defs":[["a.","逗人笑的，有趣的",true]],"tier":"f","ety":"amuse（逗乐）+ -ing → 令人发笑的","mem":"amuse + ing → 让人\"发笑\"的 → 有趣的。画面：看喜剧哈哈大笑","ex":"an amusing story · He told an amusing story.（他讲了个有趣的故事。）","nua":"amusing（令人发笑，修饰事物）、amused（感到好笑，修饰人）；同根 amuse"},{"id":876,"day":15,"w":"apple","ph":"ˈæpl","defs":[["n.","苹果",false]],"tier":"l","hint":"苹果。联想 apple 苹果、an apple a day 一天一苹果","ex":"She eats an apple every day.（她每天吃一个苹果。）"},{"id":877,"day":15,"w":"available","ph":"əˈveɪləbl","defs":[["a.","可利用的；可得到的",false]],"tier":"l","hint":"可用的、可获得的。词组 be available to 可供…使用","ex":"The book is available in the library.（这本书图书馆里有。）"},{"id":878,"day":15,"w":"body","ph":"ˈbɑːdi","defs":[["n.","身体，躯体；主体；物体；尸体",false]],"tier":"l","hint":"身体。词组 body language 肢体语言","ex":"Exercise is good for the body.（锻炼对身体好。）"},{"id":879,"day":15,"w":"breathe","ph":"briːð","defs":[["vi.","/vt.吸入，呼吸",false]],"tier":"l","hint":"呼吸。联想 breath 呼吸（名词）、breathe 呼吸（动词）","ex":"It's hard to breathe in the smoke.（在烟雾里很难呼吸。）"},{"id":880,"day":15,"w":"bubble","ph":"ˈbʌbl","defs":[["n.","/v. 泡，气泡；冒泡",true]],"tier":"f","ety":"拟声词，模仿气泡破裂声","mem":"拟声：bubble 读起来像\"卜卜\"冒泡声。画面：水开冒泡","ex":"soap bubble · The children blew soap bubbles.（孩子们吹肥皂泡。）","nua":"bubble（气泡）、bubble economy（泡沫经济，引申）"},{"id":881,"day":15,"w":"chair","ph":"tʃer","defs":[["n.","椅子；主席",false]],"tier":"l","hint":"椅子。词组 sit on a chair 坐在椅子上","ex":"Please sit on the chair.（请坐在椅子上。）"},{"id":882,"day":15,"w":"class","ph":"klæs","defs":[["n.","种类，等级，阶级；班，班级，年级；(一节)课",false]],"tier":"l","hint":"班级、课。词组 in class 在课上、after class 课后","ex":"There are forty students in our class.（我们班有四十名学生。）"},{"id":883,"day":15,"w":"clay","ph":"kleɪ","defs":[["n.","泥土，黏土",false]],"tier":"l","hint":"黏土。联想 clay 黏土、pottery 陶器","ex":"The pot is made of clay.（这个罐子是黏土做的。）"},{"id":884,"day":15,"w":"cliff","ph":"klɪf","defs":[["n.","崖，悬崖",false]],"tier":"l","hint":"悬崖。联想 cliff 悬崖、mountain 山","ex":"The cliff is very steep.（悬崖很陡。）"},{"id":885,"day":15,"w":"clothing","ph":"ˈkloʊðɪŋ","defs":[["n.","[总称]衣服",false]],"tier":"l","hint":"衣服（总称）。联想 clothes 衣服、clothing 服装（总称）","ex":"We need warm clothing in winter.（冬天我们需要保暖的衣物。）"},{"id":886,"day":15,"w":"control","ph":"kənˈtroʊl","defs":[["vt.","/n.控制，操纵；抑制",false]],"tier":"l","hint":"控制。词组 in control of 控制、out of control 失控","ex":"The situation is under control.（局势在控制之中。）"},{"id":887,"day":15,"w":"defense/-ce","ph":"dɪˈfens","defs":[["n.","防御，保卫；答辩",false]],"tier":"l","hint":"defend（防守）的名词 → 防御","ex":"The army is responsible for national defense.（军队负责国防。）"},{"id":888,"day":15,"w":"depend","ph":"dɪˈpend","defs":[["vi.","(on/upon)依靠，依赖；信任；取决于",false]],"tier":"l","hint":"依赖。词组 depend on 依赖、it depends 看情况","ex":"Success depends on hard work.（成功取决于努力。）"},{"id":889,"day":15,"w":"direction","ph":"dəˈrekʃn","defs":[["n.","方向，方位；指导，指令；(pl.)说明",false]],"tier":"l","hint":"方向。词组 in the direction of 朝…方向","ex":"He walked in the direction of the station.（他朝车站方向走。）"},{"id":890,"day":15,"w":"dismiss","ph":"dɪsˈmɪs","defs":[["vt.","不再考虑；免职，解雇，开除；解散",false]],"tier":"l","hint":"解雇、解散。联想 dis-（离）+ miss（送）→ 送走 → 解雇","ex":"The worker was dismissed for being late.（这个工人因迟到被解雇。）"},{"id":891,"day":15,"w":"drink","ph":"drɪŋk","defs":[["vt.","饮，喝，饮酒 n.饮料，酒",false]],"tier":"l","hint":"喝、饮料。过去式 drank。词组 drink water 喝水","ex":"You should drink more water.（你应该多喝水。）"},{"id":892,"day":15,"w":"enjoy","ph":"ɪnˈdʒɔɪ","defs":[["vt.","欣赏，喜爱；享受，享有",false]],"tier":"l","hint":"享受、喜欢。词组 enjoy doing 喜欢做、enjoy oneself 玩得开心","ex":"I enjoy reading books.（我喜欢读书。）"},{"id":893,"day":15,"w":"example","ph":"ɪɡˈzæmpl","defs":[["n.","例，实例；范例，榜样",false]],"tier":"l","hint":"例子。词组 for example 例如","ex":"Many fruits, for example, apples, are good for health.（很多水果，例如苹果，对健康有益。）"},{"id":894,"day":15,"w":"extreme","ph":"ɪkˈstriːm","defs":[["n.","尽头的，末端的；极端的，极度的 n.极端",false]],"tier":"l","hint":"极端的。联想 extremely 极其（副词）","ex":"The weather was extreme last winter.（去年冬天天气极端。）"},{"id":895,"day":15,"w":"fat","ph":"fæt","defs":[["n.","脂肪，肥肉 a.肥胖的，多脂肪的",false]],"tier":"l","hint":"胖的、脂肪。联想 thin 瘦的（反义）","ex":"Too much fat is bad for health.（太多脂肪对健康不好。）"},{"id":896,"day":15,"w":"foot","ph":"fʊt","defs":[["n.","脚，足；英尺；最下部，底部",false]],"tier":"l","hint":"脚（复数 feet）。词组 on foot 步行","ex":"I go to school on foot.（我步行上学。）"},{"id":897,"day":15,"w":"free","ph":"friː","defs":[["a.","自由的；(of)免费的；自由开放的；空闲的，空余的 vt.使自 由，解放",false]],"tier":"l","hint":"自由的、免费的。词组 be free to 自由做、free of charge 免费","ex":"The concert is free.（这场音乐会是免费的。）"},{"id":898,"day":15,"w":"grateful","ph":"ˈɡreɪtfl","defs":[["a.","感激的，感谢的",false]],"tier":"l","hint":"感激的。词组 be grateful to 感激","ex":"I'm grateful for your help.（我很感激你的帮助。）"},{"id":899,"day":15,"w":"great","ph":"ɡreɪt","defs":[["a.","大，极大；重大的；伟大的；美妙的",false]],"tier":"l","hint":"伟大的、极好的。词组 a great deal of 大量","ex":"She is a great teacher.（她是位伟大的老师。）"},{"id":900,"day":15,"w":"grey","ph":"ɡreɪ","defs":[["a.","/n.灰色（的）",false]],"tier":"l","hint":"灰色。联想颜色词：grey 灰色","ex":"The old man has grey hair.（老人头发花白。）"},{"id":901,"day":15,"w":"guard","ph":"ɡɑːrd","defs":[["vt.","守卫，保卫，提防 vi.防止 n.哨兵，瞥卫，看守；守卫；警戒",false]],"tier":"l","hint":"守卫、警卫。词组 guard against 防范","ex":"The soldiers guard the palace.（士兵守卫宫殿。）"},{"id":902,"day":15,"w":"gun","ph":"ɡʌn","defs":[["n.","枪，炮",false]],"tier":"l","hint":"枪。联想 gun 枪、shoot 射击","ex":"The police officer carries a gun.（警察带着枪。）"},{"id":903,"day":15,"w":"help","ph":"help","defs":[["vi.","/vt./n.帮助，援助",false]],"tier":"l","hint":"帮助。词组 help sb with 帮某人做、can't help doing 忍不住做","ex":"Can you help me with my English?（你能帮我学英语吗？）"},{"id":904,"day":15,"w":"honest","ph":"ˈɑːnɪst","defs":[["a.","诚实的，老实的，正直的",false]],"tier":"l","hint":"诚实的。联想 honesty 诚实（名词）、dishonest 不诚实的","ex":"He is an honest man.（他是个诚实的人。）"},{"id":905,"day":15,"w":"hotel","ph":"hoʊˈtel","defs":[["n.","旅馆",false]],"tier":"l","hint":"旅馆。联想 hotel 旅馆、stay at a hotel 住旅馆","ex":"We stayed at a hotel near the beach.（我们住在海滩附近的旅馆。）"},{"id":906,"day":15,"w":"hungry","ph":"ˈhʌŋɡri","defs":[["a.","饥饿的；渴望的",false]],"tier":"l","hint":"饥饿的。联想 hungry 饿、thirsty 渴","ex":"I'm hungry after the long walk.（走了很久后我饿了。）"},{"id":907,"day":15,"w":"include","ph":"ɪnˈkluːd","defs":[["vt.","包含，包括，计入",false]],"tier":"l","hint":"包含。联想 in-（内）+ clude（关）→ 关进去 → 包含","ex":"The price includes tax.（价格含税。）"},{"id":908,"day":15,"w":"judgement","ph":"ˈdʒʌdʒmənt","defs":[["n.","审判，判决；判断力，识别力；意见，看法，判断",false]],"tier":"l","hint":"judge（判断）+ -ment → 判断","ex":"In my judgement, the plan will work.（依我看，这个计划可行。）"},{"id":909,"day":15,"w":"knee","ph":"niː","defs":[["n.","膝，膝盖",false]],"tier":"l","hint":"膝盖。词组 on one's knees 跪着","ex":"He hurt his knee playing football.（他踢球时伤了膝盖。）"},{"id":910,"day":15,"w":"medicine","ph":"ˈmedsn","defs":[["n.","(内服）药，医药；医学，医术",false]],"tier":"l","hint":"药、医学。词组 take medicine 吃药","ex":"Take this medicine three times a day.（这药一天吃三次。）"},{"id":911,"day":15,"w":"mistake","ph":"mɪˈsteɪk","defs":[["n.","错误，过失，误会 vt.误解，弄错，错认",false]],"tier":"l","hint":"错误。词组 make a mistake 犯错、by mistake 错误地","ex":"I made a mistake in the exam.（我考试犯了错。）"},{"id":912,"day":15,"w":"near","ph":"nɪr","defs":[["a.","近的，接近的；亲密的 ad.接近，靠近；大约，差不多 prep.在……近旁，接近 vt.接近",false]],"tier":"l","hint":"近的。联想 far 远的（反义）、nearly 几乎","ex":"The school is near my home.（学校离我家很近。）"},{"id":913,"day":15,"w":"new","ph":"nuː","defs":[["a.","新的，新近的；新来的；不熟悉的，没经验的",false]],"tier":"l","hint":"新的。联想 old 旧的（反义）","ex":"She bought a new bike.（她买了辆新自行车。）"},{"id":914,"day":15,"w":"outdoor(s)","ph":"ˈaʊtdɔːr","defs":[["a.","户外的，野外的 ad.在户外，在野外",false]],"tier":"l","hint":"out（外）+ door（门）→ 户外的。联想 indoor 室内的（反义）","ex":"We like outdoor activities.（我们喜欢户外活动。）"},{"id":915,"day":15,"w":"period","ph":"ˈpɪriəd","defs":[["n.","期间，一段时间；时期，时代",false]],"tier":"l","hint":"时期、句号。词组 a period of 一段时间","ex":"The class lasts for a period of one hour.（这节课持续一小时。）"},{"id":916,"day":15,"w":"please","ph":"pliːz","defs":[["int.","请 vt.使愉快，使满意；喜欢，愿意",false]],"tier":"l","hint":"请、使高兴。词组 please do 请做、be pleased with 对…满意","ex":"Please close the door.（请关门。）"},{"id":917,"day":15,"w":"produce","ph":"ˈprɑːduːs","defs":[["vt.","生产，制造，产生；显示，出示；上演，演出 n.农产品",false]],"tier":"l","hint":"生产、制造。联想 product 产品、production 生产","ex":"The factory produces cars.（这家工厂生产汽车。）"},{"id":918,"day":15,"w":"realize/-se","ph":"ˈriːəlaɪz","defs":[["vt.","认识到，体会到；实现",false]],"tier":"l","hint":"意识到、实现。词组 realize one's dream 实现梦想","ex":"He realized his mistake.（他意识到了自己的错误。）"},{"id":919,"day":15,"w":"replace","ph":"rɪˈpleɪs","defs":[["vt.","放回；替换，取代",false]],"tier":"l","hint":"re-（再）+ place（放置）→ 重新放置 → 替换","ex":"We need to replace the old computer.（我们需要换掉旧电脑。）"},{"id":920,"day":15,"w":"risk","ph":"rɪsk","defs":[["n.","风险 vt.冒风险",false]],"tier":"l","hint":"风险。词组 at risk 处于危险中、take a risk 冒险","ex":"He took a risk and started his own business.（他冒险创业。）"},{"id":921,"day":15,"w":"shore","ph":"ʃɔːr","defs":[["n.","岸；海滨，湖滨",false]],"tier":"l","hint":"海岸、岸。联想 shore 岸、beach 海滩","ex":"The children played on the shore.（孩子们在岸边玩。）"},{"id":922,"day":15,"w":"snake","ph":"sneɪk","defs":[["n.","蛇",false]],"tier":"l","hint":"蛇。联想 snake 蛇、poisonous snake 毒蛇","ex":"There is a snake in the grass.（草丛里有条蛇。）"},{"id":923,"day":15,"w":"speech","ph":"spiːtʃ","defs":[["n.","讲话，演说；言语，语言",false]],"tier":"l","hint":"演讲、言语。词组 make a speech 发表演讲","ex":"He made a speech at the meeting.（他在会上发表了演讲。）"},{"id":924,"day":15,"w":"steel","ph":"stiːl","defs":[["n.","钢",false]],"tier":"l","hint":"钢。联想 steal 偷（同音不同词）","ex":"The bridge is made of steel.（这座桥是钢造的。）"},{"id":925,"day":15,"w":"stem","ph":"stem","defs":[["n.","茎，干 vt.堵住，挡住 vi.起源于，由……造成",false]],"tier":"l","hint":"茎、干。联想 leaf 叶、stem 茎、root 根","ex":"The flower has a long stem.（这朵花有长长的茎。）"},{"id":926,"day":15,"w":"sting","ph":"stɪŋ","defs":[["n.","刺，刺痛，针刺 vi./vt.刺，刺痛；刺激",false]],"tier":"l","hint":"叮、刺。过去式 stung。联想 bee sting 蜜蜂蜇","ex":"A bee stung my hand.（蜜蜂蜇了我的手。）"},{"id":927,"day":15,"w":"strike","ph":"straɪk","defs":[["vi.","/n.罢工；敲响，报点 vt.打，击；攻击，冲击；给……深刻印象",false]],"tier":"l","hint":"打、罢工。过去式 struck。词组 on strike 罢工","ex":"The workers went on strike for higher pay.（工人为加薪罢工。）"},{"id":928,"day":15,"w":"student","ph":"ˈstuːdnt","defs":[["n.","学生，学员",false]],"tier":"l","hint":"学生。联想 study 学习、student 学生","ex":"He is a hard-working student.（他是个勤奋的学生。）"},{"id":929,"day":15,"w":"suffer","ph":"ˈsʌfər","defs":[["vt.","受苦，受难，受罪 vi.忍受痛苦；受损失",false]],"tier":"l","hint":"遭受、受苦。词组 suffer from 遭受","ex":"He suffers from a headache.（他头痛。）"},{"id":930,"day":15,"w":"suggest","ph":"səɡˈdʒest","defs":[["vt.","建议，提出；使想起，暗示",false]],"tier":"l","hint":"建议、暗示。词组 suggest doing 建议做、suggest that 建议","ex":"I suggest going there by bus.（我建议坐公交去那里。）"},{"id":931,"day":15,"w":"swallow","ph":"ˈswɑːloʊ","defs":[["n.","燕子；吞咽 vt.咽；淹没，吞没 vi.吞下，咽下",false]],"tier":"l","hint":"吞、燕子。词组 swallow 吞下","ex":"Swallow the medicine with water.（用水吞服药。）"},{"id":932,"day":15,"w":"thing","ph":"θɪŋ","defs":[["n.","物，东西；事，事情；(pl.)所有物；(pl.)情况",false]],"tier":"l","hint":"东西、事情。词组 all things 一切","ex":"I have many things to do today.（我今天有很多事要做。）"},{"id":933,"day":15,"w":"thunder","ph":"ˈθʌndər","defs":[["n.","雷，轰隆响",false]],"tier":"l","hint":"雷。联想 lightning 闪电、thunder 雷","ex":"We heard thunder in the distance.（我们听到远处的雷声。）"},{"id":934,"day":15,"w":"video","ph":"ˈvɪdioʊ","defs":[["n.","电视，视频；录像 a.电视的，视频的；录像的",false]],"tier":"l","hint":"视频。词组 video game 电子游戏","ex":"We watched a video about animals.（我们看了关于动物的视频。）"},{"id":935,"day":15,"w":"well","ph":"wel","defs":[["n.","井，水井 ad.好，令人满意地；恰当地；完全地，充分地 a.健康的，良好的 int.好啦，那么",false]],"tier":"l","hint":"好、井。词组 as well 也、as well as 以及","ex":"She sings well.（她唱得好。）"},{"id":936,"day":15,"w":"whatever","ph":"wətˈevər","defs":[["pron.","无论什么，不管什么；任何事物 a.不管怎样的，无论什么样的",false]],"tier":"l","hint":"无论什么。词组 whatever happens 无论发生什么","ex":"Whatever happens, I'll support you.（无论发生什么，我都支持你。）"},{"id":937,"day":15,"w":"yesterday","ph":"ˈjestərdeɪ","defs":[["n.","/ad.昨天",false]],"tier":"l","hint":"昨天。联想 today 今天、tomorrow 明天","ex":"It rained yesterday.（昨天下雨了。）"},{"id":938,"day":16,"w":"age","ph":"eɪdʒ","defs":[["n.","年龄；时代 vi.变老",false]],"tier":"l","hint":"年龄、时代。词组 at the age of 在…岁时","ex":"He started school at the age of six.（他六岁开始上学。）"},{"id":939,"day":16,"w":"ago","ph":"əˈɡoʊ","defs":[["ad.","以前，……前",false]],"tier":"l","hint":"以前。词组 three days ago 三天前","ex":"I saw him two days ago.（我两天前见过他。）"},{"id":940,"day":16,"w":"agree","ph":"əˈɡriː","defs":[["vi.","(with...on)同意；(to)一致，适合；商定，约定",false]],"tier":"l","hint":"同意。词组 agree with 同意、agree to 同意（提议）","ex":"I agree with your idea.（我同意你的想法。）"},{"id":941,"day":16,"w":"amuse","ph":"əˈmjuːz","defs":[["vt.","逗乐，使开心",true]],"tier":"f","ety":"a-（向）+ muse（沉思）→ 让人放松不想事 → 娱乐","mem":"a + muse（=music 音乐）→ 用\"音乐\"逗人开心 → 逗乐。画面：弹琴唱歌让人笑","ex":"amuse oneself · The kids amused themselves with toys.（孩子们玩玩具自娱自乐。）","nua":"amuse oneself（自娱自乐）、amuse sb with（用…逗乐）；派生 amusing/amused"},{"id":942,"day":16,"w":"attitude","ph":"ˈætɪtuːd","defs":[["n.","态度，看法",false]],"tier":"l","hint":"态度。词组 attitude to/towards 对…的态度","ex":"He has a positive attitude to life.（他对生活有积极的态度。）"},{"id":943,"day":16,"w":"authority","ph":"əˈθɔːrəti","defs":[["n.","权威；当局",true]],"tier":"f","ety":"author（创始人）+ -ity → 创始人地位 → 权威","mem":"author（作者）+ ity → 作者最懂自己的书 → 权威。画面：专家发言","ex":"the authorities · The authorities are investigating the case.（当局正在调查此案。）","nua":"authority（权威，不可数）、the authorities（当局，复数）；authorize（授权）"},{"id":944,"day":16,"w":"beat","ph":"biːt","defs":[["vt.","打，击；打败，战胜 vi.跳动 n.跳动；拍子，节拍",false]],"tier":"l","hint":"打、打败、心跳。过去式 beat。词组 beat the record 破纪录","ex":"Our team beat them by two goals.（我们队以两球击败他们。）"},{"id":945,"day":16,"w":"bit","ph":"bɪt","defs":[["n.","一片，一点，一些",false]],"tier":"l","hint":"一点。词组 a bit of 一点","ex":"I'm a bit tired today.（我今天有点累。）"},{"id":946,"day":16,"w":"build","ph":"bɪld","defs":[["vt.","修建，建造，建立",false]],"tier":"l","hint":"建造。过去式 built。词组 build up 建立","ex":"They built a new bridge last year.（他们去年建了座新桥。）"},{"id":947,"day":16,"w":"chest","ph":"tʃest","defs":[["n.","柜子，橱；胸脯，胸腔",false]],"tier":"l","hint":"胸膛、箱子。词组 chest pain 胸痛","ex":"He felt a pain in his chest.（他感到胸口痛。）"},{"id":948,"day":16,"w":"circular","ph":"ˈsɜːrkjələr","defs":[["a.","圆形的；循环的",false]],"tier":"l","hint":"circle（圆）+ -ar → 圆形的","ex":"The table is circular.（这张桌子是圆形的。）"},{"id":949,"day":16,"w":"citizen","ph":"ˈsɪtɪzn","defs":[["n.","公民，市民，居民",false]],"tier":"l","hint":"公民、市民。联想 city 城市、citizen 市民","ex":"Every citizen should obey the law.（每个公民都应守法。）"},{"id":950,"day":16,"w":"clean","ph":"kliːn","defs":[["a.","清洁的，干净的 vt.弄清洁，擦干净",false]],"tier":"l","hint":"干净的、打扫。联想 dirty 脏的（反义）","ex":"Please keep the classroom clean.（请保持教室干净。）"},{"id":951,"day":16,"w":"curve","ph":"kɜːrv","defs":[["vi.","/vt.弄弯，使成曲线 n.曲线，弯曲",false]],"tier":"l","hint":"曲线、弯曲。联想 curve 曲线、curved 弯曲的","ex":"The road curves to the left.（道路向左弯曲。）"},{"id":952,"day":16,"w":"debt","ph":"det","defs":[["n.","债，欠债",false]],"tier":"l","hint":"债务。词组 in debt 负债","ex":"He paid off all his debts.（他还清了所有债务。）"},{"id":953,"day":16,"w":"depth","ph":"depθ","defs":[["n.","深度；深厚，深切",false]],"tier":"l","hint":"deep（深）的名词 → 深度。词组 in depth 深入","ex":"The lake has a depth of ten meters.（这个湖深十米。）"},{"id":954,"day":16,"w":"desert","ph":"ˈdezərt","defs":[["n.","沙漠，不毛之地 vt.离开，拋弃；从……开小差",false]],"tier":"l","hint":"沙漠、抛弃。注意 desert（沙漠）/dessert（甜点）拼写","ex":"The camel can walk in the desert.（骆驼能在沙漠里行走。）"},{"id":955,"day":16,"w":"die","ph":"daɪ","defs":[["vi.","死亡，死",false]],"tier":"l","hint":"死。过去式 died。词组 die of 死于、die out 灭绝","ex":"The flowers died because of no water.（花因缺水死了。）"},{"id":956,"day":16,"w":"dirty","ph":"ˈdɜːrti","defs":[["a.","脏的；卑鄙的",false]],"tier":"l","hint":"dirt（污垢）+ -y → 脏的。联想 clean 干净的（反义）","ex":"Your hands are dirty, wash them.（你的手脏了，去洗洗。）"},{"id":957,"day":16,"w":"during","ph":"ˈdʊrɪŋ","defs":[["prep.","在……期间，在……时候",false]],"tier":"l","hint":"在…期间。词组 during the day 在白天","ex":"We went swimming during the summer.（夏天我们去游泳了。）"},{"id":958,"day":16,"w":"dust","ph":"dʌst","defs":[["n.","灰尘，尘土 vi/vt.拂，掸；撒（粉）",false]],"tier":"l","hint":"灰尘。联想 dust 灰尘、dusty 布满灰尘的","ex":"There is dust on the desk.（桌子上有灰尘。）"},{"id":959,"day":16,"w":"flow","ph":"floʊ","defs":[["vi.","流，流动；飘扬 n.流，流动；流量，流速",false]],"tier":"l","hint":"流动。联想 flow 流动、river flows 河流流淌","ex":"The river flows into the sea.（这条河流入大海。）"},{"id":960,"day":16,"w":"frighten","ph":"ˈfraɪtn","defs":[["vt.","吓唬，使惊恐",false]],"tier":"l","hint":"使害怕。词组 be frightened of 害怕","ex":"The loud noise frightened the baby.（巨响吓到了婴儿。）"},{"id":961,"day":16,"w":"frightening","ph":"ˈfraɪtnɪŋ","defs":[["a.","吓人的，令人害怕的",false]],"tier":"l","hint":"frighten（害怕）+ -ing → 令人害怕的","ex":"It was a frightening experience.（那是次可怕的经历。）"},{"id":962,"day":16,"w":"fun","ph":"fʌn","defs":[["n.","玩笑，乐趣；有趣的人/事",false]],"tier":"l","hint":"乐趣。词组 have fun 玩得开心、make fun of 取笑","ex":"We had a lot of fun at the party.（我们在聚会上玩得很开心。）"},{"id":963,"day":16,"w":"further","ph":"ˈfɜːrðər","defs":[["ad.","(far的比较级）更远地，更大程度上；而且此 外；进一步地 a.另外的，更多的；更远的 vt.促进，增进",false]],"tier":"l","hint":"far（远）的比较级 → 更远、进一步","ex":"For further information, please call us.（欲知详情，请致电。）"},{"id":964,"day":16,"w":"gentle","ph":"ˈdʒentl","defs":[["a.","和蔼的，文雅的，有礼貌的；轻柔的；坡度小的",false]],"tier":"l","hint":"温柔的、温和的。联想 gentleman 绅士（同源）","ex":"She spoke in a gentle voice.（她用温柔的声音说话。）"},{"id":965,"day":16,"w":"get","ph":"ɡet","defs":[["vt.","获得，得到；使得，使变得，成为；感染（疾病） vi.到达，抵达",false]],"tier":"l","hint":"得到、变得。过去式 got。词组 get up 起床、get along 相处","ex":"I get up at six every day.（我每天六点起床。）"},{"id":966,"day":16,"w":"hear","ph":"hɪr","defs":[["vt.","听见；听说，得知；倾听，听取；审讯，听证 vi.听见；(of/about)听说",false]],"tier":"l","hint":"听见。过去式 heard。词组 hear from 收到…来信","ex":"Can you hear me?（你能听见我吗？）"},{"id":967,"day":16,"w":"here","ph":"hɪr","defs":[["ad.","这里，到这里；在这一点上；这时",false]],"tier":"l","hint":"这里。词组 here and there 到处","ex":"Come here, please.（请过来。）"},{"id":968,"day":16,"w":"holy","ph":"ˈhoʊli","defs":[["a.","神圣的，圣洁的",false]],"tier":"l","hint":"神圣的。联想 holy 神圣、holy day 宗教节日","ex":"This is a holy place for them.（对他们来说这是圣地。）"},{"id":969,"day":16,"w":"horizontal","ph":"ˌhɔːrəˈzɑːntl","defs":[["a.","水平的，横的；地平线的水平线",false]],"tier":"l","hint":"水平的。联想 vertical 垂直的（反义）","ex":"The table is horizontal.（这张桌子是水平的。）"},{"id":970,"day":16,"w":"humor","ph":"hjuːmər","defs":[["n.","幽默，诙谐",false]],"tier":"l","hint":"幽默。联想 humorous 幽默的","ex":"He has a good sense of humor.（他很有幽默感。）"},{"id":971,"day":16,"w":"hurt","ph":"hɜːrt","defs":[["vt.","伤害，刺痛；伤……感情；损害，伤害 vi.痛，受痛苦 n.损害，伤害",false]],"tier":"l","hint":"伤害、疼痛。过去式 hurt。词组 hurt oneself 伤到自己","ex":"My head hurts.（我头疼。）"},{"id":972,"day":16,"w":"improvement","ph":"ɪmˈpruːvmənt","defs":[["n.","改进，改良，增进；改进措施",false]],"tier":"l","hint":"improve（改进）+ -ment → 改进","ex":"There is a big improvement in his English.（他的英语有很大进步。）"},{"id":973,"day":16,"w":"invite","ph":"ɪnˈvaɪt","defs":[["vt.","邀请，招待",false]],"tier":"l","hint":"邀请。词组 invite sb to 邀请某人","ex":"She invited me to her birthday party.（她邀请我去她的生日聚会。）"},{"id":974,"day":16,"w":"local","ph":"ˈloʊkl","defs":[["a.","地方的，当地的；局部的",false]],"tier":"l","hint":"当地的。词组 local people 当地人","ex":"The local people are very friendly.（当地人很友好。）"},{"id":975,"day":16,"w":"lung","ph":"lʌŋ","defs":[["n.","肺",false]],"tier":"l","hint":"肺。联想 heart 心、lung 肺","ex":"Smoking is bad for your lungs.（吸烟伤肺。）"},{"id":976,"day":16,"w":"oppose","ph":"əˈpoʊz","defs":[["vt.","反对，反抗",false]],"tier":"l","hint":"反对。词组 be opposed to 反对","ex":"Many people oppose the plan.（很多人反对这个计划。）"},{"id":977,"day":16,"w":"or","ph":"ɔːr","defs":[["conj.","或，或者；即；否则，要不然",false]],"tier":"l","hint":"或者。词组 either...or 要么…要么","ex":"Do you want tea or coffee?（你要茶还是咖啡？）"},{"id":978,"day":16,"w":"perform","ph":"pərˈfɔːrm","defs":[["vt.","做，施行，完成；表演，演出",false]],"tier":"l","hint":"表演、执行。联想 performance 表演（名词）","ex":"She performed a song at the concert.（她在音乐会上演唱了一首歌。）"},{"id":979,"day":16,"w":"plate","ph":"pleɪt","defs":[["n.","盘子，盆子；板，钢板 vt.镀，电镀",false]],"tier":"l","hint":"盘子。联想 plate 盘子、dish 菜/盘","ex":"Put the food on the plate.（把食物放在盘子里。）"},{"id":980,"day":16,"w":"plenty","ph":"ˈplenti","defs":[["n.","丰富，富裕",false]],"tier":"l","hint":"大量。词组 plenty of 大量的","ex":"There is plenty of time.（时间很充裕。）"},{"id":981,"day":16,"w":"possibility","ph":"ˌpɑːsəˈbɪləti","defs":[["n.","可能性",true]],"tier":"f","ety":"possible（可能的）+ -ity → 可能性","mem":"possible + ity → 可能的（possible）名词 → 可能性","ex":"the possibility of · There is a possibility of rain.（有可能下雨。）","nua":"possibility（可能性）、probability（概率，更确定）；there is a possibility of/that"},{"id":982,"day":16,"w":"prevent","ph":"prɪˈvent","defs":[["vt.","预防，防止",false]],"tier":"l","hint":"预防、阻止。词组 prevent...from 阻止…做","ex":"The rain prevented us from going out.（雨阻止了我们外出。）"},{"id":983,"day":16,"w":"relationship","ph":"rɪˈleɪʃnʃɪp","defs":[["n.","关系，联系",false]],"tier":"l","hint":"relation（关系）+ -ship → 关系","ex":"They have a good relationship.（他们关系很好。）"},{"id":984,"day":16,"w":"rent","ph":"rent","defs":[["n.","租金 vt.租，租赁 vi.出租",false]],"tier":"l","hint":"租。词组 rent a house 租房","ex":"They rent a house in the city.（他们在城里租房。）"},{"id":985,"day":16,"w":"say","ph":"seɪ","defs":[["vt.","说，讲；说明，表明；比方说，大约 vi.说，发表意见",false]],"tier":"l","hint":"说。过去式 said。词组 say to 对…说","ex":"What did you say?（你说什么？）"},{"id":986,"day":16,"w":"seat","ph":"siːt","defs":[["n.","席位，座位；底座；所在地 vt.使……就座",false]],"tier":"l","hint":"座位。词组 take a seat 坐下、have a seat 请坐","ex":"Please take a seat.（请坐。）"},{"id":987,"day":16,"w":"serious","ph":"sɪriəs","defs":[["a.","严肃的，庄重的；严重的，危急的；认真的",false]],"tier":"l","hint":"严肃的、严重的。词组 a serious problem 严重的问题","ex":"The situation is very serious.（形势很严重。）"},{"id":988,"day":16,"w":"smell","ph":"smel","defs":[["n.","气味；嗅觉；臭味",false]],"tier":"l","hint":"闻、气味。词组 smell good 闻起来好","ex":"The flowers smell sweet.（花闻起来很香。）"},{"id":989,"day":16,"w":"soil","ph":"sɔɪl","defs":[["n.","土壤，土地",false]],"tier":"l","hint":"土壤。联想 soil 土壤、earth 泥土","ex":"Plants grow in the soil.（植物在土壤里生长。）"},{"id":990,"day":16,"w":"soon","ph":"suːn","defs":[["ad.","不久；早，快",false]],"tier":"l","hint":"很快、不久。词组 as soon as 一…就","ex":"I'll come back soon.（我很快就回来。）"},{"id":991,"day":16,"w":"store","ph":"stɔːr","defs":[["vt.","贮藏，贮存 n.贮藏，贮存；商店，店铺；贮存品，备用品",false]],"tier":"l","hint":"商店、储存。词组 department store 百货商店","ex":"He bought some food at the store.（他在商店买了些食物。）"},{"id":992,"day":16,"w":"stupid","ph":"ˈstuːpɪd","defs":[["a.","愚蠢的，迟钝的",false]],"tier":"l","hint":"愚蠢的。联想 clever 聪明的（反义）","ex":"It was stupid of me to forget.（我忘记真是太蠢了。）"},{"id":993,"day":16,"w":"succeed","ph":"səkˈsiːd","defs":[["vi.","成功;继承，接替 vt.接替，接……之后",false]],"tier":"l","hint":"成功。词组 succeed in 在…成功","ex":"He succeeded in passing the exam.（他成功通过了考试。）"},{"id":994,"day":16,"w":"sure","ph":"ʃʊr","defs":[["a.","必然的；确信的；稳当的，可靠的",false]],"tier":"l","hint":"确信。词组 be sure of 确信、make sure 确保","ex":"Make sure to lock the door.（一定要锁门。）"},{"id":995,"day":16,"w":"whole","ph":"hoʊl","defs":[["n.","/a.全部（的），全体（的），完整（的）",false]],"tier":"l","hint":"整个的。词组 the whole 全部、on the whole 总的来说","ex":"I spent the whole day reading.（我花了一整天读书。）"},{"id":996,"day":16,"w":"width","ph":"wɪdθ","defs":[["n.","宽度",true]],"tier":"f","ety":"wide（宽）+ -th（名词）→ 宽度","mem":"wide + th → 宽（wide）的名词 → 宽度。画面：量尺横着量","ex":"in width · The room is 5 meters in width.（这个房间宽 5 米。）","nua":"-th 名词：width 宽、length 长、depth 深、strength 强；wide（形）→ width（名）"},{"id":997,"day":16,"w":"wild","ph":"waɪld","defs":[["a.","野生的，野蛮的；荒芜的，荒凉的；凶猛的，狂 暴的；疯狂的，狂热的",false]],"tier":"l","hint":"野生的、狂野的。词组 wild animals 野生动物","ex":"There are many wild animals in the forest.（森林里有很多野生动物。）"},{"id":998,"day":16,"w":"wing","ph":"wɪŋ","defs":[["n.","翼，翅膀",false]],"tier":"l","hint":"翅膀。联想 bird 鸟、wing 翅膀","ex":"The bird spread its wings.（鸟儿展开了翅膀。）"},{"id":999,"day":16,"w":"wool","ph":"wʊl","defs":[["n.","羊毛；毛线，毛织品",false]],"tier":"l","hint":"羊毛。联想 wool 羊毛、woolen 羊毛的","ex":"This sweater is made of wool.（这件毛衣是羊毛做的。）"},{"id":1000,"day":16,"w":"worse","ph":"wɜːrs","defs":[["a.","/ad.更坏（的），更差（的）",false]],"tier":"l","hint":"bad 的比较级 → 更糟。词组 worse and worse 越来越糟","ex":"The weather is getting worse.（天气越来越糟。）"},{"id":1001,"day":17,"w":"anxiety","ph":"æŋˈzaɪəti","defs":[["n.","焦虑，担心；渴望",true]],"tier":"f","ety":"拉丁 anxius（焦虑的）→ anxiety","mem":"谐音\"俺在爱特\"→ \"俺\"因为太\"爱\"所以\"特\"别焦虑 → 焦虑。画面：坐立不安","ex":"anxiety about · She felt anxiety about the exam.（她对考试感到焦虑。）","nua":"anxiety（名词焦虑）、anxious（形容词焦虑的）；anxiety about/over（对…焦虑）"},{"id":1002,"day":17,"w":"argument","ph":"ˈɑːrɡjumənt","defs":[["n.","争论；论点，依据",true]],"tier":"f","ety":"argue（争论）+ -ment → 争论","mem":"argue + ment → 争论的名词（注意 argue 去 e）。画面：两人面红耳赤","ex":"a strong argument · He gave a strong argument for the plan.（他为这个计划提出了有力论据。）","nua":"argument（争论、论点）、argue with sb（与…争论）；注意 argue→argument 拼写去 e"},{"id":1003,"day":17,"w":"as","ph":"əz","defs":[["conj.","当/在……时候；如……一样；由于，因为 prep.作为，当作",false]],"tier":"l","hint":"作为、因为、当…时。词组 as soon as 一…就、as if 好像","ex":"He works as a teacher.（他当老师。）"},{"id":1004,"day":17,"w":"but","ph":"bət","defs":[["conj.","可是，但是，然而 prep.除……之外 ad.只，仅仅",false]],"tier":"s"},{"id":1005,"day":17,"w":"cause","ph":"kɔːz","defs":[["n.","原因，理由，缘故；事业，奋斗目标 vt.引起",false]],"tier":"l","hint":"原因、导致。词组 cause...to do 导致…做、the cause of …的原因","ex":"What caused the accident?（是什么导致了事故？）"},{"id":1006,"day":17,"w":"climb","ph":"klaɪm","defs":[["vi.","/vt.爬，攀登 n.爬，攀登",false]],"tier":"l","hint":"爬。词组 climb the mountain 爬山","ex":"They climbed the mountain last Sunday.（他们上周日爬了山。）"},{"id":1007,"day":17,"w":"collect","ph":"kəˈlekt","defs":[["vt.","收集，收（税等） vi.聚集，堆积",false]],"tier":"l","hint":"收集。联想 collection 收集（名词）","ex":"He collects stamps as a hobby.（他集邮作为爱好。）"},{"id":1008,"day":17,"w":"complete","ph":"kəmˈpliːt","defs":[["a.","全，完全；已完成的，彻底的 vt.完成，结束",false]],"tier":"l","hint":"完成、完整的。联想 completely 完全地","ex":"She completed the task on time.（她按时完成了任务。）"},{"id":1009,"day":17,"w":"corner","ph":"ˈkɔːrnər","defs":[["n.","角，角落",false]],"tier":"l","hint":"角落。词组 at the corner 在角落","ex":"The shop is at the corner of the street.（商店在街角。）"},{"id":1010,"day":17,"w":"cry","ph":"kraɪ","defs":[["vi.","/n.叫，喊，哭泣",false]],"tier":"l","hint":"哭、喊。联想 laugh 笑（反义）","ex":"The baby cried for milk.（婴儿哭着要奶。）"},{"id":1011,"day":17,"w":"customer","ph":"ˈkʌstəmər","defs":[["n.","顾客，主顾",false]],"tier":"l","hint":"custom（习惯）+ -er → 顾客（常来的人）","ex":"The shop has many customers.（这家店有很多顾客。）"},{"id":1012,"day":17,"w":"desire","ph":"dɪˈzaɪər","defs":[["vt.","/n.愿望，欲望；要求",false]],"tier":"l","hint":"渴望。词组 a desire for 对…的渴望","ex":"She has a strong desire to learn.（她有强烈的学习渴望。）"},{"id":1013,"day":17,"w":"determined","ph":"dɪˈtɜːrmɪnd","defs":[["a.","下定决心的，决意的",false]],"tier":"l","hint":"determine（决定）+ -d → 坚定的。词组 be determined to 决心做","ex":"He is determined to succeed.（他决心成功。）"},{"id":1014,"day":17,"w":"dollar","ph":"ˈdɑːlər","defs":[["n.","美元，元",false]],"tier":"l","hint":"美元。联想 money 钱、dollar 美元","ex":"The book costs ten dollars.（这本书十美元。）"},{"id":1015,"day":17,"w":"elect","ph":"ɪˈlekt","defs":[["vt.","推选，选举",false]],"tier":"l","hint":"选举。联想 election 选举（名词）","ex":"They elected him as their leader.（他们选他做领导。）"},{"id":1016,"day":17,"w":"end","ph":"end","defs":[["n.","端，尾；目标，目的 vt.终止，结束",false]],"tier":"l","hint":"结束、末端。词组 in the end 最后、come to an end 结束","ex":"The meeting came to an end at five.（会议五点结束。）"},{"id":1017,"day":17,"w":"examination","ph":"ɪɡˌzæmɪˈneɪʃn","defs":[["n.","考试，测验；检验，检查，审查",false]],"tier":"l","hint":"examine（考试）+ -ation → 考试（缩写 exam）","ex":"The examination is next week.（考试在下周。）"},{"id":1018,"day":17,"w":"fashion","ph":"ˈfæʃn","defs":[["n.","样子,方式；流行，风尚，时髦",false]],"tier":"l","hint":"时尚。词组 in fashion 流行、out of fashion 过时","ex":"This style is in fashion now.（这种款式现在很流行。）"},{"id":1019,"day":17,"w":"fasten","ph":"ˈfæsn","defs":[["vt.","扣紧，结牢，闩上",false]],"tier":"l","hint":"fast（紧）+ -en → 系紧。词组 fasten the seat belt 系安全带","ex":"Please fasten your seat belt.（请系好安全带。）"},{"id":1020,"day":17,"w":"favo(u)rite","ph":"ˈfevərɪt","defs":[["a.","最喜爱的 n.最喜爱的人（或物）",false]],"tier":"l","hint":"favour（喜爱）+ -ite → 最喜爱的","ex":"Blue is my favourite colour.（蓝色是我最喜欢的颜色。）"},{"id":1021,"day":17,"w":"fence","ph":"fens","defs":[["n.","篱笆，围栏，栅栏",false]],"tier":"l","hint":"栅栏。联想 fence 栅栏、garden fence 花园栅栏","ex":"The garden is surrounded by a fence.（花园围着栅栏。）"},{"id":1022,"day":17,"w":"fight","ph":"faɪt","defs":[["vi.","/vt./n.打架，打仗，斗争",false]],"tier":"l","hint":"打架、战斗。过去式 fought。词组 fight against 与…斗争","ex":"They fought against the enemy.（他们与敌人战斗。）"},{"id":1023,"day":17,"w":"first","ph":"fɜːrst","defs":[["a.","第一 ad.最初，首先",false]],"tier":"l","hint":"第一、首先。词组 at first 起初、first of all 首先","ex":"First of all, let me introduce myself.（首先，让我自我介绍一下。）"},{"id":1024,"day":17,"w":"forest","ph":"ˈfɔːrɪst","defs":[["n.","森林，森林地带",false]],"tier":"l","hint":"森林。联想 tree 树、forest 森林","ex":"Many animals live in the forest.（很多动物住在森林里。）"},{"id":1025,"day":17,"w":"front","ph":"frʌnt","defs":[["a.","前部的，前面的 n.前部；前面；前线，战线，阵线 vt.面向，面对",false]],"tier":"l","hint":"前面。词组 in front of 在…前面","ex":"There is a tree in front of the house.（房子前面有棵树。）"},{"id":1026,"day":17,"w":"glass","ph":"ɡlæs","defs":[["n.","玻璃，玻璃杯；镜子；(pl.)眼镜",false]],"tier":"l","hint":"玻璃、玻璃杯。词组 a glass of water 一杯水","ex":"Please give me a glass of water.（请给我一杯水。）"},{"id":1027,"day":17,"w":"hollow","ph":"ˈhɑːloʊ","defs":[["a.","空的，中空的；空洞的，空虚的",false]],"tier":"l","hint":"空的、中空的。联想 hollow 中空的、empty 空的","ex":"The tree is hollow inside.（这棵树里面是空的。）"},{"id":1028,"day":17,"w":"hook","ph":"hʊk","defs":[["n.","钩，钩状物 vt.钩住",false]],"tier":"l","hint":"钩子。联想 hook 钩、fishing hook 鱼钩","ex":"He hung his coat on the hook.（他把外套挂在钩子上。）"},{"id":1029,"day":17,"w":"map","ph":"mæp","defs":[["n.","图，地图",false]],"tier":"l","hint":"地图。词组 on the map 在地图上","ex":"Look at the map and find the city.（看地图找这座城市。）"},{"id":1030,"day":17,"w":"mark","ph":"mɑːrk","defs":[["n.","记号，标记，痕迹；分数 vt.记分，打分；作标记",false]],"tier":"l","hint":"标记、分数。词组 full mark 满分","ex":"Please mark the correct answer.（请标出正确答案。）"},{"id":1031,"day":17,"w":"material","ph":"məˈtɪriəl","defs":[["n.","材料，原料；资料 a.物质的，实物的，具体的",false]],"tier":"l","hint":"材料。词组 teaching material 教材","ex":"The bridge is made of strong material.（这座桥用坚固材料建造。）"},{"id":1032,"day":17,"w":"meter/-re","ph":"ˈmiːtər","defs":[["n.","公尺，米；仪表",false]],"tier":"l","hint":"米（长度单位）。联想 kilometer 千米","ex":"The room is five meters long.（房间长五米。）"},{"id":1033,"day":17,"w":"milk","ph":"mɪlk","defs":[["n.","乳，牛奶 vt.给（牛、羊)挤奶",false]],"tier":"l","hint":"牛奶。词组 a glass of milk 一杯牛奶","ex":"I drink milk every morning.（我每天早晨喝牛奶。）"},{"id":1034,"day":17,"w":"move","ph":"muːv","defs":[["vt.","移动，搬动，迁移；感动 vi.动，走动；搬家，迁移 n.动，动作，行动",false]],"tier":"l","hint":"移动、搬家。词组 move to 搬到","ex":"They moved to a new house.（他们搬到了新房子。）"},{"id":1035,"day":17,"w":"northern","ph":"ˈnɔːrðərn","defs":[["a.","北的，北方的",false]],"tier":"l","hint":"north（北）+ -ern → 北方的。联想 southern 南方的","ex":"They live in the northern part of China.（他们住在中国北方。）"},{"id":1036,"day":17,"w":"past","ph":"pæst","defs":[["a.","过去的，过去，昔时，往事 prep.过，经过",false]],"tier":"l","hint":"过去的、经过。词组 in the past 在过去","ex":"In the past, people used horses for travel.（过去人们骑马出行。）"},{"id":1037,"day":17,"w":"pet","ph":"pet","defs":[["n.","爱畜，宠儿 a.宠爱，表示亲昵的",false]],"tier":"l","hint":"宠物。联想 pet dog 宠物狗","ex":"She has a pet cat.（她养了只宠物猫。）"},{"id":1038,"day":17,"w":"poison","ph":"ˈpɔɪzn","defs":[["n.","毒物，毒药 vt.放毒，毒害",false]],"tier":"l","hint":"毒药。联想 poisonous 有毒的","ex":"Some mushrooms contain poison.（有些蘑菇含毒。）"},{"id":1039,"day":17,"w":"principle","ph":"ˈprɪnsəpl","defs":[["n.","原理，原则；主义，信念",false]],"tier":"l","hint":"原则。词组 in principle 原则上","ex":"We should stick to our principles.（我们应该坚持原则。）"},{"id":1040,"day":17,"w":"process","ph":"ˈprɑːses","defs":[["n.","过程，历程；工序，工艺 vt.加工，处理",false]],"tier":"l","hint":"过程、加工。词组 in the process of 在…过程中","ex":"Learning is a long process.（学习是个漫长的过程。）"},{"id":1041,"day":17,"w":"product","ph":"ˈprɑːdʌkt","defs":[["n.","产品，产物；乘积",false]],"tier":"l","hint":"produce（生产）的名词 → 产品","ex":"The company makes electronic products.（这家公司生产电子产品。）"},{"id":1042,"day":17,"w":"promise","ph":"ˈprɑːmɪs","defs":[["vt.","答应，允诺；有……可能，有希望 n.承诺，诺言；希望，出息",false]],"tier":"l","hint":"承诺。词组 make a promise 许下承诺、promise to do 承诺做","ex":"He promised to help me.（他答应帮我。）"},{"id":1043,"day":17,"w":"pump","ph":"pʌmp","defs":[["n.","泵 vt.打气，泵送",false]],"tier":"l","hint":"泵、抽水。联想 pump water 抽水","ex":"They pumped water from the well.（他们从井里抽水。）"},{"id":1044,"day":17,"w":"really","ph":"ˈriːəli","defs":[["ad.","确实，实在；真正地，果然",false]],"tier":"l","hint":"real（真实）+ -ly → 真正地、确实","ex":"I really like this book.（我真的很喜欢这本书。）"},{"id":1045,"day":17,"w":"reduce","ph":"rɪˈduːs","defs":[["vt.","缩小，减小，减低；使成为；简化；还原",false]],"tier":"l","hint":"减少。词组 reduce to 减少到","ex":"We should reduce pollution.（我们应该减少污染。）"},{"id":1046,"day":17,"w":"rubber","ph":"ˈrʌbər","defs":[["n.","橡皮，橡胶；橡胶制品，胶鞋 a.橡胶的",false]],"tier":"l","hint":"橡胶。联想 rubber 橡胶、rubber band 橡皮筋","ex":"The ball is made of rubber.（这个球是橡胶做的。）"},{"id":1047,"day":17,"w":"rule","ph":"ruːl","defs":[["n.","规则，规章，规律；惯例，常规 vi./vt.裁决，裁定；统治，支配",false]],"tier":"l","hint":"规则、统治。词组 obey the rules 遵守规则","ex":"Everyone must follow the rules.（每个人都必须遵守规则。）"},{"id":1048,"day":17,"w":"scene","ph":"siːn","defs":[["n.","景色，景象；（戏）一场；布景；镜头",false]],"tier":"l","hint":"场景、景色。词组 behind the scenes 幕后","ex":"The mountain scene is beautiful.（山景很美。）"},{"id":1049,"day":17,"w":"service","ph":"ˈsɜːrvɪs","defs":[["n.","服务；公共事业；服役，帮助；服侍；公共设施 vi.维护，保养",false]],"tier":"l","hint":"serve（服务）的名词 → 服务","ex":"The hotel provides good service.（这家旅馆服务很好。）"},{"id":1050,"day":17,"w":"shy","ph":"ʃaɪ","defs":[["a.","害羞的，腼腆的；易受惊的，胆怯的",false]],"tier":"l","hint":"害羞的。联想 shy 害羞、shyly 害羞地","ex":"The little girl is very shy.（小女孩很害羞。）"},{"id":1051,"day":17,"w":"skirt","ph":"skɜːrt","defs":[["n.","裙子；(pl.)边缘，郊区",false]],"tier":"l","hint":"裙子。联想 dress 连衣裙、skirt 短裙","ex":"She wore a red skirt.（她穿了条红裙子。）"},{"id":1052,"day":17,"w":"slow","ph":"sloʊ","defs":[["a.","慢的，缓慢的；迟钝的 vi./vt.放慢，（使）减速",false]],"tier":"l","hint":"慢的。联想 fast 快的（反义）、slowly 慢慢地","ex":"The bus is slow in the traffic.（公交车在车流中很慢。）"},{"id":1053,"day":17,"w":"soft","ph":"sɔːft","defs":[["a.","软的；柔软的，温柔的，柔和的；细嫩的，光滑 的；不含酒精的",false]],"tier":"l","hint":"柔软的。联想 hard 硬的（反义）","ex":"The bed is soft and comfortable.（床柔软舒适。）"},{"id":1054,"day":17,"w":"software","ph":"ˈsɔːftwer","defs":[["n.","软件",false]],"tier":"l","hint":"soft（软）+ ware（件）→ 软件。联想 hardware 硬件","ex":"I need to update the software.（我需要更新软件。）"},{"id":1055,"day":17,"w":"speak","ph":"spiːk","defs":[["vi.","说话，讲，发言，演说",false]],"tier":"l","hint":"说、讲。过去式 spoke。词组 speak English 说英语","ex":"She speaks English very well.（她英语说得很好。）"},{"id":1056,"day":17,"w":"sudden","ph":"ˈsʌdn","defs":[["a.","突然的，意想不到的",false]],"tier":"l","hint":"突然的。词组 all of a sudden 突然","ex":"There was a sudden change in the weather.（天气突然变化。）"},{"id":1057,"day":17,"w":"television","ph":"ˈtelɪvɪʒn","defs":[["n.","电视，电视机",false]],"tier":"l","hint":"电视（缩写 TV）。词组 watch television 看电视","ex":"We watch television in the evening.（我们晚上看电视。）"},{"id":1058,"day":17,"w":"thousand","ph":"ˈθaʊznd","defs":[["num.","/n.一千；(pl.)许许多多，成千上万",false]],"tier":"l","hint":"千。词组 thousands of 数千","ex":"There are thousands of books in the library.（图书馆有数千本书。）"},{"id":1059,"day":17,"w":"toe","ph":"toʊ","defs":[["n.","脚趾，足尖",false]],"tier":"l","hint":"脚趾。联想 finger 手指、toe 脚趾","ex":"He hurt his toe when walking.（他走路时伤了脚趾。）"},{"id":1060,"day":17,"w":"tongue","ph":"tʌŋ","defs":[["n.","舌，舌头；语言",false]],"tier":"l","hint":"舌头、语言。词组 mother tongue 母语","ex":"English is not my mother tongue.（英语不是我的母语。）"},{"id":1061,"day":17,"w":"tool","ph":"tuːl","defs":[["n.","工具",false]],"tier":"l","hint":"工具。联想 tool 工具、machine 机器","ex":"He needs some tools to fix the bike.（他需要工具修自行车。）"},{"id":1062,"day":17,"w":"tribe","ph":"traɪb","defs":[["n.","部落，宗族",false]],"tier":"l","hint":"部落。联想 tribe 部落、clan 氏族","ex":"The tribe lives in the mountains.（这个部落住在山里。）"},{"id":1063,"day":17,"w":"use","ph":"juːs","defs":[["vt.","用，使用，运用；消耗 n.使用，应用；用法，用途；益处，用处",false]],"tier":"l","hint":"使用、用途。词组 use up 用完、make use of 利用","ex":"May I use your pen?（我可以用你的笔吗？）"},{"id":1064,"day":18,"w":"actor","ph":"ˈæktər","defs":[["n.","男演员",false]],"tier":"l","hint":"act（表演）+ -or（人）→ 演员（男）。联想 actress 女演员","ex":"He is a famous actor.（他是著名演员。）"},{"id":1065,"day":18,"w":"actually","ph":"ˈæktʃuəli","defs":[["ad.","事实上，实际上",true]],"tier":"f","ety":"actual（实际的）+ -ly → 实际上","mem":"actual + ly → 实际的（actual）副词 → 实际上。画面：戳破表面看真相","ex":"in fact · Actually, I don't agree with you.（实际上，我不同意你的看法。）","nua":"actually（实际上，表转折或纠正）、in fact（事实上）；都用于引出真实情况"},{"id":1066,"day":18,"w":"agreement","ph":"əˈɡriːmənt","defs":[["n.","同意，一致；协议，协定，契约",false]],"tier":"l","hint":"agree（同意）+ -ment → 协议。词组 reach an agreement 达成协议","ex":"They reached an agreement at last.（他们最终达成了协议。）"},{"id":1067,"day":18,"w":"approval","ph":"əˈpruːvl","defs":[["n.","同意，赞同；批准",true]],"tier":"f","ety":"approve（赞成）+ -al → 赞成","mem":"approve + al → 赞成（approve）的名词。画面：领导盖章通过","ex":"with approval · The plan met with general approval.（这个计划得到普遍赞同。）","nua":"approve（动词）、approval（名词）、disapproval（反对）；meet with approval 获得赞成"},{"id":1068,"day":18,"w":"art","ph":"ɑːrt","defs":[["n.","艺术，美术；技术，技艺；(pl.)文科",false]],"tier":"l","hint":"艺术。联想 artist 艺术家、art 艺术","ex":"She is interested in art.（她对艺术感兴趣。）"},{"id":1069,"day":18,"w":"beautiful","ph":"ˈbjuːtɪfl","defs":[["a.","美的，美丽的",false]],"tier":"l","hint":"beauty（美）+ -ful → 美丽的","ex":"The garden is very beautiful.（花园很美。）"},{"id":1070,"day":18,"w":"better","ph":"ˈbetər","defs":[["a.","较好的，更好的 ad.更好 vt.改良，改善",false]],"tier":"l","hint":"good 的比较级 → 更好。词组 had better 最好","ex":"You had better go now.（你最好现在走。）"},{"id":1071,"day":18,"w":"breath","ph":"breθ","defs":[["n.","呼吸，气息",false]],"tier":"l","hint":"呼吸（名词）。词组 out of breath 上气不接下气、take a breath 呼吸","ex":"Take a deep breath and relax.（深呼吸，放松。）"},{"id":1072,"day":18,"w":"choice","ph":"tʃɔɪs","defs":[["n.","选择；选择机会",false]],"tier":"l","hint":"choose（选择）的名词 → 选择。词组 make a choice 做选择","ex":"You have no choice but to wait.（你别无选择只能等。）"},{"id":1073,"day":18,"w":"colo(u)r","ph":"ˈkʌlər","defs":[["n.","颜色，色彩；颜料；肤色 vi.给……染色",false]],"tier":"l","hint":"颜色（英式，美式 color）","ex":"She likes bright colours.（她喜欢鲜艳的颜色。）"},{"id":1074,"day":18,"w":"concerning","ph":"kənˈsɜːrnɪŋ","defs":[["prep.","关于，就…而论",true]],"tier":"f","ety":"concern（涉及）+ -ing → 涉及的 → 关于","mem":"concern（涉及）+ ing → 涉及到的 → 关于。画面：话题范围圈定","ex":"concerning the matter · I have nothing to say concerning the matter.（关于此事我无可奉告。）","nua":"concerning（介词，关于，正式）= regarding；不要与 concern 动词混淆"},{"id":1075,"day":18,"w":"confusing","ph":"kənˈfjuːzɪŋ","defs":[["a.","令人困惑的，使混淆的",false]],"tier":"l","hint":"confuse（困惑）+ -ing → 令人困惑的","ex":"The directions are confusing.（这些说明令人困惑。）"},{"id":1076,"day":18,"w":"conversation","ph":"ˌkɑːnvərˈseɪʃn","defs":[["n.","会话，谈话",false]],"tier":"l","hint":"converse（交谈）+ -ation → 谈话。词组 have a conversation 交谈","ex":"They had a long conversation.（他们谈了很长时间。）"},{"id":1077,"day":18,"w":"course","ph":"kɔːrs","defs":[["n.","进程，过程；课程；（一）道（菜）",false]],"tier":"l","hint":"课程、过程、路线。词组 of course 当然、in the course of 在…过程中","ex":"Of course I will help you.（我当然会帮你。）"},{"id":1078,"day":18,"w":"decide","ph":"dɪˈsaɪd","defs":[["vi.","决定；裁决",false]],"tier":"l","hint":"决定。词组 decide to do 决定做、decide on 决定","ex":"We decided to go by train.（我们决定坐火车去。）"},{"id":1079,"day":18,"w":"deliberate","ph":"dɪˈlɪbərət","defs":[["a.","故意的，蓄意的；从容的",true]],"tier":"f","ety":"de-（完全）+ liber（称量，同 libra 天平）+ -ate → 反复掂量 → 深思熟虑的、故意的","mem":"de + liber（=liberty 自由）+ ate → 想清楚了才\"自由\"行动 → 从容的、蓄意的。画面：慢慢盘算再出手","ex":"a deliberate act · It was a deliberate act, not an accident.（这是蓄意行为，不是意外。）","nua":"deliberate（故意的、从容的）、deliberately（故意地，副词）；反义 accidental"},{"id":1080,"day":18,"w":"discover","ph":"dɪˈskʌvər","defs":[["vt.","发现；暴露，显示",false]],"tier":"l","hint":"发现。联想 discovery 发现（名词）","ex":"Columbus discovered America.（哥伦布发现了美洲。）"},{"id":1081,"day":18,"w":"embarrassing","ph":"ɪmˈbærəsɪŋ","defs":[["a.","令人尴尬的",true]],"tier":"f","ety":"embarrass（使尴尬）+ -ing → 令人尴尬的","mem":"embarrass + ing → 让人\"尴尬\"的 → 令人尴尬的。画面：当众出丑","ex":"an embarrassing moment · It was an embarrassing moment for me.（那是我尴尬的一刻。）","nua":"embarrassing（令人尴尬，修饰事）、embarrassed（感到尴尬，修饰人）"},{"id":1082,"day":18,"w":"eye","ph":"aɪ","defs":[["n.","眼睛；眼光，眼力 vt.看，注视",false]],"tier":"l","hint":"眼睛。词组 keep an eye on 照看、catch one's eye 引人注目","ex":"She has beautiful eyes.（她有美丽的眼睛。）"},{"id":1083,"day":18,"w":"fault","ph":"fɔːlt","defs":[["n.","缺点，缺陷；过失，过错",false]],"tier":"l","hint":"过错、缺点。词组 at fault 有过错、find fault with 挑剔","ex":"It's my fault that we were late.（我们迟到是我的错。）"},{"id":1084,"day":18,"w":"goat","ph":"ɡoʊt","defs":[["n.","山羊",false]],"tier":"l","hint":"山羊。联想 sheep 绵羊、goat 山羊","ex":"The goat is eating grass.（山羊在吃草。）"},{"id":1085,"day":18,"w":"herb","ph":"ɜːrb","defs":[["n.","(调味或药用的）草本植物",false]],"tier":"l","hint":"香草、药草。联想 herb 药草、herbal 草药的","ex":"They grow herbs in the garden.（他们在花园里种香草。）"},{"id":1086,"day":18,"w":"importance","ph":"ɪmˈpɔːrtns","defs":[["n.","重要，重要性",false]],"tier":"l","hint":"important（重要的）的名词 → 重要性。词组 of importance 重要的","ex":"The matter is of great importance.（这件事非常重要。）"},{"id":1087,"day":18,"w":"important","ph":"ɪmˈpɔːrtnt","defs":[["a.","重要的，重大的；有地位的，显要的",false]],"tier":"l","hint":"重要的。词组 be important to 对…重要","ex":"Health is important to everyone.（健康对每个人都很重要。）"},{"id":1088,"day":18,"w":"leather","ph":"ˈleðər","defs":[["n.","皮革，皮革制品",false]],"tier":"l","hint":"皮革。联想 leather shoes 皮鞋","ex":"These shoes are made of leather.（这双鞋是皮革做的。）"},{"id":1089,"day":18,"w":"leave","ph":"liːv","defs":[["vt.","离开，动身；留下；忘带；听任 vi.离开，出发 n.许可，同意；告假，休息",false]],"tier":"l","hint":"离开、留下。过去式 left。词组 leave for 动身去、leave out 遗漏","ex":"He left the office at six.（他六点离开办公室。）"},{"id":1090,"day":18,"w":"library","ph":"ˈlaɪbreri","defs":[["n.","图书馆；丛书，文库",false]],"tier":"l","hint":"图书馆。联想 book 书、library 图书馆","ex":"She goes to the library every day.（她每天去图书馆。）"},{"id":1091,"day":18,"w":"market","ph":"ˈmɑːrkɪt","defs":[["n.","市场    vt.销售",false]],"tier":"l","hint":"市场。词组 go to the market 去市场","ex":"My mother goes to the market every morning.（我妈妈每天早上去市场。）"},{"id":1092,"day":18,"w":"mud","ph":"mʌd","defs":[["n.","泥，泥浆",false]],"tier":"l","hint":"泥。联想 mud 泥、muddy 泥泞的","ex":"The car got stuck in the mud.（车陷进泥里了。）"},{"id":1093,"day":18,"w":"murder","ph":"ˈmɜːrdər","defs":[["vt.","/n.谋杀，凶杀",false]],"tier":"l","hint":"谋杀。联想 kill 杀、murder 谋杀","ex":"The police are investigating the murder.（警方正在调查这起谋杀案。）"},{"id":1094,"day":18,"w":"news","ph":"nuːz","defs":[["n.","新闻，消息",false]],"tier":"l","hint":"新闻。词组 a piece of news 一条新闻","ex":"Have you heard the news?（你听说这消息了吗？）"},{"id":1095,"day":18,"w":"office","ph":"ˈɔːfɪs","defs":[["n.","办公室，办事处；部，处，局；职务，公职",false]],"tier":"l","hint":"办公室。词组 office worker 办公室职员","ex":"He works in an office.（他在办公室工作。）"},{"id":1096,"day":18,"w":"ought to","ph":"ˈɔːt tə","defs":[["aux.","v.应该，应当；本应，本当",false]],"tier":"l","hint":"应该。词组 ought to do 应该做","ex":"You ought to work harder.（你应该更努力。）"},{"id":1097,"day":18,"w":"petrol","ph":"ˈpetrəl","defs":[["n.","汽油",false]],"tier":"l","hint":"汽油（英）。联想 gas 汽油（美）","ex":"The car needs some petrol.（车需要加汽油。）"},{"id":1098,"day":18,"w":"poisonous","ph":"ˈpɔɪzənəs","defs":[["a.","有毒的；恶毒的",false]],"tier":"l","hint":"poison（毒）+ -ous → 有毒的","ex":"Some snakes are poisonous.（有些蛇有毒。）"},{"id":1099,"day":18,"w":"possess","ph":"pəˈzes","defs":[["vt.","拥有，占有",false]],"tier":"l","hint":"拥有。联想 possession 财产（名词）","ex":"He possesses a large house.（他拥有一栋大房子。）"},{"id":1100,"day":18,"w":"property","ph":"ˈprɑːpərti","defs":[["n.","财产，所有物；性质，特性",false]],"tier":"l","hint":"财产、特性。联想 property 财产、possess 拥有","ex":"This is private property.（这是私有财产。）"},{"id":1101,"day":18,"w":"protection","ph":"prəˈtekʃn","defs":[["n.","保护",false]],"tier":"l","hint":"protect（保护）+ -ion → 保护","ex":"Wear a helmet for protection.（戴头盔保护自己。）"},{"id":1102,"day":18,"w":"pull","ph":"pʊl","defs":[["vt.","/n.拉，拖，牵",false]],"tier":"l","hint":"拉。联想 push 推（反义）","ex":"Please pull the door open.（请把门拉开。）"},{"id":1103,"day":18,"w":"put","ph":"pʊt","defs":[["vi.","放，置；记下，写下；表达；使……进入(状态）",false]],"tier":"l","hint":"放。过去式 put。词组 put on 穿上、put off 推迟","ex":"Put the book on the desk.（把书放在桌上。）"},{"id":1104,"day":18,"w":"rat","ph":"ræt","defs":[["n.","鼠",false]],"tier":"l","hint":"老鼠（大）。联想 mouse 老鼠（小）、rat 大老鼠","ex":"There is a rat in the house.（房子里有只老鼠。）"},{"id":1105,"day":18,"w":"reporter","ph":"rɪˈpɔːrtər","defs":[["n.","记者，报道者，通讯员",false]],"tier":"l","hint":"report（报道）+ -er（人）→ 记者","ex":"The reporter asked many questions.（记者问了很多问题。）"},{"id":1106,"day":18,"w":"responsible","ph":"rɪˈspɑːnsəbl","defs":[["a.","(for)有责任的；可靠的；责任重大的，重要的",false]],"tier":"l","hint":"负责的。词组 be responsible for 对…负责","ex":"You are responsible for your actions.（你要为自己的行为负责。）"},{"id":1107,"day":18,"w":"reward","ph":"rɪˈwɔːrd","defs":[["n.","报酬，奖金    vt.酬谢，报答",false]],"tier":"l","hint":"奖励、报酬。词组 as a reward 作为奖励","ex":"He got a reward for his hard work.（他因努力工作得到奖励。）"},{"id":1108,"day":18,"w":"seed","ph":"siːd","defs":[["n.","种子",false]],"tier":"l","hint":"种子。联想 seed 种子、plant 植物","ex":"We planted the seeds in spring.（我们春天种下种子。）"},{"id":1109,"day":18,"w":"shade","ph":"ʃeɪd","defs":[["n.","荫，阴影；遮光物，罩",false]],"tier":"l","hint":"阴凉、阴影。词组 in the shade 在阴凉处","ex":"Let's sit in the shade of the tree.（我们坐在树荫下吧。）"},{"id":1110,"day":18,"w":"shall","ph":"ʃəl","defs":[["aux.","v.将，将要；必须，应该",false]],"tier":"l","hint":"将要、应该（用于第一人称）。","ex":"Shall we go now?（我们现在走好吗？）"},{"id":1111,"day":18,"w":"shock","ph":"ʃɑːk","defs":[["n.","冲击，震动；震惊；休克；电击，触电 vi./vt.（使）震动，（使）震惊",false]],"tier":"l","hint":"震惊、震动。词组 be shocked at 对…震惊","ex":"I was shocked at the news.（我对这消息感到震惊。）"},{"id":1112,"day":18,"w":"simple","ph":"ˈsɪmpl","defs":[["a.","简单的；单纯的，直率的；迟钝的，头脑简单的",false]],"tier":"l","hint":"简单的。联想 difficult 困难的（反义）、simply 简单地","ex":"The question is very simple.（这个问题很简单。）"},{"id":1113,"day":18,"w":"spacecraft","ph":"ˈspeɪskræft","defs":[["n.","宇宙飞船",false]],"tier":"l","hint":"space（太空）+ craft（飞行器）→ 宇宙飞船","ex":"The spacecraft landed on the moon.（宇宙飞船在月球着陆。）"},{"id":1114,"day":18,"w":"steep","ph":"stiːp","defs":[["a.","陡峭的，险峻的",false]],"tier":"l","hint":"陡峭的。联想 steep 陡峭、flat 平的（反义）","ex":"The hill is too steep to climb.（这座山太陡了，爬不上去。）"},{"id":1115,"day":18,"w":"study","ph":"ˈstʌdi","defs":[["vt.","学习，读书；研究，探讨；细看 vi.读书，用功，求学 n.学习，研究；书房",false]],"tier":"l","hint":"学习、研究。词组 study hard 努力学习","ex":"He studies English at school.（他在学校学英语。）"},{"id":1116,"day":18,"w":"subject","ph":"ˈsʌbdʒekt","defs":[["n.","主题，题目；学科，科目；实验对象 a.(to)易遭……的，受……支配的",false]],"tier":"l","hint":"科目、主题。词组 school subject 学校科目","ex":"English is my favorite subject.（英语是我最喜欢的科目。）"},{"id":1117,"day":18,"w":"support","ph":"səˈpɔːrt","defs":[["vt.","支持    n.支持；支撑物；支援",false]],"tier":"l","hint":"支持。词组 support sb 支持某人、in support of 支持","ex":"Thank you for your support.（谢谢你的支持。）"},{"id":1118,"day":18,"w":"thread","ph":"θred","defs":[["n.","线；思路；线索",false]],"tier":"l","hint":"线。联想 needle 针、thread 线（针线）","ex":"She used a thread to sew the button.（她用线缝扣子。）"},{"id":1119,"day":18,"w":"tie","ph":"taɪ","defs":[["n.","领带；纽带，联系    vt.系，捆；打领结",false]],"tier":"l","hint":"领带、系。词组 tie...to 把…系在","ex":"He wore a tie to the meeting.（他系着领带开会。）"},{"id":1120,"day":18,"w":"today","ph":"təˈdeɪ","defs":[["ad.","/n.今天；现在，目前",false]],"tier":"l","hint":"今天。联想 yesterday 昨天、tomorrow 明天","ex":"It is sunny today.（今天阳光明媚。）"},{"id":1121,"day":18,"w":"training","ph":"ˈtreɪnɪŋ","defs":[["n.","训练，培训，培养",false]],"tier":"l","hint":"train（训练）+ -ing → 训练。词组 training course 培训课程","ex":"He is receiving training for the job.（他在接受工作培训。）"},{"id":1122,"day":18,"w":"travel","ph":"ˈtrævl","defs":[["vi.","/n.旅行；传播",false]],"tier":"l","hint":"旅行。联想 traveler 旅行者、travel 旅行","ex":"They travel to many countries every year.（他们每年去很多国家旅行。）"},{"id":1123,"day":18,"w":"trousers","ph":"ˈtraʊzərz","defs":[["n.","裤子",false]],"tier":"l","hint":"裤子（复数）。词组 a pair of trousers 一条裤子","ex":"He bought a new pair of trousers.（他买了条新裤子。）"},{"id":1124,"day":18,"w":"wave","ph":"weɪv","defs":[["n.","波，波浪；飘扬，起伏 vi.挥舞，摇动",false]],"tier":"l","hint":"波浪、挥手。词组 wave to 向…挥手","ex":"She waved to me from across the street.（她在街对面向我挥手。）"},{"id":1125,"day":18,"w":"worst","ph":"wɜːrst","defs":[["a.","/ad.最坏（的），最差（的）",false]],"tier":"l","hint":"bad 的最高级 → 最糟。词组 at worst 在最坏的情况下","ex":"This is the worst movie I've seen.（这是我看过最糟的电影。）"},{"id":1126,"day":18,"w":"wrist","ph":"rɪst","defs":[["n.","腕，腕关节",false]],"tier":"l","hint":"手腕。联想 wrist 手腕、watch 手表（戴在手腕）","ex":"He wears a watch on his wrist.（他手腕上戴着手表。）"},{"id":1127,"day":19,"w":"afford","ph":"əˈfɔːrd","defs":[["vt.","提供，给予；供应得起",false]],"tier":"l","hint":"负担得起。词组 afford to do 负担得起做、can't afford 负担不起","ex":"I can't afford to buy a new car.（我买不起新车。）"},{"id":1128,"day":19,"w":"again","ph":"əˈɡen","defs":[["ad.","再，再次；又，重新",false]],"tier":"l","hint":"再、又。词组 again and again 反复、once again 再一次","ex":"Please say it again.（请再说一遍。）"},{"id":1129,"day":19,"w":"attempt","ph":"əˈtempt","defs":[["vt.","/n.试图，努力",false]],"tier":"l","hint":"尝试、企图。词组 attempt to do 试图做","ex":"He attempted to climb the mountain.（他试图爬山。）"},{"id":1130,"day":19,"w":"avoid","ph":"əˈvɔɪd","defs":[["vt.","避免，逃避",false]],"tier":"l","hint":"避免。词组 avoid doing 避免做","ex":"You should avoid making the same mistake.（你应该避免犯同样的错误。）"},{"id":1131,"day":19,"w":"belief","ph":"bɪˈliːf","defs":[["n.","相信；信仰，信条，信念",false]],"tier":"l","hint":"believe（相信）的名词 → 信念。词组 beyond belief 难以置信","ex":"He has a strong belief in himself.（他对自己有坚定的信念。）"},{"id":1132,"day":19,"w":"beneath","ph":"bɪˈniːθ","defs":[["prep.","在……下方，在……之下 ad.在下方 vi.赌，打赌 n.打赌；赌注，赌金",false]],"tier":"l","hint":"在…下方。联想 under 在下面（同义）","ex":"The cat is sleeping beneath the table.（猫在桌子下面睡觉。）"},{"id":1133,"day":19,"w":"best","ph":"best","defs":[["a.","最好的 ad.最，最好",false]],"tier":"l","hint":"good 的最高级 → 最好。词组 do one's best 尽力、best wishes 最美好的祝愿","ex":"I will do my best to help you.（我会尽力帮你。）"},{"id":1134,"day":19,"w":"boat","ph":"boʊt","defs":[["n.","船，小船",false]],"tier":"l","hint":"船。词组 by boat 乘船","ex":"They crossed the river by boat.（他们乘船过河。）"},{"id":1135,"day":19,"w":"boring","ph":"ˈbɔːrɪŋ","defs":[["a.","令人厌烦的 n.钻孔",false]],"tier":"l","hint":"bore（使厌烦）+ -ing → 令人厌烦的","ex":"The movie was very boring.（这部电影很无聊。）"},{"id":1136,"day":19,"w":"bottle","ph":"ˈbɑːtl","defs":[["n.","瓶子",false]],"tier":"l","hint":"瓶子。词组 a bottle of 一瓶","ex":"Please buy a bottle of milk.（请买一瓶牛奶。）"},{"id":1137,"day":19,"w":"bring","ph":"brɪŋ","defs":[["vt.","拿来，带来；产生，引起；使处于某种状态",false]],"tier":"l","hint":"带来。过去式 brought。词组 bring up 抚养、bring about 引起","ex":"Please bring your book tomorrow.（请明天带书来。）"},{"id":1138,"day":19,"w":"bullet","ph":"ˈbʊlɪt","defs":[["n.","子弹，枪弹",true]],"tier":"f","ety":"法语 boulette（小球）→ 子弹","mem":"bull（公牛）+ et → 像公牛冲撞一样有力 → 子弹。画面：子弹呼啸而出","ex":"a bullet · The bullet hit the target.（子弹击中目标。）","nua":"bullet（子弹）、bulletin（公告，多一个 in）；bullet train 高铁"},{"id":1139,"day":19,"w":"center/-re","ph":"ˈsentər","defs":[["n.","中心，中央 vi./vt.（使）放在中央",false]],"tier":"l","hint":"中心。词组 in the center of 在…中心","ex":"The park is in the center of the city.（公园在市中心。）"},{"id":1140,"day":19,"w":"change","ph":"tʃeɪndʒ","defs":[["vi.","/vt.改变，变化 vt.换，兑换 n.改变，变化，找零",false]],"tier":"l","hint":"改变、零钱。词组 change...into 变成","ex":"The city has changed a lot.（这座城市变化很大。）"},{"id":1141,"day":19,"w":"cinema","ph":"ˈsɪnəmə","defs":[["n.","电影院",false]],"tier":"l","hint":"电影院。词组 go to the cinema 去看电影","ex":"We went to the cinema last night.（我们昨晚去看了电影。）"},{"id":1142,"day":19,"w":"clash","ph":"klæʃ","defs":[["n.","/v. 碰撞；冲突",true]],"tier":"f","ety":"拟声词，模仿碰撞声","mem":"拟声：clash 像\"咔啦\"碰撞声。画面：两车相撞、意见冲突","ex":"clash with · His view clashes with mine.（他的观点与我的冲突。）","nua":"clash（意见冲突、金属碰撞声）、crash（撞毁）、crush（压碎）；三词易混"},{"id":1143,"day":19,"w":"connection","ph":"kəˈnekʃn","defs":[["n.","连接，联系，关系",false]],"tier":"l","hint":"connect（连接）+ -ion → 联系。词组 in connection with 与…有关","ex":"There is a close connection between them.（他们之间有密切联系。）"},{"id":1144,"day":19,"w":"contract","ph":"ˈkɑːntrækt","defs":[["n.","契约，合同，包工 vi./vt.收缩；感染；定约",false]],"tier":"l","hint":"合同。词组 sign a contract 签合同","ex":"They signed a contract with the company.（他们和公司签了合同。）"},{"id":1145,"day":19,"w":"counter","ph":"ˈkaʊntər","defs":[["n.","柜台；计数器 vi.计数；指望 a./ad.相反的（地），反对的（地） vt.反对，对抗",false]],"tier":"l","hint":"柜台、计数器。联想 counter 柜台、counter 计算","ex":"She works behind the counter.（她在柜台后工作。）"},{"id":1146,"day":19,"w":"decision","ph":"dɪˈsɪʒn","defs":[["n.","决心，决定；果断",false]],"tier":"l","hint":"decide（决定）的名词 → 决定。词组 make a decision 做决定","ex":"He made an important decision.（他做了个重要决定。）"},{"id":1147,"day":19,"w":"disappointing","ph":"ˌdɪsəˈpɔɪntɪŋ","defs":[["a.","令人失望的，令人扫兴的",false]],"tier":"l","hint":"disappoint（使失望）+ -ing → 令人失望的","ex":"The result was disappointing.（结果令人失望。）"},{"id":1148,"day":19,"w":"dream","ph":"driːm","defs":[["n.","梦，梦想，幻想 vi./vt.做梦，幻想",false]],"tier":"l","hint":"梦、梦想。过去式 dreamt/dreamed。词组 dream of 梦想","ex":"She dreams of becoming a doctor.（她梦想成为医生。）"},{"id":1149,"day":19,"w":"enemy","ph":"ˈenəmi","defs":[["n.","敌人，仇敌",false]],"tier":"l","hint":"敌人。联想 friend 朋友（反义）","ex":"They fought against the enemy bravely.（他们勇敢地与敌人战斗。）"},{"id":1150,"day":19,"w":"escape","ph":"ɪˈskeɪp","defs":[["vi.","逃跑；逃避，避免；逸出",false]],"tier":"l","hint":"逃跑。词组 escape from 从…逃跑","ex":"The bird escaped from the cage.（鸟从笼子里逃走了。）"},{"id":1151,"day":19,"w":"fever","ph":"ˈfiːvər","defs":[["n.","发烧，发热，热病；狂热，兴奋",false]],"tier":"l","hint":"发烧。词组 have a fever 发烧","ex":"He has a high fever.（他发高烧。）"},{"id":1152,"day":19,"w":"flat","ph":"flæt","defs":[["a.","平坦的，扁平的；平淡的，乏味的；单调的 n.一套房间，公寓套房",false]],"tier":"l","hint":"平的、公寓。联想 flat 平的、apartment 公寓","ex":"The land here is very flat.（这里的土地很平坦。）"},{"id":1153,"day":19,"w":"frequent","ph":"ˈfriːkwənt","defs":[["a.","频繁的",false]],"tier":"l","hint":"频繁的。联想 frequently 频繁地（副词）","ex":"He is a frequent visitor to our house.（他是我们家的常客。）"},{"id":1154,"day":19,"w":"hat","ph":"hæt","defs":[["n.","帽子",false]],"tier":"l","hint":"帽子（有边）。联想 cap 便帽、hat 礼帽","ex":"She wore a beautiful hat.（她戴了顶漂亮的帽子。）"},{"id":1155,"day":19,"w":"hope","ph":"hoʊp","defs":[["vi.","/vt./n.希望，期望",false]],"tier":"l","hint":"希望。词组 hope to do 希望做、in the hope of 希望","ex":"I hope to see you soon.（我希望很快见到你。）"},{"id":1156,"day":19,"w":"hour","ph":"ˈaʊər","defs":[["n.","小时；钟点，时刻；课时，工作时间",false]],"tier":"l","hint":"小时。词组 half an hour 半小时","ex":"The meeting lasted two hours.（会议持续了两小时。）"},{"id":1157,"day":19,"w":"infection","ph":"ɪnˈfekʃn","defs":[["n.","传染，感染",false]],"tier":"l","hint":"infect（感染）+ -ion → 感染","ex":"He got an infection in his leg.（他的腿感染了。）"},{"id":1158,"day":19,"w":"infectious","ph":"ɪnˈfekʃəs","defs":[["a.","传染的；有感染力的",false]],"tier":"l","hint":"infect（感染）+ -ious → 传染性的","ex":"The flu is highly infectious.（流感传染性很强。）"},{"id":1159,"day":19,"w":"inside","ph":"ˌɪnˈsaɪd","defs":[["prep.","在……里，在……内 a.内部的，里面的，内幕的 ad.在内部，在里面 n.内部，里面，内侧",false]],"tier":"l","hint":"in（内）+ side（边）→ 在里面。联想 outside 在外面（反义）","ex":"It's warm inside the house.（房子里很暖和。）"},{"id":1160,"day":19,"w":"insurance","ph":"ɪnˈʃʊrəns","defs":[["n.","保险，保险费",false]],"tier":"l","hint":"insure（保险）+ -ance → 保险。词组 insurance company 保险公司","ex":"He bought health insurance.（他买了健康保险。）"},{"id":1161,"day":19,"w":"iron","ph":"ˈaɪərn","defs":[["n.","铁；烙铁，熨斗 vt.熨平，烫（衣）",false]],"tier":"l","hint":"铁、熨斗、熨。联想 iron 铁、ironing 熨烫","ex":"The gate is made of iron.（大门是铁做的。）"},{"id":1162,"day":19,"w":"life","ph":"laɪf","defs":[["n.","生命；寿命，一生；生活，生计；生物",false]],"tier":"l","hint":"生命、生活。词组 all one's life 一生、daily life 日常生活","ex":"She has a happy life.（她生活幸福。）"},{"id":1163,"day":19,"w":"mention","ph":"ˈmenʃn","defs":[["vt.","/n.提及，说起，讲述",false]],"tier":"l","hint":"提及。词组 not to mention 更不用说","ex":"He mentioned your name in the letter.（他在信里提到了你的名字。）"},{"id":1164,"day":19,"w":"minute","ph":"ˈmɪnɪt","defs":[["n.","分，分钟；一会儿，片刻",false]],"tier":"l","hint":"分钟。词组 in a minute 马上、just a minute 等一下","ex":"Wait a minute, please.（请等一下。）"},{"id":1165,"day":19,"w":"mood","ph":"muːd","defs":[["n.","心境，情绪；语气",false]],"tier":"l","hint":"情绪。词组 in a good mood 心情好","ex":"She is in a good mood today.（她今天心情好。）"},{"id":1166,"day":19,"w":"old","ph":"oʊld","defs":[["a.","年老的；陈旧的，古老的；……岁的",false]],"tier":"l","hint":"老的、旧的。联想 young 年轻的（反义）","ex":"This is an old house.（这是栋老房子。）"},{"id":1167,"day":19,"w":"organize/-se","ph":"ˈɔːrɡənaɪz","defs":[["vt.","组织，编组",false]],"tier":"l","hint":"组织。联想 organization 组织（名词）","ex":"They organized a party for the children.（他们为孩子们组织了聚会。）"},{"id":1168,"day":19,"w":"peaceful","ph":"ˈpiːsfl","defs":[["a.","平静的；爱好和平的",false]],"tier":"l","hint":"peace（和平）+ -ful → 和平的、宁静的","ex":"The village is very peaceful.（这个村庄很宁静。）"},{"id":1169,"day":19,"w":"percent","ph":"pərˈsent","defs":[["n.","百分之一",false]],"tier":"l","hint":"百分之。词组 50 percent 百分之五十","ex":"Ninety percent of the students passed the exam.（百分之九十的学生通过了考试。）"},{"id":1170,"day":19,"w":"power","ph":"ˈpaʊər","defs":[["n.","力，能力，精力；权力，势力，政权；功率，动 力，电力；乘方",false]],"tier":"l","hint":"力量、权力。词组 come to power 上台执政","ex":"Knowledge is power.（知识就是力量。）"},{"id":1171,"day":19,"w":"prepare","ph":"prɪˈper","defs":[["vt.","准备，预备；制作，制备",false]],"tier":"l","hint":"准备。词组 prepare for 为…准备","ex":"We are preparing for the exam.（我们在为考试做准备。）"},{"id":1172,"day":19,"w":"pretend","ph":"prɪˈtend","defs":[["vt.","假装，假托",false]],"tier":"l","hint":"假装。词组 pretend to do 假装做","ex":"He pretended to be asleep.（他假装睡着了。）"},{"id":1173,"day":19,"w":"pure","ph":"pjʊr","defs":[["a.","纯的，纯洁的；抽象的，纯理论的",false]],"tier":"l","hint":"纯净的、纯洁的。联想 pure 纯的、purity 纯净","ex":"The water here is pure.（这里的水很纯净。）"},{"id":1174,"day":19,"w":"real","ph":"ˈriːəl","defs":[["a.","真的，真实的；实际的，现实的",false]],"tier":"l","hint":"真实的。联想 fake 假的（反义）、really 真正地","ex":"Is this a real diamond?（这是真钻石吗？）"},{"id":1175,"day":19,"w":"reduction","ph":"rɪˈdʌkʃn","defs":[["n.","减少，缩小",false]],"tier":"l","hint":"reduce（减少）+ -tion → 减少","ex":"There is a reduction in the price.（价格有下降。）"},{"id":1176,"day":19,"w":"relative","ph":"ˈrelətɪv","defs":[["a.","相对的，比较的 n.亲属，亲戚",false]],"tier":"l","hint":"相对的、亲戚。联想 relation 关系（同源）","ex":"He invited all his relatives to the wedding.（他邀请所有亲戚参加婚礼。）"},{"id":1177,"day":19,"w":"shape","ph":"ʃeɪp","defs":[["n.","形状，外形；状况，状态 vt.形成，成形",false]],"tier":"l","hint":"形状。词组 in the shape of 呈…形状、in good shape 状态好","ex":"The cloud has a strange shape.（这朵云形状奇特。）"},{"id":1178,"day":19,"w":"shut","ph":"ʃʌt","defs":[["vt.","关，关闭；停止营业；禁闭 vi.关上",false]],"tier":"l","hint":"关闭。过去式 shut。词组 shut up 闭嘴、shut down 关闭","ex":"Please shut the door.（请关门。）"},{"id":1179,"day":19,"w":"silver","ph":"ˈsɪlvər","defs":[["n.","银，银器，银币",false]],"tier":"l","hint":"银。联想 gold 金、silver 银","ex":"She wears a silver necklace.（她戴着银项链。）"},{"id":1180,"day":19,"w":"substance","ph":"ˈsʌbstəns","defs":[["n.","物质；实质，本质；要旨，大意",false]],"tier":"l","hint":"物质、实质。联想 substance 物质、chemical substance 化学物质","ex":"Water is a common substance.（水是常见的物质。）"},{"id":1181,"day":19,"w":"tell","ph":"tel","defs":[["vt.","告诉，讲述；告诫，劝告；吩咐，命令；辨别，",false]],"tier":"l","hint":"告诉。过去式 told。词组 tell a story 讲故事","ex":"Please tell me the truth.（请告诉我真相。）"},{"id":1182,"day":19,"w":"tend","ph":"tend","defs":[["vt.","照料，护理 vi.趋于，倾向",false]],"tier":"l","hint":"倾向于、照料。词组 tend to do 倾向于做","ex":"People tend to sleep more in winter.（人们冬天倾向于多睡。）"},{"id":1183,"day":19,"w":"transport","ph":"ˈtrænspɔːrt","defs":[["vt.","/n.运输，运送",false]],"tier":"l","hint":"trans-（转移）+ port（港口）→ 运输","ex":"The goods are transported by train.（货物用火车运输。）"},{"id":1184,"day":19,"w":"trick","ph":"trɪk","defs":[["n.","诡计，花招；恶作剧；窍门 vt.欺诈，哄骗",false]],"tier":"l","hint":"诡计、欺骗。词组 play a trick on 捉弄","ex":"The children played a trick on their teacher.（孩子们捉弄了老师。）"},{"id":1185,"day":19,"w":"trust","ph":"trʌst","defs":[["vt.","相信，信赖；委托，托付；依靠，依赖 n.信任，信赖；可信任的人/物",false]],"tier":"l","hint":"信任。词组 trust in 信任、trust sb 信任某人","ex":"I trust him completely.（我完全信任他。）"},{"id":1186,"day":19,"w":"vegetable","ph":"ˈvedʒtəbl","defs":[["n.","植物，蔬菜",false]],"tier":"l","hint":"蔬菜。联想 fruit 水果、vegetable 蔬菜","ex":"Eat more vegetables and fruit.（多吃蔬菜和水果。）"},{"id":1187,"day":19,"w":"weak","ph":"wiːk","defs":[["a.","虚弱的，软弱的；薄弱的，差的",false]],"tier":"l","hint":"虚弱的。联想 strong 强壮的（反义）、weakness 弱点","ex":"He is weak after the illness.（病后他很虚弱。）"},{"id":1188,"day":19,"w":"west","ph":"west","defs":[["n.","/a.西（的），西部（的），西方（的） ad.向/自/在西方",false]],"tier":"l","hint":"西方。联想 east 东、west 西、south 南、north 北","ex":"The sun sets in the west.（太阳从西方落下。）"},{"id":1189,"day":19,"w":"whether","ph":"ˈweðər","defs":[["conj.","是否，会不会；不管，无论",false]],"tier":"l","hint":"是否。词组 whether...or 是…还是","ex":"I don't know whether he will come.（我不知道他是否会来。）"},{"id":1190,"day":20,"w":"active","ph":"ˈæktɪv","defs":[["a.","活动的，活跃的；积极的，主动的",false]],"tier":"l","hint":"act（行动）+ -ive → 活跃的。词组 be active in 积极从事","ex":"He is active in class activities.（他积极参加课堂活动。）"},{"id":1191,"day":20,"w":"approve","ph":"əˈpruːv","defs":[["v.","赞成；批准",true]],"tier":"f","ety":"ap-（向）+ prove（证明）→ 证明是对的 → 赞成","mem":"ap + prove（证明）→ 被\"证明\"靠谱 → 赞成、批准。画面：审查通过盖章","ex":"approve of · I don't approve of his plan.（我不赞成他的计划。）","nua":"approve of（赞成）、approve（批准，正式）；名词 approval"},{"id":1192,"day":20,"w":"around","ph":"əˈraʊnd","defs":[["ad.","周围，在附近；到处；大约 prep.在……周围，围着；在各地",false]],"tier":"l","hint":"周围、大约。词组 look around 环顾、around the world 全世界","ex":"The earth goes around the sun.（地球绕太阳转。）"},{"id":1193,"day":20,"w":"attack","ph":"əˈtæk","defs":[["vt.","/n.攻击，进攻，抨击；(病)发作",false]],"tier":"l","hint":"攻击。词组 attack 攻击、under attack 遭到攻击","ex":"The enemy attacked the city at night.（敌人夜里袭击了城市。）"},{"id":1194,"day":20,"w":"beer","ph":"bɪr","defs":[["n.","啤酒",false]],"tier":"l","hint":"啤酒。联想 wine 葡萄酒、beer 啤酒","ex":"He drank a glass of beer.（他喝了杯啤酒。）"},{"id":1195,"day":20,"w":"both","ph":"boʊθ","defs":[["pron.","二者，双方 a.两，双",false]],"tier":"l","hint":"两者都。词组 both...and 两者都","ex":"Both of them are my friends.（他们俩都是我的朋友。）"},{"id":1196,"day":20,"w":"chase","ph":"tʃeɪs","defs":[["vi.","/n.追赶，追逐",false]],"tier":"l","hint":"追逐。词组 chase after 追赶","ex":"The dog chased the cat.（狗追猫。）"},{"id":1197,"day":20,"w":"chocolate","ph":"ˈtʃɑːklət","defs":[["n.","巧克力",false]],"tier":"l","hint":"巧克力。音译词。词组 a bar of chocolate 一块巧克力","ex":"She loves eating chocolate.（她爱吃巧克力。）"},{"id":1198,"day":20,"w":"continue","ph":"kənˈtɪnjuː","defs":[["vi.","/vt.连续，继续",false]],"tier":"l","hint":"继续。词组 continue to do 继续做","ex":"Please continue your work.（请继续你的工作。）"},{"id":1199,"day":20,"w":"continuous","ph":"kənˈtɪnjuəs","defs":[["a.","连续的，继续的，持续的",false]],"tier":"l","hint":"continue（继续）+ -ous → 连续的","ex":"The noise was continuous all night.（噪音整夜不断。）"},{"id":1200,"day":20,"w":"crash","ph":"kræʃ","defs":[["vi.","/n.摔坏，坠毁",false]],"tier":"l","hint":"撞毁、坠毁。联想 crash 撞车、clash 冲突","ex":"The car crashed into a tree.（汽车撞上了树。）"},{"id":1201,"day":20,"w":"definitely","ph":"ˈdefɪnətli","defs":[["ad.","明确地，一定地",true]],"tier":"f","ety":"definite（明确的）+ -ly → 明确地","mem":"definite + ly → 明确（definite）的副词。画面：斩钉截铁","ex":"definitely · It will definitely rain tomorrow.（明天一定会下雨。）","nua":"definitely（一定、明确）、certainly（当然）；拼写：definite 是 finite（有限）加 de"},{"id":1202,"day":20,"w":"deliberately","ph":"dɪˈlɪbərətli","defs":[["ad.","故意地，蓄意地；审慎地；从容地",false]],"tier":"l","hint":"deliberate（故意的）+ -ly → 故意地","ex":"He deliberately broke the window.（他故意打破了窗户。）"},{"id":1203,"day":20,"w":"desirable","ph":"dɪˈzaɪərəbl","defs":[["a.","合乎需要的，令人满意的",true]],"tier":"f","ety":"desire（渴望）+ -able → 值得渴望的 → 合意的","mem":"desire + able → 让人\"渴望\"（desire）的 → 合意的。画面：梦寐以求","ex":"a desirable result · Getting a high score is a desirable result.（得高分是理想的结果。）","nua":"desirable（合意的，修饰物）、desirous（渴望的，修饰人）；desire（渴望）"},{"id":1204,"day":20,"w":"determination","ph":"dɪˌtɜːrmɪˈneɪʃn","defs":[["n.","决心，决定",true]],"tier":"f","ety":"determine（决定）+ -ation → 决心","mem":"determine + ation → 决定（determine）的名词。画面：握拳下定决心","ex":"with determination · She worked with great determination.（她以极大的决心工作。）","nua":"determination（决心，不可数）、decision（决定，具体）；determine to do（决心做）"},{"id":1205,"day":20,"w":"dirt","ph":"dɜːrt","defs":[["n.","污垢，泥土",false]],"tier":"l","hint":"污垢。联想 dirty 脏的（形容词）","ex":"There is dirt on the floor.（地板上有污垢。）"},{"id":1206,"day":20,"w":"effect","ph":"ɪˈfekt\\|","defs":[["n.","效果，作用，影响",false]],"tier":"l","hint":"影响、效果。词组 have an effect on 对…有影响（对比 affect 动词）","ex":"The medicine had a good effect.（这药效果很好。）"},{"id":1207,"day":20,"w":"effort","ph":"ˈefərt","defs":[["n.","努力，尽力",false]],"tier":"l","hint":"努力。词组 make an effort 努力、spare no effort 不遗余力","ex":"He made great efforts to pass the exam.（他为通过考试付出巨大努力。）"},{"id":1208,"day":20,"w":"encourage","ph":"ɪnˈkɜːrɪdʒ","defs":[["vt.","鼓励，助长，促进",false]],"tier":"l","hint":"鼓励。词组 encourage sb to do 鼓励某人做","ex":"The teacher encouraged us to study hard.（老师鼓励我们努力学习。）"},{"id":1209,"day":20,"w":"exciting","ph":"ɪkˈsaɪtɪŋ","defs":[["a.","令人兴奋的",false]],"tier":"l","hint":"excite（使兴奋）+ -ing → 令人兴奋的","ex":"The football match was very exciting.（足球赛很激动人心。）"},{"id":1210,"day":20,"w":"extra","ph":"ˈekstrə","defs":[["a.","额外的，附加的 n.附加物，额外的东西 ad.特别地",false]],"tier":"l","hint":"额外的。词组 extra time 额外时间","ex":"He did extra work to earn money.（他做额外工作赚钱。）"},{"id":1211,"day":20,"w":"female","ph":"ˈfiːmeɪl","defs":[["n.","女子；雌性动物 a.女性的；雌性的",false]],"tier":"l","hint":"女性的。联想 male 男性的（反义）","ex":"The school has both male and female students.（学校有男女学生。）"},{"id":1212,"day":20,"w":"field","ph":"fiːld","defs":[["n.","原野，田野；活动范围；领域，界；(电/磁)场",false]],"tier":"l","hint":"田地、领域。词组 in the field of 在…领域","ex":"The farmers work in the field.（农民在田里干活。）"},{"id":1213,"day":20,"w":"final","ph":"ˈfaɪnl","defs":[["a.","最后的，最终的；决定性的",false]],"tier":"l","hint":"最终的。联想 final exam 期末考试、finally 最终","ex":"This is the final decision.（这是最终决定。）"},{"id":1214,"day":20,"w":"finger","ph":"ˈfɪŋɡər","defs":[["n.","手指，指头",false]],"tier":"l","hint":"手指。联想 hand 手、finger 手指、thumb 拇指","ex":"He has a ring on his finger.（他手指上戴着戒指。）"},{"id":1215,"day":20,"w":"graceful","ph":"ˈɡreɪsfl","defs":[["a.","优美的，文雅的",true]],"tier":"f","ety":"grace（优雅）+ -ful → 优美的","mem":"grace + ful → 充满\"优雅\"（grace）→ 优美的。画面：芭蕾舞者","ex":"a graceful dancer · She is a graceful dancer.（她是位优雅的舞者。）","nua":"graceful（优美的）、gracious（和蔼的）；grace（优雅、恩惠）"},{"id":1216,"day":20,"w":"ground","ph":"ɡraʊnd","defs":[["n.","地面，土地；场所，场地；根据，理由",false]],"tier":"l","hint":"地面。词组 on the ground 在地面上","ex":"The ball fell on the ground.（球掉在地上。）"},{"id":1217,"day":20,"w":"impressive","ph":"ɪmˈpresɪv","defs":[["a.","给人印象深刻的",true]],"tier":"f","ety":"impress（留下印象）+ -ive → 印象深刻的","mem":"impress + ive → 让人\"印象深刻\"（impress）的 → 感人的。画面：叹为观止","ex":"an impressive performance · It was an impressive performance.（那是场令人印象深刻的演出。）","nua":"impressive（令人印象深刻的）、impressed（感到印象深刻的）；impress sb with"},{"id":1218,"day":20,"w":"instead","ph":"ɪnˈsted","defs":[["ad.","代替，顶替；反而，却",false]],"tier":"l","hint":"代替。词组 instead of 代替、而不是","ex":"Let's walk instead of taking a bus.（我们走路，而不是坐公交。）"},{"id":1219,"day":20,"w":"lift","ph":"lɪft","defs":[["vi.","/vt.提起，举起；消散，（云雾）升起 n.举起；升起；电梯，升降机；搭便车",false]],"tier":"l","hint":"举起、电梯。词组 lift up 举起、take the lift 乘电梯","ex":"He lifted the heavy box.（他举起了重箱子。）"},{"id":1220,"day":20,"w":"low","ph":"loʊ","defs":[["a.","低的，矮的；低级的，下层的；低声的",false]],"tier":"l","hint":"低的。联想 high 高的（反义）","ex":"The price is very low.（价格很低。）"},{"id":1221,"day":20,"w":"message","ph":"ˈmesɪdʒ","defs":[["n.","消息，音信；口信，便条；启示，要旨",false]],"tier":"l","hint":"信息、留言。词组 leave a message 留言、send a message 发信息","ex":"Please leave a message for me.（请给我留言。）"},{"id":1222,"day":20,"w":"mind","ph":"maɪnd","defs":[["n.","头脑，精神；理智；想法，意见；心情 vi./vt.留心，当心，注意，介意，在乎",false]],"tier":"l","hint":"介意、头脑。词组 make up one's mind 下定决心、never mind 没关系","ex":"Do you mind if I open the window?（你介意我开窗吗？）"},{"id":1223,"day":20,"w":"mine","ph":"maɪn","defs":[["pron.","[所有格]我的 n.矿，矿山，矿井 vt.采掘，开矿",false]],"tier":"l","hint":"我的（名词性物主代词）、矿。","ex":"This book is mine.（这本书是我的。）"},{"id":1224,"day":20,"w":"mirror","ph":"ˈmɪrər","defs":[["n.","镜子",false]],"tier":"l","hint":"镜子。词组 look in the mirror 照镜子","ex":"She looked at herself in the mirror.（她照镜子看自己。）"},{"id":1225,"day":20,"w":"notice","ph":"ˈnoʊtɪs","defs":[["n.","注意，认识；通知，通告，布告 vt.看到，注意到",false]],"tier":"l","hint":"注意到、通知。词组 take notice of 注意到","ex":"I noticed a change in him.（我注意到他变了。）"},{"id":1226,"day":20,"w":"operation","ph":"ˌɑːpəˈreɪʃn","defs":[["n.","操作，工作，运转；手术；运算",false]],"tier":"l","hint":"operate（操作/手术）+ -ion → 操作、手术","ex":"He had an operation on his leg.（他的腿做了手术。）"},{"id":1227,"day":20,"w":"outer","ph":"ˈaʊtər","defs":[["a.","外部的，外层的，外表的",false]],"tier":"l","hint":"out（外）+ -er → 外部的。联想 inner 内部的（反义）","ex":"The outer wall is painted white.（外墙刷成白色。）"},{"id":1228,"day":20,"w":"pick","ph":"pɪk","defs":[["vt.","拾，采，摘；挑选 n.镐",false]],"tier":"l","hint":"挑选、采摘。词组 pick up 捡起/接、pick out 挑选","ex":"She picked some flowers in the garden.（她在花园里摘了些花。）"},{"id":1229,"day":20,"w":"pity","ph":"ˈpɪti","defs":[["vt.","/n.怜悯，惋惜 n.可惜的事，憾事",false]],"tier":"l","hint":"遗憾、同情。词组 What a pity! 真遗憾！","ex":"What a pity that you can't come!（你不能来真遗憾！）"},{"id":1230,"day":20,"w":"pleasant","ph":"ˈpleznt","defs":[["a.","舒适的，令人愉快的",false]],"tier":"l","hint":"please（使高兴）+ -ant → 令人愉快的","ex":"We had a pleasant evening.（我们度过了愉快的夜晚。）"},{"id":1231,"day":20,"w":"positive","ph":"ˈpɑːzətɪv","defs":[["a.","确定的；正面的，积极的；正的，阳性的",false]],"tier":"l","hint":"积极的、肯定的。联想 negative 消极的（反义）","ex":"Keep a positive attitude.（保持积极的态度。）"},{"id":1232,"day":20,"w":"pot","ph":"pɑːt","defs":[["n.","壶，罐，盆",false]],"tier":"l","hint":"锅、壶。联想 pot 锅、cooking pot 煮锅","ex":"She cooked soup in a pot.（她在锅里煮汤。）"},{"id":1233,"day":20,"w":"production","ph":"prəˈdʌkʃn","defs":[["n.","生产，产量；产品，作品",false]],"tier":"l","hint":"produce（生产）+ -tion → 生产、产量","ex":"The factory increased its production.（工厂提高了产量。）"},{"id":1234,"day":20,"w":"regular","ph":"ˈreɡjəlr","defs":[["a.","有规律的；规矩的；定期的；正规的，正式的； 匀称的，整齐的",false]],"tier":"l","hint":"规律的、定期的。联想 regularly 定期地","ex":"He does regular exercise.（他定期锻炼。）"},{"id":1235,"day":20,"w":"sense","ph":"sens","defs":[["vt.","感觉到，意识到 n.感官，官能；辨别力，感觉；意义，意思",false]],"tier":"l","hint":"感觉、意义。词组 make sense 有意义、common sense 常识","ex":"Your words make sense.（你的话有道理。）"},{"id":1236,"day":20,"w":"several","ph":"ˈsevrəl","defs":[["a.","若干，数个",false]],"tier":"l","hint":"几个。词组 several times 几次","ex":"I have been there several times.（我去过那里几次。）"},{"id":1237,"day":20,"w":"sew","ph":"soʊ","defs":[["vt.","缝，缝纫",false]],"tier":"l","hint":"缝。过去式 sewed。联想 needle 针、sew 缝","ex":"She sewed a button on her shirt.（她在衬衫上缝了个扣子。）"},{"id":1238,"day":20,"w":"sick","ph":"sɪk","defs":[["a.","有病的，患病的；恶心的，想吐的",false]],"tier":"l","hint":"生病的。联想 ill 生病的（同义）","ex":"He is sick in bed.（他卧病在床。）"},{"id":1239,"day":20,"w":"society","ph":"səˈsaɪəti","defs":[["n.","社会；协会；社交界，上流社会",false]],"tier":"l","hint":"社会。词组 modern society 现代社会","ex":"We should contribute to society.（我们应该为社会做贡献。）"},{"id":1240,"day":20,"w":"solution","ph":"səˈluːʃn","defs":[["n.","解答，解决办法；溶解，溶液",false]],"tier":"l","hint":"solve（解决）的名词 → 解决办法。词组 a solution to …的解决办法","ex":"We found a solution to the problem.（我们找到了问题的解决办法。）"},{"id":1241,"day":20,"w":"start","ph":"stɑːrt","defs":[["vt.","开始，着手；启动；引起；开设，创办 vi.启动，开动；动身，出发 n.开端，起点；动身，出发；吃惊",false]],"tier":"l","hint":"开始。词组 start to do 开始做、at the start 开始","ex":"The meeting will start at nine.（会议九点开始。）"},{"id":1242,"day":20,"w":"thorough","ph":"ˈθɜːroʊ","defs":[["a.","彻底的，完全的；精心的",true]],"tier":"f","ety":"古英语 þurh（穿过），与 through 同源","mem":"拼写对比：through（穿过，有 r + ough）vs thorough（彻底，多个 o）。记：查得\"彻彻底底\"多一个 o","ex":"a thorough check · We made a thorough check of the house.（我们彻底检查了房子。）","nua":"thorough（彻底 /ˈθɜːroʊ/）、through（穿过 /θruː/）；发音和拼写都不同"},{"id":1243,"day":20,"w":"those","ph":"ðoʊz","defs":[["a.","那些",false]],"tier":"l","hint":"那些（that 的复数）。","ex":"Those books are mine.（那些书是我的。）"},{"id":1244,"day":20,"w":"tomorrow","ph":"təˈmɔːroʊ","defs":[["n.","明天 ad.明天，在明天",false]],"tier":"l","hint":"明天。联想 today 今天、yesterday 昨天","ex":"I will see you tomorrow.（我明天见你。）"},{"id":1245,"day":20,"w":"town","ph":"taʊn","defs":[["n.","市镇；闹区，商业区",false]],"tier":"l","hint":"城镇。词组 home town 家乡、in town 在城里","ex":"He lives in a small town.（他住在一个小镇。）"},{"id":1246,"day":20,"w":"trade","ph":"treɪd","defs":[["n.","贸易，商业；行业，职业 vt.做买卖，交换",false]],"tier":"l","hint":"贸易、交易。词组 trade with 与…贸易","ex":"China trades with many countries.（中国和很多国家有贸易往来。）"},{"id":1247,"day":20,"w":"translate","ph":"trænsˈleɪt","defs":[["vt.","翻译",false]],"tier":"l","hint":"翻译。词组 translate...into 把…翻译成","ex":"Please translate this sentence into Chinese.（请把这个句子翻译成中文。）"},{"id":1248,"day":20,"w":"vertical","ph":"ˈvɜːrtɪkl","defs":[["a.","垂直的，竖的",false]],"tier":"l","hint":"垂直的。联想 horizontal 水平的（反义）","ex":"The cliff is almost vertical.（悬崖几乎是垂直的。）"},{"id":1249,"day":20,"w":"voice","ph":"vɔɪs","defs":[["n.","嗓音，声音；发言权",false]],"tier":"l","hint":"声音。词组 in a low voice 低声","ex":"She has a sweet voice.（她的声音很甜。）"},{"id":1250,"day":20,"w":"weekly","ph":"ˈwiːkli","defs":[["a.","每周的，一周一次的 n.周刊，周报",false]],"tier":"l","hint":"week（周）+ -ly → 每周的。联想 daily 每日、monthly 每月","ex":"The magazine comes out weekly.（这本杂志每周出版。）"},{"id":1251,"day":20,"w":"willing","ph":"ˈwɪlɪŋ","defs":[["a.","自愿的，心甘情愿的",false]],"tier":"l","hint":"愿意的。词组 be willing to do 愿意做","ex":"He is willing to help others.（他乐于助人。）"},{"id":1252,"day":20,"w":"wish","ph":"wɪʃ","defs":[["vt.","祝，祝愿；希望，想要 n.希望，愿望",false]],"tier":"l","hint":"希望、祝愿。词组 wish to do 希望做、best wishes 最美好的祝愿","ex":"I wish you success.（祝你成功。）"},{"id":1253,"day":21,"w":"ahead","ph":"əˈhed","defs":[["ad.","前头，在前，向前",false]],"tier":"l","hint":"向前、提前。词组 ahead of 在…前面、go ahead 继续","ex":"Go ahead with your plan.（继续你的计划。）"},{"id":1254,"day":21,"w":"already","ph":"ɔːlˈredi","defs":[["ad.","已，已经",false]],"tier":"l","hint":"已经。联想 yet 还（用于否定/疑问）","ex":"I have already finished my homework.（我已经完成作业了。）"},{"id":1255,"day":21,"w":"animal","ph":"ˈænɪml","defs":[["n.","动物，野兽，牲畜 a.动物的，野兽的",false]],"tier":"l","hint":"动物。联想 plant 植物、animal 动物","ex":"The zoo has many animals.（动物园有很多动物。）"},{"id":1256,"day":21,"w":"ashamed","ph":"əˈʃeɪmd","defs":[["a.","惭愧的，害臊的",true]],"tier":"f","ety":"a-（加强）+ shame（羞耻）+ -ed → 感到羞耻的","mem":"a + shame（羞耻）+ d → 心里\"羞耻\" → 惭愧。画面：低头脸红","ex":"be ashamed of · He is ashamed of his mistake.（他为自己的错误感到羞愧。）","nua":"be ashamed of（为…羞愧）、shameful（可耻的，修饰事）；区分 ashamed/shameful"},{"id":1257,"day":21,"w":"bell","ph":"bel","defs":[["n.","钟，铃",false]],"tier":"l","hint":"铃、钟。词组 ring the bell 按铃","ex":"The bell rang for class.（上课铃响了。）"},{"id":1258,"day":21,"w":"business","ph":"ˈbɪznəs","defs":[["n.","生意，业务；事务，职责；行业",false]],"tier":"l","hint":"生意、事务。词组 do business 做生意、on business 出差","ex":"He is in Beijing on business.（他在北京出差。）"},{"id":1259,"day":21,"w":"case","ph":"keɪs","defs":[["n.","事实，情况；案件；病例；箱子，盒子",false]],"tier":"l","hint":"情况、箱子、案件。词组 in case 以防、in any case 无论如何","ex":"Take an umbrella in case it rains.（带把伞以防下雨。）"},{"id":1260,"day":21,"w":"catch","ph":"kætʃ","defs":[["vt.","捕，捉；赶上；感染，染上病；听清楚",false]],"tier":"l","hint":"抓住、赶上。过去式 caught。词组 catch up with 赶上、catch a cold 感冒","ex":"I caught the early bus.（我赶上了早班车。）"},{"id":1261,"day":21,"w":"clever","ph":"ˈklevər","defs":[["a.","聪明的，伶俐的",false]],"tier":"l","hint":"聪明的。联想 smart 聪明的（同义）","ex":"The boy is very clever.（这个男孩很聪明。）"},{"id":1262,"day":21,"w":"coffee","ph":"ˈkɔːfi","defs":[["n.","咖啡",false]],"tier":"l","hint":"咖啡。词组 a cup of coffee 一杯咖啡","ex":"I'd like a cup of coffee.（我想要杯咖啡。）"},{"id":1263,"day":21,"w":"courage","ph":"ˈkɜːrɪdʒ","defs":[["n.","勇气，胆量",false]],"tier":"l","hint":"勇气。联想 brave 勇敢的（形容词）","ex":"It takes courage to tell the truth.（说真话需要勇气。）"},{"id":1264,"day":21,"w":"crowd","ph":"kraʊd","defs":[["n.","人群，群众 vi./vt.挤满，拥挤",false]],"tier":"l","hint":"人群。词组 a crowd of 一群、crowded 拥挤的","ex":"A crowd of people gathered there.（一群人聚集在那里。）"},{"id":1265,"day":21,"w":"cruel","ph":"kruːəl","defs":[["a.","残酷的，残忍的",false]],"tier":"l","hint":"残忍的。联想 kind 善良的（反义）","ex":"It's cruel to hurt animals.（伤害动物是残忍的。）"},{"id":1266,"day":21,"w":"crush","ph":"krʌʃ","defs":[["n.","/vt.压碎，榨；压服，压垮",false]],"tier":"l","hint":"压碎、挤。联想 crash 撞、crush 压碎","ex":"Don't crush the flowers.（别压坏花。）"},{"id":1267,"day":21,"w":"death","ph":"deθ","defs":[["n.","死，死亡；消亡，毁灭",false]],"tier":"l","hint":"die（死）的名词 → 死亡。词组 the death of …的死","ex":"The death of the old man made us sad.（老人的去世让我们悲伤。）"},{"id":1268,"day":21,"w":"decrease","ph":"dɪˈkriːs","defs":[["v.","/n. 减少，减小",true]],"tier":"f","ety":"de-（向下）+ crease（增长，同 create）→ 向下增长 → 减少","mem":"de（向下）+ crease（=increase 增长）→ \"向下增长\"→ 减少。对比 increase（增加）","ex":"decrease by · The number decreased by 10%.（数字下降了 10%。）","nua":"decrease（减少，动词/名词）、reduce（减少，及物）；decrease by（减少了）、decrease to（减少到）"},{"id":1269,"day":21,"w":"demand","ph":"dɪˈmænd","defs":[["vt.","/n.要求，需要",false]],"tier":"l","hint":"需求、要求。词组 demand for 对…的需求","ex":"There is a great demand for workers.（对工人的需求很大。）"},{"id":1270,"day":21,"w":"describe","ph":"dɪˈskraɪb","defs":[["vt.","描述，形容",false]],"tier":"l","hint":"描述。词组 describe...as 把…描述为","ex":"Can you describe the thief?（你能描述小偷的样子吗？）"},{"id":1271,"day":21,"w":"dig","ph":"dɪɡ","defs":[["vi.","/vt.挖，掘；探究",false]],"tier":"l","hint":"挖。过去式 dug。词组 dig a hole 挖洞","ex":"They dug a hole to plant the tree.（他们挖坑种树。）"},{"id":1272,"day":21,"w":"doctor","ph":"ˈdɑːktər","defs":[["n.","医生，大夫；博士",false]],"tier":"l","hint":"医生、博士。联想 doctor 医生、nurse 护士","ex":"The doctor examined the patient.（医生给病人检查。）"},{"id":1273,"day":21,"w":"draw","ph":"drɔː","defs":[["vt.","画；拉，拖；拔出，引出；汲取，提取；推断出 n.平局，和局",false]],"tier":"l","hint":"画、拉。过去式 drew。词组 draw a picture 画画","ex":"The child is drawing a picture.（孩子在画画。）"},{"id":1274,"day":21,"w":"election","ph":"ɪˈlekʃn","defs":[["n.","选举",false]],"tier":"l","hint":"elect（选举）+ -ion → 选举","ex":"The election will be held next month.（选举下月举行。）"},{"id":1275,"day":21,"w":"employ","ph":"ɪmˈplɔɪ","defs":[["vt.","雇用，使用",false]],"tier":"l","hint":"雇用。联想 employment 就业（名词）","ex":"The company employs 500 workers.（这家公司雇用了 500 名工人。）"},{"id":1276,"day":21,"w":"enable","ph":"ɪˈneɪbl","defs":[["vt.","使能够，使可能",false]],"tier":"l","hint":"en-（使）+ able（能）→ 使能够。词组 enable sb to do 使某人能做","ex":"The Internet enables us to work from home.（互联网使我们能在家工作。）"},{"id":1277,"day":21,"w":"excite","ph":"ɪkˈsaɪt","defs":[["vt.","使兴奋；激发",true]],"tier":"f","ety":"ex-（出）+ cite（唤起，同 cit-）→ 唤起出来 → 激发","mem":"ex + cite（=cit 唤起）→ 把情绪\"唤起\"来 → 使兴奋。画面：一触即发","ex":"excite interest · The news excited great interest.（这消息激起了极大兴趣。）","nua":"excite（动词）、excited（感到兴奋）、exciting（令人兴奋）；-ed 修饰人、-ing 修饰物"},{"id":1278,"day":21,"w":"feel","ph":"fiːl","defs":[["vt.","触，摸；认为，以为 vi.感觉，感到；摸起来；摸索，寻找 n.感觉，觉得；触摸",false]],"tier":"l","hint":"感觉。过去式 felt。词组 feel like 想要、feel at home 感到自在","ex":"I feel very happy today.（我今天感到很开心。）"},{"id":1279,"day":21,"w":"figure","ph":"ˈfɪɡjər","defs":[["n.","外形，轮廓，体形；图形，图表；数字，数值；形 象，人物",false]],"tier":"l","hint":"数字、身材、认为。词组 figure out 弄明白","ex":"I can't figure out the answer.（我想不出答案。）"},{"id":1280,"day":21,"w":"finally","ph":"ˈfaɪnəli","defs":[["ad.","最后，终于",false]],"tier":"l","hint":"final（最终）+ -ly → 最终、最后","ex":"Finally, he succeeded.（最终他成功了。）"},{"id":1281,"day":21,"w":"fire","ph":"ˈfaɪər","defs":[["n.","火，炉火 vi./n.开火，射击 vt.解雇",false]],"tier":"l","hint":"火、解雇。词组 catch fire 着火、put out the fire 灭火","ex":"The house caught fire last night.（房子昨晚着火了。）"},{"id":1282,"day":21,"w":"fruit","ph":"fruːt","defs":[["n.","水果，果实；成果，结果",false]],"tier":"l","hint":"水果。联想 vegetable 蔬菜、fruit 水果","ex":"Eating fruit is good for health.（吃水果有益健康。）"},{"id":1283,"day":21,"w":"go","ph":"ɡoʊ","defs":[["vi.","去，走；运行，进行；变为，成为；被放置",false]],"tier":"l","hint":"去。过去式 went。词组 go on 继续、go to bed 上床睡觉","ex":"I go to school by bike.（我骑自行车上学。）"},{"id":1284,"day":21,"w":"hold","ph":"hoʊld","defs":[["vt.","拿住，握住，持有；掌握(权力)，担任(职务)；举行， 召开(会议)；认为；吸引；占据；支撑；包含 vi.持续，保持；有效，适用握住；控制，掌握",false]],"tier":"l","hint":"握住、举行。过去式 held。词组 hold on 等一下、hold a meeting 开会","ex":"Please hold my hand.（请握住我的手。）"},{"id":1285,"day":21,"w":"honor","ph":"ˈɑːnər","defs":[["n.","/v. 荣誉；尊敬",true]],"tier":"f","ety":"拉丁 honor（荣誉）","mem":"honor（荣誉，英式 honour 多一个 u）→ 谐音\"奥诺\"像颁奖时的庄重。画面：领奖台","ex":"in honor of · The dinner was held in honor of the guests.（晚宴为款待客人而举行。）","nua":"in honor of（为纪念/向…致敬）、honor（美）/honour（英）；honorable（光荣的）"},{"id":1286,"day":21,"w":"instrument","ph":"ˈɪnstrəmənt","defs":[["n.","工具，仪器；乐器",false]],"tier":"l","hint":"仪器、乐器。词组 musical instrument 乐器","ex":"He can play several musical instruments.（他会演奏几种乐器。）"},{"id":1287,"day":21,"w":"let","ph":"let","defs":[["vt.","让，允许；使；出租",false]],"tier":"l","hint":"让。过去式 let。词组 let sb do 让某人做、let alone 更不用说","ex":"Let me help you.（让我帮你。）"},{"id":1288,"day":21,"w":"level","ph":"ˈlevl","defs":[["n.","水平；水准，等级 vt.弄平，铺平 a.水平的",false]],"tier":"l","hint":"水平、级别。词组 sea level 海平面","ex":"Her English is at a high level.（她的英语水平很高。）"},{"id":1289,"day":21,"w":"lion","ph":"ˈlaɪən","defs":[["n.","狮子",false]],"tier":"l","hint":"狮子。联想 tiger 老虎、lion 狮子","ex":"The lion is the king of animals.（狮子是百兽之王。）"},{"id":1290,"day":21,"w":"moment","ph":"ˈmoʊmənt","defs":[["n.","片刻，瞬间，时刻",false]],"tier":"l","hint":"时刻。词组 at the moment 此刻、for a moment 一会儿","ex":"Wait a moment, please.（请等一会儿。）"},{"id":1291,"day":21,"w":"network","ph":"ˈnetwɜːrk","defs":[["n.","网络，网状系统；广播网，电视网",false]],"tier":"l","hint":"net（网）+ work → 网络。词组 social network 社交网络","ex":"The network is very fast.（网络很快。）"},{"id":1292,"day":21,"w":"nor","ph":"nɔːr","defs":[["conj.","也不，又不",false]],"tier":"l","hint":"也不。词组 neither...nor 既不…也不","ex":"He can neither read nor write.（他既不会读也不会写。）"},{"id":1293,"day":21,"w":"normal","ph":"ˈnɔːrml","defs":[["a.","正常的，标准的；正规的；精神健全的",false]],"tier":"l","hint":"正常的。联想 abnormal 异常的（反义）","ex":"The temperature is normal.（温度正常。）"},{"id":1294,"day":21,"w":"nut","ph":"nʌt","defs":[["n.","坚果；螺母，螺帽",false]],"tier":"l","hint":"坚果。联想 nut 坚果、peanut 花生","ex":"Squirrels like eating nuts.（松鼠爱吃坚果。）"},{"id":1295,"day":21,"w":"pilot","ph":"ˈpaɪlət","defs":[["n.","驾驶员，飞行员；领航员 vt.驾驶（飞机等）；领航",false]],"tier":"l","hint":"飞行员。词组 a pilot 飞行员","ex":"The pilot landed the plane safely.（飞行员安全着陆。）"},{"id":1296,"day":21,"w":"pretty","ph":"ˈprɪti","defs":[["a.","漂亮的，俊俏的 ad.相当",false]],"tier":"l","hint":"漂亮的、相当。联想 beautiful 漂亮的（同义）","ex":"She is a pretty girl.（她是个漂亮的女孩。）"},{"id":1297,"day":21,"w":"profession","ph":"prəˈfeʃn","defs":[["n.","职业，自由职业",false]],"tier":"l","hint":"职业。联想 professional 专业的","ex":"Teaching is a noble profession.（教书是崇高的职业。）"},{"id":1298,"day":21,"w":"reason","ph":"ˈriːzn","defs":[["n.","理由，原因；理性，理智 vt.推论，推理",false]],"tier":"l","hint":"原因、理由。词组 the reason for …的原因、for this reason 因此","ex":"What is the reason for your absence?（你缺席的原因是什么？）"},{"id":1299,"day":21,"w":"restaurant","ph":"ˈrestrɑːnt","defs":[["n.","餐馆，饭店",false]],"tier":"l","hint":"餐馆。联想 restaurant 餐馆、dine out 外出就餐","ex":"We had dinner at a Chinese restaurant.（我们在一家中餐馆吃饭。）"},{"id":1300,"day":21,"w":"scatter","ph":"ˈskætər","defs":[["vt.","撒，驱散，散开；散布，散播 vi.分散，消散",false]],"tier":"l","hint":"散开、撒。联想 scatter 散开、spread 传播","ex":"The wind scattered the leaves.（风吹散了树叶。）"},{"id":1301,"day":21,"w":"screw","ph":"skruː","defs":[["n.","螺钉，螺丝 vt.拧，拧紧",false]],"tier":"l","hint":"螺丝。词组 screw 螺丝、tighten the screw 拧紧螺丝","ex":"The chair needs a new screw.（椅子需要个新螺丝。）"},{"id":1302,"day":21,"w":"secret","ph":"ˈsiːkrət","defs":[["a.","秘密的，机密的 n.秘密，奥秘",false]],"tier":"l","hint":"秘密。词组 keep a secret 保守秘密、in secret 秘密地","ex":"Can you keep a secret?（你能保守秘密吗？）"},{"id":1303,"day":21,"w":"sheep","ph":"ʃiːp","defs":[["n.","羊，绵羊",false]],"tier":"l","hint":"绵羊（单复数同形）。联想 goat 山羊、sheep 绵羊","ex":"There are many sheep on the farm.（农场里有很多绵羊。）"},{"id":1304,"day":21,"w":"ship","ph":"ʃɪp","defs":[["n.","船，舰；太空船 vt.航运，装运，运送",false]],"tier":"l","hint":"船（大）。词组 by ship 乘船","ex":"The ship sailed across the sea.（船驶过大海。）"},{"id":1305,"day":21,"w":"shop","ph":"ʃɑːp","defs":[["n.","商店，店铺；工场，车间 vi.购物",false]],"tier":"l","hint":"商店、购物。词组 go shopping 购物","ex":"She went shopping on Sunday.（她周日去购物了。）"},{"id":1306,"day":21,"w":"should","ph":"ʃəd","defs":[["aux.","v.[shall的过去式]；[表示假设]万一；[表示义务、 责任]应当，应该；[表示说话者意愿]就，该；[表示可 能、推测]可能，该；[表示惊奇、遗憾]竟然会",false]],"tier":"l","hint":"应该。词组 should do 应该做","ex":"You should study harder.（你应该更努力学习。）"},{"id":1307,"day":21,"w":"sideways","ph":"ˈsaɪdweɪz","defs":[["ad.","从（向）一侧，斜着",false]],"tier":"l","hint":"side（边）+ ways → 向一边、侧身","ex":"He looked at me sideways.（他斜着眼看我。）"},{"id":1308,"day":21,"w":"situation","ph":"ˌsɪtʃuˈeɪʃn","defs":[["n.","形势，局面；环境，状况；位置，地点",false]],"tier":"l","hint":"情况、形势。词组 in this situation 在这种情况下","ex":"The situation is under control.（情况在控制中。）"},{"id":1309,"day":21,"w":"slope","ph":"sloʊp","defs":[["n.","坡，斜坡；倾斜，斜度",false]],"tier":"l","hint":"斜坡。联想 slope 斜坡、hill 小山","ex":"The children slid down the slope.（孩子们从斜坡上滑下。）"},{"id":1310,"day":21,"w":"spoil","ph":"spɔɪl","defs":[["vt.","搞糟，损坏；宠坏，溺爱 vi.食物变坏",false]],"tier":"l","hint":"宠坏、损坏。过去式 spoilt/spoiled","ex":"Don't spoil the children too much.（别太宠孩子。）"},{"id":1311,"day":21,"w":"sport","ph":"spɔːrt","defs":[["n.","运动；(pl.)运动会",false]],"tier":"l","hint":"运动。词组 do sport 做运动","ex":"Swimming is my favorite sport.（游泳是我最喜欢的运动。）"},{"id":1312,"day":21,"w":"system","ph":"ˈsɪstəm","defs":[["n.","系统，体系；制度，体制",false]],"tier":"l","hint":"系统。词组 computer system 计算机系统","ex":"The school has a new teaching system.（学校有新的教学系统。）"},{"id":1313,"day":21,"w":"toward(s)","ph":"tɔːrd","defs":[["prep.","[表示运动方向]朝，向；[表示关系]对于；[表示 时间]将近；[表示目 的]为了",false]],"tier":"l","hint":"朝向、对于。词组 walk toward 走向","ex":"He walked toward the door.（他朝门口走去。）"},{"id":1314,"day":21,"w":"tropical","ph":"ˈtrɑːpɪkl","defs":[["a.","热带的",false]],"tier":"l","hint":"热带的。词组 tropical fruit 热带水果","ex":"The tropical forest is full of life.（热带森林充满生机。）"},{"id":1315,"day":21,"w":"would","ph":"wʊd","defs":[["aux.","v.将；可能，大概；总会；宁愿",false]],"tier":"l","hint":"将会、愿意（will 的过去式）。词组 would like 想要","ex":"I would like a cup of tea.（我想要杯茶。）"},{"id":1316,"day":22,"w":"add","ph":"æd","defs":[["vt.","加，加上；增加，增进；进一步说/写 vi. (to)增添",false]],"tier":"l","hint":"加、增加。词组 add to 增加、add up 加起来","ex":"Please add some sugar to the coffee.（请给咖啡加点糖。）"},{"id":1317,"day":22,"w":"advertisement","ph":"ˌædvərˈtaɪzmənt","defs":[["n.","广告",true]],"tier":"f","ety":"advertise（做广告）+ -ment → 广告","mem":"advertise + ment → 广告。联想前面学的 advertise。画面：广告牌","ex":"a TV advertisement · I saw a TV advertisement for the phone.（我看到这款手机的电视广告。）","nua":"advertisement（正式）、ad（口语缩写）；advertise for（登广告）"},{"id":1318,"day":22,"w":"away","ph":"əˈweɪ","defs":[["ad.","远离，离开",false]],"tier":"l","hint":"离开、远离。词组 go away 走开、right away 立刻","ex":"He went away without saying goodbye.（他没说再见就走了。）"},{"id":1319,"day":22,"w":"begin","ph":"bɪˈɡɪn","defs":[["vi.","/vt.开始，着手",false]],"tier":"l","hint":"开始。过去式 began。词组 begin to do 开始做","ex":"The class begins at eight.（八点开始上课。）"},{"id":1320,"day":22,"w":"border","ph":"ˈbɔːrdər","defs":[["n.","边缘；边界，边境 vi.交界，与……毗邻；与……相似",false]],"tier":"l","hint":"边界、边境。联想 border 边界、boundary 界限","ex":"They crossed the border into another country.（他们越过边境进入另一个国家。）"},{"id":1321,"day":22,"w":"brain","ph":"breɪn","defs":[["n.","大脑，脑髄；(pl.)心智，智力",false]],"tier":"l","hint":"大脑。词组 use one's brain 动脑筋","ex":"The human brain is very complex.（人脑非常复杂。）"},{"id":1322,"day":22,"w":"cheese","ph":"tʃiːz","defs":[["n.","干酪，乳酪",false]],"tier":"l","hint":"奶酪。联想 milk 牛奶、cheese 奶酪","ex":"I like cheese on my bread.（我喜欢面包上放奶酪。）"},{"id":1323,"day":22,"w":"cool","ph":"kuːl","defs":[["a.","凉，凉爽；冷静，沉着，冷淡 vi./vt.（使）冷却，（使）镇静",false]],"tier":"l","hint":"凉爽的、酷的。联想 warm 温暖的（反义）","ex":"The weather is cool in autumn.（秋天天气凉爽。）"},{"id":1324,"day":22,"w":"department","ph":"dɪˈpɑːrtmənt","defs":[["n.","部门，系",false]],"tier":"l","hint":"部门。词组 department store 百货商店","ex":"He works in the sales department.（他在销售部门工作。）"},{"id":1325,"day":22,"w":"deserve","ph":"dɪˈzɜːrv","defs":[["vt.","应受，值得",true]],"tier":"f","ety":"de-（完全）+ serve（服务）→ 服务到位应得的 → 应受","mem":"de + serve（服务）→ 干得好、服务到位 → \"值得\"奖赏。画面：劳有所得","ex":"deserve to · You deserve to win the prize.（你理应获奖。）","nua":"deserve to do（理应做）、deserve + 名词（应受）；deserve 后不接 for"},{"id":1326,"day":22,"w":"develop","ph":"dɪˈveləp","defs":[["vi.","/vt.发展，进展；开发，研制；生长；进化",false]],"tier":"l","hint":"发展、开发。词组 develop into 发展成","ex":"The city has developed quickly.（这座城市发展很快。）"},{"id":1327,"day":22,"w":"different","ph":"ˈdɪfrənt","defs":[["a.","差异的，不同的",false]],"tier":"l","hint":"不同的。词组 be different from 与…不同","ex":"Your idea is different from mine.（你的想法和我的不同。）"},{"id":1328,"day":22,"w":"drum","ph":"drʌm","defs":[["n.","鼓，鼓状物",false]],"tier":"l","hint":"鼓。词组 play the drum 打鼓","ex":"He plays the drum in the band.（他在乐队里打鼓。）"},{"id":1329,"day":22,"w":"electric","ph":"ɪˈlektrɪk","defs":[["a.","电的，带电的，电动的",false]],"tier":"l","hint":"电的。联想 electricity 电（名词）","ex":"The car is powered by electric energy.（这辆车用电力驱动。）"},{"id":1330,"day":22,"w":"electricity","ph":"ɪˌlekˈtrɪsəti","defs":[["n.","电，电流，电学",false]],"tier":"l","hint":"electric（电的）+ -ity → 电","ex":"The village has no electricity.（这个村庄没有电。）"},{"id":1331,"day":22,"w":"envelope","ph":"ˈenvəloʊp","defs":[["n.","信封",false]],"tier":"l","hint":"信封。联想 letter 信、envelope 信封","ex":"He put the letter in an envelope.（他把信放进信封。）"},{"id":1332,"day":22,"w":"equipment","ph":"ɪˈkwɪpmənt","defs":[["n.","装备，设备，器材",false]],"tier":"l","hint":"equip（装备）+ -ment → 设备（不可数）","ex":"The lab has modern equipment.（实验室有现代化设备。）"},{"id":1333,"day":22,"w":"exist","ph":"ɪɡˈzɪst","defs":[["vi.","在，存在",false]],"tier":"l","hint":"存在。联想 existence 存在（名词）","ex":"Do you believe ghosts exist?（你相信鬼存在吗？）"},{"id":1334,"day":22,"w":"expect","ph":"ɪkˈspekt","defs":[["vt.","期待，盼望；料想，预期",false]],"tier":"l","hint":"期望、预料。词组 expect to do 期望做","ex":"I expect to see you soon.（我期望很快见到你。）"},{"id":1335,"day":22,"w":"head","ph":"hed","defs":[["n.","头，头顶；顶部，前部；首脑，首长 vt.领导，主管；居……之首 vi.（朝特定方向）行进",false]],"tier":"l","hint":"头、领导。词组 head for 前往、at the head of 在…之首","ex":"He has a pain in his head.（他头疼。）"},{"id":1336,"day":22,"w":"income","ph":"ˈɪnkʌm","defs":[["n.","收入，所得，进款",false]],"tier":"l","hint":"收入。联想 salary 薪水、income 收入","ex":"He has a high income.（他收入很高。）"},{"id":1337,"day":22,"w":"increase","ph":"ˈɪnkriːs","defs":[["vi.","/vt.增加，增长，增进 n.增加，增长，增进",false]],"tier":"l","hint":"增加。联想 decrease 减少（反义）","ex":"The population is increasing rapidly.（人口在迅速增加。）"},{"id":1338,"day":22,"w":"information","ph":"ˌɪnfərˈmeɪʃn","defs":[["n.","信息，资料，情报",false]],"tier":"l","hint":"信息（不可数）。词组 a piece of information 一条信息","ex":"I need some information about the train.（我需要一些关于火车的信息。）"},{"id":1339,"day":22,"w":"inner","ph":"ˈɪnər","defs":[["a.","内部的，里面的；内心的",false]],"tier":"l","hint":"内部的。联想 outer 外部的（反义）","ex":"She lives in the inner city.（她住在市中心。）"},{"id":1340,"day":22,"w":"insure","ph":"ɪnˈʃʊr","defs":[["vt.","保险，替……保险；保证",false]],"tier":"l","hint":"保险、确保。联想 insurance 保险（名词）","ex":"He insured his car against accidents.（他给车投了事故险。）"},{"id":1341,"day":22,"w":"interrupt","ph":"ˌɪntəˈrʌpt","defs":[["vt.","打断，打扰；断绝，中断",false]],"tier":"l","hint":"打断。词组 interrupt sb 打断某人","ex":"Don't interrupt me when I'm speaking.（我说话时别打断我。）"},{"id":1342,"day":22,"w":"juice","ph":"dʒuːs","defs":[["n.","汁，液",false]],"tier":"l","hint":"果汁。词组 a glass of juice 一杯果汁","ex":"I'd like a glass of orange juice.（我想要杯橙汁。）"},{"id":1343,"day":22,"w":"just","ph":"dʒʌst","defs":[["ad.","正好，恰好；刚刚；仅仅是，只不过 a.公正，公平",false]],"tier":"l","hint":"刚刚、只是、公正的。词组 just now 刚才、just as 正如","ex":"I just arrived.（我刚到。）"},{"id":1344,"day":22,"w":"necessary","ph":"ˈnesəseri","defs":[["a.","必需的，必要的；必然的",false]],"tier":"l","hint":"必要的。词组 be necessary for 对…必要","ex":"Sleep is necessary for health.（睡眠对健康是必要的。）"},{"id":1345,"day":22,"w":"onion","ph":"ˈʌnjən","defs":[["n.","洋葱",false]],"tier":"l","hint":"洋葱。联想 vegetable 蔬菜、onion 洋葱","ex":"She cut the onion into pieces.（她把洋葱切成片。）"},{"id":1346,"day":22,"w":"onto","ph":"ˈɑːntə","defs":[["prep.","到……之上，在……之上",false]],"tier":"l","hint":"到…上。词组 jump onto 跳到…上","ex":"The cat jumped onto the table.（猫跳上了桌子。）"},{"id":1347,"day":22,"w":"order","ph":"ˈɔːrdər","defs":[["n.","命令；次序；等级；秩序；整齐；订货(单) vt.命令；定制，订购",false]],"tier":"l","hint":"顺序、命令、订购。词组 in order to 为了、place an order 下订单","ex":"He ordered a cup of coffee.（他点了杯咖啡。）"},{"id":1348,"day":22,"w":"perhaps","ph":"pərˈhæps","defs":[["ad.","也许，恐怕，大概",false]],"tier":"l","hint":"也许。联想 maybe 也许（同义）","ex":"Perhaps he will come tomorrow.（也许他明天会来。）"},{"id":1349,"day":22,"w":"permission","ph":"pərˈmɪʃn","defs":[["n.","许可，允许",false]],"tier":"l","hint":"permit（允许）的名词 → 许可。词组 with permission 经许可","ex":"You need permission to enter.（你需要许可才能进入。）"},{"id":1350,"day":22,"w":"plane","ph":"pleɪn","defs":[["n.","飞机；平面",false]],"tier":"l","hint":"飞机（airplane 缩写）。词组 by plane 乘飞机","ex":"They went to Beijing by plane.（他们乘飞机去北京。）"},{"id":1351,"day":22,"w":"poet","ph":"ˈpoʊət","defs":[["n.","诗人",false]],"tier":"l","hint":"诗人。联想 poem 诗、poetry 诗歌","ex":"Li Bai was a great poet.（李白是伟大的诗人。）"},{"id":1352,"day":22,"w":"pour","ph":"pɔːr","defs":[["vi.","/vt.灌，倒，注；泻，流出",false]],"tier":"l","hint":"倒、倾泻。词组 pour...into 倒入","ex":"Please pour some water into the cup.（请往杯里倒点水。）"},{"id":1353,"day":22,"w":"present","ph":"ˈpreznt","defs":[["vt.","赠送，给予；提出，呈递，出示；介绍 a.出席的，在场的；目前的，现在的 n. 目前，现在；礼物，礼品",false]],"tier":"l","hint":"礼物、现在的、出席的。词组 at present 目前","ex":"He gave me a present for my birthday.（他送我生日礼物。）"},{"id":1354,"day":22,"w":"protect","ph":"prəˈtekt","defs":[["vt.","保护，保卫",false]],"tier":"l","hint":"保护。词组 protect...from 保护…免受","ex":"We should protect the environment.（我们应该保护环境。）"},{"id":1355,"day":22,"w":"rate","ph":"reɪt","defs":[["n.","速率，比率；等级；价格，费 vt.评级，评价",false]],"tier":"l","hint":"比率、速度。词组 at the rate of 以…速度","ex":"The birth rate is falling.（出生率在下降。）"},{"id":1356,"day":22,"w":"relation","ph":"rɪˈleɪʃn","defs":[["n.","亲属，亲戚；关系，联系",false]],"tier":"l","hint":"关系。词组 in relation to 关于、与…相关","ex":"He has a good relation with his colleagues.（他和同事关系好。）"},{"id":1357,"day":22,"w":"remind","ph":"rɪˈmaɪnd","defs":[["vt.","提醒，使想起",false]],"tier":"l","hint":"提醒。词组 remind sb of 使某人想起、remind sb to do 提醒某人做","ex":"This photo reminds me of my childhood.（这张照片让我想起童年。）"},{"id":1358,"day":22,"w":"rid","ph":"rɪd","defs":[["vt.","(of)免除，使获自由，使摆脱",false]],"tier":"l","hint":"摆脱。词组 get rid of 摆脱、除去","ex":"We must get rid of the bad habit.（我们必须改掉坏习惯。）"},{"id":1359,"day":22,"w":"rise","ph":"raɪz","defs":[["vi.","上升，上涨；升起；起床，起立 n.增加，升高；起源，发生；高地",false]],"tier":"l","hint":"上升（不及物）。过去式 rose。对比 raise（及物）","ex":"The sun rises in the east.（太阳从东方升起。）"},{"id":1360,"day":22,"w":"sex","ph":"seks","defs":[["n.","性别；性",false]],"tier":"l","hint":"性别、性。词组 the opposite sex 异性","ex":"The school admits students of either sex.（学校招收男女学生。）"},{"id":1361,"day":22,"w":"share","ph":"ʃer","defs":[["vt.","分享，分担；均分，分配 vi. (in)分担 n.部分，一份；分担；份子，份额，股份",false]],"tier":"l","hint":"分享、份额。词组 share...with 与…分享","ex":"She shared her food with me.（她和我分享食物。）"},{"id":1362,"day":22,"w":"shot","ph":"ʃɑːt","defs":[["n.","射击，枪声；射门，投篮；弹丸，弹炮",false]],"tier":"l","hint":"shoot（射击）的名词 → 射击、投篮。词组 a shot 一枪","ex":"He heard a shot in the distance.（他听到远处一声枪响。）"},{"id":1363,"day":22,"w":"sit","ph":"sɪt","defs":[["vi.","坐，坐下；位于；栖息；孵卵 vt.使就座",false]],"tier":"l","hint":"坐。过去式 sat。词组 sit down 坐下","ex":"Please sit down and have a rest.（请坐下休息。）"},{"id":1364,"day":22,"w":"size","ph":"saɪz","defs":[["n.","大小，尺寸；号码，尺码",false]],"tier":"l","hint":"尺寸、大小。词组 what size 什么尺寸","ex":"What size do you wear?（你穿多大尺寸？）"},{"id":1365,"day":22,"w":"sleeve","ph":"sliːv","defs":[["n.","袖子",false]],"tier":"l","hint":"袖子。词组 short sleeves 短袖","ex":"He rolled up his sleeves.（他卷起袖子。）"},{"id":1366,"day":22,"w":"snow","ph":"snoʊ","defs":[["n.","雪 vi.下雪",false]],"tier":"l","hint":"雪、下雪。词组 heavy snow 大雪","ex":"It snowed heavily last night.（昨晚下了大雪。）"},{"id":1367,"day":22,"w":"story","ph":"ˈstɔːri","defs":[["n.","故事，小说；传说，事迹；新闻报道",false]],"tier":"l","hint":"故事。词组 tell a story 讲故事","ex":"Grandma told us a story.（奶奶给我们讲故事。）"},{"id":1368,"day":22,"w":"strong","ph":"strɔːŋ","defs":[["a.","强壮的，强大的；强硬的；强烈的",false]],"tier":"l","hint":"强壮的。联想 weak 虚弱的（反义）、strength 力量","ex":"He is strong enough to lift the box.（他强壮得能举起箱子。）"},{"id":1369,"day":22,"w":"sum","ph":"sʌm","defs":[["n.","总数，总和；金额 vt.总结，概括；估量，估计",false]],"tier":"l","hint":"总和、金额。词组 in sum 总之、a large sum of 一大笔","ex":"He spent a large sum of money.（他花了一大笔钱。）"},{"id":1370,"day":22,"w":"summer","ph":"ˈsʌmər","defs":[["n.","夏天，夏季",false]],"tier":"l","hint":"夏天。联想 spring 春、summer 夏、autumn 秋、winter 冬","ex":"We go swimming in summer.（我们夏天去游泳。）"},{"id":1371,"day":22,"w":"tent","ph":"tent","defs":[["n.","帐蓬",false]],"tier":"l","hint":"帐篷。词组 put up a tent 搭帐篷","ex":"They put up a tent by the lake.（他们在湖边搭了帐篷。）"},{"id":1372,"day":22,"w":"thumb","ph":"θʌm","defs":[["n.","拇指",false]],"tier":"l","hint":"拇指。联想 finger 手指、thumb 拇指","ex":"He has a cut on his thumb.（他拇指上有道口子。）"},{"id":1373,"day":22,"w":"tidy","ph":"ˈtaɪdi","defs":[["vt.","整理，收拾 a.整洁的，整齐的",false]],"tier":"l","hint":"整洁的。联想 neat 整洁的（同义）","ex":"Please keep your room tidy.（请保持房间整洁。）"},{"id":1374,"day":22,"w":"train","ph":"treɪn","defs":[["vt.","培训，训练 n.列车；一连串",false]],"tier":"l","hint":"火车、训练。词组 by train 乘火车","ex":"They went to Shanghai by train.（他们乘火车去上海。）"},{"id":1375,"day":22,"w":"try","ph":"traɪ","defs":[["vt.","尝试，试验 vi./n.尝试，努力",false]],"tier":"l","hint":"尝试、努力。词组 try to do 努力做、try one's best 尽力","ex":"I will try my best to help you.（我会尽力帮你。）"},{"id":1376,"day":22,"w":"various","ph":"ˈveriəs","defs":[["a.","各种各样的，不同的；多方面的，多种的",false]],"tier":"l","hint":"vary（变化）+ -ious → 各种各样的","ex":"The store sells various goods.（这家店卖各种商品。）"},{"id":1377,"day":22,"w":"world","ph":"wɜːrld","defs":[["n.","世界，地球；领域；世间，人间；全世界",false]],"tier":"l","hint":"世界。词组 all over the world 全世界、in the world 世界上","ex":"People all over the world love peace.（全世界人民都爱和平。）"},{"id":1378,"day":22,"w":"wrap","ph":"ræp","defs":[["vt.","卷，包，缠绕 n.披肩，围巾",false]],"tier":"l","hint":"包裹。词组 wrap up 包起来","ex":"She wrapped the gift in paper.（她用纸把礼物包起来。）"},{"id":1379,"day":23,"w":"affect","ph":"əˈfekt","defs":[["vt.","影响",true]],"tier":"f","ety":"af-（向）+ fect（做，同 fac-）→ 对…起作用 → 影响","mem":"A 联想 action（动词）→ affect 作\"动词\"；E 联想 end result（结果）→ effect 作\"名词\"。画面：一石激起千层浪","ex":"affect sb · The noise affects my sleep.（噪音影响我的睡眠。）","nua":"affect（动词，影响）、effect（名词，影响/结果）；have an effect on = affect"},{"id":1380,"day":23,"w":"atom","ph":"ˈætəm","defs":[["n.","原子",true]],"tier":"f","ety":"a-（不）+ tom（切）→ 不可再切的 → 原子","mem":"a（不）+ tom（切）→ \"切不开\"的最小粒子 → 原子。画面：最小的微粒","ex":"an atom · Water is made of atoms.（水由原子组成。）","nua":"atom（原子）、atomic（原子的）；a- 否定 + tom 切割 = 不可分割"},{"id":1381,"day":23,"w":"attach","ph":"əˈtætʃ","defs":[["vt.","贴上，系上，附上",true]],"tier":"f","ety":"a-（向）+ tach（钉，同 tack）→ 钉上去 → 附上","mem":"a + tach（=tack 图钉）→ 用\"图钉\"钉上去 → 附上。画面：把便签钉在板上","ex":"attach importance to · We attach great importance to education.（我们高度重视教育。）","nua":"attach importance to（重视）、be attached to（依恋、附属）；attachment（附件）"},{"id":1382,"day":23,"w":"attend","ph":"əˈtend","defs":[["vt.","出席；参加；照顾，护理 vi. (to)注意，留意；专心于",false]],"tier":"l","hint":"出席、参加。词组 attend a meeting 参加会议","ex":"He attended the meeting yesterday.（他昨天参加了会议。）"},{"id":1383,"day":23,"w":"awkward","ph":"ˈɔːkwərd","defs":[["a.","笨拙的；尴尬的",true]],"tier":"f","ety":"awk（反向，古诺斯语）+ -ward → 转向错误方向 → 笨拙","mem":"谐音\"奥克沃德\"→ 手脚不协调\"噢\"地撞到 → 笨拙、尴尬。画面：同手同脚","ex":"an awkward situation · It was an awkward situation.（那是个尴尬的局面。）","nua":"awkward（笨拙、尴尬）、clumsy（笨拙，侧重动作）；an awkward question 棘手的问题"},{"id":1384,"day":23,"w":"because","ph":"bɪˈkəz","defs":[["conj.","因为",false]],"tier":"l","hint":"因为。词组 because of 因为（后接名词）","ex":"He was late because of the rain.（他因下雨迟到了。）"},{"id":1385,"day":23,"w":"belong","ph":"bɪˈlɔːŋ","defs":[["vi.","(to)属，附属；归类于",false]],"tier":"l","hint":"属于。词组 belong to 属于","ex":"This book belongs to me.（这本书是我的。）"},{"id":1386,"day":23,"w":"besides","ph":"bɪˈsaɪdz","defs":[["ad.","而且，还有 prep.除……之外",false]],"tier":"l","hint":"此外、除…之外。联想 except 除了（不同义）","ex":"Besides English, she also learns French.（除了英语，她还学法语。）"},{"id":1387,"day":23,"w":"burn","ph":"bɜːrn","defs":[["vi.","/vt.燃烧，烧毁 n.灼伤，烧伤",false]],"tier":"l","hint":"燃烧、烧伤。过去式 burnt/burned。词组 burn down 烧毁","ex":"The fire burned the forest.（大火烧了森林。）"},{"id":1388,"day":23,"w":"ceremony","ph":"ˈserəmoʊni","defs":[["n.","仪式，典礼，礼节",false]],"tier":"l","hint":"仪式、典礼。词组 opening ceremony 开幕式","ex":"The wedding ceremony was beautiful.（婚礼仪式很美。）"},{"id":1389,"day":23,"w":"cheat","ph":"tʃiːt","defs":[["vt.","欺骗，骗取 vi.作弊，欺诈 n.欺骗；骗子",false]],"tier":"l","hint":"欺骗、作弊。词组 cheat in the exam 考试作弊","ex":"Don't cheat in the exam.（考试不要作弊。）"},{"id":1390,"day":23,"w":"circle","ph":"ˈsɜːrkl","defs":[["n.","圆，圆周；圈子，阶层；周期，循环 vt.环绕 vi.盘旋；画圈",false]],"tier":"l","hint":"圆、圆圈。联想 circular 圆形的","ex":"The children sat in a circle.（孩子们围成一圈坐着。）"},{"id":1391,"day":23,"w":"contain","ph":"kənˈteɪn","defs":[["vt.","容纳，含有，装有；克制，抑制",false]],"tier":"l","hint":"包含。联想 container 容器、contain 包含","ex":"The box contains some books.（箱子里有一些书。）"},{"id":1392,"day":23,"w":"country","ph":"ˈkʌntri","defs":[["n.","国家；农村，乡间",false]],"tier":"l","hint":"国家、乡村。词组 in the country 在乡下","ex":"China is a great country.（中国是个伟大的国家。）"},{"id":1393,"day":23,"w":"cow","ph":"kaʊ","defs":[["n.","母牛，奶牛",false]],"tier":"l","hint":"母牛。联想 cattle 牛（总称）","ex":"The cow gives us milk.（母牛给我们牛奶。）"},{"id":1394,"day":23,"w":"cream","ph":"kriːm","defs":[["n.","奶油；奶油色",false]],"tier":"l","hint":"奶油、乳霜。词组 ice cream 冰淇淋","ex":"She likes ice cream very much.（她很喜欢冰淇淋。）"},{"id":1395,"day":23,"w":"crime","ph":"kraɪm","defs":[["n.","罪，罪行，犯罪",false]],"tier":"l","hint":"犯罪。联想 criminal 罪犯、crime 犯罪","ex":"He was punished for his crime.（他因犯罪受罚。）"},{"id":1396,"day":23,"w":"definite","ph":"ˈdefɪnət","defs":[["a.","明确的，确定的",true]],"tier":"f","ety":"de-（加强）+ finite（有限）→ 划清界限 → 明确","mem":"de + finite（有限）→ 把范围\"限\"清楚 → 明确。画面：划出清晰边界","ex":"a definite answer · I need a definite answer.（我需要一个明确的答复。）","nua":"definite（明确的）、definitely（明确地）、infinite（无限的）；de + finite 限"},{"id":1397,"day":23,"w":"dish","ph":"dɪʃ","defs":[["n.","碟，盘子；菜肴",false]],"tier":"l","hint":"盘子、菜。词组 wash the dishes 洗碗","ex":"She cooked a delicious dish.（她做了道美味的菜。）"},{"id":1398,"day":23,"w":"doubt","ph":"daʊt","defs":[["n.","怀疑，疑问，疑惑 vi./vt.怀疑，不相信",false]],"tier":"l","hint":"怀疑。词组 no doubt 毫无疑问、doubt that 怀疑","ex":"There is no doubt that he will come.（毫无疑问他会来。）"},{"id":1399,"day":23,"w":"empty","ph":"ˈempti","defs":[["a.","空的；空洞的 vt.倒空，搬空",false]],"tier":"l","hint":"空的。联想 full 满的（反义）","ex":"The room is empty now.（房间现在空了。）"},{"id":1400,"day":23,"w":"entrance","ph":"ˈentrəns","defs":[["n.","入口，门口；入场，入会，入学",false]],"tier":"l","hint":"enter（进入）+ -ance → 入口。词组 at the entrance 在入口","ex":"They met at the entrance of the park.（他们在公园入口见面。）"},{"id":1401,"day":23,"w":"explode","ph":"ɪkˈsploʊd","defs":[["vi.","/vt.（使）爆炸，爆发，破裂",false]],"tier":"l","hint":"爆炸。联想 explosion 爆炸（名词）","ex":"The bomb exploded in the street.（炸弹在街上爆炸了。）"},{"id":1402,"day":23,"w":"feather","ph":"ˈfeðər","defs":[["n.","羽毛",false]],"tier":"l","hint":"羽毛。联想 bird 鸟、feather 羽毛","ex":"The bird has beautiful feathers.（这只鸟有美丽的羽毛。）"},{"id":1403,"day":23,"w":"flag","ph":"flæɡ","defs":[["n.","旗",false]],"tier":"l","hint":"旗帜。词组 national flag 国旗","ex":"The flag is flying in the wind.（旗帜在风中飘扬。）"},{"id":1404,"day":23,"w":"healthy","ph":"ˈhelθi","defs":[["a.","健康，健壮的；有益健康的，合乎卫生的",false]],"tier":"l","hint":"health（健康）+ -y → 健康的。词组 keep healthy 保持健康","ex":"Exercise keeps you healthy.（锻炼使你健康。）"},{"id":1405,"day":23,"w":"height","ph":"haɪt","defs":[["n.","高，高度，身高；高处，高地；顶点",false]],"tier":"l","hint":"high（高）的名词 → 高度。词组 in height 在高度上","ex":"The tower is 100 meters in height.（这座塔高 100 米。）"},{"id":1406,"day":23,"w":"high","ph":"haɪ","defs":[["a.","高；高度的；高级的，高尚的 ad.高",false]],"tier":"l","hint":"高的。联想 low 低的（反义）","ex":"The mountain is very high.（这座山很高。）"},{"id":1407,"day":23,"w":"independent","ph":"ˌɪndɪˈpendənt","defs":[["a.","独立的，自主的",true]],"tier":"f","ety":"in-（不）+ dependent（依赖的）→ 不依赖的 → 独立","mem":"in（不）+ dependent（依赖）→ \"不依赖\"别人 → 独立。画面：自己站立","ex":"be independent of · Children should learn to be independent of parents.（孩子应学会独立于父母。）","nua":"be independent of（独立于）、depend on（依赖）；名词 independence（独立）"},{"id":1408,"day":23,"w":"intelligent","ph":"ɪnˈtelɪdʒənt","defs":[["a.","聪明的，理智的",false]],"tier":"l","hint":"intelligence（智力）+ -t → 聪明的","ex":"She is an intelligent student.（她是个聪明的学生。）"},{"id":1409,"day":23,"w":"loyalty","ph":"ˈlɔɪəlti","defs":[["n.","忠诚，忠心",false]],"tier":"l","hint":"loyal（忠诚）+ -ty → 忠诚","ex":"His loyalty to the company is well known.（他对公司的忠诚众所周知。）"},{"id":1410,"day":23,"w":"lucky","ph":"ˈlʌki","defs":[["a.","幸运的，侥幸的",false]],"tier":"l","hint":"luck（运气）+ -y → 幸运的。词组 be lucky to 幸运地","ex":"You are lucky to get the ticket.（你很幸运拿到票。）"},{"id":1411,"day":23,"w":"method","ph":"ˈmeθəd","defs":[["n.","方法，办法",false]],"tier":"l","hint":"方法。联想 way 方法（同义）","ex":"This is a good method of learning.（这是好的学习方法。）"},{"id":1412,"day":23,"w":"might","ph":"maɪt","defs":[["aux.","v.[may的过去式] n.力量，威力",false]],"tier":"l","hint":"可能、也许（may 的过去式）。","ex":"It might rain tomorrow.（明天可能下雨。）"},{"id":1413,"day":23,"w":"mix","ph":"mɪks","defs":[["vt.","混合，掺和；混淆，混乱",false]],"tier":"l","hint":"混合。词组 mix...with 把…混合","ex":"Mix the sugar with the flour.（把糖和面粉混合。）"},{"id":1414,"day":23,"w":"moral","ph":"ˈmɔːrəl","defs":[["a.","道德的，道义的，有道德的 n.寓意，教育意义",false]],"tier":"l","hint":"道德的、寓意。词组 moral values 道德观","ex":"The story has a moral meaning.（这个故事有寓意。）"},{"id":1415,"day":23,"w":"north","ph":"nɔːrθ","defs":[["a.","/n.北（的），北方（的） ad.向/自/在北方",false]],"tier":"l","hint":"北方。联想 south 南方、east 东、west 西","ex":"The wind blows from the north.（风从北方吹来。）"},{"id":1416,"day":23,"w":"parliament","ph":"ˈpɑːrləmənt","defs":[["n.","国会，议会",false]],"tier":"l","hint":"议会。联想 parliament 议会、government 政府","ex":"The parliament passed the new law.（议会通过了新法律。）"},{"id":1417,"day":23,"w":"patient","ph":"ˈpeɪʃnt","defs":[["a.","有耐心的，能忍耐的 n.病人，患者",false]],"tier":"l","hint":"耐心的、病人。词组 be patient with 对…耐心","ex":"The doctor is patient with his patients.（医生对病人很耐心。）"},{"id":1418,"day":23,"w":"payment","ph":"ˈpeɪmənt","defs":[["n.","支付，付款",false]],"tier":"l","hint":"pay（支付）+ -ment → 支付","ex":"The payment must be made in advance.（必须提前付款。）"},{"id":1419,"day":23,"w":"population","ph":"ˌpɑːpjuˈleɪʃn","defs":[["n.","人口",false]],"tier":"l","hint":"人口。词组 the population of …的人口","ex":"The population of the city is growing.（这座城市的人口在增长。）"},{"id":1420,"day":23,"w":"president","ph":"ˈprezɪdənt","defs":[["n.","主席，总统；校长，会长；总裁；董事长",false]],"tier":"l","hint":"总统、主席。联想 president 总统、president of 主席","ex":"The president gave a speech.（总统发表了演讲。）"},{"id":1421,"day":23,"w":"proud","ph":"praʊd","defs":[["a.","骄傲的，自豪的；引以为豪的",false]],"tier":"l","hint":"自豪的。词组 be proud of 为…自豪","ex":"I'm proud of my country.（我为我的国家自豪。）"},{"id":1422,"day":23,"w":"rather","ph":"ˈræðər","defs":[["ad.","有些，相当；宁可，宁愿",false]],"tier":"l","hint":"相当、宁愿。词组 rather than 而不是、would rather 宁愿","ex":"I would rather stay at home.（我宁愿待在家里。）"},{"id":1423,"day":23,"w":"reply","ph":"rɪˈplaɪ","defs":[["vi.","/n.答复，回答",false]],"tier":"l","hint":"回答。词组 reply to 回答","ex":"He replied to my letter quickly.（他很快回了我信。）"},{"id":1424,"day":23,"w":"rush","ph":"rʌʃ","defs":[["vi.","冲，突进；匆忙行动 vt.使急行；匆忙地做；催促 n.冲，奔，急速流动",false]],"tier":"l","hint":"冲、匆忙。词组 rush hour 高峰时间、rush to 冲向","ex":"He rushed to the station.（他冲向车站。）"},{"id":1425,"day":23,"w":"separate","ph":"ˈseprət","defs":[["a.","分离的，分开的 [ˈsepəreɪt] vt.分离，分开",false]],"tier":"l","hint":"分开的、分离。词组 separate...from 把…与…分开","ex":"Separate the good apples from the bad ones.（把好苹果和坏苹果分开。）"},{"id":1426,"day":23,"w":"sign","ph":"saɪn","defs":[["n.","符号，标记，招牌；征兆，迹象 vi./vt.签（名），签署",false]],"tier":"l","hint":"标志、签名。词组 road sign 路标、sign one's name 签名","ex":"Please sign your name here.（请在这里签名。）"},{"id":1427,"day":23,"w":"silent","ph":"ˈsaɪlənt","defs":[["a.","寂静的，沉默的",false]],"tier":"l","hint":"沉默的。联想 silence 沉默（名词）","ex":"He kept silent at the meeting.（他在会上保持沉默。）"},{"id":1428,"day":23,"w":"silk","ph":"sɪlk","defs":[["n.","丝，绸",false]],"tier":"l","hint":"丝绸。联想 silk 丝绸、silky 丝滑的","ex":"The dress is made of silk.（这条裙子是丝绸做的。）"},{"id":1429,"day":23,"w":"smile","ph":"smaɪl","defs":[["vt.","/n.微笑",false]],"tier":"l","hint":"微笑。词组 smile at 对…微笑","ex":"She smiled at the children.（她对孩子们微笑。）"},{"id":1430,"day":23,"w":"solid","ph":"ˈsɑːlɪd","defs":[["n.","固体 a.固体的；实心的；结实的，稳固的，可靠的",false]],"tier":"l","hint":"固体的、坚固的。联想 liquid 液体、solid 固体","ex":"Ice is solid water.（冰是固态的水。）"},{"id":1431,"day":23,"w":"some","ph":"səm","defs":[["pron.","一些；有些 a.某，某一个；大约，大概 ad.大约",false]],"tier":"l","hint":"一些。词组 some day 有一天、some...others 一些…另一些","ex":"Some students are playing basketball.（一些学生在打篮球。）"},{"id":1432,"day":23,"w":"spicy","ph":"ˈspaɪsi","defs":[["a.","辛辣的；加有香料的；有刺激性的",false]],"tier":"l","hint":"spice（香料）+ -y → 辣的、香的","ex":"Sichuan food is very spicy.（四川菜很辣。）"},{"id":1433,"day":23,"w":"style","ph":"staɪl","defs":[["n.","风格，文体；时尚，时髦；种类，类型",false]],"tier":"l","hint":"风格、样式。词组 in style 时髦、life style 生活方式","ex":"She has her own style of dressing.（她有自己的穿衣风格。）"},{"id":1434,"day":23,"w":"swim","ph":"swɪm","defs":[["vi.","/n.游泳；浸，泡",false]],"tier":"l","hint":"游泳。过去式 swam。词组 go swimming 去游泳","ex":"He swims in the river in summer.（他夏天在河里游泳。）"},{"id":1435,"day":23,"w":"temperature","ph":"ˈtemprətʃər","defs":[["n.","温度",false]],"tier":"l","hint":"温度。词组 take one's temperature 量体温","ex":"The temperature is very high today.（今天气温很高。）"},{"id":1436,"day":23,"w":"there","ph":"ðer","defs":[["ad.","在那里，往那里",false]],"tier":"l","hint":"那里。词组 over there 在那边","ex":"The book is over there.（书在那边。）"},{"id":1437,"day":23,"w":"thirsty","ph":"ˈθɜːrsti","defs":[["a.","渴的；渴望的",false]],"tier":"l","hint":"thirst（渴）+ -y → 渴的。联想 hungry 饿的","ex":"I'm thirsty after running.（跑步后我渴了。）"},{"id":1438,"day":23,"w":"traditional","ph":"trəˈdɪʃənl","defs":[["a.","传统的",false]],"tier":"l","hint":"tradition（传统）+ -al → 传统的","ex":"Spring Festival is a traditional Chinese festival.（春节是中国的传统节日。）"},{"id":1439,"day":23,"w":"village","ph":"ˈvɪlɪdʒ","defs":[["n.","村，村庄",false]],"tier":"l","hint":"村庄。联想 town 城镇、village 村庄","ex":"They live in a small village.（他们住在一个小村庄。）"},{"id":1440,"day":23,"w":"while","ph":"waɪl","defs":[["conj.","当……的时候；然而；虽然，尽管 n.一会儿，一段时间",false]],"tier":"l","hint":"当…时、而。词组 for a while 一会儿、after a while 过了一会儿","ex":"He read a book while waiting.（他边等边看书。）"},{"id":1441,"day":23,"w":"wood","ph":"wʊd","defs":[["n.","木头，木材；(pl.)小森林，树林",false]],"tier":"l","hint":"木头、森林。联想 wooden 木制的","ex":"The table is made of wood.（这张桌子是木头的。）"},{"id":1442,"day":24,"w":"actual","ph":"ˈæktʃuəl","defs":[["a.","实际的，事实上的",true]],"tier":"f","ety":"act（做）+ -ual → 做出来的 → 实际的","mem":"act + ual → 真正\"做\"出来的 → 实际的。画面：眼见为实","ex":"the actual cost · The actual cost is higher than expected.（实际成本比预期高。）","nua":"actual（实际的，与想象相对）、current（当前的）；actual ≠ 当前的"},{"id":1443,"day":24,"w":"addition","ph":"əˈdɪʃn","defs":[["n.","加，加法；附加部分，增加（物）",false]],"tier":"l","hint":"add（加）+ -ition → 增加、加法。词组 in addition 此外、in addition to 除…之外","ex":"In addition to English, she speaks French.（除英语外，她还会说法语。）"},{"id":1444,"day":24,"w":"air","ph":"er","defs":[["n.","空气，大气；天空 vt.晾干；使通风",false]],"tier":"l","hint":"空气。词组 in the air 在空中、by air 乘飞机","ex":"The air is fresh in the morning.（早晨空气清新。）"},{"id":1445,"day":24,"w":"along","ph":"əˈlɔːŋ","defs":[["prep.","沿着 ad.向前",false]],"tier":"l","hint":"沿着。词组 along with 连同、walk along 沿着走","ex":"We walked along the river.（我们沿着河走。）"},{"id":1446,"day":24,"w":"arm","ph":"ɑːrm","defs":[["n.","手臂，臂状物；(pl.)武器 vt.武装，装备",false]],"tier":"l","hint":"手臂、武器。词组 arm in arm 手挽手","ex":"He carried a bag under his arm.（他腋下夹着个包。）"},{"id":1447,"day":24,"w":"behave","ph":"bɪˈheɪv","defs":[["vi.","举动，举止，表现",true]],"tier":"f","ety":"be-（使）+ have（拥有）→ 把持自己 → 举止","mem":"be + have → 把自己\"拥有\"好、管住 → 举止。画面：规规矩矩","ex":"behave well · The children behaved well in class.（孩子们课堂上表现很好。）","nua":"behave（举止）、behavior（行为，名词）；behave oneself（守规矩）"},{"id":1448,"day":24,"w":"bicycle","ph":"ˈbaɪsɪkl","defs":[["n.","自行车",false]],"tier":"l","hint":"自行车（缩写 bike）。词组 by bicycle 骑自行车","ex":"He goes to school by bicycle.（他骑自行车上学。）"},{"id":1449,"day":24,"w":"blade","ph":"bleɪd","defs":[["n.","刀刃，刀片；叶片；翼",false]],"tier":"l","hint":"刀刃、叶片。联想 knife 刀、blade 刀刃","ex":"The blade of the knife is sharp.（刀刃很锋利。）"},{"id":1450,"day":24,"w":"bored","ph":"bɔːrd","defs":[["a.","厌烦的",false]],"tier":"l","hint":"bore（使厌烦）+ -d → 感到无聊的。区分 boring 令人无聊的","ex":"I'm bored with the same food.（我吃腻了同样的食物。）"},{"id":1451,"day":24,"w":"bowl","ph":"boʊl","defs":[["n.","碗，钵",false]],"tier":"l","hint":"碗。词组 a bowl of rice 一碗饭","ex":"He ate a bowl of noodles.（他吃了碗面。）"},{"id":1452,"day":24,"w":"box","ph":"bɑːks","defs":[["n.","箱子，盒子 vi.拳击；打耳光",false]],"tier":"l","hint":"盒子、箱子。词组 a box of 一盒","ex":"She put the gift in a box.（她把礼物放进盒子里。）"},{"id":1453,"day":24,"w":"brother","ph":"ˈbrʌðər","defs":[["n.","兄弟，同胞",false]],"tier":"l","hint":"兄弟。联想 sister 姐妹","ex":"My brother is three years older than me.（我哥哥比我大三岁。）"},{"id":1454,"day":24,"w":"burst","ph":"bɜːrst","defs":[["vi.","/n.破裂，爆炸 vi. (into)突然发生，突然发作",false]],"tier":"l","hint":"爆裂、爆发。过去式 burst。词组 burst into 突然…起来","ex":"The balloon burst suddenly.（气球突然爆了。）"},{"id":1455,"day":24,"w":"cell","ph":"sel","defs":[["n.","细胞；电池",false]],"tier":"l","hint":"细胞、电池、牢房。词组 cell phone 手机","ex":"The body is made up of cells.（身体由细胞组成。）"},{"id":1456,"day":24,"w":"character","ph":"ˈkærəktər","defs":[["n.","性格；特征；人物，角色；符号，(汉)字 n.特征，特性",false]],"tier":"l","hint":"性格、角色、字符。词组 a person's character 一个人的性格","ex":"She has a strong character.（她性格坚强。）"},{"id":1457,"day":24,"w":"claim","ph":"kleɪm","defs":[["vt.","声称，主张；要求，认领，索赔 n.权利；要求；主张",false]],"tier":"l","hint":"声称、要求。词组 claim to 声称","ex":"He claimed that he was innocent.（他声称自己是无辜的。）"},{"id":1458,"day":24,"w":"consider","ph":"kənˈsɪdər","defs":[["vt.","考虑，细想；认为，以为；关心，顾及",false]],"tier":"l","hint":"考虑、认为。词组 consider doing 考虑做、consider...as 认为","ex":"I'm considering changing my job.（我在考虑换工作。）"},{"id":1459,"day":24,"w":"deceive","ph":"dɪˈsiːv","defs":[["vt.","欺骗，蒙骗",true]],"tier":"f","ety":"de-（向下）+ ceive（拿，同 capt-）→ 把人骗到手 → 欺骗","mem":"de + ceive（=receive 拿）→ 用花招\"拿\"走你的信任 → 欺骗。画面：谎言骗走信任","ex":"deceive sb into · He deceived us into believing him.（他骗我们相信他。）","nua":"deceive sb into doing（骗某人做）、cheat（作弊/欺骗）；名词 deception"},{"id":1460,"day":24,"w":"difficult","ph":"ˈdɪfɪkəlt","defs":[["a.","困难的，艰难的；难应付的，难满足的",false]],"tier":"l","hint":"困难的。联想 easy 容易的（反义）","ex":"The question is too difficult for me.（这问题对我来说太难了。）"},{"id":1461,"day":24,"w":"equal","ph":"ˈiːkwəl","defs":[["a.","同等的，相等的；平等的；胜任的 n.（地位等）相同的人，匹敌者 vt.等于，比得上",false]],"tier":"l","hint":"平等的、等于。词组 be equal to 等于、equal rights 平等权利","ex":"All people are equal before the law.（法律面前人人平等。）"},{"id":1462,"day":24,"w":"fortunate","ph":"ˈfɔːrtʃənət","defs":[["a.","幸运的",true]],"tier":"f","ety":"fortune（运气）+ -ate → 有好运的 → 幸运","mem":"fortune + ate → 有好\"运气\"（fortune）的 → 幸运。画面：中彩票","ex":"be fortunate to · I was fortunate to pass the exam.（我很幸运通过了考试。）","nua":"fortunate（幸运的）、fortunately（幸运地）、unfortunately（不幸地）；反义 unlucky"},{"id":1463,"day":24,"w":"holiday","ph":"ˈhɑːlədeɪ","defs":[["n.","假日，假期，休假",false]],"tier":"l","hint":"假日。词组 on holiday 度假","ex":"We went to the beach on holiday.（我们假期去了海滩。）"},{"id":1464,"day":24,"w":"insult","ph":"ɪnˈsʌlt/ˈɪnsʌlt","defs":[["vt.","/n.侮辱，凌辱",false]],"tier":"l","hint":"侮辱。联想 insult 侮辱、offend 冒犯","ex":"He felt insulted by her words.（她的话让他感到受辱。）"},{"id":1465,"day":24,"w":"journey","ph":"ˈdʒɜːrni","defs":[["n.","旅行，旅程 vi.旅行",false]],"tier":"l","hint":"旅程。联想 travel 旅行、journey 旅程","ex":"The journey took three days.（这段旅程花了三天。）"},{"id":1466,"day":24,"w":"like","ph":"laɪk","defs":[["vt.","喜爱，喜欢；想要 prep.像……一样 a.同样的，相像的",false]],"tier":"l","hint":"喜欢、像。词组 look like 看起来像、feel like 想要","ex":"I like reading very much.（我很喜欢读书。）"},{"id":1467,"day":24,"w":"likely","ph":"ˈlaɪkli","defs":[["a.","可能的，有希望的 ad.大概，多半",false]],"tier":"l","hint":"可能的。词组 be likely to 很可能","ex":"It is likely to rain tonight.（今晚很可能下雨。）"},{"id":1468,"day":24,"w":"look","ph":"lʊk","defs":[["vi.","(at)看，注视 vi.好像，显得 n.脸色，外表",false]],"tier":"l","hint":"看、看起来。词组 look at 看、look for 寻找、look after 照顾","ex":"Look at the blackboard, please.（请看黑板。）"},{"id":1469,"day":24,"w":"loose","ph":"luːs","defs":[["a.","松的，宽的，松散的",false]],"tier":"l","hint":"松的。联想 tight 紧的（反义）、loosen 放松","ex":"The shirt is too loose for me.（这件衬衫对我来说太宽松了。）"},{"id":1470,"day":24,"w":"middle","ph":"ˈmɪdl","defs":[["n.","中间，当中 a.中间的，中部的",false]],"tier":"l","hint":"中间的。词组 in the middle of 在…中间","ex":"He stood in the middle of the room.（他站在房间中间。）"},{"id":1471,"day":24,"w":"million","ph":"ˈmɪljən","defs":[["n.","百万",false]],"tier":"l","hint":"百万。词组 millions of 数百万","ex":"The city has a population of five million.（这座城市有五百万人口。）"},{"id":1472,"day":24,"w":"miss","ph":"mɪs","defs":[["n.","小姐；[M-]……小姐 vt.未击中，没达到；未看到；没赶上；遗漏；惦念",false]],"tier":"l","hint":"错过、想念、小姐。词组 miss the bus 错过公交、miss sb 想念某人","ex":"I missed the train this morning.（我今早错过了火车。）"},{"id":1473,"day":24,"w":"motor","ph":"ˈmoʊtər","defs":[["n.","发动机，电动机，马达",false]],"tier":"l","hint":"发动机、马达。音译词。词组 motor car 汽车","ex":"The motor is running well.（发动机运转良好。）"},{"id":1474,"day":24,"w":"mouse","ph":"maʊs","defs":[["n.","鼠，耗子；鼠标",false]],"tier":"l","hint":"老鼠（复数 mice）、鼠标。联想 rat 大老鼠","ex":"The cat caught a mouse.（猫抓了只老鼠。）"},{"id":1475,"day":24,"w":"mystery","ph":"ˈmɪstri","defs":[["n.","神秘，神秘的事；神秘小说，侦探小说",false]],"tier":"l","hint":"神秘、谜。联想 mysterious 神秘的（形容词）","ex":"The disappearance of the ship is still a mystery.（船只失踪仍是个谜。）"},{"id":1476,"day":24,"w":"nervous","ph":"ˈnɜːrvəs","defs":[["a.","神经的；神经过敏的，紧张不安的",false]],"tier":"l","hint":"紧张的。词组 be nervous about 对…紧张","ex":"She is nervous about the exam.（她对考试很紧张。）"},{"id":1477,"day":24,"w":"noise","ph":"nɔɪz","defs":[["n.","噪音，吵嚷声，杂音",false]],"tier":"l","hint":"噪音。联想 noisy 吵闹的、noise 噪音","ex":"The noise kept me awake.（噪音让我睡不着。）"},{"id":1478,"day":24,"w":"out","ph":"aʊt","defs":[["ad.","向外，不在家；熄灭，完结；问世",false]],"tier":"l","hint":"出去、外面。词组 go out 出去、find out 查明","ex":"Let's go out for a walk.（我们出去散步吧。）"},{"id":1479,"day":24,"w":"pocket","ph":"ˈpɑːkɪt","defs":[["n.","衣袋 a.袖珍的",false]],"tier":"l","hint":"口袋。词组 pocket money 零花钱","ex":"He put the key in his pocket.（他把钥匙放进口袋。）"},{"id":1480,"day":24,"w":"police","ph":"pəˈliːs","defs":[["n.","警察，警察局",false]],"tier":"l","hint":"警察（总称）。词组 the police 警察、police station 警察局","ex":"The police caught the thief.（警察抓住了小偷。）"},{"id":1481,"day":24,"w":"poor","ph":"pɔːr","defs":[["a.","穷；可怜的；低劣的，不好的",false]],"tier":"l","hint":"穷的、可怜的。联想 rich 富的（反义）","ex":"They were too poor to buy food.（他们穷得买不起食物。）"},{"id":1482,"day":24,"w":"port","ph":"pɔːrt","defs":[["n.","港口",false]],"tier":"l","hint":"港口。联想 airport 机场、port 港口","ex":"The ship arrived at the port.（船到达了港口。）"},{"id":1483,"day":24,"w":"press","ph":"pres","defs":[["vt.","压，挤，按；催促 n.压，挤，按；报刊，出版社；压榨机，印刷机",false]],"tier":"l","hint":"按、压、新闻界。词组 press the button 按按钮","ex":"Press the button to start.（按按钮开始。）"},{"id":1484,"day":24,"w":"previous","ph":"ˈpriːviəs","defs":[["a.","先的，前的，以前的",false]],"tier":"l","hint":"先前的。词组 the previous day 前一天","ex":"He left the company the previous year.（他前一年离开了公司。）"},{"id":1485,"day":24,"w":"prove","ph":"pruːv","defs":[["vi.","/vt.证明，证实；结果是，表明是",false]],"tier":"l","hint":"证明。词组 prove to be 证明是","ex":"He proved his point with facts.（他用事实证明了自己的观点。）"},{"id":1486,"day":24,"w":"record","ph":"ˈrekərd","defs":[["n.","唱片；记录，记载 [rɪˈkɔːrd] vt.记录，记载；将（声音等）录下",false]],"tier":"l","hint":"记录、唱片、创纪录。词组 break a record 破纪录、keep a record 记录","ex":"She keeps a record of her daily life.（她记录自己的日常生活。）"},{"id":1487,"day":24,"w":"related","ph":"rɪˈleɪtɪd","defs":[["a.","与…有关的",true]],"tier":"f","ety":"relate（关联）+ -ed → 相关的","mem":"relate + ed → 有关联（relate）的 → 相关的。画面：一根线连着两头","ex":"be related to · Health is related to diet.（健康与饮食有关。）","nua":"be related to（与…相关）、relative（相对的、亲戚）；relate to（涉及）"},{"id":1488,"day":24,"w":"ride","ph":"raɪd","defs":[["vt.","/n.骑，乘",false]],"tier":"l","hint":"骑、乘。过去式 rode。词组 ride a bike 骑自行车","ex":"He rides his bike to school.（他骑自行车上学。）"},{"id":1489,"day":24,"w":"right","ph":"raɪt","defs":[["a.","正确的；合适的，恰当的；右边的；直角的 n.权利；右面 ad.正确地，笔直地；完全，正好；直接，马上",false]],"tier":"l","hint":"正确的、右边的、权利。词组 all right 好、right now 立刻","ex":"Your answer is right.（你的答案是对的。）"},{"id":1490,"day":24,"w":"rude","ph":"ruːd","defs":[["a.","粗鲁的，不礼貌的；粗糙的，粗陋的",false]],"tier":"l","hint":"粗鲁的。联想 polite 礼貌的（反义）","ex":"It's rude to interrupt others.（打断别人是不礼貌的。）"},{"id":1491,"day":24,"w":"scissors","ph":"ˈsɪzərz","defs":[["n.","剪刀",false]],"tier":"l","hint":"剪刀。词组 a pair of scissors 一把剪刀","ex":"She cut the paper with scissors.（她用剪刀剪纸。）"},{"id":1492,"day":24,"w":"shadow","ph":"ˈʃædoʊ","defs":[["n.","影子，阴影；暗处，阴暗",false]],"tier":"l","hint":"影子。联想 shadow 影子、shade 阴影","ex":"The tree casts a shadow on the ground.（树在地上投下影子。）"},{"id":1493,"day":24,"w":"shoulder","ph":"ˈʃoʊldər","defs":[["n.","肩，肩膀",false]],"tier":"l","hint":"肩膀。词组 shoulder to shoulder 肩并肩","ex":"He carried the bag on his shoulder.（他把包扛在肩上。）"},{"id":1494,"day":24,"w":"sister","ph":"ˈsɪstər","defs":[["n.","姐妹",false]],"tier":"l","hint":"姐妹。联想 brother 兄弟","ex":"My sister is a teacher.（我姐姐是老师。）"},{"id":1495,"day":24,"w":"space","ph":"speɪs","defs":[["n.","空地，场地；太空，宇宙；空间，距离",false]],"tier":"l","hint":"空间、太空。词组 in space 在太空、make space 腾出空间","ex":"There is no space for more books.（没有空间放更多书了。）"},{"id":1496,"day":24,"w":"storm","ph":"stɔːrm","defs":[["n.","暴风雨",false]],"tier":"l","hint":"暴风雨。联想 storm 暴风雨、thunderstorm 雷雨","ex":"The storm lasted all night.（暴风雨持续了一整夜。）"},{"id":1497,"day":24,"w":"sugar","ph":"ˈʃʊɡər","defs":[["n.","糖",false]],"tier":"l","hint":"糖。联想 salt 盐、sugar 糖","ex":"He put some sugar in his coffee.（他在咖啡里放了糖。）"},{"id":1498,"day":24,"w":"suit","ph":"suːt","defs":[["vt.","适合，合适；满足，中……的意 n.一套衣服/西服；诉讼",false]],"tier":"l","hint":"西装、适合。词组 suit sb 适合某人、a suit 一套西装","ex":"This color suits you well.（这个颜色很适合你。）"},{"id":1499,"day":24,"w":"think","ph":"θɪŋk","defs":[["vt.","以为，认为；想要，打算 vi.想，思索",false]],"tier":"l","hint":"想、认为。过去式 thought。词组 think of 想到、think about 考虑","ex":"I think you are right.（我认为你是对的。）"},{"id":1500,"day":24,"w":"title","ph":"ˈtaɪtl","defs":[["n.","书名，题目；头衔，称号",false]],"tier":"l","hint":"标题、头衔。词组 the title of 标题","ex":"What is the title of the book?（这本书的标题是什么？）"},{"id":1501,"day":24,"w":"tree","ph":"triː","defs":[["n.","树",false]],"tier":"l","hint":"树。词组 plant trees 种树","ex":"There are many trees in the park.（公园里有很多树。）"},{"id":1502,"day":24,"w":"until","ph":"ənˈtɪl","defs":[["prep.","/conj.到……为止，在……以前；直到……",false]],"tier":"l","hint":"直到。词组 not...until 直到…才","ex":"He waited until midnight.（他一直等到半夜。）"},{"id":1503,"day":24,"w":"week","ph":"wiːk","defs":[["n.","星期，周",false]],"tier":"l","hint":"周。词组 this week 本周、next week 下周","ex":"I will visit you next week.（我下周去看你。）"},{"id":1504,"day":24,"w":"without","ph":"wɪˈðaʊt","defs":[["prep.","没有，毫无 ad.在外面",false]],"tier":"l","hint":"没有。词组 without doing 没有做","ex":"He left without saying goodbye.（他没说再见就走了。）"},{"id":1505,"day":25,"w":"advance","ph":"ədˈvæns","defs":[["v.","/n. 推进，前进；提升",true]],"tier":"f","ety":"拉丁 abante（向前）→ 前进","mem":"ad + vance（=vant 前）→ 朝\"前\" → 前进。画面：冲锋向前","ex":"in advance · Please book the tickets in advance.（请提前订票。）","nua":"in advance（提前）、advance（前进、提升）、advanced（先进的）；反义 retreat"},{"id":1506,"day":25,"w":"allow","ph":"əˈlaʊ","defs":[["vt.","允许，准许；给予 vi. (for)考虑到",false]],"tier":"l","hint":"允许。词组 allow sb to do 允许某人做","ex":"The teacher allowed us to leave early.（老师允许我们早走。）"},{"id":1507,"day":25,"w":"ancient","ph":"ˈeɪnʃənt","defs":[["a.","古代的，古老的",false]],"tier":"l","hint":"古代的。联想 modern 现代的（反义）","ex":"We visited an ancient temple.（我们参观了一座古庙。）"},{"id":1508,"day":25,"w":"annoy","ph":"əˈnɔɪ","defs":[["vt.","使烦恼，使生气",true]],"tier":"f","ety":"古法语 anoier（烦扰）","mem":"谐音\"安闹\"→ 心里\"闹\"得不安 → 烦恼。画面：蚊子嗡嗡烦人","ex":"annoy sb · The noise annoyed me.（噪音让我很烦。）","nua":"be annoyed with（对人生气）、be annoyed at（对事生气）；annoying（烦人的）"},{"id":1509,"day":25,"w":"ask","ph":"æsk","defs":[["vt.","问，询问；请求；邀请，约请",false]],"tier":"l","hint":"问、请求。词组 ask for 请求、ask sb to do 请某人做","ex":"May I ask you a question?（我能问你个问题吗？）"},{"id":1510,"day":25,"w":"attract","ph":"əˈtrækt","defs":[["vt.","吸引，招引，引诱",false]],"tier":"l","hint":"吸引。词组 attract attention 吸引注意","ex":"The beautiful scenery attracts many tourists.（美景吸引了很多游客。）"},{"id":1511,"day":25,"w":"attractive","ph":"əˈtræktɪv","defs":[["a.","有吸引力的；有魅力的，动人的",false]],"tier":"l","hint":"attract（吸引）+ -ive → 有吸引力的","ex":"The city is attractive to young people.（这座城市对年轻人有吸引力。）"},{"id":1512,"day":25,"w":"become","ph":"bɪˈkʌm","defs":[["vi.","成为，变成",false]],"tier":"l","hint":"变成。过去式 became。词组 become a doctor 成为医生","ex":"She wants to become a doctor.（她想成为医生。）"},{"id":1513,"day":25,"w":"blow","ph":"bloʊ","defs":[["vi.","吹，吹气，打气；爆炸，爆裂 n.打，殴打，打击",false]],"tier":"l","hint":"吹。过去式 blew。词组 blow away 吹走","ex":"The wind blew strongly last night.（昨晚风刮得很猛。）"},{"id":1514,"day":25,"w":"bone","ph":"boʊn","defs":[["n.","骨，骨骼",false]],"tier":"l","hint":"骨头。联想 bone 骨头、skeleton 骨架","ex":"The dog is chewing a bone.（狗在啃骨头。）"},{"id":1515,"day":25,"w":"building","ph":"ˈbɪldɪŋ","defs":[["n.","建筑物，大楼",false]],"tier":"l","hint":"build（建造）+ -ing → 建筑物","ex":"There are many tall buildings in the city.（城市里有很多高楼。）"},{"id":1516,"day":25,"w":"come","ph":"kʌm","defs":[["vi.","来，来到；出现，产生",false]],"tier":"l","hint":"来。过去式 came。词组 come true 实现、come from 来自","ex":"Please come to my house tomorrow.（请明天来我家。）"},{"id":1517,"day":25,"w":"cotton","ph":"ˈkɑːtn","defs":[["n.","棉花；棉纱，棉织品",false]],"tier":"l","hint":"棉花。词组 cotton clothes 棉质衣服","ex":"This shirt is made of cotton.（这件衬衫是棉的。）"},{"id":1518,"day":25,"w":"design","ph":"dɪˈzaɪn","defs":[["vt.","计划，设计，制图 n.图纸；图案，花样；设计",false]],"tier":"l","hint":"设计。词组 design a building 设计建筑","ex":"She designed a beautiful dress.（她设计了条漂亮的裙子。）"},{"id":1519,"day":25,"w":"destruction","ph":"dɪˈstrʌkʃn","defs":[["n.","破坏，毁灭",false]],"tier":"l","hint":"destroy（破坏）+ -tion → 破坏","ex":"The war caused great destruction.（战争造成了巨大破坏。）"},{"id":1520,"day":25,"w":"dull","ph":"dʌl","defs":[["a.","钝的；愚笨的，迟钝的；阴暗的，沉闷的；暗淡的",false]],"tier":"l","hint":"枯燥的、钝的。联想 boring 枯燥的（同义）","ex":"The lecture was rather dull.（讲座相当枯燥。）"},{"id":1521,"day":25,"w":"experience","ph":"ɪkˈspɪriəns","defs":[["n.","经验，感受，体验；经历 vt.体验，经历",false]],"tier":"l","hint":"经验、经历。词组 work experience 工作经验","ex":"He has much teaching experience.（他有很多教学经验。）"},{"id":1522,"day":25,"w":"father","ph":"ˈfɑːðər","defs":[["n.","父亲，创始人；[F-]神父",false]],"tier":"l","hint":"父亲。联想 mother 母亲、parent 父母","ex":"My father works in a factory.（我父亲在工厂工作。）"},{"id":1523,"day":25,"w":"fear","ph":"fɪr","defs":[["n.","/vi./vt.恐惧，害怕，担心",false]],"tier":"l","hint":"害怕、恐惧。词组 in fear of 害怕、for fear of 以免","ex":"She has a fear of dogs.（她怕狗。）"},{"id":1524,"day":25,"w":"guess","ph":"ɡes","defs":[["vi.","/vt./n.推测，猜测",false]],"tier":"l","hint":"猜。词组 guess the meaning 猜意思","ex":"Can you guess my age?（你能猜我的年龄吗？）"},{"id":1525,"day":25,"w":"guilty","ph":"ˈɡɪlti","defs":[["a.","有罪的，犯罪的；自觉有罪的，负疚的",false]],"tier":"l","hint":"有罪的、内疚的。词组 be guilty of 犯…罪","ex":"He was found guilty of the crime.（他被判有罪。）"},{"id":1526,"day":25,"w":"horn","ph":"hɔːrn","defs":[["n.","角；角质；角状物，角制品；号，喇叭",false]],"tier":"l","hint":"角、喇叭。联想 horn 角、喇叭","ex":"The car sounded its horn.（汽车按了喇叭。）"},{"id":1527,"day":25,"w":"horse","ph":"hɔːrs","defs":[["n.","马",false]],"tier":"l","hint":"马。词组 ride a horse 骑马","ex":"He rides a horse every weekend.（他每周末骑马。）"},{"id":1528,"day":25,"w":"immediately","ph":"ɪˈmiːdiətli","defs":[["ad.","立即，马上",false]],"tier":"l","hint":"immediate（立即）+ -ly → 立即","ex":"Please come here immediately.（请立即过来。）"},{"id":1529,"day":25,"w":"introduction","ph":"ˌɪntrəˈdʌkʃn","defs":[["n.","介绍，引进，传入；引论，导言，绪论；入门",false]],"tier":"l","hint":"introduce（介绍）+ -tion → 介绍、引言","ex":"The book has a long introduction.（这本书有很长的引言。）"},{"id":1530,"day":25,"w":"layer","ph":"ˈler","defs":[["n.","层",false]],"tier":"l","hint":"层。词组 a layer of 一层","ex":"There is a layer of dust on the desk.（桌上有一层灰。）"},{"id":1531,"day":25,"w":"left","ph":"left","defs":[["a.","/n.左（的），左面（的），左边(的） ad.往左，向左",false]],"tier":"l","hint":"左边的、leave 的过去式。词组 on the left 在左边","ex":"The bank is on the left of the street.（银行在街左边。）"},{"id":1532,"day":25,"w":"liquid","ph":"ˈlɪkwɪd","defs":[["n.","液体 a.液体的，液态的；流动的；可兑换成现金的",false]],"tier":"l","hint":"液体。联想 solid 固体、gas 气体、liquid 液体","ex":"Water is a liquid.（水是液体。）"},{"id":1533,"day":25,"w":"memory","ph":"ˈmeməri","defs":[["n.","记忆力，记忆；回忆；内存",false]],"tier":"l","hint":"记忆。词组 in memory of 纪念、good memory 好记性","ex":"He has a good memory.（他记性很好。）"},{"id":1534,"day":25,"w":"military","ph":"ˈmɪləteri","defs":[["a.","军队的，军事的，军用的",false]],"tier":"l","hint":"军事的。词组 military training 军训","ex":"He served in the military for two years.（他服了两年兵役。）"},{"id":1535,"day":25,"w":"neck","ph":"nek","defs":[["n.","颈，脖子",false]],"tier":"l","hint":"脖子。联想 head 头、neck 脖子","ex":"She wore a scarf around her neck.（她脖子上围着围巾。）"},{"id":1536,"day":25,"w":"nurse","ph":"nɜːrs","defs":[["n.","护士",false]],"tier":"l","hint":"护士。联想 doctor 医生、nurse 护士","ex":"The nurse took care of the patient.（护士照顾病人。）"},{"id":1537,"day":25,"w":"only","ph":"ˈoʊnli","defs":[["ad.","只，仅仅 a.唯一的",false]],"tier":"l","hint":"仅仅、唯一的。词组 not only...but also 不但…而且","ex":"He is the only child in the family.（他是家里的独生子。）"},{"id":1538,"day":25,"w":"open","ph":"ˈoʊpən","defs":[["vt.","打开；开始，开张，开放 vi.开，打开；开始，开放 a.开着的；开放的；营业的；开阔的，空旷的",false]],"tier":"l","hint":"打开、开放的。词组 open the door 开门","ex":"Please open the window.（请打开窗户。）"},{"id":1539,"day":25,"w":"opportunity","ph":"ˌɑːpərˈtuːnəti","defs":[["n.","机会",false]],"tier":"l","hint":"机会。词组 seize the opportunity 抓住机会","ex":"This is a good opportunity to learn.（这是学习的好机会。）"},{"id":1540,"day":25,"w":"particular","ph":"pərˈtɪkjələr","defs":[["a.","特别的，特殊的；个别的 n. (pl.)细节，详情",false]],"tier":"l","hint":"特别的、特定的。词组 in particular 尤其","ex":"I like music, in particular pop music.（我喜欢音乐，尤其是流行音乐。）"},{"id":1541,"day":25,"w":"popular","ph":"ˈpɑːpjələr","defs":[["a.","广受欢迎的，有名的；通俗的，流行的，大众的",false]],"tier":"l","hint":"受欢迎的、流行的。词组 be popular with 受…欢迎","ex":"The singer is popular with young people.（这位歌手很受年轻人欢迎。）"},{"id":1542,"day":25,"w":"reaction","ph":"riˈækʃn","defs":[["n.","反应；反作用（力）",false]],"tier":"l","hint":"react（反应）+ -ion → 反应。词组 reaction to 对…的反应","ex":"What was his reaction to the news?（他对这消息的反应如何？）"},{"id":1543,"day":25,"w":"ruin","ph":"ˈruːɪn","defs":[["vt.","毁坏，破坏 n.毁灭，崩溃；(pl.)废墟，遗址",false]],"tier":"l","hint":"毁坏、废墟。词组 in ruins 成为废墟","ex":"The storm ruined the crops.（暴风雨毁了庄稼。）"},{"id":1544,"day":25,"w":"scale","ph":"skeɪl","defs":[["n.","标度，刻度；(pl.)天平，天平盘；标尺，比例尺",false]],"tier":"l","hint":"规模、刻度、秤。词组 on a large scale 大规模","ex":"The company operates on a large scale.（这家公司大规模经营。）"},{"id":1545,"day":25,"w":"sea","ph":"siː","defs":[["n.","海，海洋",false]],"tier":"l","hint":"海。词组 by sea 乘船、at sea 在海上","ex":"We swam in the sea last summer.（我们去年夏天在海里游泳。）"},{"id":1546,"day":25,"w":"servant","ph":"ˈsɜːrvənt","defs":[["n.","仆人",false]],"tier":"l","hint":"serve（服务）+ -ant（人）→ 仆人","ex":"The servant cleaned the house every day.（仆人每天打扫房子。）"},{"id":1547,"day":25,"w":"silence","ph":"ˈsaɪləns","defs":[["n.","寂静，沉默 vt.使寂静，使沉默",false]],"tier":"l","hint":"silent（沉默）的名词 → 沉默、寂静。词组 in silence 沉默地","ex":"They listened in silence.（他们静静地听着。）"},{"id":1548,"day":25,"w":"skillful","ph":"ˈskɪlfl","defs":[["a.","灵巧的，娴熟的",false]],"tier":"l","hint":"skill（技能）+ -ful → 熟练的","ex":"He is skillful at drawing.（他擅长画画。）"},{"id":1549,"day":25,"w":"slippery","ph":"ˈslɪpəri","defs":[["a.","滑的，滑溜的；狡猾的",false]],"tier":"l","hint":"slip（滑）+ -ery → 滑的","ex":"The road is slippery after the rain.（雨后路很滑。）"},{"id":1550,"day":25,"w":"soldier","ph":"ˈsoʊldʒər","defs":[["n.","士兵，军人",false]],"tier":"l","hint":"士兵。联想 army 军队、soldier 士兵","ex":"The soldier stood guard at the gate.（士兵在门口站岗。）"},{"id":1551,"day":25,"w":"song","ph":"sɔːŋ","defs":[["n.","歌声；歌曲",false]],"tier":"l","hint":"歌。词组 sing a song 唱歌","ex":"She sang a beautiful song.（她唱了首动听的歌。）"},{"id":1552,"day":25,"w":"soul","ph":"soʊl","defs":[["n.","灵魂，心灵；人；精华；中心人物",false]],"tier":"l","hint":"灵魂、心灵。词组 heart and soul 全心全意","ex":"He put his heart and soul into the work.（他全心全意投入工作。）"},{"id":1553,"day":25,"w":"specific","ph":"spəˈsɪfɪk","defs":[["a.","具体的，明确的；特有的，特定的",false]],"tier":"l","hint":"具体的、特定的。联想 general 一般的（反义）","ex":"Please give me a specific answer.（请给我具体的回答。）"},{"id":1554,"day":25,"w":"stay","ph":"steɪ","defs":[["vi.","/n.停留，逗留，作客",false]],"tier":"l","hint":"停留、保持。词组 stay at home 待在家、stay up 熬夜","ex":"He stayed at home all day.（他整天待在家里。）"},{"id":1555,"day":25,"w":"step","ph":"step","defs":[["n.","脚步，脚步声；台阶，梯级；步骤，措施 vi.举步，走",false]],"tier":"l","hint":"步骤、脚步。词组 step by step 逐步、take steps 采取措施","ex":"We should learn step by step.（我们应该循序渐进地学习。）"},{"id":1556,"day":25,"w":"straight","ph":"streɪt","defs":[["a.","直的，平直的；正直的；直率的 ad.直接，一直；正直地；直率地",false]],"tier":"l","hint":"直的、直接。词组 go straight 直走","ex":"Go straight and turn left.（直走然后左转。）"},{"id":1557,"day":25,"w":"symbol","ph":"ˈsɪmbl","defs":[["n.","象征，符号，标志",false]],"tier":"l","hint":"象征、符号。词组 a symbol of …的象征","ex":"The dove is a symbol of peace.（鸽子是和平的象征。）"},{"id":1558,"day":25,"w":"together","ph":"təˈɡeðər","defs":[["ad.","共同地，在一起；相互，彼此；一致地",false]],"tier":"l","hint":"一起。词组 together with 和…一起、get together 聚在一起","ex":"Let's work together.（我们一起努力吧。）"},{"id":1559,"day":25,"w":"tune","ph":"tuːn","defs":[["n.","调子，曲调；和谐，协调 vt.为……调音；调整，调节",false]],"tier":"l","hint":"曲调。词组 in tune 合调、out of tune 走调","ex":"She hummed a happy tune.（她哼着欢快的曲调。）"},{"id":1560,"day":25,"w":"typical","ph":"ˈtɪpɪkl","defs":[["a.","典型的，有代表性的；独有的，独特的",false]],"tier":"l","hint":"典型的。词组 be typical of 是…的典型","ex":"This is a typical example.（这是个典型的例子。）"},{"id":1561,"day":25,"w":"unless","ph":"ənˈles","defs":[["conj.","如果不，除非",false]],"tier":"l","hint":"除非。联想 if...not 如果不","ex":"You will fail unless you work hard.（除非你努力，否则会失败。）"},{"id":1562,"day":25,"w":"water","ph":"ˈwɔːtər","defs":[["n.","水    vt.浇，灌",false]],"tier":"l","hint":"水、浇水。词组 a glass of water 一杯水","ex":"Please give me some water.（请给我点水。）"},{"id":1563,"day":25,"w":"wedding","ph":"ˈwedɪŋ","defs":[["n.","婚礼",false]],"tier":"l","hint":"婚礼。词组 wedding ceremony 婚礼","ex":"They held a wedding last week.（他们上周举行了婚礼。）"},{"id":1564,"day":25,"w":"whenever","ph":"wenˈevər","defs":[["conj.","无论何时，随时；每当",false]],"tier":"l","hint":"when（何时）+ ever → 无论何时","ex":"Come to see me whenever you like.（你想什么时候来看我都行。）"},{"id":1565,"day":25,"w":"winter","ph":"ˈwɪntər","defs":[["n.","冬天",false]],"tier":"l","hint":"冬天。联想 spring 春、summer 夏、autumn 秋、winter 冬","ex":"It snows a lot in winter here.（这里冬天下很多雪。）"},{"id":1566,"day":25,"w":"with","ph":"wɪð","defs":[["prep.","跟……一起；用，以，籍；具有，带有；关于， 就……而言；因，由于；随着；虽然，尽管",false]],"tier":"l","hint":"和…一起、用。词组 with the help of 在…帮助下","ex":"I go to school with my friend.（我和朋友一起上学。）"},{"id":1567,"day":25,"w":"woman","ph":"ˈwʊmən","defs":[["n.","(pl. women）妇女，女人",false]],"tier":"l","hint":"女人（复数 women）。联想 man 男人","ex":"The woman is a doctor.（这位女士是医生。）"},{"id":1568,"day":26,"w":"advice","ph":"ədˈvaɪs","defs":[["n.","忠告，意见",false]],"tier":"l","hint":"建议（名词）。联想 advise 建议（动词）。词组 a piece of advice 一条建议","ex":"He gave me some good advice.（他给了我一些好建议。）"},{"id":1569,"day":26,"w":"against","ph":"əˈɡenst","defs":[["prep.","对(着)，逆；反对；靠近；和……对比",false]],"tier":"l","hint":"反对、靠着。词组 be against 反对、against the wall 靠着墙","ex":"He leaned against the wall.（他靠在墙上。）"},{"id":1570,"day":26,"w":"announce","ph":"əˈnaʊns","defs":[["vt.","宣布，通告",false]],"tier":"l","hint":"宣布。词组 announce that 宣布","ex":"The school announced the exam results.（学校公布了考试成绩。）"},{"id":1571,"day":26,"w":"anxious","ph":"ˈæŋkʃəs","defs":[["a.","担心的，焦虑的；渴望的",true]],"tier":"f","ety":"拉丁 anxius（焦虑的）","mem":"anx（=anxiety 焦虑）+ ious → 焦虑的。联想 anxiety。画面：眉头紧锁","ex":"be anxious about · She is anxious about her health.（她担心自己的健康。）","nua":"be anxious about（担心）、be anxious to do（渴望做）；名词 anxiety"},{"id":1572,"day":26,"w":"any","ph":"ˈeni","defs":[["a.","任何的；[否定、疑问、条件句中]什么，一些 pron.无论哪个，无论哪些，任一",false]],"tier":"l","hint":"任何。词组 any more 不再、in any case 无论如何","ex":"Do you have any questions?（你有问题吗？）"},{"id":1573,"day":26,"w":"apartment","ph":"əˈpɑːrtmənt","defs":[["n.","一套房间",false]],"tier":"l","hint":"公寓。联想 flat 公寓（英）、apartment 公寓（美）","ex":"They live in an apartment in the city.（他们住在城里的公寓。）"},{"id":1574,"day":26,"w":"bottom","ph":"ˈbɑːtəm","defs":[["n.","底，底部",false]],"tier":"l","hint":"底部。联想 top 顶部（反义）","ex":"The keys are at the bottom of the bag.（钥匙在包底。）"},{"id":1575,"day":26,"w":"ceiling","ph":"ˈsiːlɪŋ","defs":[["n.","天花板",false]],"tier":"l","hint":"天花板。联想 floor 地板、ceiling 天花板","ex":"The lamp hangs from the ceiling.（灯挂在天花板上。）"},{"id":1576,"day":26,"w":"chemical","ph":"ˈkemɪkl","defs":[["a.","化学的 n.化学制品/产品/物质/成分",false]],"tier":"l","hint":"chemistry（化学）的形容词 → 化学的。词组 chemical reaction 化学反应","ex":"The factory uses many chemicals.（这家工厂用很多化学品。）"},{"id":1577,"day":26,"w":"criminal","ph":"ˈkrɪmɪnl","defs":[["a.","犯罪的，刑事的 n.罪犯，刑事犯",false]],"tier":"l","hint":"crime（犯罪）+ -al → 罪犯、犯罪的","ex":"The criminal was caught by the police.（罪犯被警察抓住了。）"},{"id":1578,"day":26,"w":"description","ph":"dɪˈskrɪpʃn","defs":[["n.","描写，形容",true]],"tier":"f","ety":"describe（描写）+ -tion → 描写","mem":"describe + tion → 描写（describe）的名词。画面：用文字画像","ex":"a detailed description · He gave a detailed description of the man.（他详细描述了那个人。）","nua":"describe（动词）→ description（名词，注意 e→p）；describe sth as（把…描述为）"},{"id":1579,"day":26,"w":"divide","ph":"dɪˈvaɪd","defs":[["vt.","分，划分，隔开；分配，分享，分担；隔开；除",false]],"tier":"l","hint":"划分、除。词组 divide...into 分成","ex":"Divide the class into four groups.（把班级分成四组。）"},{"id":1580,"day":26,"w":"drawer","ph":"drɔːr","defs":[["n.","抽屉",false]],"tier":"l","hint":"draw（拉）+ -er → 抽屉（拉出来的）","ex":"He put the papers in the drawer.（他把文件放进抽屉。）"},{"id":1581,"day":26,"w":"dry","ph":"draɪ","defs":[["a.","干的，干旱的；干渴的；干巴巴的，枯燥的 vt.使干燥，晒干",false]],"tier":"l","hint":"干的。联想 wet 湿的（反义）","ex":"The clothes are dry now.（衣服现在干了。）"},{"id":1582,"day":26,"w":"enter","ph":"ˈentər","defs":[["vi.","/vt.走进，进入；参加，加入；写入，登录",false]],"tier":"l","hint":"进入。联想 entrance 入口（名词）","ex":"Please knock before you enter.（进来前请敲门。）"},{"id":1583,"day":26,"w":"expensive","ph":"ɪkˈspensɪv","defs":[["a.","花钱多的，高价的，昂贵的",false]],"tier":"l","hint":"昂贵的。联想 cheap 便宜的（反义）","ex":"The car is too expensive for me.（这车对我来说太贵了。）"},{"id":1584,"day":26,"w":"fast","ph":"fæst","defs":[["a.","/ad.快，迅速；紧，牢",false]],"tier":"l","hint":"快的。联想 slow 慢的（反义）","ex":"He runs very fast.（他跑得很快。）"},{"id":1585,"day":26,"w":"flesh","ph":"fleʃ","defs":[["n.","肉，肉体，肌体",false]],"tier":"l","hint":"肉、肉体。联想 flesh 肉（身体）、meat 肉（食物）","ex":"The wound cut into the flesh.（伤口切到了肉。）"},{"id":1586,"day":26,"w":"flight","ph":"flaɪt","defs":[["n.","飞行，飞翔；航班；逃跑；一段楼梯",false]],"tier":"l","hint":"fly（飞）的名词 → 飞行、航班。词组 book a flight 订航班","ex":"The flight to Beijing takes two hours.（飞往北京的航班要两小时。）"},{"id":1587,"day":26,"w":"freedom","ph":"ˈfriːdəm","defs":[["n.","自由，自主",false]],"tier":"l","hint":"free（自由）+ -dom → 自由。词组 freedom of speech 言论自由","ex":"People fought for freedom.（人们为自由而战。）"},{"id":1588,"day":26,"w":"freeze","ph":"friːz","defs":[["vi.","/vt.（使）结冰，（使）凝固",false]],"tier":"l","hint":"结冰、冻结。过去式 froze。词组 freeze to death 冻死","ex":"The lake froze in winter.（湖在冬天结冰了。）"},{"id":1589,"day":26,"w":"funeral","ph":"ˈfjuːnərəl","defs":[["n.","葬礼，丧葬",false]],"tier":"l","hint":"葬礼。联想 bury 埋葬、funeral 葬礼","ex":"Many people attended the funeral.（很多人参加了葬礼。）"},{"id":1590,"day":26,"w":"hot","ph":"hɑːt","defs":[["a.","热的；辣的；热烈的，激烈的",false]],"tier":"l","hint":"热的。联想 cold 冷的（反义）","ex":"The weather is hot in summer.（夏天天气热。）"},{"id":1591,"day":26,"w":"interesting","ph":"ˈɪntrəstɪŋ","defs":[["a.","有趣的，引人入胜的",false]],"tier":"l","hint":"interest（兴趣）+ -ing → 有趣的","ex":"The book is very interesting.（这本书很有趣。）"},{"id":1592,"day":26,"w":"legal","ph":"ˈliːɡl","defs":[["a.","合法的，正当的；法律的",false]],"tier":"l","hint":"合法的、法律的。联想 illegal 非法的（反义）","ex":"He took legal action against the company.（他对公司提起了法律诉讼。）"},{"id":1593,"day":26,"w":"line","ph":"laɪn","defs":[["n.","线条；界线；行，行列；航线，交通线，通信线 vi.排队，排列",false]],"tier":"l","hint":"线、行。词组 in line 排队、stand in line 排队","ex":"Please stand in line.（请排队。）"},{"id":1594,"day":26,"w":"lot","ph":"lɑːt","defs":[["n.","许多；签，抽签",false]],"tier":"l","hint":"许多。词组 a lot of 许多、lots of 许多","ex":"There are a lot of books here.（这里有很多书。）"},{"id":1595,"day":26,"w":"measurement","ph":"ˈmeʒərmənt","defs":[["n.","测量，度量；尺寸，大小",false]],"tier":"l","hint":"measure（测量）+ -ment → 测量、尺寸","ex":"The measurement of the room is 4 by 5 meters.（房间尺寸是 4 乘 5 米。）"},{"id":1596,"day":26,"w":"month","ph":"mʌnθ","defs":[["n.","月，月份",false]],"tier":"l","hint":"月。词组 this month 本月、next month 下月","ex":"I will go to Beijing next month.（我下个月去北京。）"},{"id":1597,"day":26,"w":"nowhere","ph":"ˈnoʊwer","defs":[["ad.","哪儿也不，什么地方都没有",false]],"tier":"l","hint":"no（无）+ where（地方）→ 无处","ex":"There is nowhere to sit in the room.（房间里没地方坐。）"},{"id":1598,"day":26,"w":"often","ph":"ˈɔːfn","defs":[["ad.","常常，屡次",false]],"tier":"l","hint":"经常。词组 how often 多久一次","ex":"I often go to the library.（我经常去图书馆。）"},{"id":1599,"day":26,"w":"ordinary","ph":"ˈɔːrdneri","defs":[["a.","平常，普通；平凡，平淡",false]],"tier":"l","hint":"普通的。联想 special 特别的（反义）","ex":"He is an ordinary worker.（他是个普通工人。）"},{"id":1600,"day":26,"w":"organization","ph":"ˌɔːrɡənəˈzeɪʃn","defs":[["n.","组织，体制；团体，机构",false]],"tier":"l","hint":"organize（组织）+ -ation → 组织","ex":"She works for an international organization.（她在一个国际组织工作。）"},{"id":1601,"day":26,"w":"other","ph":"ˈʌðər","defs":[["a.","另外的，别的；其他的 pron.别的东西，别人",false]],"tier":"l","hint":"其他的。词组 each other 互相、the other 另一个","ex":"They help each other.（他们互相帮助。）"},{"id":1602,"day":26,"w":"picture","ph":"ˈpɪktʃər","defs":[["n.","画，图片；照片；电影 vt.想象，描述",false]],"tier":"l","hint":"图片、照片。词组 take a picture 拍照","ex":"There is a picture on the wall.（墙上有一幅画。）"},{"id":1603,"day":26,"w":"piece","ph":"piːs","defs":[["n.","(一)件，(一)片，(一)篇；碎块，片断 vt.拼合，修补",false]],"tier":"l","hint":"片、块。词组 a piece of 一块/一张","ex":"Please give me a piece of paper.（请给我一张纸。）"},{"id":1604,"day":26,"w":"pole","ph":"poʊl","defs":[["n.","柱，杆；地极，磁极",false]],"tier":"l","hint":"杆、极。词组 the North Pole 北极","ex":"The flag is on a tall pole.（旗子在高高的旗杆上。）"},{"id":1605,"day":26,"w":"possible","ph":"ˈpɑːsəbl","defs":[["a.","可能的，做得到的",false]],"tier":"l","hint":"可能的。词组 as...as possible 尽可能","ex":"Come as early as possible.（尽可能早点来。）"},{"id":1606,"day":26,"w":"practice/-se","ph":"ˈpræktɪs","defs":[["n.","实践，实施；练习，实习；业务，开业 vi./vt.实践，实行；练习，实习；开业，从事",false]],"tier":"l","hint":"练习、实践。词组 practice doing 练习做、in practice 实际上","ex":"Practice makes perfect.（熟能生巧。）"},{"id":1607,"day":26,"w":"prefer","ph":"prɪˈfɜːr","defs":[["vt.","更喜欢，宁愿",false]],"tier":"l","hint":"更喜欢。词组 prefer A to B 比起 B 更喜欢 A、prefer to do 宁愿做","ex":"I prefer tea to coffee.（比起咖啡我更喜欢茶。）"},{"id":1608,"day":26,"w":"proof","ph":"pruːf","defs":[["n.","证明，证据",false]],"tier":"l","hint":"prove（证明）的名词 → 证据。词组 proof of …的证据","ex":"Do you have any proof?（你有什么证据吗？）"},{"id":1609,"day":26,"w":"sensible","ph":"ˈsensəbl","defs":[["a.","明理的，明智的",false]],"tier":"l","hint":"sense（理智）+ -ible → 明智的","ex":"That is a sensible choice.（那是个明智的选择。）"},{"id":1610,"day":26,"w":"sheet","ph":"ʃiːt","defs":[["n.","被单；（一）张，（一）片",false]],"tier":"l","hint":"床单、一张。词组 a sheet of paper 一张纸","ex":"Please write on this sheet of paper.（请写在这张纸上。）"},{"id":1611,"day":26,"w":"shell","ph":"ʃel","defs":[["n.","壳，贝壳；炮弹",false]],"tier":"l","hint":"壳、贝壳。联想 shell 贝壳、seashell 海贝","ex":"The child collected shells on the beach.（孩子在海滩捡贝壳。）"},{"id":1612,"day":26,"w":"single","ph":"ˈsɪŋɡl","defs":[["a.","单人的；单身的；单一的，单个的",false]],"tier":"l","hint":"单一的、单身的。联想 double 双的（反义）","ex":"He is still single.（他还单身。）"},{"id":1613,"day":26,"w":"spoon","ph":"spuːn","defs":[["n.","勺，汤勺",false]],"tier":"l","hint":"勺子。联想 fork 叉、knife 刀、spoon 勺","ex":"He ate soup with a spoon.（他用勺子喝汤。）"},{"id":1614,"day":26,"w":"stamp","ph":"stæmp","defs":[["n.","邮票；戳记；图章；踩脚，重踩 vt.盖章，盖印；跺脚，践踏",false]],"tier":"l","hint":"邮票、跺脚。词组 put a stamp on 贴邮票","ex":"She put a stamp on the letter.（她在信上贴了邮票。）"},{"id":1615,"day":26,"w":"state","ph":"steɪt","defs":[["n.","国家，州；情况，状态 vt.声明，陈述",false]],"tier":"l","hint":"状态、州、陈述。词组 in a good state 状态好","ex":"The house is in a good state.（房子状态很好。）"},{"id":1616,"day":26,"w":"stone","ph":"stoʊn","defs":[["n.","石，石料",false]],"tier":"l","hint":"石头。联想 rock 岩石、stone 石头","ex":"He threw a stone into the river.（他往河里扔了块石头。）"},{"id":1617,"day":26,"w":"stream","ph":"striːm","defs":[["n.","小河，溪流 vi.流，流出",false]],"tier":"l","hint":"小溪、流。联想 river 河（大）、stream 小溪","ex":"A small stream runs through the village.（一条小溪流经村庄。）"},{"id":1618,"day":26,"w":"structure","ph":"ˈstrʌktʃər","defs":[["n.","结构，构造；建筑物",false]],"tier":"l","hint":"结构。词组 the structure of …的结构","ex":"The building has a strong structure.（这座建筑结构坚固。）"},{"id":1619,"day":26,"w":"terrible","ph":"ˈterəbl","defs":[["a.","可怕的；很糟的",true]],"tier":"f","ety":"拉丁 terribilis（可怕的），与 terror 同源","mem":"terr（=terror 恐怖）+ ible → 恐怖的 → 可怕的。画面：吓得发抖","ex":"terrible weather · The weather was terrible yesterday.（昨天天气很糟糕。）","nua":"terrible（可怕的、糟糕的）、terrific（极好的，反义！）；terrified（感到恐惧的）"},{"id":1620,"day":26,"w":"therefore","ph":"ˈðerfɔːr","defs":[["ad.","因此，所以",false]],"tier":"l","hint":"因此。联想 so 因此（同义）","ex":"He was ill, therefore he stayed at home.（他病了，因此待在家。）"},{"id":1621,"day":26,"w":"tired","ph":"ˈtaɪərd","defs":[["a.","疲劳的；厌倦的",false]],"tier":"l","hint":"tire（累）+ -d → 疲倦的。词组 be tired of 厌倦","ex":"I'm tired after the long walk.（走了很久我累了。）"},{"id":1622,"day":26,"w":"truck","ph":"trʌk","defs":[["n.","卡车，载重汽车",false]],"tier":"l","hint":"卡车。联想 lorry 卡车（英）、truck 卡车（美）","ex":"The truck carries goods to the city.（卡车把货物运到城里。）"},{"id":1623,"day":26,"w":"truth","ph":"truːθ","defs":[["n.","真实，真相；真实性；真理",false]],"tier":"l","hint":"true（真）的名词 → 真相。词组 tell the truth 说实话","ex":"You should always tell the truth.（你应该总是说实话。）"},{"id":1624,"day":26,"w":"turn","ph":"tɜːrn","defs":[["n.","翻，旋转；机会，轮替；变化，改变；转折点 vi.转动；翻，翻转；改变方向；回头，转身 vi.变为，变得；转动；翻；翻转；改变方向，回头",false]],"tier":"l","hint":"转动、轮流。词组 turn on 打开、turn off 关闭、turn left 左转","ex":"Please turn left at the corner.（请在拐角处左转。）"},{"id":1625,"day":26,"w":"when","ph":"wen","defs":[["ad.","什么时候，何时；[关系副词]在……时候 conj.当……时；其时，然后；可是，然而 pron.什么时候",false]],"tier":"l","hint":"何时、当…时。词组 when... 当…时候","ex":"When will you come back?（你什么时候回来？）"},{"id":1626,"day":26,"w":"whose","ph":"huːz","defs":[["pron.","谁的；哪个（人）的，哪些（人）的",false]],"tier":"l","hint":"谁的。","ex":"Whose book is this?（这是谁的书？）"},{"id":1627,"day":26,"w":"win","ph":"wɪn","defs":[["vi.","/vt.赢得，获胜",false]],"tier":"l","hint":"赢。过去式 won。词组 win the game 赢得比赛","ex":"Our team won the match.（我们队赢了比赛。）"},{"id":1628,"day":26,"w":"wire","ph":"ˈwaɪər","defs":[["n.","铁丝，电线；电报，电话",false]],"tier":"l","hint":"电线、金属丝。联想 wire 电线、electric wire 电线","ex":"The electric wire is broken.（电线断了。）"},{"id":1629,"day":26,"w":"within","ph":"wɪˈðɪn","defs":[["prep.","在……里面，在……以内",false]],"tier":"l","hint":"在…之内。词组 within an hour 一小时内","ex":"I will finish it within an hour.（我一小时内完成。）"},{"id":1630,"day":26,"w":"word","ph":"wɜːrd","defs":[["n.","词，单词；言语，话；诺言，保证；音信，消息",false]],"tier":"l","hint":"单词、话。词组 in a word 总之、in other words 换句话说","ex":"What does this word mean?（这个单词什么意思？）"},{"id":1631,"day":27,"w":"admit","ph":"ədˈmɪt","defs":[["vt.","承认；允许进入",true]],"tier":"f","ety":"ad-（向）+ mit（送，同 miss）→ 送进去 → 准入、承认","mem":"ad + mit（=送）→ 把话\"送\"出来 → 承认；把门\"送\"开 → 准入。画面：坦白","ex":"admit doing · He admitted making a mistake.（他承认犯了错。）","nua":"admit doing / admit to doing（承认做）、be admitted to（被录取/准入）；admission（准入）"},{"id":1632,"day":27,"w":"affair","ph":"əˈfer","defs":[["n.","事情，事务",true]],"tier":"f","ety":"法语 à faire（去做的事）→ 事务","mem":"af + fair（公平）→ 处理\"公平\"的事 → 事务。画面：处理公务","ex":"foreign affairs · He works in foreign affairs.（他从事外交工作。）","nua":"affair（事务、事件，常用复数 affairs）、matter（事情）；foreign affairs 外交"},{"id":1633,"day":27,"w":"although","ph":"ɔːlˈðoʊ","defs":[["conj.","虽然，即使",false]],"tier":"l","hint":"虽然。联想 though 虽然（同义）","ex":"Although it rained, they went out.（虽然下雨了，他们还是出去了。）"},{"id":1634,"day":27,"w":"appear","ph":"əˈpɪr","defs":[["vi.","出现，出场，问世；好像是",false]],"tier":"l","hint":"出现、似乎。联想 disappear 消失（反义）","ex":"A rainbow appeared after the rain.（雨后出现了彩虹。）"},{"id":1635,"day":27,"w":"arrive","ph":"əˈraɪv","defs":[["vi.","到来，到达；(at)达成，得出",false]],"tier":"l","hint":"到达。词组 arrive at/in 到达","ex":"The train arrived at the station.（火车到站了。）"},{"id":1636,"day":27,"w":"beauty","ph":"ˈbjuːti","defs":[["n.","美，美丽；美人，美丽的东西",false]],"tier":"l","hint":"beautiful（美丽）的名词 → 美","ex":"The beauty of the mountain is amazing.（山的美令人惊叹。）"},{"id":1637,"day":27,"w":"between","ph":"bɪˈtwiːn","defs":[["prep.","在……中间，在……之间 ad.当中，中间",false]],"tier":"l","hint":"在…之间（两者）。联想 among 在…之间（三者以上）","ex":"The shop is between the bank and the school.（商店在银行和学校之间。）"},{"id":1638,"day":27,"w":"black","ph":"blæk","defs":[["a.","/n.黑，黑色；黑暗 n.黑色，黑人",false]],"tier":"l","hint":"黑色。联想 white 白色（反义）","ex":"He wore a black coat.（他穿了件黑外套。）"},{"id":1639,"day":27,"w":"boil","ph":"bɔɪl","defs":[["vi.","沸腾 vt.煮沸",false]],"tier":"l","hint":"沸腾、煮。词组 boil water 烧水","ex":"The water is boiling.（水开了。）"},{"id":1640,"day":27,"w":"bright","ph":"braɪt","defs":[["a.","明亮的；聪明的；美好的；(颜色)鲜艳的",false]],"tier":"l","hint":"明亮的、聪明的。联想 dark 黑暗的（反义）","ex":"The room is bright and clean.（房间明亮干净。）"},{"id":1641,"day":27,"w":"buy","ph":"baɪ","defs":[["vt.","买，购买",false]],"tier":"l","hint":"买。过去式 bought。联想 sell 卖（反义）","ex":"I want to buy a new phone.（我想买部新手机。）"},{"id":1642,"day":27,"w":"central","ph":"ˈsentrəl","defs":[["a.","中心的，中央的，中枢的；主要的",false]],"tier":"l","hint":"center（中心）+ -al → 中心的、中央的","ex":"The hotel is in the central area of the city.（旅馆在市中心区。）"},{"id":1643,"day":27,"w":"chance","ph":"tʃæns","defs":[["n.","机会，机遇；可能性，偶然性，运气",false]],"tier":"l","hint":"机会、可能性。词组 by chance 偶然、take a chance 冒险","ex":"I met him by chance yesterday.（我昨天偶然遇见他。）"},{"id":1644,"day":27,"w":"coal","ph":"koʊl","defs":[["n.","煤，煤块",false]],"tier":"l","hint":"煤。联想 coal 煤、coal mine 煤矿","ex":"They use coal to keep warm in winter.（他们冬天烧煤取暖。）"},{"id":1645,"day":27,"w":"coin","ph":"kɔɪn","defs":[["n.","硬币，货币",false]],"tier":"l","hint":"硬币。联想 money 钱、coin 硬币","ex":"He put a coin in the machine.（他把硬币投进机器。）"},{"id":1646,"day":27,"w":"committee","ph":"kəˈmɪti","defs":[["n.","委员会，全体委员",false]],"tier":"l","hint":"commit（委托）+ -ee → 委员会","ex":"The committee made a decision.（委员会做了决定。）"},{"id":1647,"day":27,"w":"condition","ph":"kənˈdɪʃn","defs":[["n.","状况，状态；(pl.)环境，情形；条件",false]],"tier":"l","hint":"条件、状况。词组 on condition that 条件是、in good condition 状况良好","ex":"The car is in good condition.（这辆车状况良好。）"},{"id":1648,"day":27,"w":"council","ph":"ˈkaʊnsl","defs":[["n.","理事会，委员会；议事机构",false]],"tier":"l","hint":"委员会、理事会。联想 council 理事会、committee 委员会","ex":"The city council discussed the plan.（市议会讨论了这个计划。）"},{"id":1649,"day":27,"w":"decay","ph":"dɪˈkeɪ","defs":[["vi.","/n.腐败；衰落",false]],"tier":"l","hint":"腐烂、衰败。联想 decay 腐烂、rot 腐烂","ex":"The old house is falling into decay.（老房子在衰败。）"},{"id":1650,"day":27,"w":"discuss","ph":"dɪˈskʌs","defs":[["vt.","讨论",false]],"tier":"l","hint":"讨论。词组 discuss...with 与…讨论","ex":"We discussed the plan at the meeting.（我们在会上讨论了计划。）"},{"id":1651,"day":27,"w":"document","ph":"ˈdɑːkjumənt","defs":[["n.","文件，文献",false]],"tier":"l","hint":"文件、文档。词组 official document 官方文件","ex":"Please sign the document.（请签署这份文件。）"},{"id":1652,"day":27,"w":"down","ph":"daʊn","defs":[["ad.","下，向下；由多到少；往南；处于低落状态 prep.下，顺……而下",false]],"tier":"l","hint":"向下。词组 sit down 坐下、up and down 上下","ex":"The sun goes down in the west.（太阳从西边落下。）"},{"id":1653,"day":27,"w":"drop","ph":"drɑːp","defs":[["n.","下降；滴，水滴 vt.投下，落下；降低 vi.落下，下降",false]],"tier":"l","hint":"落下、滴、下降。词组 drop in 顺便拜访","ex":"The apple dropped from the tree.（苹果从树上掉下来。）"},{"id":1654,"day":27,"w":"else","ph":"els","defs":[["ad.","其他，另外，别的；[与or连用]否则",false]],"tier":"l","hint":"其他、另外。词组 something else 别的东西、or else 否则","ex":"Is there anything else you want?（你还要别的吗？）"},{"id":1655,"day":27,"w":"energy","ph":"ˈenərdʒi","defs":[["n.","精力，气力，活力；能，能量",false]],"tier":"l","hint":"能量、精力。词组 full of energy 充满活力","ex":"He is full of energy every day.（他每天充满活力。）"},{"id":1656,"day":27,"w":"especially","ph":"ɪˈspeʃəli","defs":[["ad.","特别，尤其，格外",false]],"tier":"l","hint":"especially 尤其。联想 special 特别的（同源）","ex":"I like fruit, especially apples.（我喜欢水果，尤其是苹果。）"},{"id":1657,"day":27,"w":"etc.(=et cetera)","ph":"ˌetˈsetərə","defs":[["abbr.","及其他",false]],"tier":"l","hint":"等等（et cetera 的缩写）","ex":"We need paper, pens, etc.（我们需要纸、笔等等。）"},{"id":1658,"day":27,"w":"except","ph":"ɪkˈsept","defs":[["prep.","除……之外",false]],"tier":"l","hint":"除了。词组 except for 除了（整体中除去）","ex":"Everyone came except Tom.（除了汤姆大家都来了。）"},{"id":1659,"day":27,"w":"explain","ph":"ɪkˈspleɪn","defs":[["vt.","解释，说明",false]],"tier":"l","hint":"解释。词组 explain...to 向…解释","ex":"Please explain this rule to me.（请给我解释这条规则。）"},{"id":1660,"day":27,"w":"express","ph":"ɪkˈspres","defs":[["vt.","表示，表达 a.特快的，快速的 n.快车，快运",false]],"tier":"l","hint":"表达、快递。词组 express oneself 表达自己","ex":"He expressed his thanks to us.（他向我们表达了感谢。）"},{"id":1661,"day":27,"w":"flour","ph":"ˈflaʊər","defs":[["n.","面粉，粉状物",false]],"tier":"l","hint":"面粉。联想 flower 花（同音不同词）","ex":"She used flour to make bread.（她用面粉做面包。）"},{"id":1662,"day":27,"w":"foreigner","ph":"ˈfɔːrənər","defs":[["n.","外国人",false]],"tier":"l","hint":"foreign（外国的）+ -er（人）→ 外国人","ex":"Many foreigners visit China every year.（每年很多外国人来中国。）"},{"id":1663,"day":27,"w":"forward","ph":"ˈfɔːrwərd","defs":[["a.","前部的，向前的；进步的，激进的 ad.(=forwards)向前；将来 vt.转交，转递",false]],"tier":"l","hint":"向前。词组 look forward to 期待","ex":"He stepped forward to speak.（他走上前说话。）"},{"id":1664,"day":27,"w":"hate","ph":"heɪt","defs":[["n.","恨，憎恨 vt.不喜欢，不愿",false]],"tier":"l","hint":"恨、讨厌。联想 love 爱（反义）","ex":"I hate getting up early.（我讨厌早起。）"},{"id":1665,"day":27,"w":"hatred","ph":"ˈheɪtrɪd","defs":[["n.","憎恶，憎恨，怨恨",false]],"tier":"l","hint":"hate（恨）的名词 → 仇恨","ex":"There is no hatred between them.（他们之间没有仇恨。）"},{"id":1666,"day":27,"w":"intelligence","ph":"ɪnˈtelɪdʒəns","defs":[["n.","智力，理解力；情报，消息，报道",false]],"tier":"l","hint":"intelligent（聪明的）的名词 → 智力、情报","ex":"The test measures intelligence.（这个测试测智力。）"},{"id":1667,"day":27,"w":"lead","ph":"liːd","defs":[["vt.","领导，率领，领先；引导，带领；导致，通向 n.领导，领先",false]],"tier":"l","hint":"领导、带领、铅。过去式 led。词组 lead to 导致","ex":"He led the team to victory.（他带领团队走向胜利。）"},{"id":1668,"day":27,"w":"lie","ph":"laɪ","defs":[["vi.","躺，平放；处于；位于，在于 n.谎言 vi.说谎",false]],"tier":"l","hint":"躺、说谎、位于。过去式 lay（躺）/lied（说谎）","ex":"He likes to lie on the grass.（他喜欢躺在草地上。）"},{"id":1669,"day":27,"w":"long","ph":"lɔːŋ","defs":[["a.","长的，长远的；长期的 ad.长久地，长期地 vi.渴望，极想",false]],"tier":"l","hint":"长的。联想 short 短的（反义）、length 长度","ex":"The river is very long.（这条河很长。）"},{"id":1670,"day":27,"w":"morning","ph":"ˈmɔːrnɪŋ","defs":[["n.","早晨，上午",false]],"tier":"l","hint":"早晨。词组 in the morning 在早晨","ex":"I get up early in the morning.（我早晨起得早。）"},{"id":1671,"day":27,"w":"need","ph":"niːd","defs":[["n.","/vt.必须，必要；缺少 aux. v.需要，必须",false]],"tier":"l","hint":"需要。词组 need to do 需要做、in need of 需要","ex":"I need some help.（我需要帮助。）"},{"id":1672,"day":27,"w":"newspaper","ph":"ˈnuːzpeɪpər","defs":[["n.","报纸",false]],"tier":"l","hint":"news（新闻）+ paper（纸）→ 报纸","ex":"He reads the newspaper every morning.（他每天早晨读报。）"},{"id":1673,"day":27,"w":"next","ph":"nekst","defs":[["ad.","其次，然后，下次；居后 a.紧接的，其次的；贴近的",false]],"tier":"l","hint":"下一个、紧接着。词组 next to 紧挨着、next week 下周","ex":"The post office is next to the bank.（邮局在银行旁边。）"},{"id":1674,"day":27,"w":"noun","ph":"naʊn","defs":[["n.","名词",false]],"tier":"l","hint":"名词（语法术语）。联想 verb 动词、noun 名词","ex":"\"Apple\" is a noun.（\"苹果\"是名词。）"},{"id":1675,"day":27,"w":"possession","ph":"pəˈzeʃn","defs":[["n.","(pl.)所有物；拥有，占有",false]],"tier":"l","hint":"possess（拥有）+ -ion → 财产、拥有","ex":"The house is his most valuable possession.（房子是他最值钱的财产。）"},{"id":1676,"day":27,"w":"send","ph":"send","defs":[["vt.","送，寄；派遗，打发",false]],"tier":"l","hint":"发送。过去式 sent。词组 send for 派人去请","ex":"Please send me an email.（请给我发邮件。）"},{"id":1677,"day":27,"w":"shelf","ph":"ʃelf","defs":[["n.","架子",false]],"tier":"l","hint":"架子（复数 shelves）。词组 on the shelf 在架子上","ex":"The books are on the shelf.（书在架子上。）"},{"id":1678,"day":27,"w":"shelter","ph":"ˈʃeltər","defs":[["n.","/v. 躲避处；庇护",true]],"tier":"f","ety":"古英语 sceld（盾）+ truma（队伍）→ 盾牌掩护 → 庇护","mem":"shel（=shell 壳）+ ter → 像\"壳\"（shell）一样护住 → 庇护。画面：躲进避风港","ex":"take shelter · They took shelter from the storm.（他们躲避暴风雨。）","nua":"take shelter（躲避）、shelter sb（庇护某人）；shelter 作名词不可数多"},{"id":1679,"day":27,"w":"shocking","ph":"ˈʃɑːkɪŋ","defs":[["a.","令人震惊的",true]],"tier":"f","ety":"shock（震惊）+ -ing → 令人震惊的","mem":"shock + ing → 让人\"震惊\"（shock）的 → 令人震惊的。画面：目瞪口呆","ex":"shocking news · The news was shocking to everyone.（这消息令所有人震惊。）","nua":"shocking（令人震惊）、shocked（感到震惊）；-ed 修饰人、-ing 修饰物"},{"id":1680,"day":27,"w":"still","ph":"stɪl","defs":[["ad.","还，仍然；然而，仍旧；更；另外，又 a.静的，静止的；寂静的，平静的",false]],"tier":"l","hint":"仍然、静止的。词组 still 仍然","ex":"He is still working.（他还在工作。）"},{"id":1681,"day":27,"w":"successful","ph":"səkˈsesfl","defs":[["a.","成功的",false]],"tier":"l","hint":"success（成功）+ -ful → 成功的","ex":"She is a successful businesswoman.（她是成功的女商人。）"},{"id":1682,"day":27,"w":"such","ph":"sʌtʃ","defs":[["a.","如此的；这样的 pron.这样的人/事物",false]],"tier":"l","hint":"这样的。词组 such as 例如、such...that 如此…以至于","ex":"I like sports such as football.（我喜欢足球之类的运动。）"},{"id":1683,"day":27,"w":"supply","ph":"səˈplaɪ","defs":[["vt.","/n.供给，供应",false]],"tier":"l","hint":"供应。词组 supply...with 供应、water supply 供水","ex":"The factory supplies us with goods.（工厂给我们供应货物。）"},{"id":1684,"day":27,"w":"surround","ph":"səˈraʊnd","defs":[["vt.","围绕，包围",false]],"tier":"l","hint":"包围。词组 be surrounded by 被…包围","ex":"The house is surrounded by trees.（房子被树包围。）"},{"id":1685,"day":27,"w":"ticket","ph":"ˈtɪkɪt","defs":[["n.","票，门票，车票；标签；(交通违章)罚款，传票",false]],"tier":"l","hint":"票。词组 buy a ticket 买票、train ticket 火车票","ex":"I bought two tickets for the movie.（我买了两张电影票。）"},{"id":1686,"day":27,"w":"toy","ph":"tɔɪ","defs":[["n.","玩具",false]],"tier":"l","hint":"玩具。词组 toy shop 玩具店","ex":"The child is playing with a toy.（孩子在玩玩具。）"},{"id":1687,"day":27,"w":"traffic","ph":"ˈtræfɪk","defs":[["n.","交通，交通量",false]],"tier":"l","hint":"交通。词组 traffic jam 交通堵塞、traffic lights 交通灯","ex":"The traffic is heavy at this hour.（这个时段交通拥堵。）"},{"id":1688,"day":27,"w":"twice","ph":"twaɪs","defs":[["ad.","两次，两倍",false]],"tier":"l","hint":"两次、两倍。词组 once or twice 一两次","ex":"I go to the gym twice a week.（我每周去两次健身房。）"},{"id":1689,"day":27,"w":"upper","ph":"ˈʌpər","defs":[["a.","上的，上部的，较高的",false]],"tier":"l","hint":"上面的。联想 lower 下面的（反义）","ex":"He lives on the upper floor.（他住在楼上。）"},{"id":1690,"day":27,"w":"wheat","ph":"wiːt","defs":[["n.","小麦",false]],"tier":"l","hint":"小麦。联想 rice 水稻、wheat 小麦","ex":"The farmers grow wheat in the field.（农民在地里种小麦。）"},{"id":1691,"day":27,"w":"whistle","ph":"ˈwɪsl","defs":[["vi.","吹口哨，鸣笛 n.口哨声，汽笛声；哨子，汽笛",false]],"tier":"l","hint":"口哨、鸣笛。词组 blow the whistle 吹口哨","ex":"The referee blew the whistle.（裁判吹了哨。）"},{"id":1692,"day":27,"w":"worry","ph":"ˈwɜːri","defs":[["n.","担心，忧虑，烦恼；令人烦恼的事/人 vi./vt.（使）发愁，（使）担忧，（使）烦恼",false]],"tier":"l","hint":"担心。词组 worry about 担心、don't worry 别担心","ex":"Don't worry about the exam.（别担心考试。）"},{"id":1693,"day":27,"w":"wound","ph":"wuːnd","defs":[["n.","创伤，伤口 vt.使受伤，伤害",false]],"tier":"l","hint":"伤口、使受伤。联想 injure 伤害（同义）","ex":"The wound healed quickly.（伤口很快愈合了。）"},{"id":1694,"day":28,"w":"alone","ph":"əˈloʊn","defs":[["a.","/ad.独自，单独 ad.仅仅，只",false]],"tier":"l","hint":"单独的。联想 lonely 孤独的（情绪）。词组 leave...alone 别打扰","ex":"He lives alone in the city.（他独自住在城里。）"},{"id":1695,"day":28,"w":"anger","ph":"ˈæŋɡər","defs":[["n.","气愤，愤怒 vt.使发怒，激怒",false]],"tier":"l","hint":"angry（生气的）的名词 → 愤怒","ex":"He could not control his anger.（他无法控制愤怒。）"},{"id":1696,"day":28,"w":"angle","ph":"ˈæŋɡl","defs":[["n.","角；角度；观点",true]],"tier":"f","ety":"拉丁 angulus（角）","mem":"谐音\"俺狗\"→ 狗看问题有狗的角度 → 角度。画面：换个角度看","ex":"from a different angle · Let's look at it from a different angle.（我们换个角度看问题。）","nua":"angle（角度）、angel（天使，a-n-g-e-l）；from the angle of（从…角度）"},{"id":1697,"day":28,"w":"answer","ph":"ˈænsər","defs":[["n.","回答，答复；答案 vi./vt.回答，答复",false]],"tier":"l","hint":"回答、答案。词组 answer the question 回答问题","ex":"Please answer my question.（请回答我的问题。）"},{"id":1698,"day":28,"w":"awake","ph":"əˈweɪk","defs":[["a.","醒着的；意识到的 vt.唤醒，唤起 vi.醒来；醒悟，觉悟",false]],"tier":"l","hint":"a-（在）+ wake（醒）→ 醒着的。词组 stay awake 保持清醒","ex":"The baby is awake now.（婴儿现在醒了。）"},{"id":1699,"day":28,"w":"believe","ph":"bɪˈliːv","defs":[["vt.","相信，认为 vi.相信，信任，信奉",false]],"tier":"l","hint":"相信。词组 believe in 相信、believe it or not 信不信由你","ex":"I believe what he said.（我相信他说的话。）"},{"id":1700,"day":28,"w":"below","ph":"bɪˈloʊ","defs":[["prep.","在……下面，在……以下 ad.在下，以下，向下",false]],"tier":"l","hint":"在…下面。联想 above 在…上面（反义）","ex":"The temperature is below zero.（气温在零度以下。）"},{"id":1701,"day":28,"w":"block","ph":"blɑːk","defs":[["vt.","阻塞，封锁； n.街区；大块(木料、石料、冰等)；阻塞物，路障",false]],"tier":"l","hint":"街区、块、阻挡。词组 block the way 挡路","ex":"He lives two blocks away.（他住在两个街区外。）"},{"id":1702,"day":28,"w":"born","ph":"bɔːrn","defs":[["a.","出生的；天生的，生来的",false]],"tier":"l","hint":"bear（出生）的过去分词 → 出生的。词组 be born 出生","ex":"She was born in 1990.（她出生于 1990 年。）"},{"id":1703,"day":28,"w":"branch","ph":"bræntʃ","defs":[["n.","枝，树枝；分支，分科",false]],"tier":"l","hint":"树枝、分支。联想 branch 树枝、bank 分行","ex":"A bird is sitting on the branch.（鸟停在树枝上。）"},{"id":1704,"day":28,"w":"break","ph":"breɪk","defs":[["vt.","打破，打碎；损坏，破坏，违反；中止 n.（课间或工间）休息时间 vi.破，破裂",false]],"tier":"l","hint":"打破、休息。过去式 broke。词组 break down 出故障、break out 爆发","ex":"He broke the window by accident.（他意外打破了窗户。）"},{"id":1705,"day":28,"w":"breast","ph":"brest","defs":[["n.","胸脯，乳房",false]],"tier":"l","hint":"胸、乳房。联想 chest 胸膛、breast 胸","ex":"He held the baby to his breast.（他把婴儿抱在胸前。）"},{"id":1706,"day":28,"w":"chew","ph":"tʃuː","defs":[["vi.","/vt.咀嚼",false]],"tier":"l","hint":"咀嚼。词组 chew food 嚼食物","ex":"Chew your food well before swallowing.（吞下前好好嚼食物。）"},{"id":1707,"day":28,"w":"close","ph":"kloʊz","defs":[["vi.","/vt.关，关闭；结束 a.近的；紧密的，亲密的；周密的，仔细的 n.结束，了结 ad.接近，紧密地",false]],"tier":"l","hint":"关闭、接近的。词组 close the door 关门、be close to 接近","ex":"Please close the door behind you.（请随手关门。）"},{"id":1708,"day":28,"w":"comparison","ph":"kəmˈpærɪsn","defs":[["n.","比较，对照",true]],"tier":"f","ety":"compare（比较）+ -ison → 比较","mem":"compare + ison → 比较（compare）的名词。画面：并排对比","ex":"in comparison with · In comparison with last year, sales rose.（与去年相比，销量上升了。）","nua":"in comparison with（与…相比）、compare A with B（比较）；comparison 名词"},{"id":1709,"day":28,"w":"confidence","ph":"ˈkɑːnfɪdəns","defs":[["n.","信任，信心",false]],"tier":"l","hint":"confident（自信）的名词 → 信心。词组 with confidence 自信地","ex":"She spoke with confidence.（她自信地发言。）"},{"id":1710,"day":28,"w":"consist","ph":"kənˈsɪst","defs":[["vi.","(of)由……构成，由……组成；(in)在于",false]],"tier":"l","hint":"由…组成。词组 consist of 由…组成","ex":"The team consists of ten members.（这个团队由十名成员组成。）"},{"id":1711,"day":28,"w":"disappoint","ph":"ˌdɪsəˈpɔɪnt","defs":[["vt.","令失望，使扫兴",false]],"tier":"l","hint":"使失望。词组 be disappointed in/with 对…失望","ex":"The result disappointed everyone.（结果让大家失望。）"},{"id":1712,"day":28,"w":"duck","ph":"dʌk","defs":[["n.","鸭，鸭肉",false]],"tier":"l","hint":"鸭子。联想 duck 鸭子、swim 游泳","ex":"The duck is swimming in the pond.（鸭子在池塘里游泳。）"},{"id":1713,"day":28,"w":"effective","ph":"ɪˈfektɪv","defs":[["a.","有效的，生效的",false]],"tier":"l","hint":"effect（效果）+ -ive → 有效的","ex":"This is an effective way to learn.（这是有效的学习方法。）"},{"id":1714,"day":28,"w":"finish","ph":"ˈfɪnɪʃ","defs":[["vt.","/n.完毕，结束，完成",false]],"tier":"l","hint":"完成。词组 finish doing 完成做","ex":"I finished my homework at nine.（我九点完成了作业。）"},{"id":1715,"day":28,"w":"glue","ph":"ɡluː","defs":[["n.","胶，胶水 vt.（用胶水）粘贴",false]],"tier":"l","hint":"胶水、粘。词组 glue...to 把…粘到","ex":"He glued the photo to the paper.（他把照片粘在纸上。）"},{"id":1716,"day":28,"w":"guest","ph":"ɡest","defs":[["n.","客人，宾客，旅客",false]],"tier":"l","hint":"客人。联想 host 主人、guest 客人","ex":"We have some guests tonight.（我们今晚有客人。）"},{"id":1717,"day":28,"w":"hopeful","ph":"ˈhoʊpfl","defs":[["a.","有希望的，怀有希望的",false]],"tier":"l","hint":"hope（希望）+ -ful → 有希望的","ex":"I'm hopeful about the future.（我对未来充满希望。）"},{"id":1718,"day":28,"w":"hospital","ph":"ˈhɑːspɪtl","defs":[["n.","医院",false]],"tier":"l","hint":"医院。词组 go to hospital 去医院","ex":"He was taken to the hospital.（他被送去了医院。）"},{"id":1719,"day":28,"w":"humorous","ph":"ˈhjuːmərəs","defs":[["a.","幽默的",false]],"tier":"l","hint":"humor（幽默）+ -ous → 幽默的","ex":"He is a humorous person.（他是个幽默的人。）"},{"id":1720,"day":28,"w":"husband","ph":"ˈhʌzbənd","defs":[["n.","丈夫",false]],"tier":"l","hint":"丈夫。联想 wife 妻子（反义）","ex":"Her husband is a teacher.（她丈夫是老师。）"},{"id":1721,"day":28,"w":"industry","ph":"ˈɪndəstri","defs":[["n.","工业，产业",false]],"tier":"l","hint":"工业、勤奋。联想 industrial 工业的","ex":"The industry of the country is developing.（这个国家的工业在发展。）"},{"id":1722,"day":28,"w":"injury","ph":"ˈɪndʒəri","defs":[["n.","损伤，伤害",true]],"tier":"f","ety":"in-（不）+ jury（法，同 law）→ 不合法地伤害 → 伤害","mem":"in + jury（=jury 陪审团）→ 受伤了得上\"陪审团\"（jury）讨公道 → 伤害。画面：工伤","ex":"a serious injury · He suffered a serious injury in the accident.（他在事故中受了重伤。）","nua":"injure（动词）→ injury（名词）；injury 是事故伤害，wound 是刀枪伤，hurt 是泛指"},{"id":1723,"day":28,"w":"logical","ph":"ˈlɑːdʒɪkl","defs":[["a.","逻辑（上）的，符合逻辑的",false]],"tier":"l","hint":"logic（逻辑）+ -al → 合逻辑的","ex":"His argument is logical.（他的论证合乎逻辑。）"},{"id":1724,"day":28,"w":"loyal","ph":"ˈlɔɪəl","defs":[["a.","忠诚的，忠贞的",false]],"tier":"l","hint":"忠诚的。词组 be loyal to 忠于","ex":"He is loyal to his friends.（他对朋友忠诚。）"},{"id":1725,"day":28,"w":"married","ph":"ˈmærid","defs":[["a.","已婚的，夫妇的",false]],"tier":"l","hint":"marry（结婚）+ -ed → 已婚的。词组 be married to 与…结婚","ex":"She is married to a doctor.（她嫁给了一位医生。）"},{"id":1726,"day":28,"w":"meet","ph":"miːt","defs":[["vt.","遇见，碰上；会见；会谈；迎接；满足，符合 vi.相遇，相会；接触；开会",false]],"tier":"l","hint":"遇见、开会。过去式 met。词组 meet with 遇到","ex":"Nice to meet you.（很高兴认识你。）"},{"id":1727,"day":28,"w":"member","ph":"ˈmembər","defs":[["n.","成员，会员",false]],"tier":"l","hint":"成员。词组 a member of …的成员","ex":"He is a member of the club.（他是俱乐部成员。）"},{"id":1728,"day":28,"w":"negative","ph":"ˈneɡətɪv","defs":[["a.","否定的，消极的，反面的；负的，阴性的",false]],"tier":"l","hint":"消极的、否定的。联想 positive 积极的（反义）","ex":"Don't have a negative attitude.（不要有消极态度。）"},{"id":1729,"day":28,"w":"nonsense","ph":"ˈnɑːnsens","defs":[["n.","胡说，废话",false]],"tier":"l","hint":"non（无）+ sense（意义）→ 废话","ex":"Don't talk nonsense!（别胡说！）"},{"id":1730,"day":28,"w":"oil","ph":"ɔɪl","defs":[["n.","油，石油 vt.涂油，上油",false]],"tier":"l","hint":"油、石油。词组 cooking oil 食用油","ex":"The country is rich in oil.（这个国家石油丰富。）"},{"id":1731,"day":28,"w":"once","ph":"wʌns","defs":[["ad.","一次，一度；曾经 conj.一旦……就…… n.一次",false]],"tier":"l","hint":"一次、曾经。词组 at once 立刻、once upon a time 从前","ex":"Please come here at once.（请立刻过来。）"},{"id":1732,"day":28,"w":"operate","ph":"ˈɑːpəreɪt","defs":[["vi.","操作，运转；动手术，开刀 vt.操作，操纵，进行",false]],"tier":"l","hint":"操作、动手术。词组 operate on 给…动手术","ex":"The doctor operated on the patient.（医生给病人动了手术。）"},{"id":1733,"day":28,"w":"personal","ph":"ˈpɜːrsənl","defs":[["a.","个人的，私人的；本人的，亲自的",false]],"tier":"l","hint":"person（人）+ -al → 个人的。词组 personal information 个人信息","ex":"This is my personal opinion.（这是我个人的看法。）"},{"id":1734,"day":28,"w":"persuade","ph":"pərˈsweɪd","defs":[["vt.","劝说，说服",false]],"tier":"l","hint":"说服。词组 persuade sb to do 说服某人做","ex":"She persuaded me to go with her.（她说服我和她一起去。）"},{"id":1735,"day":28,"w":"physical","ph":"ˈfɪzɪkl","defs":[["a.","物质的，有形的；身体的；自然科学的，物理的",false]],"tier":"l","hint":"身体的、物理的。词组 physical exercise 体育锻炼","ex":"Physical exercise is good for health.（体育锻炼有益健康。）"},{"id":1736,"day":28,"w":"position","ph":"pəˈzɪʃn","defs":[["n.","位置；职务，职位；姿势，姿态；见解，立场",false]],"tier":"l","hint":"位置、职位。词组 in position 就位","ex":"He got a good position in the company.（他在公司得到好职位。）"},{"id":1737,"day":28,"w":"pressure","ph":"ˈpreʃər","defs":[["n.","压力，紧张；强制；压强",false]],"tier":"l","hint":"压力。词组 under pressure 在压力下、blood pressure 血压","ex":"He is under great pressure at work.（他工作压力很大。）"},{"id":1738,"day":28,"w":"push","ph":"pʊʃ","defs":[["vt.","/n.推；推进，促进；催促",false]],"tier":"l","hint":"推。联想 pull 拉（反义）","ex":"Please push the door open.（请把门推开。）"},{"id":1739,"day":28,"w":"question","ph":"ˈkwestʃən","defs":[["n.","问题；难题；议题 vt.怀疑；问，审问",false]],"tier":"l","hint":"问题。词组 ask a question 提问、out of the question 不可能","ex":"May I ask you a question?（我能问你个问题吗？）"},{"id":1740,"day":28,"w":"react","ph":"riˈækt","defs":[["vi.","反应，起作用",false]],"tier":"l","hint":"反应。词组 react to 对…反应","ex":"How did she react to the news?（她对这个消息反应如何？）"},{"id":1741,"day":28,"w":"rest","ph":"rest","defs":[["n.","休息，静止；仰赖，依赖(the)其余的人/物 vi.休息；静止；依赖",false]],"tier":"l","hint":"休息、其余。词组 have a rest 休息、the rest 其余","ex":"Let's have a rest.（我们休息一下吧。）"},{"id":1742,"day":28,"w":"search","ph":"sɜːrtʃ","defs":[["vi.","/vt./n.搜索，寻找，探查",false]],"tier":"l","hint":"搜索。词组 search for 寻找、search the Internet 上网搜索","ex":"They are searching for the lost child.（他们在寻找失踪的孩子。）"},{"id":1743,"day":28,"w":"second","ph":"ˈsekənd","defs":[["num.","第二 a.第二的，二等的 n.秒",false]],"tier":"l","hint":"第二、秒。词组 a second 一秒、second hand 二手","ex":"He finished second in the race.（他赛跑得了第二名。）"},{"id":1744,"day":28,"w":"sell","ph":"sel","defs":[["vi.","/vt.卖，出售",false]],"tier":"l","hint":"卖。过去式 sold。联想 buy 买（反义）","ex":"The shop sells all kinds of goods.（这家店卖各种商品。）"},{"id":1745,"day":28,"w":"soap","ph":"soʊp","defs":[["n.","肥皂",false]],"tier":"l","hint":"肥皂。词组 a bar of soap 一块肥皂","ex":"Wash your hands with soap.（用肥皂洗手。）"},{"id":1746,"day":28,"w":"solve","ph":"sɑːlv","defs":[["vt.","解答，解决",false]],"tier":"l","hint":"解决。词组 solve a problem 解决问题","ex":"We must solve this problem.（我们必须解决这个问题。）"},{"id":1747,"day":28,"w":"sweep","ph":"swiːp","defs":[["vt.","扫，打扫；冲走，席卷；掠过，扫过 vi.快速移动，扫描",false]],"tier":"l","hint":"打扫。过去式 swept。词组 sweep the floor 扫地","ex":"She sweeps the floor every morning.（她每天早晨扫地。）"},{"id":1748,"day":28,"w":"swell","ph":"swel","defs":[["vi.","膨胀，增大，隆起",false]],"tier":"l","hint":"肿胀。过去式 swelled。联想 swell 肿胀","ex":"His ankle swelled after the fall.（他摔倒后脚踝肿了。）"},{"id":1749,"day":28,"w":"tennis","ph":"ˈtenɪs","defs":[["n.","网球",false]],"tier":"l","hint":"网球。词组 play tennis 打网球","ex":"They play tennis every weekend.（他们每周末打网球。）"},{"id":1750,"day":28,"w":"unusual","ph":"ʌnˈjuːʒuəl","defs":[["a.","不平常的，稀有的；例外的，独特的，与众不同的",false]],"tier":"l","hint":"un-（不）+ usual（平常）→ 不寻常的","ex":"It's unusual for him to be late.（他迟到很不寻常。）"},{"id":1751,"day":28,"w":"variety","ph":"vəˈraɪəti","defs":[["n.","多样性；种类",true]],"tier":"f","ety":"vary（变化）+ -ety → 变化多 → 多样","mem":"vary（变化）+ ety → 变来变去 → 多样。画面：琳琅满目","ex":"a variety of · The shop sells a variety of goods.（这家店卖各种各样的商品。）","nua":"a variety of（各种各样的，接复数名词）、various（形容词，各种各样的）；vary（变化）"},{"id":1752,"day":28,"w":"wash","ph":"wɑːʃ","defs":[["vi.","/vt.洗，冲洗；（浪涛）冲刷，拍打 n.洗，冲洗；洗涤物，衣服；汹涌",false]],"tier":"l","hint":"洗。词组 wash one's hands 洗手、wash clothes 洗衣服","ex":"Please wash your hands before eating.（饭前请洗手。）"},{"id":1753,"day":28,"w":"weapon","ph":"ˈwepən","defs":[["n.","武器，兵器",false]],"tier":"l","hint":"武器。联想 gun 枪、weapon 武器","ex":"The police found a weapon at the scene.（警方在现场发现武器。）"},{"id":1754,"day":28,"w":"weight","ph":"weɪt","defs":[["n.","重量，体重；砝码，秤砣",false]],"tier":"l","hint":"weigh（称重）的名词 → 重量。词组 lose weight 减肥","ex":"He wants to lose weight.（他想减肥。）"},{"id":1755,"day":28,"w":"wise","ph":"waɪz","defs":[["a.","智慧的，聪明的",false]],"tier":"l","hint":"明智的。联想 wisdom 智慧（名词）","ex":"It was a wise decision.（那是个明智的决定。）"},{"id":1756,"day":28,"w":"work","ph":"wɜːrk","defs":[["vi.","工作，劳动；运转，开动 n.工作，劳动；著作，作品，成果，制品",false]],"tier":"l","hint":"工作。词组 work hard 努力工作、work out 解决/锻炼","ex":"He works in a bank.（他在银行工作。）"},{"id":1757,"day":29,"w":"actress","ph":"ˈæktrəs","defs":[["n.","女演员",false]],"tier":"l","hint":"act（表演）+ -ess（女）→ 女演员。联想 actor 男演员","ex":"She is a famous actress.（她是著名女演员。）"},{"id":1758,"day":29,"w":"airport","ph":"ˈerpɔːrt","defs":[["n.","机场",false]],"tier":"l","hint":"air（空中）+ port（港口）→ 机场","ex":"We arrived at the airport early.（我们很早就到了机场。）"},{"id":1759,"day":29,"w":"alive","ph":"əˈlaɪv","defs":[["a.","活着的；活跃的，活泼的",false]],"tier":"l","hint":"a-（在）+ live（活）→ 活着的。联想 dead 死的（反义）","ex":"The old man is still alive.（老人还活着。）"},{"id":1760,"day":29,"w":"apart","ph":"əˈpɑːrt","defs":[["ad.","分离，隔开；相距，相隔",false]],"tier":"l","hint":"分开、相隔。词组 apart from 除…之外、tell apart 区分","ex":"The two houses are far apart.（两栋房子相隔很远。）"},{"id":1761,"day":29,"w":"attention","ph":"əˈtenʃn","defs":[["n.","注意，注意力，留意",false]],"tier":"l","hint":"注意。词组 pay attention to 注意、attract attention 吸引注意","ex":"Please pay attention to your spelling.（请注意拼写。）"},{"id":1762,"day":29,"w":"bitter","ph":"ˈbɪtər","defs":[["a.","苦味的；痛苦的；严寒的",false]],"tier":"l","hint":"苦的。联想 sweet 甜、sour 酸、bitter 苦","ex":"The medicine tastes bitter.（这药尝起来苦。）"},{"id":1763,"day":29,"w":"blame","ph":"bleɪm","defs":[["vt.","责备，怪，怨；(on)把……归咎于 n.(过错、事故等的）责任；责怪，责备",false]],"tier":"l","hint":"责备。词组 blame sb for 因…责备某人、be to blame 该受责备","ex":"Don't blame others for your mistakes.（别把你的错误怪到别人头上。）"},{"id":1764,"day":29,"w":"broad","ph":"brɔːd","defs":[["a.","宽，广，广阔；宽宏，豁达",false]],"tier":"l","hint":"宽的、广阔的。联想 wide 宽的（同义）","ex":"He has broad shoulders.（他肩膀宽阔。）"},{"id":1765,"day":29,"w":"century","ph":"ˈsentʃəri","defs":[["n.","世纪，百年",false]],"tier":"l","hint":"世纪。词组 the 21st century 21 世纪","ex":"The bridge was built in the last century.（这座桥建于上个世纪。）"},{"id":1766,"day":29,"w":"child","ph":"tʃaɪld","defs":[["n.","(pl. children)孩子，儿童，子女",false]],"tier":"l","hint":"孩子（复数 children）。联想 adult 成人（反义）","ex":"The child is playing in the garden.（孩子在花园里玩。）"},{"id":1767,"day":29,"w":"city","ph":"ˈsɪti","defs":[["n.","城市，都市",false]],"tier":"l","hint":"城市。联想 town 城镇、village 村庄","ex":"Beijing is a big city.（北京是个大城市。）"},{"id":1768,"day":29,"w":"collar","ph":"ˈkɑːlər","defs":[["n.","衣袖，领子；（狗的）项圈",false]],"tier":"l","hint":"衣领。词组 white-collar 白领","ex":"He turned up his collar against the wind.（他竖起衣领挡风。）"},{"id":1769,"day":29,"w":"complain","ph":"kəmˈpleɪn","defs":[["","抱怨，诉苦，申诉",false]],"tier":"l","hint":"抱怨。词组 complain about 抱怨","ex":"He always complains about the weather.（他总是抱怨天气。）"},{"id":1770,"day":29,"w":"cost","ph":"kɔːst","defs":[["n.","成本，费用，代价 vt.值，花费",false]],"tier":"l","hint":"花费、成本。过去式 cost。词组 at the cost of 以…为代价","ex":"The book costs twenty yuan.（这本书二十元。）"},{"id":1771,"day":29,"w":"cough","ph":"kɔːf","defs":[["vi.","/n.咳嗽",false]],"tier":"l","hint":"咳嗽。词组 have a cough 咳嗽","ex":"He has a bad cough.（他咳嗽得厉害。）"},{"id":1772,"day":29,"w":"countryside","ph":"ˈkʌntrisaɪd","defs":[["n.","乡下，农村",false]],"tier":"l","hint":"country（乡村）+ side（边）→ 乡下","ex":"They live in the countryside.（他们住在乡下。）"},{"id":1773,"day":29,"w":"court","ph":"kɔːrt","defs":[["n.","法院，法庭；宫殿，朝廷；院子；球场",false]],"tier":"l","hint":"法庭、球场。词组 tennis court 网球场","ex":"The case will be heard in court.（这个案子将在法庭审理。）"},{"id":1774,"day":29,"w":"cover","ph":"ˈkʌvər","defs":[["vt.","盖，覆；包括，涉及 n.覆盖物，套，封面",false]],"tier":"l","hint":"覆盖、封面。词组 be covered with 覆盖着","ex":"The ground is covered with snow.（地面被雪覆盖。）"},{"id":1775,"day":29,"w":"cure","ph":"kjʊr","defs":[["n.","治愈，医治；良药，疗法 vt.治愈，医治",false]],"tier":"l","hint":"治愈、治疗。词组 cure...of 治好…的病","ex":"The doctor cured him of his illness.（医生治好了他的病。）"},{"id":1776,"day":29,"w":"dinner","ph":"ˈdɪnər","defs":[["n.","正餐，主餐；宴会",false]],"tier":"l","hint":"晚餐。词组 have dinner 吃晚饭","ex":"We have dinner at six.（我们六点吃晚饭。）"},{"id":1777,"day":29,"w":"drive","ph":"draɪv","defs":[["vt.","驾驶，开动；驱，赶；驱使，迫使 vi.驾驶，开车",false]],"tier":"l","hint":"驾驶。过去式 drove。词组 drive a car 开车","ex":"He drives to work every day.（他每天开车上班。）"},{"id":1778,"day":29,"w":"enjoyable","ph":"ɪnˈdʒɔɪəbl","defs":[["a.","令人愉快的，惬意的",false]],"tier":"l","hint":"enjoy（享受）+ -able → 令人愉快的","ex":"We had an enjoyable weekend.（我们度过了愉快的周末。）"},{"id":1779,"day":29,"w":"environment","ph":"ɪnˈvaɪrənmənt","defs":[["n.","环境，四周，外界",false]],"tier":"l","hint":"环境。词组 protect the environment 保护环境","ex":"We should protect the environment.（我们应该保护环境。）"},{"id":1780,"day":29,"w":"flame","ph":"fleɪm","defs":[["n.","火焰，火苗；热情，激情",false]],"tier":"l","hint":"火焰。联想 fire 火、flame 火焰","ex":"The flame of the candle is dancing.（烛火在跳动。）"},{"id":1781,"day":29,"w":"fork","ph":"fɔːrk","defs":[["n.","叉，叉子；分岔，岔口",false]],"tier":"l","hint":"叉子。联想 knife 刀、spoon 勺、fork 叉","ex":"He ate the noodles with a fork.（他用叉子吃面。）"},{"id":1782,"day":29,"w":"full","ph":"fʊl","defs":[["a.","满的，充满的；完全的，充分的",false]],"tier":"l","hint":"满的。联想 empty 空的（反义）。词组 be full of 充满","ex":"The glass is full of water.（杯子装满了水。）"},{"id":1783,"day":29,"w":"govern","ph":"ˈɡʌvərn","defs":[["vt.","统治，管理；支配，影响",false]],"tier":"l","hint":"统治、治理。联想 government 政府","ex":"The country is governed by the law.（国家由法律治理。）"},{"id":1784,"day":29,"w":"guide","ph":"ɡaɪd","defs":[["n.","向导，导游者；人门书，手册；引导，指导 vt.引导，指导",false]],"tier":"l","hint":"向导、指导。词组 guide sb 指导某人","ex":"The guide led us through the museum.（导游带我们参观博物馆。）"},{"id":1785,"day":29,"w":"heel","ph":"hiːl","defs":[["n.","脚后跟，踵，跟部",false]],"tier":"l","hint":"脚后跟。联想 foot 脚、heel 脚跟","ex":"She hurt her heel when running.（她跑步时伤了脚跟。）"},{"id":1786,"day":29,"w":"helpful","ph":"ˈhelpfl","defs":[["a.","有帮助的；有益的",false]],"tier":"l","hint":"help（帮助）+ -ful → 有帮助的","ex":"This dictionary is helpful to me.（这本词典对我有帮助。）"},{"id":1787,"day":29,"w":"including","ph":"ɪnˈkluːdɪŋ","defs":[["conj.","包括",false]],"tier":"l","hint":"include（包含）+ -ing → 包括。词组 including 包括","ex":"Ten people, including me, were there.（包括我在内，有十个人在那里。）"},{"id":1788,"day":29,"w":"injure","ph":"ˈɪndʒər","defs":[["vt.","损害，伤害",true]],"tier":"f","ety":"in-（不）+ jure（法，同 law）→ 不合法地伤害 → 伤害","mem":"in + jure → 违\"法\"（jure）伤人 → 伤害。画面：事故受伤","ex":"injure oneself · He injured himself playing football.（他踢球时弄伤了自己。）","nua":"injure（事故伤害）、wound（刀枪伤）、hurt（泛指/情感伤）；injured（受伤的）"},{"id":1789,"day":29,"w":"institution","ph":"ˌɪnstɪˈtuːʃn","defs":[["n.","公共机关，协会，学校；制度，习俗",false]],"tier":"l","hint":"机构、制度。联想 institution 机构、institute 学院","ex":"The bank is a financial institution.（银行是金融机构。）"},{"id":1790,"day":29,"w":"know","ph":"noʊ","defs":[["vt.","知道，了解，懂得；认识，熟悉；识别，认出 vi.知道，了解",false]],"tier":"l","hint":"知道。过去式 knew。词组 know about 了解、as far as I know 据我所知","ex":"I don't know the answer.（我不知道答案。）"},{"id":1791,"day":29,"w":"lawyer","ph":"ˈlɔːjər","defs":[["n.","律师",false]],"tier":"l","hint":"law（法律）+ -yer（人）→ 律师","ex":"He hired a lawyer to defend him.（他请律师为他辩护。）"},{"id":1792,"day":29,"w":"lean","ph":"liːn","defs":[["a.","瘦的；贫乏的；歉收的 vi.倚靠，倾斜；依赖；倾向，偏向",false]],"tier":"l","hint":"倾斜、倚靠、瘦的。词组 lean against 倚靠","ex":"He leaned against the wall.（他靠在墙上。）"},{"id":1793,"day":29,"w":"match","ph":"mætʃ","defs":[["n.","火柴；比赛，竞赛；对手，敌手 vi./vt.(与……)匹配，相配",false]],"tier":"l","hint":"比赛、火柴、相配。词组 a football match 足球赛","ex":"The football match was exciting.（足球赛很精彩。）"},{"id":1794,"day":29,"w":"mean","ph":"miːn","defs":[["vt.","意指，意味着；意欲，打算 a.低劣的，平庸的；卑鄙的，吝啬的；平均的 n.平均值",false]],"tier":"l","hint":"意味着、打算、刻薄的。过去式 meant。词组 mean to do 打算做","ex":"What does this word mean?（这个单词什么意思？）"},{"id":1795,"day":29,"w":"means","ph":"miːnz","defs":[["n.","方法，手段，工具",false]],"tier":"l","hint":"方法、手段（单复数同形）。词组 by means of 通过","ex":"We traveled by means of train.（我们乘火车旅行。）"},{"id":1796,"day":29,"w":"movement","ph":"ˈmuːvmənt","defs":[["n.","运动，活动；移动",false]],"tier":"l","hint":"move（移动）+ -ment → 运动、移动","ex":"The movement of the train made me sleepy.（火车的晃动让我困了。）"},{"id":1797,"day":29,"w":"officer","ph":"ˈɔːfɪsər","defs":[["n.","工作人员，公务员；军官",false]],"tier":"s"},{"id":1798,"day":29,"w":"old-fashioned","ph":"ˌoʊldˈfæʃnd","defs":[["a.","老式样的",false]],"tier":"l","hint":"old（旧）+ fashioned（式样）→ 老式的","ex":"She wore an old-fashioned dress.（她穿了件老式裙子。）"},{"id":1799,"day":29,"w":"pence","ph":"pens","defs":[["n.","便士。（penny的复数）",false]],"tier":"s"},{"id":1800,"day":29,"w":"perfect","ph":"pərˈfekt","defs":[["a.","完善的，完美的；完全的，十足的 vt.使完美，改进",false]],"tier":"l","hint":"完美的。联想 perfect 完美、perfectly 完美地","ex":"The weather is perfect today.（今天天气完美。）"},{"id":1801,"day":29,"w":"pleasure","ph":"ˈpleʒər","defs":[["n.","愉快，欢乐；乐事，乐趣",false]],"tier":"l","hint":"please（使高兴）+ -ure → 愉快。词组 with pleasure 乐意","ex":"It's a pleasure to meet you.（认识你很荣幸。）"},{"id":1802,"day":29,"w":"price","ph":"praɪs","defs":[["n.","价格，价钱；代价 vt.标价",false]],"tier":"l","hint":"价格。词组 at a high price 高价","ex":"The price of the house is high.（房价很高。）"},{"id":1803,"day":29,"w":"priest","ph":"priːst","defs":[["n.","牧师",false]],"tier":"l","hint":"牧师、神父。联想 church 教堂、priest 牧师","ex":"The priest gave a speech in the church.（牧师在教堂演讲。）"},{"id":1804,"day":29,"w":"private","ph":"ˈpraɪvət","defs":[["a.","私人的，私立的；秘密的，私下的 vt.珍视，珍惜",false]],"tier":"l","hint":"私人的。联想 public 公共的（反义）","ex":"This is a private matter.（这是私事。）"},{"id":1805,"day":29,"w":"probably","ph":"ˈprɑːbəbli","defs":[["ad.","或许，大概，很可能",false]],"tier":"l","hint":"probable（可能的）+ -ly → 很可能","ex":"It will probably rain tomorrow.（明天很可能下雨。）"},{"id":1806,"day":29,"w":"progress","ph":"ˈprɑːɡres/prəˈɡres","defs":[["n.","/vi.前进，进步，进展",false]],"tier":"l","hint":"进步。词组 make progress 取得进步","ex":"He has made great progress in English.（他英语进步很大。）"},{"id":1807,"day":29,"w":"quarter","ph":"ˈkwɔːrtər","defs":[["n.","四分之一；一刻钟；季，季度",false]],"tier":"l","hint":"四分之一、一刻钟。词组 a quarter of 四分之一","ex":"It's a quarter past three.（现在三点一刻。）"},{"id":1808,"day":29,"w":"religion","ph":"rɪˈlɪdʒən","defs":[["n.","宗教，信仰",true]],"tier":"f","ety":"拉丁 religio（敬畏神）","mem":"re + lig（=lig 绑）+ ion → 把人和神\"绑\"在一起 → 宗教。画面：信仰纽带","ex":"freedom of religion · Everyone has the right to freedom of religion.（人人有宗教信仰自由。）","nua":"religion（宗教）、religious（宗教的）；freedom of religion 信仰自由"},{"id":1809,"day":29,"w":"request","ph":"rɪˈkwest","defs":[["n.","/vt.请求，要求",false]],"tier":"l","hint":"请求。词组 make a request 提出请求","ex":"He made a request for help.（他请求帮助。）"},{"id":1810,"day":29,"w":"season","ph":"ˈsiːzn","defs":[["n.","季，季节，时节",false]],"tier":"l","hint":"季节。词组 four seasons 四季","ex":"Spring is my favorite season.（春天是我最喜欢的季节。）"},{"id":1811,"day":29,"w":"singular","ph":"ˈsɪŋɡjələr","defs":[["a.","单一的；突出的",true]],"tier":"f","ety":"single（单一）+ -ar → 单一的","mem":"single + ar → 单一（single）的 → 单数、单一的。画面：形单影只","ex":"singular form · \"Child\" is the singular form of \"children\".（child 是 children 的单数形式。）","nua":"singular（单数、单一）、plural（复数）；反义 plural"},{"id":1812,"day":29,"w":"sink","ph":"sɪŋk","defs":[["n.","水槽，水池 vi.下落，下沉",false]],"tier":"l","hint":"下沉、水槽。过去式 sank。联想 float 漂浮（反义）","ex":"The ship sank in the storm.（船在暴风雨中沉没。）"},{"id":1813,"day":29,"w":"somewhere","ph":"ˈsʌmwer","defs":[["ad.","某处，某地",false]],"tier":"l","hint":"some（某）+ where（地方）→ 某处","ex":"I left my keys somewhere.（我把钥匙落在某处了。）"},{"id":1814,"day":29,"w":"sorry","ph":"ˈsɑːri","defs":[["a.","对不起的，抱歉的；难过的，悔恨的",false]],"tier":"l","hint":"抱歉的。词组 be sorry for 为…抱歉","ex":"I'm sorry for being late.（抱歉我迟到了。）"},{"id":1815,"day":29,"w":"spring","ph":"sprɪŋ","defs":[["n.","跳跃；春天；弹簧，弹性，发条；泉，源泉 vi.跳，跃",false]],"tier":"l","hint":"春天、弹簧、泉。词组 in spring 在春天","ex":"Flowers bloom in spring.（春天花开。）"},{"id":1816,"day":29,"w":"suitable","ph":"ˈsuːtəbl","defs":[["a.","合适的，适宜的",false]],"tier":"l","hint":"suit（适合）+ -able → 合适的。词组 be suitable for 适合","ex":"This book is suitable for children.（这本书适合孩子。）"},{"id":1817,"day":29,"w":"thief","ph":"θiːf","defs":[["n.","贼，小偷",true]],"tier":"f","ety":"古英语 þeof（贼）","mem":"谐音\"西服\"→ 偷了别人\"西服\"的贼 → 小偷。画面：鬼鬼祟祟","ex":"a thief · The police caught the thief.（警察抓住了小偷。）","nua":"thief（小偷）→ 复数 thieves（f→v+es）；steal（动词偷）、robbery（抢劫）"},{"id":1818,"day":29,"w":"violent","ph":"ˈvaɪələnt","defs":[["a.","猛烈的，强烈的，剧烈的；暴力的，狂暴的",false]],"tier":"l","hint":"violence（暴力）的形容词 → 暴力的、猛烈的","ex":"The movie has many violent scenes.（这部电影有很多暴力场面。）"},{"id":1819,"day":29,"w":"welcome","ph":"ˈwelkəm","defs":[["a.","受欢迎的 vt./n./int.欢迎",false]],"tier":"l","hint":"欢迎。词组 welcome to 欢迎到、you're welcome 不客气","ex":"Welcome to our school!（欢迎来我们学校！）"},{"id":1820,"day":30,"w":"after","ph":"ˈæftər","defs":[["prep.","/conj.在……之后 ad.以后，后来",false]],"tier":"l","hint":"在…之后。词组 after all 毕竟、look after 照顾","ex":"After class, we play basketball.（课后我们打篮球。）"},{"id":1821,"day":30,"w":"autumn","ph":"ˈɔːtəm","defs":[["n.","秋，秋季",false]],"tier":"l","hint":"秋天。联想 fall 秋天（美）","ex":"Leaves fall in autumn.（秋天树叶飘落。）"},{"id":1822,"day":30,"w":"blind","ph":"blaɪnd","defs":[["a.","盲的，瞎的；盲目的 vt.使失明；蒙蔽",false]],"tier":"l","hint":"盲的。词组 blind 盲的、turn a blind eye to 视而不见","ex":"He is blind in one eye.（他一只眼失明。）"},{"id":1823,"day":30,"w":"borrow","ph":"ˈbɑːroʊ","defs":[["vt.","借，借用",false]],"tier":"l","hint":"借入。联想 lend 借出（反义）。词组 borrow...from 从…借","ex":"I borrowed a book from the library.（我从图书馆借了本书。）"},{"id":1824,"day":30,"w":"brick","ph":"brɪk","defs":[["n.","砖，砖状物",false]],"tier":"l","hint":"砖。联想 brick 砖、build 建造","ex":"The house is made of bricks.（这房子是砖造的。）"},{"id":1825,"day":30,"w":"button","ph":"ˈbʌtn","defs":[["n.","扣子；按钮 vt.扣，扣紧",false]],"tier":"l","hint":"纽扣、按钮。词组 press the button 按按钮","ex":"Press the button to start the machine.（按按钮启动机器。）"},{"id":1826,"day":30,"w":"carry","ph":"ˈkæri","defs":[["vt.","搬运，运送，携带；传送，传播",false]],"tier":"l","hint":"携带、搬运。词组 carry out 执行、carry on 继续","ex":"He carried the heavy box upstairs.（他把重箱子搬上楼。）"},{"id":1827,"day":30,"w":"cattle","ph":"ˈkætl","defs":[["n.","[用作复数]牛",false]],"tier":"l","hint":"牛（总称，复数）。联想 cow 母牛、cattle 牛","ex":"The farmer keeps many cattle.（农民养了很多牛。）"},{"id":1828,"day":30,"w":"club","ph":"klʌb","defs":[["n.","俱乐部，社；棒，球棒",false]],"tier":"l","hint":"俱乐部、棍棒。词组 join a club 加入俱乐部","ex":"He joined the football club.（他加入了足球俱乐部。）"},{"id":1829,"day":30,"w":"copy","ph":"ˈkɑːpi","defs":[["n.","抄件，副本；本，册 vt.抄写，复印，临摹",false]],"tier":"l","hint":"抄写、副本。词组 make a copy 复印","ex":"Please copy the new words.（请抄写生词。）"},{"id":1830,"day":30,"w":"defeat","ph":"dɪˈfiːt","defs":[["vt.","/n.战胜，挫败",false]],"tier":"l","hint":"击败。联想 win 赢、defeat 击败（对手）","ex":"Our team defeated them in the final.（我们队在决赛中击败了他们。）"},{"id":1831,"day":30,"w":"defend","ph":"dɪˈfend","defs":[["vt.","保卫，防守；答辩",false]],"tier":"l","hint":"防守、保卫。词组 defend...from 保护…免受","ex":"The soldiers defended the city.（士兵们保卫了城市。）"},{"id":1832,"day":30,"w":"degree","ph":"dɪˈɡriː","defs":[["n.","度，程度；等级；学位",false]],"tier":"l","hint":"度数、学位、程度。词组 a bachelor's degree 学士学位","ex":"He got a degree from the university.（他获得了大学学位。）"},{"id":1833,"day":30,"w":"egg","ph":"eɡ","defs":[["n.","卵，蛋",false]],"tier":"l","hint":"鸡蛋。词组 a boiled egg 煮鸡蛋","ex":"I have an egg for breakfast.（我早餐吃个鸡蛋。）"},{"id":1834,"day":30,"w":"entertainment","ph":"ˌentərˈteɪnmənt","defs":[["n.","娱乐",false]],"tier":"l","hint":"entertain（娱乐）+ -ment → 娱乐","ex":"The city offers many forms of entertainment.（这座城市提供多种娱乐。）"},{"id":1835,"day":30,"w":"evening","ph":"ˈiːvnɪŋ","defs":[["n.","晚上，傍晚，黄昏",false]],"tier":"l","hint":"傍晚。词组 in the evening 在傍晚","ex":"We watch TV in the evening.（我们傍晚看电视。）"},{"id":1836,"day":30,"w":"event","ph":"ɪˈvent","defs":[["n.","事件，事变，大事；比赛项目",false]],"tier":"l","hint":"事件、比赛项目。词组 sports event 体育赛事","ex":"The event attracted many people.（这个活动吸引了许多人。）"},{"id":1837,"day":30,"w":"expression","ph":"ɪkˈspreʃn","defs":[["n.","表达",false]],"tier":"l","hint":"express（表达）+ -ion → 表达、表情","ex":"His expression showed surprise.（他的表情显出惊讶。）"},{"id":1838,"day":30,"w":"fit","ph":"fɪt","defs":[["a.","合适，恰当，合身；健康，健壮 vt.适合，适应，配合",false]],"tier":"l","hint":"适合、健康的。词组 keep fit 保持健康、be fit for 适合","ex":"Running helps you keep fit.（跑步帮助你保持健康。）"},{"id":1839,"day":30,"w":"future","ph":"ˈfjuːtʃər","defs":[["a.","将来的，未来的 n.将来，未来；前途，远景",false]],"tier":"l","hint":"未来。词组 in the future 在未来","ex":"He has big plans for the future.（他对未来有远大计划。）"},{"id":1840,"day":30,"w":"generous","ph":"ˈdʒenərəs","defs":[["a.","慷慨的，大方的；丰盛的，丰富的",false]],"tier":"l","hint":"慷慨的。词组 be generous with 慷慨给予","ex":"He is generous with his money.（他花钱很大方。）"},{"id":1841,"day":30,"w":"gram(me)","ph":"ɡræm","defs":[["n.","克",false]],"tier":"l","hint":"克（重量单位）。联想 kilogram 千克","ex":"The apple weighs 200 grams.（这个苹果重 200 克。）"},{"id":1842,"day":30,"w":"grammar","ph":"ˈɡræmər","defs":[["n.","语法，语法书",false]],"tier":"l","hint":"语法。词组 English grammar 英语语法","ex":"English grammar is important.（英语语法很重要。）"},{"id":1843,"day":30,"w":"grass","ph":"ɡræs","defs":[["n.","草，牧草",false]],"tier":"l","hint":"草。联想 grass 草、green grass 青草","ex":"The cows are eating grass.（牛在吃草。）"},{"id":1844,"day":30,"w":"group","ph":"ɡruːp","defs":[["n.","群，小组 vt.分组，聚集",false]],"tier":"l","hint":"群、组。词组 a group of 一组、group work 小组合作","ex":"A group of students are playing.（一群学生在玩。）"},{"id":1845,"day":30,"w":"house","ph":"haʊs","defs":[["n.","房子，住宅；议院，大楼，会议厅",false]],"tier":"l","hint":"房子。词组 at home 在家、house 房子","ex":"They live in a big house.（他们住在大房子里。）"},{"id":1846,"day":30,"w":"ink","ph":"ɪŋk","defs":[["n.","墨水",false]],"tier":"l","hint":"墨水。联想 pen 钢笔、ink 墨水","ex":"The pen is out of ink.（钢笔没墨水了。）"},{"id":1847,"day":30,"w":"inward(s)","ph":"ˈɪnwərd","defs":[["a.","内心的，向内的",false]],"tier":"l","hint":"in（内）+ ward（向）→ 向内的。联想 outward 向外的","ex":"The door opens inward.（门朝里开。）"},{"id":1848,"day":30,"w":"island","ph":"ˈaɪlənd","defs":[["n.","岛",false]],"tier":"l","hint":"岛屿。联想 island 岛、sea 海","ex":"They spent the holiday on an island.（他们在一个岛上度假。）"},{"id":1849,"day":30,"w":"letter","ph":"ˈletər","defs":[["n.","信，函件；字母",false]],"tier":"l","hint":"信、字母。词组 write a letter 写信","ex":"She wrote a letter to her friend.（她给朋友写了封信。）"},{"id":1850,"day":30,"w":"mist","ph":"mɪst","defs":[["n.","薄雾",false]],"tier":"l","hint":"薄雾。联想 fog 浓雾、mist 薄雾","ex":"The village was covered in mist.（村庄笼罩在薄雾中。）"},{"id":1851,"day":30,"w":"neat","ph":"niːt","defs":[["a.","整洁的，简洁的；优美的，精致的；利索的",false]],"tier":"l","hint":"整洁的。联想 tidy 整洁的（同义）","ex":"Her room is always neat.（她的房间总是整洁。）"},{"id":1852,"day":30,"w":"neither","ph":"ˈnaɪðər","defs":[["a.","（两者）没有一个的 pron.两者都不 conj./ad.也不",false]],"tier":"l","hint":"两者都不。词组 neither...nor 既不…也不","ex":"Neither of them came to the party.（他们俩都没来聚会。）"},{"id":1853,"day":30,"w":"pepper","ph":"ˈpepər","defs":[["n.","胡椒粉，胡椒，辣椒",false]],"tier":"l","hint":"胡椒、辣椒。联想 salt 盐、pepper 胡椒","ex":"She put some pepper in the soup.（她在汤里放了点胡椒。）"},{"id":1854,"day":30,"w":"permanent","ph":"ˈpɜːrmənənt","defs":[["a.","永久的，持久的",false]],"tier":"l","hint":"永久的。联想 temporary 暂时的（反义）","ex":"He found a permanent job.（他找到份稳定的工作。）"},{"id":1855,"day":30,"w":"pink","ph":"pɪŋk","defs":[["n.","粉红色",false]],"tier":"l","hint":"粉色。联想颜色词：pink 粉色","ex":"She likes pink very much.（她很喜欢粉色。）"},{"id":1856,"day":30,"w":"place","ph":"pleɪs","defs":[["n.","地方，位置；职位；住所；地位，等级，名次 vt.放，置；安排，任命；发出（订单等）",false]],"tier":"l","hint":"地方、放置。词组 take place 发生、in place 到位","ex":"This is a beautiful place.（这是个美丽的地方。）"},{"id":1857,"day":30,"w":"pool","ph":"puːl","defs":[["n.","水塘，池子，水潭 vt.把……集中在一起",false]],"tier":"l","hint":"池塘、游泳池。词组 swimming pool 游泳池","ex":"The children swim in the pool.（孩子们在游泳池游泳。）"},{"id":1858,"day":30,"w":"prince","ph":"prɪns","defs":[["n.","王子，亲王",false]],"tier":"l","hint":"王子。联想 princess 公主、prince 王子","ex":"The prince married the princess.（王子和公主结婚了。）"},{"id":1859,"day":30,"w":"proposal","ph":"prəˈpoʊzl","defs":[["n.","提议，建议；求婚",false]],"tier":"l","hint":"propose（提议）+ -al → 提议","ex":"He made a proposal at the meeting.（他在会上提了个建议。）"},{"id":1860,"day":30,"w":"respect","ph":"rɪˈspekt","defs":[["vt.","尊敬，尊重 n.尊敬 (pl.)敬意，问候",false]],"tier":"l","hint":"尊重。词组 respect sb 尊重某人、show respect for 尊重","ex":"We should respect the old.（我们应该尊重老人。）"},{"id":1861,"day":30,"w":"restrict","ph":"rɪˈstrɪkt","defs":[["vt.","限制，约束",false]],"tier":"l","hint":"限制。词组 restrict...to 把…限制在","ex":"Smoking is restricted in public places.（公共场所限制吸烟。）"},{"id":1862,"day":30,"w":"shoot","ph":"ʃuːt","defs":[["vi.","射击；射(门)，投(篮)；发芽，长高 vt.射中；发射；拍摄 n.枝条，嫩条，苗",false]],"tier":"l","hint":"射击、拍摄。过去式 shot。词组 shoot at 向…射击","ex":"He shot at the target.（他朝目标射击。）"},{"id":1863,"day":30,"w":"somehow","ph":"ˈsʌmhaʊ","defs":[["ad.","设法；不知怎么的",false]],"tier":"l","hint":"some（某）+ how（怎样）→ 不知怎么地","ex":"Somehow, he finished the work on time.（不知怎么地，他按时完成了工作。）"},{"id":1864,"day":30,"w":"sore","ph":"sɔːr","defs":[["a.","疼痛的；痛心的 n.痛处，疮口",false]],"tier":"l","hint":"疼痛的。词组 sore throat 嗓子疼","ex":"I have a sore throat.（我嗓子疼。）"},{"id":1865,"day":30,"w":"success","ph":"səkˈses","defs":[["n.","成功，成就",false]],"tier":"l","hint":"成功。词组 achieve success 取得成功","ex":"Hard work leads to success.（努力通向成功。）"},{"id":1866,"day":30,"w":"temper","ph":"ˈtempər","defs":[["n.","情绪，脾气",true]],"tier":"f","ety":"拉丁 temperare（调和），与 temperature 同源","mem":"temper（=temperature 温度）→ 情绪像\"温度\"一样升降 → 脾气。画面：火冒三丈","ex":"lose one's temper · He lost his temper at the meeting.（他在会上发了脾气。）","nua":"lose one's temper（发脾气）、in a good/bad temper（情绪好/坏）；与 temperature 同源"},{"id":1867,"day":30,"w":"thick","ph":"θɪk","defs":[["a.","粗的，厚的；稠的，浓的；浓密的；茂密的 ad.厚厚地，浓浓地，密集地",false]],"tier":"l","hint":"厚的、浓的。联想 thin 薄的（反义）","ex":"The book is very thick.（这本书很厚。）"},{"id":1868,"day":30,"w":"tight","ph":"taɪt","defs":[["a.","紧的，紧身的，贴身的；密封的，紧密的 ad.紧紧地",false]],"tier":"l","hint":"紧的。联想 loose 松的（反义）","ex":"The shoes are too tight.（这双鞋太紧了。）"},{"id":1869,"day":30,"w":"tomato","ph":"təˈmeɪtoʊ","defs":[["n.","西红柿",false]],"tier":"l","hint":"西红柿。联想 potato 土豆","ex":"She put some tomatoes in the salad.（她在沙拉里放了西红柿。）"},{"id":1870,"day":30,"w":"tyre","ph":"ˈtaɪər","defs":[["n.","轮胎",false]],"tier":"l","hint":"轮胎（英式 tire）。联想 wheel 轮子、tyre 轮胎","ex":"The car has a flat tyre.（车胎瘪了。）"},{"id":1871,"day":30,"w":"up","ph":"ʌp","defs":[["ad.","向上；起床；激动起来 prep.向上，向/在髙处；沿着，在……那边 a.向上的",false]],"tier":"l","hint":"向上。词组 get up 起床、up to 直到","ex":"The balloon went up into the sky.（气球升上了天空。）"},{"id":1872,"day":30,"w":"waste","ph":"weɪst","defs":[["a.","荒废的，没用的 vt.浪费，消耗 n.浪费，消耗；废物，废品",false]],"tier":"l","hint":"浪费、废物。词组 waste time 浪费时间","ex":"Don't waste your time on games.（别把时间浪费在游戏上。）"},{"id":1873,"day":30,"w":"way","ph":"weɪ","defs":[["n.","道路；方法，方式；习惯，作风；状态，情况",false]],"tier":"l","hint":"路、方法。词组 by the way 顺便、on the way 在路上","ex":"Can you tell me the way to the station?（你能告诉我去车站的路吗？）"},{"id":1874,"day":30,"w":"website","ph":"ˈwebsaɪt","defs":[["n.","网址",false]],"tier":"l","hint":"web（网）+ site（地点）→ 网站","ex":"You can find the information on the website.（你可以在网站上找到信息。）"},{"id":1875,"day":30,"w":"wet","ph":"wet","defs":[["a.","湿；下雨的，多雨的 vt.沾湿，弄湿",false]],"tier":"l","hint":"湿的。联想 dry 干的（反义）","ex":"My clothes are wet from the rain.（我的衣服被雨淋湿了。）"},{"id":1876,"day":30,"w":"young","ph":"jʌŋ","defs":[["a.","年轻的",false]],"tier":"l","hint":"年轻的。联想 old 老的（反义）","ex":"She is still very young.（她还很年轻。）"}];
